import { AsyncPipe } from '@angular/common';
import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Input,
    booleanAttribute,
    Output,
    EventEmitter,
    inject,
} from '@angular/core';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EuiAppShellService } from '@eui/core';

@Component({
    selector: 'eui-toolbar-selector',
    templateUrl: './toolbar-selector.component.html',
    styleUrl: './toolbar-selector.component.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        ...EUI_BUTTON,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
    ],
})
export class EuiToolbarSelectorComponent {
    @HostBinding() class = 'eui-toolbar-selector';

    @Input() label: string;
    @Input() iconSvgName: string;

    @Input({ transform: booleanAttribute }) euiDisabled = false;

    @Output() selectorClick: EventEmitter<boolean> = new EventEmitter();
    protected asService = inject(EuiAppShellService);

    onClick(): void {
        this.selectorClick.emit(true);
    }
}
