import {
    Directive,
    Input,
    OnInit,
    OnDestroy,
    ElementRef,
    HostListener,
    OnChanges,
    numberAttribute,
    booleanAttribute,
    ComponentRef,
    inject,
} from '@angular/core';
import {
    ConnectedOverlayPositionChange,
    ConnectionPositionPair,
    FlexibleConnectedPositionStrategyOrigin,
    Overlay,
    OverlayRef,
} from '@angular/cdk/overlay';
import { BehaviorSubject, fromEvent, Subject, Subscription, take, timer } from 'rxjs';
import { ComponentPortal } from '@angular/cdk/portal';

import { EuiTooltipContainerComponent } from './container/eui-tooltip-container.component';
import { EuiTooltipInterface } from './models/eui-tooltip.config';

/**
 * @description
 * A tooltip is a text box that displays addition information when a user hovers over, clicks or gives focus to a UI element such as an icon, a highlighted word or a button.
 *
 * The information should be contextual, useful and non-essential.
 *
 */
@Directive({
    selector: '[euiTooltip]',
    exportAs: 'euiTooltip',
})
export class EuiTooltipDirective implements OnChanges, OnInit, OnDestroy {
    /**
     * Sets the `data-e2e` attribute for the host element.
     *
     * @default 'eui-tooltip'
     */
    @Input() e2eAttr = 'eui-tooltip';
    /**
     * Sets the delay for the tooltip to be visible.
     *
     * @default 0
     */
    @Input({ transform: numberAttribute }) showDelay = 0;
    /**
     * Sets the delay for the tooltip to be hidden
     *
     * @default 0
     */
    @Input({ transform: numberAttribute }) hideDelay = 0;
    /**
     * Sets the alignment of the content in the tooltip.
     *
     * @default 'center''
     */
    @Input() contentAlignment: 'left' | 'right' | 'center' | 'justify' = 'center';
    /**
     * Sets the position of the tooltip relative to its trigger element.
     *
     * @default 'center''
     */
    @Input() position: 'left' | 'right' | 'above' | 'below' | 'before' | 'after' | string = 'above';
    /**
     * Whether the tooltip is disabled.
     *
     * @default false (enable)
     */
    @Input({ transform: booleanAttribute }) isDisabled = false;
    /**
     * Tooltip content.
     */
    @Input('euiTooltip') tooltipContent: string;
    /**
     * Whether the tooltip has a Primary state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipPrimary = false;
    /**
     * Whether the tooltip has a Secondary state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipSecondary = false;
    /**
     * Whether the tooltip has Info state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipInfo = false;
    /**
     * Whether the tooltip has a Success state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipSuccess = false;
    /**
     * Whether the tooltip has a Warning state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipWarning = false;
    /**
     * Whether the tooltip has a Danger state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipDanger = false;
    /**
     * Whether the tooltip has Accent state.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiTooltipAccent = false;

    private originX: 'start' | 'end' | 'center' = 'center';
    private originY: 'top' | 'bottom' | 'center' = 'top';
    private overlayX: 'start' | 'end' | 'center' = 'center';
    private overlayY: 'top' | 'bottom' | 'center' = 'bottom';
    private fallbackOriginX: 'start' | 'end' | 'center' = 'center';
    private fallbackOriginY: 'top' | 'bottom' | 'center' = 'bottom';
    private fallbackOverlayX: 'start' | 'end' | 'center' = 'center';
    private fallbackOverlayY: 'top' | 'bottom' | 'center' = 'top';
    private overlayRef: OverlayRef;
    private destroy$ = new Subject<boolean>();
    private isOpen$ = new BehaviorSubject<boolean>(false);
    private mouseleaveSubscription = new Subscription();
    private blurSubscription = new Subscription();
    private showDelaySubscription = new Subscription();
    private positionStrategySubscription = new Subscription();
    private tooltipInstance: ComponentRef<EuiTooltipContainerComponent>;
    private overlay = inject(Overlay);
    private host = inject<ElementRef<HTMLElement>>(ElementRef);

    ngOnChanges(): void {
        if (this.tooltipInstance) {
            this.tooltipInstance.setInput('config', this.getTooltipConfig());
        }

        this.setPosition();
    }

    ngOnInit(): void {
        this.setPosition();
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
        this.mouseleaveSubscription.unsubscribe();
        this.blurSubscription.unsubscribe();
        this.showDelaySubscription.unsubscribe();
        this.positionStrategySubscription.unsubscribe();
        this.overlayRef?.dispose();
        this.overlayRef = null;
    }

    @HostListener('mouseenter', ['$event'])
    mouseEntering(event: MouseEvent): void {
        this.show(event.target);
    }

    @HostListener('focus', ['$event'])
    focused(event: FocusEvent): void {
        this.show(event.target);
    }

    /**
     * Returns the current open state.
     *
     * @returns {boolean} `true` if the element is open, otherwise `false`.
     */
    get isOpen(): boolean {
        return this.isOpen$.value;
    }

    /**
     * Method that shows a tooltip.
     *
     * @param origin Origin of the tooltip. Where it will be displayed.
     */
    public show(origin: EventTarget = this.host.nativeElement): void {
        this.showDelaySubscription = timer(this.showDelay).subscribe(() => {
            if (!this.isOpen && !this.isDisabled && this.tooltipContent) {
                const positionStrategy = this.overlay
                    .position()
                    .flexibleConnectedTo(origin as FlexibleConnectedPositionStrategyOrigin)
                    .withPositions([
                        new ConnectionPositionPair(
                            { originX: this.originX, originY: this.originY },
                            { overlayX: this.overlayX, overlayY: this.overlayY },
                        ),
                        new ConnectionPositionPair(
                            { originX: this.fallbackOriginX, originY: this.fallbackOriginY },
                            { overlayX: this.fallbackOverlayX, overlayY: this.fallbackOverlayY },
                        ),
                    ])
                    .withFlexibleDimensions(false)
                    .withLockedPosition(true);
                const scrollStrategy = this.overlay.scrollStrategies.reposition({ scrollThrottle: 10 });

                this.overlayRef = this.overlay.create({
                    hasBackdrop: false,
                    panelClass: ['eui-tooltip__container', 'eui-19'],
                    positionStrategy,
                    scrollStrategy,
                });

                this.positionStrategySubscription = positionStrategy.positionChanges.subscribe((overlayPosition) => {
                    this.position = this.getPosition(overlayPosition);
                    const positionClasses = [
                        'eui-tooltip--left',
                        'eui-tooltip--right',
                        'eui-tooltip--above',
                        'eui-tooltip--below',
                        'eui-tooltip--before',
                        'eui-tooltip--after',
                    ];
                    this.overlayRef.removePanelClass(positionClasses);
                    this.overlayRef.addPanelClass(['eui-tooltip--' + this.position]);
                });

                const componentPortal = new ComponentPortal<EuiTooltipContainerComponent>(
                    EuiTooltipContainerComponent,
                    null,
                );

                this.tooltipInstance = this.overlayRef.attach(componentPortal);
                this.tooltipInstance.setInput('config', this.getTooltipConfig());

                this.isOpen$.next(true);
            }
        });

        this.mouseleaveSubscription = fromEvent(origin, 'mouseleave').subscribe(() => {
            this.hide();
        });

        this.blurSubscription = fromEvent(origin, 'blur').subscribe(() => {
            this.hide();
        });
    }

    /**
     * Method that closes a tooltip.
     */
    public hide(): void {
        timer(this.hideDelay)
            .pipe(take(1))
            .subscribe(() => {
                this.isOpen$.next(false);
                this.mouseleaveSubscription.unsubscribe();
                this.blurSubscription.unsubscribe();
                this.showDelaySubscription.unsubscribe();
                this.positionStrategySubscription.unsubscribe();
                this.overlayRef?.dispose();
                this.overlayRef = null;
            });
    }

    /**
     * Generates and returns the tooltip configuration based on the defined tooltip properties.
     *
     * @returns {EuiTooltipInterface} The tooltip configuration object, including attributes used in container component.
     */
    private getTooltipConfig(): EuiTooltipInterface {
        let colorClass = 'secondary';
        if (this.euiTooltipPrimary) {
            colorClass = 'primary';
        }
        if (this.euiTooltipSecondary) {
            colorClass = 'secondary';
        }
        if (this.euiTooltipInfo) {
            colorClass = 'info';
        }
        if (this.euiTooltipSuccess) {
            colorClass = 'success';
        }
        if (this.euiTooltipWarning) {
            colorClass = 'warning';
        }
        if (this.euiTooltipDanger) {
            colorClass = 'danger';
        }
        if (this.euiTooltipAccent) {
            colorClass = 'accent';
        }

        return {
            e2eAttr: this.e2eAttr,
            tooltipContent: this.tooltipContent,
            position: this.position,
            contentAlign: this.contentAlignment,
            colorClass,
        };
    }

    /**
     * Determines and returns the tooltip's position based on the overlay's connection pair.
     *
     * @param {ConnectedOverlayPositionChange} overlayPosition - The overlay position change event.
     * @returns {string} The calculated position (`'above'`, `'below'`, `'left'`, or `'right'`).
     */
    private getPosition(overlayPosition: ConnectedOverlayPositionChange): string {
        if (overlayPosition.connectionPair.originY === 'top' && overlayPosition.connectionPair.overlayY === 'bottom') {
            return 'above';
        }
        if (overlayPosition.connectionPair.originY === 'bottom' && overlayPosition.connectionPair.overlayY === 'top') {
            return 'below';
        }
        if (overlayPosition.connectionPair.originX === 'start' && overlayPosition.connectionPair.overlayX === 'end') {
            return 'left';
        }
        if (overlayPosition.connectionPair.originX === 'end' && overlayPosition.connectionPair.overlayX === 'start') {
            return 'right';
        }
    }

    /**
     * Sets the position-related properties based on the current `position` value.
     */
    private setPosition(): void {
        if (this.position === 'above') {
            this.originY = 'top';
            this.overlayY = 'bottom';
            this.fallbackOriginY = 'bottom';
            this.fallbackOverlayY = 'top';
        }
        if (this.position === 'right' || this.position === 'after') {
            this.originX = 'end';
            this.originY = 'center';
            this.overlayX = 'start';
            this.overlayY = 'center';
            this.fallbackOriginX = 'start';
            this.fallbackOriginY = 'center';
            this.fallbackOverlayX = 'end';
            this.fallbackOverlayY = 'center';
        }
        if (this.position === 'below') {
            this.originY = 'bottom';
            this.overlayY = 'top';
            this.fallbackOriginY = 'top';
            this.fallbackOverlayY = 'bottom';
        }
        if (this.position === 'left' || this.position === 'before') {
            this.originX = 'start';
            this.originY = 'center';
            this.overlayX = 'end';
            this.overlayY = 'center';
            this.fallbackOriginX = 'end';
            this.fallbackOriginY = 'center';
            this.fallbackOverlayX = 'start';
            this.fallbackOverlayY = 'center';
        }
    }
}
