import {
    booleanAttribute,
    Component,
    DoCheck,
    ElementRef,
    EventEmitter,
    HostBinding,
    HostListener,
    Input,
    IterableDiffer,
    IterableDiffers,
    OnDestroy,
    Output,
    ViewEncapsulation,
    inject,
} from '@angular/core';
import { EuiGrowlMessage } from '@eui/core';
import { TranslateModule } from '@ngx-translate/core';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_ICON_STATE } from '@eui/components/eui-icon-state';
import { NgClass } from '@angular/common';

@Component({
    selector: 'eui-growl',
    templateUrl: './eui-growl.component.html',
    styleUrl: './eui-growl.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgClass,
        TranslateModule,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
        ...EUI_ICON_STATE,
    ],
})
export class EuiGrowlComponent implements DoCheck, OnDestroy {
    el = inject(ElementRef);
    titleId = 'msg-title';
    contentId = 'msg-detail';

    @HostBinding('class')
    get cssClasses(): string {
        return ['eui-growl', `eui-growl--${this.position}`].join(' ').trim();
    }
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-growl';
    @HostBinding('attr.role')
    protected role = 'status';
    @HostBinding('attr.aria-live') @Input() ariaLive: 'off' | 'polite' | 'assertive' = 'polite';
    @HostBinding('attr.aria-labelledby')
    get ariaLabelledBy(): string {
        return this.value?.length ? this.titleId : null;
    }
    @HostBinding('attr.aria-describedby')
    get ariaDescribedBy(): string {
        return this.value?.length ? this.contentId : null;
    }

    @Input({ transform: booleanAttribute }) sticky = false;

    @Input() life = 3000;
    @Input() value: EuiGrowlMessage[] = [];
    @Input() closeAllSticky = false;

    @Input() position: string;

    @Output() growlClick: EventEmitter<void> = new EventEmitter<void>();

    private differ: IterableDiffer<EuiGrowlMessage>;

    constructor() {
        const differs = inject(IterableDiffers);

        this.differ = differs.find([]).create(undefined);
    }

    ngDoCheck(): void {
        const changes = this.differ.diff(this.value);

        if (changes) {
            // clear timeout in the queue to avoid memory leak
            changes.forEachRemovedItem(({ item }) => clearTimeout(item?.timeout));
            // for newly added items create timeout if they are not sticky
            changes.forEachAddedItem(({ item }) => this.createRemovalTimeout(item));
        }
    }

    /**
     * @param msg The text message to appear in the container
     */
    remove(msg: EuiGrowlMessage): void {
        this.value.splice(this.findMessageIndex(msg), 1);
    }

    /**
     * Removes all growl messages from the stack
     */
    removeAll(): void {
        if (this.value?.length) {
            this.value.splice(0, this.value.length);
        }
    }

    ngOnDestroy(): void {
        if (!this.sticky) {
            // make sure to clear any leftover async Timeout for messages
            this.value.forEach((v) => clearTimeout(v?.timeout));
        }
    }

    @HostListener('click')
    onClick(): void {
        this.growlClick.emit();
    }

    /**
     * check whether sticky growls are greater than two
     */
    isGrowlMoreThanTwo(): boolean {
        return this.value.filter((m) => m.sticky).length > 2;
    }

    /**
     * Removes all growl messages from the stack
     *
     * @param value
     */
    private createRemovalTimeout(value: EuiGrowlMessage): void {
        // if message it's NOT sticky and there's not any async running timeout
        if (!value.sticky && !value.timeout) {
            // set Timeout callback for each message based on the given life value
            value.timeout = setTimeout(() => this.remove(value), value.life || this.life) as unknown as number;
        }
    }

    /**
     * Finds UxMessage index of the array otherwise returns -1
     *
     * @param msg UxMessage
     */
    private findMessageIndex(msg: EuiGrowlMessage): number {
        return this.value?.length ? this.value.findIndex((value) => value === msg) : -1;
    }
}
