import { Component, HostBinding, ViewEncapsulation, Input, Output, EventEmitter } from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_BADGE } from '@eui/components/eui-badge';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';

@Component({
    selector: 'eui-overlay-header-title',
    templateUrl: './eui-overlay-header-title.component.html',
    encapsulation: ViewEncapsulation.None,
    imports: [
        BaseStatesDirective,
        ...EUI_BADGE,
        ...EUI_BUTTON,
        ...EUI_ICON,
    ],
})
export class EuiOverlayHeaderTitleComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return 'eui-overlay-header-title';
    }

    @Input() headerTitleLabel: string = null;
    @Input() headerTitleHideLabel: string = null;
    @Input() headerTitleCount: string = null;

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    @Output() hide: EventEmitter<any> = new EventEmitter<any>();

    onHide(): void {
        this.hide.emit();
    }
}
