import { HttpErrorResponse } from '@angular/common/http';

export class UxErrorOutput<DETAILS = unknown> implements UxErrorInfo, UxHttpErrorInfo, UxErrorFeedback {
    code?: string;
    requestId?: string;
    doc?: string;
    details?: DETAILS;
    severity = UxMessageSeverity.danger;
    msgId: string;
    description: string;
    errGroupMap?: Array<UxErrorGroupMap>;
    subErrors?: SubErrors;

    constructor(
        info: UxErrorInfo & UxHttpErrorInfo,
        errorFeedback: UxErrorFeedback,
        subErrors?: SubErrors,
        errGroupMap?: Array<UxErrorGroupMap>,
    ) {
        if (!subErrors) {
            Object.assign(this, { ...info }, { ...errorFeedback });
        } else {
            Object.assign(this, { ...info }, { ...errorFeedback }, { subErrors }, { errGroupMap });
        }
    }

    getFeedBacks(byKey?: string): Array<UxErrorFeedback> {
        if (this.subErrors) {
            return this.subErrors
                .filter((err) => {
                    if (err instanceof UxValidationErrorClass) {
                        if (byKey && err.attributes) {
                            return this.checkAttribute(byKey, err.attributes);
                        } else if (byKey && !err.attributes) {
                            return false;
                        } else if (!byKey) {
                            return true;
                        }
                    }
                })
                .map((err) => ({
                    msgId: err.msgId,
                    description: err.description,
                    severity: err.severity,
                    attributes: err.attributes,
                    errGroupId: err.errGroupId,
                    br: err.br,
                    doc: err.doc,
                }));
        } else {
            if (!byKey) {
                return [{ msgId: this.msgId, description: this.description, severity: this.severity, doc: this.doc }];
            } else {
                return [];
            }
        }
    }

    private checkAttribute(key: string, attributes: UxValidationErrorAttributes): boolean {
        return attributes.some((attr) => key === attr.key);
    }
}

export class UxErrorGroupOnClickEvent {
    constructor(public groupId: string, public err?: UxErrorFeedback) {}
}

export interface UxErrorFollowMap {
    [groupId: string]: boolean;
}

export type UxErrorGroupMap = {
    id: string;
    description: string;
    severity: UxMessageSeverity;
};

export type UxErrorGroupItem = {
    groupId: string;
    description: string;
    severity: UxMessageSeverity;
    errors: Array<UxErrorFeedback>;
};

// T extends U ? X : Y
// Let's look at the ways to do detailed generic, like error
export interface UxErrorInfo<DETAILS = unknown> {
    code?: string;
    doc?: string;
    details?: DETAILS;
}

export interface UxHttpErrorInfo {
    requestId?: string;
}

export interface UxErrorFeedback extends UxErrorMessage {
    severity?: UxMessageSeverity;
    attributes?: UxValidationErrorAttributes;
    errGroupId?: string;
    br?: string;
    doc?: string;
}

export interface UxErrorMessage {
    msgId: string;
    description?: string;
}

export type UxValidationErrorAttributes = Array<UxValidationErrorAttribute>;

export interface UxValidationErrorAttribute {
    key: string | Array<string>;
    value: string;
}

export enum UxMessageSeverity {
    info = 'info',
    warning = 'warning',
    danger = 'danger',
    success = 'success',
}

export enum UxMessageSeverityMetrics {
    info = 0,
    warning = 1,
    danger = 2,
    success = 3,
}

export type SubErrors = Array<UxValidationErrorClass>;

export class UxValidationErrorClass<Details = object> implements UxErrorInfo<Details>, UxErrorFeedback {
    msgId: string;
    description?: string;
    severity = UxMessageSeverity.danger;
    attributes: UxValidationErrorAttributes;
    br?: string;
    doc?: string;
    details?: Details;
    errGroupId?: string;

    constructor(data: UxValidationErrorClass) {
        Object.assign(this, data);
    }
}

export type ErrorMappingHandler<Error = object> = (err: Error) => UxErrorOutput;

export interface UxHttpErrorResponse extends HttpErrorResponse {
    uxHttpErrorOutput: UxErrorOutput;
}

export const transformToUxHttpResponse = (resp: HttpErrorResponse, mapper: ErrorMappingHandler): UxHttpErrorResponse => {
    const updatedErr = resp as UxHttpErrorResponse;
    updatedErr.uxHttpErrorOutput = mapper(resp.error);
    return updatedErr;
};

export type UxErrorFeedbackEventType = UxPublishErrorFeedbackEvent | UxClearErrorFeedbackEvent;

export class UxPublishErrorFeedbackEvent {
    constructor(public err: UxErrorOutput, public id?: string, public groupId?: string, public accumulate?: boolean) {}
}

export class UxClearErrorFeedbackEvent {
    constructor(public id?: string, public groupId?: string) {}
}
