import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Output,
    EventEmitter,
    ContentChildren,
    forwardRef,
    QueryList,
    ElementRef,
    AfterViewInit,
    AfterContentInit,
    inject,
} from '@angular/core';
import { EuiToolbarNavbarItemComponent } from '../toolbar-navbar-item/toolbar-navbar-item.component';
import { EuiAppShellService } from '@eui/core';
import { EUI_DROPDOWN } from '@eui/components/eui-dropdown';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { AsyncPipe } from '@angular/common';

@Component({
    selector: 'eui-toolbar-navbar',
    templateUrl: './toolbar-navbar.component.html',
    styleUrl: './toolbar-navbar.component.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        ...EUI_ICON,
        ...EUI_BUTTON,
        ...EUI_DROPDOWN,
    ],
})
export class EuiToolbarNavbarComponent implements AfterContentInit, AfterViewInit {
    @HostBinding() class = 'eui-toolbar-navbar';

    @Output() itemClick: EventEmitter<string> = new EventEmitter();

    @ContentChildren(forwardRef(() => EuiToolbarNavbarItemComponent)) items: QueryList<EuiToolbarNavbarItemComponent>;

    asService = inject(EuiAppShellService);
    public baseItemSelected: EuiToolbarNavbarItemComponent;
    public isDropdownView = false;
    private elementRef = inject(ElementRef);

    ngAfterContentInit(): void {
        this.baseItemSelected = this.items.filter((i) => i.isActive)[0];
    }

    ngAfterViewInit(): void {
        // if (!this.asService?.state?.hasHeader) {
            const parentWidth = this.elementRef.nativeElement.closest('eui-toolbar').clientWidth;
            const width = this.elementRef.nativeElement.clientWidth;

            if (width > parentWidth) {
                setTimeout(() => {
                    this.isDropdownView = true;
                }, 1);
            }
        // }
    }

    public itemSelected(id: string): void {
        this.items.forEach((item) => {
            if (item.id === id) {
                item.isActive = true;
            } else {
                item.isActive = false;
            }
        });
        this.itemClick.emit(id);
    }
}
