import { Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, OnInit, inject } from '@angular/core';

import { EuiAppShellService } from '@eui/core';

@Component({
    selector: 'eui-app-breadcrumb',
    template: '<ng-content/>',
    styleUrl: './breadcrumb.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiAppBreadcrumbComponent implements OnInit {
    @HostBinding('class')
    get cssClasses(): string {
        return this.getCssClasses();
    }
    @HostBinding('attr.role') role = 'nav';
    private asService = inject(EuiAppShellService);

    ngOnInit(): void {
        this.asService.activateBreadcrumb();
    }

    private getCssClasses(): string {
        return ['eui-app-breadcrumb'].join(' ');
    }
}
