import { DOCUMENT } from '@angular/common';
import {
    ComponentRef,
    Directive,
    ElementRef,
    HostBinding,
    OnDestroy,
    OnInit,
    Renderer2,
    ViewContainerRef,
    inject,
    input,
} from '@angular/core';
import { distinctUntilChanged, map, takeUntil, tap } from 'rxjs/operators';
import { fromEvent, Subject } from 'rxjs';

import { EuiResizableComponent } from './eui-resizable.component';

export type EuiResizablePosition = 'left' | 'right';

@Directive({
    selector: '[euiResizable]',
})
export class EuiResizableDirective implements OnInit, OnDestroy {
    /**
     * This is used to determine the placement of the resizable handle and the resizing behavior.
     * Possible values are 'left' or 'right'. Default is 'right'.
     */
    euiResizablePosition = input<EuiResizablePosition>('right');
    @HostBinding('style.width.px') styleWidth: number;
    @HostBinding('style.min-width.px') styleMinWidth: number;
    @HostBinding('style.max-width.px') styleMaxWidth: number;
    @HostBinding('style.flex-basis.px') styleFlexBasisWidth: number;

    private _resizableBar: ComponentRef<EuiResizableComponent>;
    private destroy$ = new Subject<boolean>();
    private _documentRef = inject<Document>(DOCUMENT);
    private _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
    private _renderer = inject(Renderer2);
    private _viewContainerRef = inject(ViewContainerRef);

    ngOnInit(): void {
        this._createResizableBar();
        fromEvent<MouseEvent>(this._elementRef.nativeElement.querySelector('.eui-resizable-bar'), 'mousedown').pipe(
            tap((e) => e.preventDefault()),     // Disallow selecting text when dragging for resize
            takeUntil(this.destroy$),
            )
            .subscribe((e) => {
                // Only left button
                if (e.button === 0) {
                    const { width, right, left } = this._elementRef.nativeElement.getBoundingClientRect();

                    fromEvent<MouseEvent>(this._documentRef, 'mousemove').pipe(
                        map(({ clientX }) => {
                            if (this.euiResizablePosition() === 'right') {
                                return width + clientX - right;
                            } else {
                                return width + (left - clientX);
                            }
                        }),
                        distinctUntilChanged(),
                        takeUntil(fromEvent(this._documentRef, 'mouseup')))
                        .subscribe( (size) => {
                            const roundedSize = Math.round(size);
                            this.styleWidth = roundedSize;
                            this.styleMinWidth = roundedSize;
                            this.styleMaxWidth = roundedSize;
                            this.styleFlexBasisWidth = roundedSize;
                        })
                }
            })
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    private _createResizableBar(): void {
        if (!this._resizableBar) {
            this._resizableBar = this._viewContainerRef.createComponent(EuiResizableComponent);
            this._resizableBar.setInput('position', this.euiResizablePosition());
            this._renderer.appendChild(this._elementRef.nativeElement, this._resizableBar.location.nativeElement);
        }
    }
}
