import { Component, HostBinding, ViewEncapsulation, OnInit, ElementRef, inject } from '@angular/core';
import { EuiAppShellService } from '@eui/core';

@Component({
    selector: 'eui-header-app-subtitle',
    template: '<ng-content />',
    encapsulation: ViewEncapsulation.None,
})
export class EuiHeaderAppSubtitleComponent implements OnInit {
    @HostBinding('class') string = 'eui-header-app-subtitle';
    protected asService = inject(EuiAppShellService);
    private elRef = inject(ElementRef);

    ngOnInit(): void {
        this.asService?.setState({
            ...this.asService.state,
            appSubTitle: this.elRef.nativeElement.innerHTML,
        });
    }
}
