import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    Input,
    ViewChild,
    ElementRef,
    AfterViewInit,
    ChangeDetectorRef,
    booleanAttribute,
    inject,
} from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';
import { ObserversModule } from '@angular/cdk/observers';

/**
 * @description
 * A badge component that can display text, numbers, or icons with various states and styles.
 * Supports content truncation, empty states, and icon-only modes.
 *
 */
@Component({
    selector: 'div[euiBadge], span[euiBadge], eui-badge',
    templateUrl: './eui-badge.component.html',
    styleUrl: './eui-badge.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ObserversModule],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiVariant',
                'euiSizeS',
                'euiSizeM',
                'euiSizeVariant',
                'euiOutline',
            ],
        },
    ],
})
export class EuiBadgeComponent implements AfterViewInit {
    /**
     * @description
     * Computes and returns the CSS classes for the badge based on its current state
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-badge'),
            !this.hasContent ? 'eui-badge--empty' : '',
            this.euiIconBadge ? 'eui-badge--icon-only' : '',
        ].join(' ').trim();
    }

    /** @description Data attribute for e2e testing */
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-badge';

    /** @description ARIA role for accessibility */
    @HostBinding('attr.role') role = 'status';

    /** @description ARIA label for accessibility */
    @HostBinding('attr.aria-label') @Input('aria-label') ariaLabel: string | null = 'badge';

    /**
     * @description Maximum number of characters to display before truncating
     */
    @Input() maxCharCount: number;

    /**
     * @description String to display when content is truncated
     */
    @Input() charReplacement: string;

    /**
     * @description Whether the badge contains only an icon
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiIconBadge = false;

    /**
     * @description Whether to display the badge as a dot
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiDottedBadge = false;

    /** @description Reference to the content element */
    @ViewChild('contentRef') content: ElementRef;

    /** @description Tracks if content has been updated due to truncation */
    protected hasContentUpdated = false;

    /** @description Updated content after truncation when hasContentUpdated is true */
    protected updatedContent: string;

    /** @description Instance of BaseStatesDirective for managing component states */
    protected baseStatesDirective = inject(BaseStatesDirective);

    /** @description Change detector reference for manual change detection */
    private cdRef = inject(ChangeDetectorRef);

    /** @description Tracks whether the badge has any content */
    private hasContent = true;

    /**
     * @description
     * After view initialization, checks if the badge has content and handles content truncation
     */
    ngAfterViewInit(): void {
        setTimeout(() => {
            const innerHtml = this.content.nativeElement.innerHTML;
            if (!innerHtml || (innerHtml && innerHtml.trim() === '')) {
                this.hasContent = false;
            }
            this._checkContent();
        }, 1);
    }

    /**
     * @description
     * Handles content changes and triggers content checking
     */
    onContentChanged(): void {
        this._checkContent();
    }

    /**
     * @description
     * Checks if content exceeds maxCharCount and updates content if necessary
     * @private
     */
    private _checkContent(): void {
        if (this.maxCharCount) {
            const contentText = this.content.nativeElement.outerText;
            if (contentText && contentText.length > this.maxCharCount) {
                this.hasContentUpdated = true;
                this.updatedContent = this.charReplacement || '99+';
                this.cdRef.markForCheck();
            }
        }
    }
}
