import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    OnInit,
    Input,
    OnChanges,
    ContentChild,
    forwardRef,
    SimpleChanges,
    OnDestroy,
    inject,
} from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { Subscription } from 'rxjs';
import { EuiHeaderAppNameComponent } from './header-app-name.component';
import { EuiHeaderAppSubtitleComponent } from './header-app-subtitle.component';
import { EuiHeaderAppNameLogoComponent } from './header-app-name-logo.component';

@Component({
    selector: 'eui-header-app',
    templateUrl: './header-app.component.html',
    styleUrl: './header-app.component.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiHeaderAppComponent implements OnInit, OnChanges, OnDestroy {
    @HostBinding('class') cssClass = 'eui-header-app';

    @Input() appName = '';
    @Input() appShortName = '';
    @Input() appSubTitle = '';

    @ContentChild(forwardRef(() => EuiHeaderAppNameComponent))
    customAppName: EuiHeaderAppNameComponent;
    @ContentChild(forwardRef(() => EuiHeaderAppSubtitleComponent))
    customAppSubtitle: EuiHeaderAppSubtitleComponent;
    @ContentChild(forwardRef(() => EuiHeaderAppNameLogoComponent))
    customAppNameLogo: EuiHeaderAppNameLogoComponent;

    protected asService = inject(EuiAppShellService);
    private subscriptions: Subscription[] = [];

    ngOnInit(): void {
        if (this.asService) {
            this.subscriptions.push(this.asService.getState('appName').subscribe((s: string) => (this.appName = s)));
            this.subscriptions.push(this.asService.getState('appShortName').subscribe((s: string) => (this.appShortName = s)));
            this.subscriptions.push(this.asService.getState('appSubTitle').subscribe((s: string) => (this.appSubTitle = s)));
        }
    }

    ngOnDestroy(): void {
        this.subscriptions.forEach((s) => s.unsubscribe());
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.appName) {
            this.asService?.setState({
                ...this.asService.state,
                appName: changes.appName.currentValue,
            });
        }
        if (changes.appShortName) {
            let shortName = changes.appShortName.currentValue;
            shortName = shortName === '' ? this.appName : shortName;
            this.asService?.setState({
                ...this.asService.state,
                appShortName: shortName,
            });
        }
        if (changes.appSubTitle) {
            this.asService?.setState({
                ...this.asService.state,
                appSubTitle: changes.appSubTitle.currentValue,
            });
        }
    }
}

