import { Directive, HostBinding, Input, booleanAttribute } from '@angular/core';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';

@Directive({
    selector: '[euiBase]',
})
export class BaseStatesDirective {
    @HostBinding('attr.aria-disabled')
    get ariaDisabled(): boolean {
        return this.euiDisabled ? true : null;
    }
    // COLORS
    @Input()
    public get euiPrimary(): boolean {
        return this._euiPrimary;
    }
    public set euiPrimary(value: BooleanInput) {
        this._euiPrimary = coerceBooleanProperty(value);
        this._euiVariant = this._euiPrimary? 'primary': '';
    }
    @Input()
    public get euiBranding(): boolean {
        return this._euiBranding;
    }
    public set euiBranding(value: BooleanInput) {
        this._euiBranding = coerceBooleanProperty(value);
        this._euiVariant = this._euiBranding? 'branding': '';
    }

    @Input()
    public get euiSecondary(): boolean {
        return this._euiSecondary;
    }
    public set euiSecondary(value: BooleanInput) {
        this._euiSecondary = coerceBooleanProperty(value);
        this._euiVariant = this._euiSecondary? 'secondary': '';
    }

    @Input()
    public get euiSecondaryLight(): boolean {
        return this._euiSecondaryLight;
    }
    public set euiSecondaryLight(value: BooleanInput) {
        this._euiSecondaryLight = coerceBooleanProperty(value);
        this._euiVariant = this._euiSecondaryLight? 'secondaryLight': '';
    }

    @Input()
    public get euiInfo(): boolean {
        return this._euiInfo;
    }
    public set euiInfo(value: BooleanInput) {
        this._euiInfo = coerceBooleanProperty(value);
        this._euiVariant = this._euiInfo? 'info': '';
    }

    @Input()
    public get euiSuccess(): boolean {
        return this._euiSuccess;
    }
    public set euiSuccess(value: BooleanInput) {
        this._euiSuccess = coerceBooleanProperty(value);
        this._euiVariant = this._euiSuccess? 'success': '';
    }

    @Input()
    public get euiWarning(): boolean {
        return this._euiWarning;
    }
    public set euiWarning(value: BooleanInput) {
        this._euiWarning = coerceBooleanProperty(value);
        this._euiVariant = this._euiWarning? 'warning': '';
    }

    @Input()
    public get euiDanger(): boolean {
        return this._euiDanger;
    }
    public set euiDanger(value: BooleanInput) {
        this._euiDanger = coerceBooleanProperty(value);
        this._euiVariant = this._euiDanger? 'danger': '';
    }

    @Input()
    public get euiAccent(): boolean {
        return this._euiAccent;
    }
    public set euiAccent(value: BooleanInput) {
        this._euiAccent = coerceBooleanProperty(value);
        this._euiVariant = this._euiAccent? 'accent': '';
    }

    @Input()
    public get euiInverse(): boolean {
        return this._euiInverse;
    }
    public set euiInverse(value: BooleanInput) {
        this._euiInverse = coerceBooleanProperty(value);
        this._euiVariant = this._euiInverse? 'inverse': '';
    }

    @Input()
    get euiVariant(): string {
        return this._euiVariant;
    }
    set euiVariant(value: string) {
        this.euiPrimary = value === 'primary';
        this.euiBranding = value === 'branding';
        this.euiSecondary = value === 'secondary';
        this.euiSecondaryLight = value === 'secondaryLight';
        this.euiWarning = value === 'warning';
        this.euiInfo = value === 'info';
        this.euiSuccess = value === 'success';
        this.euiDanger = value === 'danger';
        this.euiAccent = value === 'accent';
        this.euiInverse = value === 'inverse';
        this._euiVariant = value;
    }

    // SIZES
    @Input()
    public get euiSize2XS(): boolean {
        return this._euiSize2XS;
    }
    public set euiSize2XS(value: BooleanInput) {
        this._euiSize2XS = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSize2XS? '2xs': '';
    }

    @Input()
    public get euiSizeXS(): boolean {
        return this._euiSizeXS;
    }
    public set euiSizeXS(value: BooleanInput) {
        this._euiSizeXS = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeXS? 'xs': '';
    }

    @Input()
    public get euiSizeS(): boolean {
        return this._euiSizeS;
    }
    public set euiSizeS(value: BooleanInput) {
        this._euiSizeS = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeS? 's': '';
    }

    @Input()
    public get euiSizeM(): boolean {
        return this._euiSizeM;
    }
    public set euiSizeM(value: BooleanInput) {
        this._euiSizeM = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeM? 'm': '';
    }

    @Input()
    public get euiSizeL(): boolean {
        return this._euiSizeL;
    }
    public set euiSizeL(value: BooleanInput) {
        this._euiSizeL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeL? 'l': '';
    }

    @Input()
    public get euiSizeXL(): boolean {
        return this._euiSizeXL;
    }
    public set euiSizeXL(value: BooleanInput) {
        this._euiSizeXL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeXL? 'xl': '';
    }

    @Input()
    public get euiSize2XL(): boolean {
        return this._euiSize2XL;
    }
    public set euiSize2XL(value: BooleanInput) {
        this._euiSize2XL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSize2XL? '2xl': '';
    }

    @Input()
    public get euiSize3XL(): boolean {
        return this._euiSize3XL;
    }
    public set euiSize3XL(value: BooleanInput) {
        this._euiSize3XL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSize3XL? '3xl': '';
    }

    @Input()
    public get euiSize4XL(): boolean {
        return this._euiSize4XL;
    }
    public set euiSize4XL(value: BooleanInput) {
        this._euiSize4XL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSize4XL? '4xl': '';
    }

    @Input()
    public get euiSize5XL(): boolean {
        return this._euiSize5XL;
    }
    public set euiSize5XL(value: BooleanInput) {
        this._euiSize5XL = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSize5XL? '5xl': '';
    }

    @Input()
    public get euiSizeAuto(): boolean {
        return this._euiSizeAuto;
    }
    public set euiSizeAuto(value: BooleanInput) {
        this._euiSizeAuto = coerceBooleanProperty(value);
        this._euiSizeVariant = this._euiSizeAuto? 'auto': '';
    }

    @Input()
    get euiSizeVariant(): string {
        return this._euiSizeVariant;
    }
    set euiSizeVariant(value: string) {
        this.euiSize2XS = value === '2xs';
        this.euiSizeXS = value === 'xs';
        this.euiSizeS = value === 's';
        this.euiSizeM = value === 'm';
        this.euiSizeL = value === 'l';
        this.euiSizeXL = value === 'xl';
        this.euiSize2XL = value === '2xl';
        this.euiSize3XL = value === '3xl';
        this.euiSize4XL = value === '4xl';
        this.euiSize5XL = value === '5xl';
        this.euiSizeAuto = value === 'auto';
        this._euiSizeVariant = value;
    }

    // EXTRA SHAPES
    @Input({ transform: booleanAttribute }) euiRounded = false;
    @Input({ transform: booleanAttribute }) euiOutline = false;
    @Input({ transform: booleanAttribute }) euiCompact = false;
    @Input({ transform: booleanAttribute }) euiDisabled = false;
    @Input({ transform: booleanAttribute }) euiResponsive = false;
    @Input({ transform: booleanAttribute }) euiHighlighted = false;
    @Input({ transform: booleanAttribute }) euiClearable = false;
    @Input({ transform: booleanAttribute }) euiLoading = false;
    @Input({ transform: booleanAttribute }) euiInverted = false;
    @Input({ transform: booleanAttribute }) euiStart = false;
    @Input({ transform: booleanAttribute }) euiEnd = false;

    private _euiPrimary = false;
    private _euiBranding = false;
    private _euiSecondary = false;
    private _euiSecondaryLight = false;
    private _euiInfo = false;
    private _euiSuccess = false;
    private _euiWarning = false;
    private _euiDanger = false;
    private _euiAccent = false;
    private _euiInverse = false;

    private _euiSize2XS = false;
    private _euiSizeXS = false;
    private _euiSizeS = false;
    private _euiSizeM = false;
    private _euiSizeL = false;
    private _euiSizeXL = false;
    private _euiSize2XL = false;
    private _euiSize3XL = false;
    private _euiSize4XL = false;
    private _euiSize5XL = false;
    private _euiSizeAuto = false;

    private _euiSizeVariant = '';
    private _euiVariant = '';

    getCssClasses(rootClass: string): string {
        return [
            rootClass,
            this.euiPrimary ? `${rootClass}--primary eui--primary` : '',
            this.euiBranding ? `${rootClass}--branding eui--branding` : '',
            this.euiSecondary ? `${rootClass}--secondary eui--secondary` : '',
            this.euiSecondaryLight ? `${rootClass}--secondary-light eui--secondary-light` : '',
            this.euiInfo ? `${rootClass}--info eui--info` : '',
            this.euiSuccess ? `${rootClass}--success eui--success` : '',
            this.euiWarning ? `${rootClass}--warning eui--warning` : '',
            this.euiDanger ? `${rootClass}--danger eui--danger` : '',
            this.euiAccent ? `${rootClass}--accent eui--accent` : '',
            this.euiInverse ? `${rootClass}--inverse eui--inverse` : '',
            this.euiSize2XS ? `${rootClass}--size-2xs eui--size-2xs` : '',
            this.euiSizeXS ? `${rootClass}--size-xs eui--size-xs` : '',
            this.euiSizeS ? `${rootClass}--size-s eui--size-s` : '',
            this.euiSizeM ? `${rootClass}--size-m eui--size-m` : '',
            this.euiSizeL ? `${rootClass}--size-l eui--size-l` : '',
            this.euiSizeXL ? `${rootClass}--size-xl eui-size-xl` : '',
            this.euiSize2XL ? `${rootClass}--size-2xl eui--size-2xl` : '',
            this.euiSize3XL ? `${rootClass}--size-3xl eui--size-3xl` : '',
            this.euiSize4XL ? `${rootClass}--size-4xl eui--size-4xl` : '',
            this.euiSize5XL ? `${rootClass}--size-5xl eui--size-5xl` : '',
            this.euiSizeAuto ? `${rootClass}--size-auto eui--size-auto` : '',
            this.euiRounded ? `${rootClass}--rounded eui--rounded` : '',
            this.euiOutline ? `${rootClass}--outline eui--outline` : '',
            this.euiDisabled ? `${rootClass}--disabled eui--disabled disabled` : '',
            this.euiCompact ? `${rootClass}--compact eui--compact` : '',
            this.euiResponsive ? `${rootClass}--responsive` : '',
            this.euiHighlighted ? `${rootClass}--highlighted` : '',
            this.euiClearable ? `${rootClass}--clearable` : '',
            this.euiLoading ? `${rootClass}--loading` : '',
            this.euiInverted ? `${rootClass}--inverted` : '',
            this.euiStart ? `${rootClass}--start` : '',
            this.euiEnd ? `${rootClass}--end` : '',
        ]
            .filter(c => c !== '')
            .join(' ')
            .trim();
    }
}
