import { Component, HostBinding, ViewEncapsulation, Input, ChangeDetectionStrategy } from '@angular/core';

@Component({
    selector: 'eui-page-hero-header',
    templateUrl: './eui-page-hero-header.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
})
export class EuiPageHeroHeaderComponent {
    @Input() label;
    @Input() subLabel;

    @HostBinding('class')
    get cssClasses(): string {
        return ['eui-page-hero-header'].join(' ').trim();
    }
}
