import { Action } from '../ngrx_kit';
import { I18nState, initialI18nState } from '@eui/base';
import { CoreI18nActionTypes, CoreI18nActions, UpdateI18nStateAction } from '../actions';

/**
 * @deprecated it will be removed in the next major version
 */
const updateI18nState = (state: I18nState, action: UpdateI18nStateAction): {activeLang: string} => ({
    ...state,
    ...action.payload,
});

/**
 * @deprecated it will be removed in the next major version
 */
const actionToReducerMap: { [key: string]: (state: I18nState, action: CoreI18nActions) => I18nState } = {
    [CoreI18nActionTypes.UPDATE_I18N_STATE]: updateI18nState,
};

/**
 * @deprecated it will be removed in the next major version
 */
export const corI18nReducers: (state: I18nState, action: Action) => I18nState = (state = initialI18nState, action: CoreI18nActions) => {
    if (actionToReducerMap[action.type]) {
        return actionToReducerMap[action.type](state, action);
    }
    return state;
};
