import { Component, HostBinding, Input, inject } from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_ICON } from '@eui/components/eui-icon';

@Component({
    selector: 'eui-icon-state',
    templateUrl: './eui-icon-state.component.html',
    styleUrl: './eui-icon-state.component.scss',
    imports: [
        ...EUI_ICON,
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiVariant',
            ],
        },
    ],
})
export class EuiIconStateComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-icon-state'),
            'eui-icon-state--info',
        ].join(' ').trim();
    }

    @Input() size: '2xs' | 'xs' | 's' | 'm' | 'l' | 'xl' | '2xl' | '3xl' | '4xl' = 'm';
    @Input() ariaLabel: string;
    baseStatesDirective = inject(BaseStatesDirective);
}
