import {
    NgModule,
    Component,
    HostBinding,
    HostListener,
    Input,
    Output,
    EventEmitter,
    ChangeDetectionStrategy,
    Renderer2,
    ElementRef,
    booleanAttribute,
    inject,
} from '@angular/core';

import { BaseStatesDirective } from '@eui/components/shared';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';

/**
 * @description
 * A versatile button component that supports various states, sizes, and visual styles.
 * Can be used as either a button or anchor element with consistent styling.
 */
@Component({
    templateUrl: './eui-button.component.html',
    // eslint-disable-next-line
    selector: 'button[euiButton], a[euiButton]',
    styleUrl: './eui-button.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiBranding',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiInverse',
                'euiVariant',
                'euiSizeS',
                'euiSizeM',
                'euiSizeL',
                'euiSizeVariant',
                'euiOutline',
                'euiRounded',
                'euiResponsive',
                'euiStart',
                'euiEnd',
            ],
        },
    ],
})
export class EuiButtonComponent {
    /**
     * @description
     * Computes and returns the CSS classes for the button based on its current state
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-button'),
            this.euiBasicButton ? 'eui-button--basic eui--basic' : '',
            this.euiBlockButton ? 'eui-button--block' : '',
            this.euiIconButton ? 'eui-button--icon-only' : '',
            this.euiLineWrap ? 'eui-button--line-wrap' : '',
            this.hasNoFocusRing ? 'eui-button--no-focus-ring': '',
            this.isCompact ? 'eui-button--compact': '',
            this.euiCTAButton ? 'eui-button--cta': '',
            this.euiAvatarButton ? 'eui-button--avatar': '',
        ]
            .join(' ')
            .trim();
    }

    /**
     * @description Data attribute for e2e testing
     * @default eui-button
     */
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-button';

    /** @description ID attribute for the button element */
    @HostBinding('attr.id')
    @Input() id: string;

    /**
     * @description When true, applies basic styling without background
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiBasicButton = false;

    /**
     * @description When true, styles the button as a call-to-action
     * @deprecated will be removed in future eUI version and replaced by euiCTAButton
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiButtonCall = false;

    /**
     * @description When true, styles the button as a call-to-action
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiCTAButton = false;

    /**
     * @description When true, makes the button full-width
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiBlockButton = false;

    /**
     * @description When true, styles the button for icon-only content
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiIconButton = false;

    /**
     * @description When true, style the button when used in avatar trigger (for dropdown trigger f.e. see actionable avatar)
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiAvatarButton = false;

    /**
     * @description When true, allows text content to wrap
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiLineWrap = false;

    /**
     * @description When true, applies styling with lower padding / reduced height and width
     * @default false
     */
    @Input({ transform: booleanAttribute }) isCompact = false;   
    
    /**
     * @description When true, applies styling without focus ring
     * @default false
     */
    @Input({ transform: booleanAttribute }) hasNoFocusRing = false;    

    /**
     * @description
     * Controls the checked state of the button
     * When true, applies accent styling
     */
    @Input()
    public get isChecked(): boolean {
        return this._isChecked;
    }
    public set isChecked(value: BooleanInput) {
        this.baseStatesDirective.euiAccent = coerceBooleanProperty(value);
        this._isChecked = coerceBooleanProperty(value);
    }

    /**
     * @description
     * Controls the disabled state of the button
     * When true, adds the disabled attribute and prevents interaction
     */
    @Input()
    public get euiDisabled(): boolean {
        return this._euiDisabled;
    }
    public set euiDisabled(value: BooleanInput) {
        this._euiDisabled = coerceBooleanProperty(value);
        if (this._euiDisabled) {
            this._renderer.setAttribute(this._elementRef.nativeElement, 'disabled', 'true');
        } else {
            this._renderer.removeAttribute(this._elementRef.nativeElement, 'disabled');
        }
    }

    /**
     * @description
     * Event emitted when the button is clicked
     * Emits the button component instance
     */
    @Output() buttonClick: EventEmitter<EuiButtonComponent> = new EventEmitter<EuiButtonComponent>();

    public baseStatesDirective: BaseStatesDirective = inject(BaseStatesDirective);
    protected _renderer: Renderer2 = inject(Renderer2);
    protected _elementRef: ElementRef<HTMLButtonElement> = inject(ElementRef);
    private _isChecked = false;
    private _euiDisabled = false;

    /**
     * @description
     * Click event handler that emits the buttonClick event
     * @private
     */
    @HostListener('click')
    protected onClick(): void {
        this.buttonClick.emit(this);
    }
}

/**
 * @description
 * Module that provides the EuiButton component.
 *
 * @deprecated Use {@link EUI_BUTTON} instead
 */
@NgModule({
    imports: [EuiButtonComponent],
    exports: [EuiButtonComponent],
})
export class EuiButtonModule {}
