import {
    AfterViewInit,
    booleanAttribute,
    ComponentRef,
    Directive,
    ElementRef,
    HostBinding,
    HostListener,
    Injector,
    Input,
    OnChanges,
    Renderer2,
    SimpleChanges,
    ViewContainerRef,
    inject,
} from '@angular/core';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';
import { NgControl, NgModel } from '@angular/forms';
import { EuiIconSvgComponent } from '@eui/components/eui-icon';
import { EuiLoadingDirective } from './eui-loading.directive';

@Directive({
    selector: 'input[euiClearable]',
})
export class EuiClearableDirective implements OnChanges, AfterViewInit {
    @Input({ transform: booleanAttribute }) euiClearable: boolean;

    @HostBinding('attr.readonly')
    @Input()
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    get readonly(): any {
        return this._isReadonly ? '' : null;
    }
    set readonly(v: BooleanInput) {
        this._isReadonly = coerceBooleanProperty(v);
    }

    @HostBinding('disabled')
    @Input()
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    get disabled(): any {
        return this._disabled ? '' : null;
    }
    set disabled(v: BooleanInput) {
        this._disabled = coerceBooleanProperty(v);
    }

    @HostBinding('class')
    public get cssClasses(): string {
        return [this._cssClasses, this.euiClearable ? `${this._elementRef.nativeElement.rootClassName}--clearable` : ''].join(' ').trim();
    }
    public set cssClasses(value: string) {
        this._cssClasses = value;
    }
    private _cssClasses: string;

    protected _clearableIcon: ComponentRef<EuiIconSvgComponent>;
    private _euiUFlexWrapper: HTMLDivElement;
    private _isReadonly: boolean;
    private _disabled: boolean;
    private _elementRef = inject(ElementRef);
    private _viewContainerRef = inject(ViewContainerRef);
    private _renderer = inject(Renderer2);
    private injector = inject(Injector);

    ngAfterViewInit(): void {
        if (this._clearableIcon) {
            const control = this.injector.get(NgControl, null, { optional: true });
            const value = control
                ? control instanceof NgModel
                    ? control.model?.toString()
                    : control.value?.toString()
                : this._elementRef.nativeElement.value;
            this._renderer.setStyle(this._clearableIcon.location.nativeElement, 'visibility', value?.length > 0 ? 'visible' : 'hidden');
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.euiClearable) {
            // get a type of the control
            const type = this._elementRef.nativeElement.type;
            if (coerceBooleanProperty(changes['euiClearable'].currentValue)) {
                // check if the type is not euiInputNumber or euiInputText, reset and throw error
                if (type !== 'eui-number' && type !== 'text' && type !== 'search') {
                    this.euiClearable = true;
                    throw new Error('euiClearable is only allowed in euiInputNumber or euiInputText');
                }
                // dynamically create the icon
                this.createClearableIcon();

                // wrap them all in an eui-u-flex class
                this.createFlexWrapper();
                this._renderer.appendChild(this._euiUFlexWrapper, this._clearableIcon.location.nativeElement);
            } else if (this._clearableIcon) {
                this.removeClearableIcon();
                const euiLoading = this.injector.get(EuiLoadingDirective, null, { optional: true })?.euiLoading;
                if (!euiLoading) {
                    this.removeFlexWrapper();
                }
            }
        }

        if (changes['readonly']) {
            if (changes['readonly'].currentValue === false && this.euiClearable) {
                // create wrapper
                this.createFlexWrapper();
                // dynamically create the icon
                this.createClearableIcon();
                this._renderer.appendChild(this._euiUFlexWrapper, this._clearableIcon.location.nativeElement);
            }
            if (changes['readonly'].currentValue === true) {
                this.removeClearableIcon();
                this.removeFlexWrapper();
            }
        }

        if (changes['disabled']) {
            if (this._clearableIcon) {
                const disabled = changes['disabled']?.currentValue;
                if (disabled) {
                    this._renderer.setStyle(this._clearableIcon.location.nativeElement, 'pointer-events', 'none');
                    this._renderer.removeAttribute(this._clearableIcon.location.nativeElement, 'tabindex');
                } else {
                    this._renderer.removeStyle(this._clearableIcon.location.nativeElement, 'pointer-events');
                    this._renderer.setAttribute(this._clearableIcon.location.nativeElement, 'tabindex', '0');
                }
            }
        }
    }

    @HostListener('input', ['$event.target.value'])
    @HostListener('ngModelChange', ['$event'])
    private onKeyUpAndModelChange(value): void {
        if (this.euiClearable) {
            const visibility = value?.toString().length > 0 ? 'visible' : 'hidden';
            this._renderer.setStyle(this._clearableIcon.location.nativeElement, 'visibility', visibility);
        }
    }

    private onClearableClicked(): void {
        if (this._elementRef.nativeElement.disabled) {
            return;
        }
        const control = this.injector.get(NgControl, undefined, { optional: true });
        if (control) {
            control.reset();
        } else {
            const inputEvent = new InputEvent('input', { data: null });
            this._elementRef.nativeElement.value = null;
            this._elementRef.nativeElement.dispatchEvent(inputEvent);
        }
        const clearEvent = new InputEvent('clear');
        this._elementRef.nativeElement.dispatchEvent(clearEvent);
        this._elementRef.nativeElement.focus();
    }

    /**
     * creates the Clearable icon component
     *
     * @private
     */
    private createClearableIcon(): void {
        if (!this._clearableIcon) {
            // TODO: turn import of EuiIconSvgComponent into a type?
            this._clearableIcon = this._viewContainerRef.createComponent(EuiIconSvgComponent);
            this._clearableIcon.instance.set = 'eui';
            this._clearableIcon.instance.icon = 'eui-close';
            this._clearableIcon.instance.ariaLabel = 'Clear input field';
            this._renderer.addClass(this._clearableIcon.location.nativeElement, 'eui-input-text--clearable-icon');
            this._renderer.listen(this._clearableIcon.location.nativeElement, 'click', this.onClearableClicked.bind(this));
            this._renderer.listen(this._clearableIcon.location.nativeElement, 'keydown.enter', this.onClearableClicked.bind(this));
            const control = this.injector.get(NgControl, null, { optional: true });
            const value = control
                ? control instanceof NgModel
                    ? control.model?.toString()
                    : control.value?.toString()
                : this._elementRef.nativeElement.value;
            this._renderer.setStyle(this._clearableIcon.location.nativeElement, 'visibility', value?.length > 0 ? 'visible' : 'hidden');
            if (!this._elementRef.nativeElement.disabled) {
                this._renderer.setAttribute(this._clearableIcon.location.nativeElement, 'tabindex', '0');
            } else {
                this._renderer.setStyle(this._clearableIcon.location.nativeElement, 'pointer-events', 'none');
            }
        }
    }

    /**
     * detach the Clearable icon from the view
     *
     * @private
     */
    private removeClearableIcon(): void {
        if (this._clearableIcon) {
            const index = this._viewContainerRef.indexOf(this._clearableIcon.hostView);
            this._viewContainerRef.detach(index);
            this._clearableIcon = null;
        }
    }

    /**
     * create a flex wrapper for the input to hold the icon
     *
     * @private
     */
    private createFlexWrapper(): void {
        if (!this._euiUFlexWrapper && !this.doesParentHasAFlexWrapper()) {
            this._euiUFlexWrapper = this._renderer.createElement('div');
            this._renderer.addClass(this._euiUFlexWrapper, 'eui-u-flex');
            this._renderer.addClass(this._euiUFlexWrapper, 'eui-u-p-relative');
            this._renderer.setAttribute(this._euiUFlexWrapper, 'flexWrapper', null);
            this._renderer.insertBefore(
                this._elementRef.nativeElement.parentElement,
                this._euiUFlexWrapper,
                this._elementRef.nativeElement,
            );
            this._renderer.appendChild(this._euiUFlexWrapper, this._elementRef.nativeElement);
        }
        if (!this._euiUFlexWrapper && this.doesParentHasAFlexWrapper()) {
            this._euiUFlexWrapper = this._elementRef.nativeElement.parentElement;
        }
    }

    /**
     * checks if the parent has a flexWrapper. This is used to avoid creating multiple flexWrappers
     *
     * @private
     */
    private doesParentHasAFlexWrapper(): boolean {
        return this._elementRef.nativeElement.parentElement.hasAttribute('flexWrapper');
    }

    /**
     * removes the flexWrapper while keeping the input element intact
     *
     * @private
     */
    private removeFlexWrapper(): void {
        if (this._euiUFlexWrapper) {
            this._renderer.insertBefore(this._euiUFlexWrapper.parentElement, this._elementRef.nativeElement, this._euiUFlexWrapper);
            this._renderer.removeChild(this._euiUFlexWrapper.parentElement, this._euiUFlexWrapper);
            this._euiUFlexWrapper.remove();
            this._euiUFlexWrapper = null;
        }
    }
}
