import { Component, ViewEncapsulation, ChangeDetectionStrategy, OnInit, inject } from '@angular/core';
import { EuiEuLanguages, EuiLanguage } from '@eui/core';

import { DIALOG_COMPONENT_CONFIG } from '@eui/components/eui-dialog';
import { EuiDialogService } from '@eui/components/eui-dialog';
import { EUI_BUTTON } from '@eui/components/eui-button';

export interface ModelConfig {
    /**
     * Available languages to select from
     */
    languages: EuiLanguage[];
    /**
     * Currently selected language
     */
    selectedLanguage: EuiLanguage;
    /**
     * Callback when language selection changes
     * @param language
     */
    languageChanged: (language: EuiLanguage) => void;
}

/**
 * Modal component for language selection.
 * Displays EU and non-EU languages in a grid layout with 4 languages per row.
 */
@Component({
    selector: 'eui-modal-selector',
    templateUrl: './modal-selector.component.html',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_BUTTON,
    ],
})
export class EuiModalSelectorComponent implements OnInit {
    /**
     * Configuration injected from the dialog service
     */
    config = inject<ModelConfig>(DIALOG_COMPONENT_CONFIG, { optional: true });

    /** EU languages organized in rows of up to 4 languages */
    public languageRows: EuiLanguage[][] = [];
    /**
     * Non-EU languages organized in rows of up to 4 languages
     * @deprecated use {@link additionalLanguageRows}
     */
    public additionaLanguageRows: EuiLanguage[][] = [];
    /** Non-EU languages organized in rows of up to 4 languages */
    public additionalLanguageRows: EuiLanguage[][] = [];
    /** Currently selected language */
    private selectedLanguage: EuiLanguage;
    /** Dialog service for handling modal operations */
    private euiDialogService = inject<EuiDialogService>(EuiDialogService);

    /**
     * Initializes language rows by separating EU and non-EU languages
     */
    ngOnInit(): void {
        this.languageRows = this.prepareLanguageRows(EuiEuLanguages.filterEULanguages(this.config?.languages));
        this.additionalLanguageRows = this.prepareLanguageRows(EuiEuLanguages.filterNonEULanguages(this.config?.languages));
        this.additionaLanguageRows = this.additionalLanguageRows;
    }

    /**
     * Handles language selection
     * @param {EuiLanguage} languageCode - The language being selected
     */
    selectLanguage(languageCode: EuiLanguage): void {
        if (this.selectedLanguage?.code !== languageCode.code) {
            for (const language of this.config?.languages || []) {
                if (language.code === languageCode.code) {
                    this.selectedLanguage = language;
                    break;
                }
            }
        }

        this.config?.languageChanged(languageCode);
        this.euiDialogService.closeDialog();
    }

    /**
     * Organizes languages into rows of up to 4 languages each
     * @param {EuiLanguage[]} languages - Array of languages to organize
     * @returns {EuiLanguage[][]} 2D array of languages organized in rows
     */
    private prepareLanguageRows(languages: EuiLanguage[]): EuiLanguage[][] {
        // If no languages, return an empty array
        if (!languages.length) return [];

        return languages.reduce<EuiLanguage[][]>((rows, language, index) => {
            // Calculate current row index
            const rowIndex = Math.floor(index / 4);

            // If we need to create a new row
            if (!rows[rowIndex]) {
                rows[rowIndex] = [];
            }

            // Add language to the current row
            rows[rowIndex].push(language);
            return rows;
        }, []);
    }
}
