import { Component, ChangeDetectionStrategy, HostBinding, ViewEncapsulation, Input, HostListener, OnInit, inject } from '@angular/core';
import { Router } from '@angular/router';
import { EUI_CONFIG_TOKEN, EuiConfig } from '@eui/core';

@Component({
    selector: 'eui-toolbar-logo',
    templateUrl: './toolbar-logo.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
})
export class EuiToolbarLogoComponent implements OnInit {
    @HostBinding() class = 'eui-toolbar-logo';

    @Input() homeUrl = '..';
    @Input() logoUrl: string;
    @Input() logoHeight = '36px'
    @Input() logoWidth = '53px';

    protected logoUrlGenerated;
    protected logoStyle;
    private router = inject(Router);
    private config = inject<EuiConfig>(EUI_CONFIG_TOKEN, { optional: true })!;

    @HostListener('click')
    onClick(): void {
        this.router.navigate([this.homeUrl]);
    }

    ngOnInit(): void {
        let assetsBaseUrl = this.config?.appConfig?.global?.eui?.assetsBaseUrl;
        if (!assetsBaseUrl) {
            assetsBaseUrl = 'assets';
        }

        if (!this.logoUrl) {
            this.logoUrlGenerated = `${assetsBaseUrl}/images/ec-europa/logos/europa-flag-small.png`;
        } else {
            this.logoUrlGenerated = this.logoUrl;
        }

        this.logoStyle = `width:${this.logoWidth}; height:${this.logoHeight};`;
    }
}
