import {
    Component,
    ContentChildren,
    ChangeDetectionStrategy,
    HostBinding,
    Input,
    Output,
    EventEmitter,
    TemplateRef,
    AfterViewInit,
    QueryList,
    booleanAttribute,
    AfterContentInit,
    inject,
} from '@angular/core';
import { EUI_AUTOCOMPLETE, EuiAutoCompleteItem } from '@eui/components/eui-autocomplete';

import { EuiTemplateDirective } from '@eui/components/directives';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_INPUT } from '@eui/components/eui-icon-input';
import { AsyncPipe, NgTemplateOutlet } from '@angular/common';
import { EUI_INPUT_TEXT } from '@eui/components/eui-input-text';
import { FormsModule } from '@angular/forms';
import { EuiAppShellService } from '@eui/core';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';

@Component({
    selector: 'eui-toolbar-search',
    templateUrl: './toolbar-search.component.html',
    styleUrl: './toolbar-search.component.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        ...EUI_BUTTON,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
        ...EUI_AUTOCOMPLETE,
        ...EUI_ICON_INPUT,
        ...EUI_INPUT_TEXT,
        EuiTemplateDirective,
        NgTemplateOutlet,
        FormsModule,
        AsyncPipe,
    ],
})
export class EuiToolbarSearchComponent implements AfterViewInit, AfterContentInit {
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            'eui-toolbar-search',
            this.isInputFocus ? 'eui-toolbar-search--focus' : '',
            !this.hasExpandAnimation ? 'eui-toolbar-search--no-animation': '',
        ]
            .join(' ')
            .trim();
    }

    isInputFocus = false;
    searchTerm: string;
    searchInput = '';

    public resultItemTemplate: TemplateRef<{ $implicit: EuiAutoCompleteItem }>;

    @Input() placeholderLabel: string;
    @Input() panelWidth = '25vw';
    @Input() searchResults: EuiAutoCompleteItem[] = [];

    @Input({ transform: booleanAttribute }) isAutocomplete = false;
    @Input({ transform: booleanAttribute }) isInputText = false;
    @Input({ transform: booleanAttribute }) hasSearchButton = false;
    @Input({ transform: booleanAttribute }) hasExpandAnimation = true;

    // eslint-disable-next-line @angular-eslint/no-output-native
    @Output() search: EventEmitter<string> = new EventEmitter();
    @Output() selectionChange: EventEmitter<EuiAutoCompleteItem[]> = new EventEmitter();
    @Output() searchClick: EventEmitter<string> = new EventEmitter();
    @Output() inputFocus: EventEmitter<Event> = new EventEmitter();
    @Output() inputBlur: EventEmitter<Event> = new EventEmitter();

    @ContentChildren(EuiTemplateDirective) templates: QueryList<EuiTemplateDirective>;
    protected asService = inject(EuiAppShellService);

    ngAfterContentInit(): void {
        if (this.isAutocomplete) {
            this.isInputText = false;
        }

        if (this.isInputText) {
            this.isAutocomplete = false;
        }

        if (!this.isInputText && !this.isAutocomplete) {
            this.isAutocomplete = true;
        }
    }

    ngAfterViewInit(): void {
        this.templates.forEach((item) => {
            if (item.getType() === 'resultItemTemplate') {
                this.resultItemTemplate = item.template;
            }
        });
    }

    onSelectionChange(items: EuiAutoCompleteItem[]): void {
        this.selectionChange.emit(items);
    }

    onInputFocus(event: Event): void {
        this.inputFocus.emit(event);
        this.isInputFocus = true;
    }

    onInputBlur(event: Event): void {
        if (!this.hasSearchButton || (this.hasSearchButton && this.searchInput === '')) {
            this.inputBlur.emit(event);
            this.isInputFocus = false;
        }
    }

    onSearch(e: string): void {
        this.searchTerm = e;
        this.search.emit(e);
    }

    onSearchInput(e: KeyboardEvent): void {
        if (e.code === 'Enter' || e.code === 'NumpadEnter') {
            this.searchTerm = this.searchInput;
            this.search.emit(this.searchInput);
        }
    }

    onSearchClick(isIconOnly: boolean): void {
        if (isIconOnly) {
            this.searchClick.emit(null);
        } else {
            this.isInputFocus = false;
            if (this.searchInput) {
                this.searchClick.emit(this.searchInput);
            }
        }
    }
}
