import { createSelector, Selector } from 'reselect';
import { UserDetails, UserPreferences } from '../models/user.models';
import { CoreState, EuiUserRight } from '../../../eui-models';
import { getUserState } from './core.selectors';
import { UserState } from '../state/user.state';

export const getUserDetails: Selector<CoreState, UserDetails> = createSelector(getUserState, (state: UserState) => state as UserDetails);
export const getUserPreferences: Selector<CoreState, UserPreferences> = createSelector(
    getUserState,
    (state: UserState) => state.preferences,
);

export const getUserId: Selector<CoreState, string> = createSelector(getUserDetails, (state: UserDetails) => state.userId);
export const getUserFirstName: Selector<CoreState, string> = createSelector(getUserDetails, (state: UserDetails) => state.firstName);
export const getUserLastName: Selector<CoreState, string> = createSelector(getUserDetails, (state: UserDetails) => state.lastName);
export const getUserFullName: Selector<CoreState, string> = createSelector(getUserDetails, (state: UserDetails) => state.fullName);

export const getUserLang: Selector<UserPreferences, string> = createSelector(getUserPreferences, (state: UserPreferences) => state.lang);

export const getUserRights: Selector<CoreState, EuiUserRight[]> = createSelector(getUserState, (state: UserState) => state.rights);
export const getUserRight = (rightId: string): Selector<CoreState, EuiUserRight> =>
    createSelector(getUserRights, (state: EuiUserRight[]) => state.find((right) => right && right.id === rightId));
export const getUserRightPermissions = (rightId: string): Selector<CoreState, string[]> =>
    createSelector(getUserRight(rightId), (state: EuiUserRight) => state && state.permissions);

export const getUserDashboard: Selector<UserPreferences<unknown>, unknown> = createSelector(
    getUserPreferences,
    (state: UserPreferences) => state.dashboard,
);
