import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    OnInit,
    HostListener,
    OnDestroy,
    inject,
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { Subscription } from 'rxjs';
import { filter } from 'rxjs/operators';
import { EuiAppShellService } from '@eui/core';
import { CssUtils } from '@eui/core';

@Component({
    selector: 'eui-app-sidebar',
    templateUrl: './sidebar.component.html',
    styleUrls: ['./_styles/_index.scss'],
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiAppSidebarComponent implements OnInit, OnDestroy {
    @HostBinding('class') string = 'eui-app-sidebar';

    asService = inject(EuiAppShellService, { optional: true })!;
    private subscriptions: Subscription[] = [];
    private document = inject<Document>(DOCUMENT);

    @HostListener('body:click')
    close(): void {
        if (
            this.asService &&
            (this.asService.state.breakpoints.isMobile || this.asService.state.breakpoints.isTablet || this.asService.state.isSidebarHidden)
        ) {
            this.asService.isSidebarOpen = false;
        }
    }

    ngOnInit(): void {
        this.asService?.activateSidebar();
        this.subscriptions.push(
            this.asService
                ?.getState('breakpoints.isMobile')
                .pipe(filter((s) => s === true))
                .subscribe(() => (this.asService.isSidebarOpen = false)),
        );
        this.subscriptions.push(
            this.asService
                ?.getState('breakpoints.isTablet')
                .pipe(filter((s) => s === true))
                .subscribe(() => (this.asService.isSidebarOpen = false)),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.forEach((s) => s.unsubscribe());
        this.asService?.setState({
            ...this.asService.state,
            hasSidebar: false,
        });
        CssUtils.removeSidebarCssVars(this.document);
    }
}
