import { Component, Inject, OnInit, OnDestroy } from '@angular/core';
import { RouterLink } from '@angular/router';
import { CONFIG_TOKEN, EuiAppConfig } from '@eui/core';
import { EUI_PAGE } from '@eui/components/eui-page';
import { TranslateModule } from '@ngx-translate/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { DataBridgeService, DataFromAngularJS } from '../../data-bridge.service';

@Component({
    standalone: true,
    template: require('./home.component.html'),
    imports: [
        CommonModule,
        TranslateModule,
        ...EUI_PAGE,
        RouterLink,
    ],
    providers: [DataBridgeService], // Explicitly provide the service for this component
})
export class HomeComponent implements OnInit, OnDestroy {
    // Data received from AngularJS
    receivedData: DataFromAngularJS | null = null;
    
    private dataSubscription?: Subscription;

    constructor(
        @Inject(CONFIG_TOKEN) protected config: EuiAppConfig,
        private dataBridge: DataBridgeService
    ) {
        console.log('HomeComponent constructor - config:', config);
        console.log('HomeComponent constructor - dataBridge:', this.dataBridge);
        
        if (!this.dataBridge) {
            console.error('❌ HomeComponent: DataBridgeService is undefined in constructor!');
        }
    }

    ngOnInit(): void {
        console.log('HomeComponent ngOnInit - dataBridge:', this.dataBridge);
        
        // Check if dataBridge is defined before accessing it
        if (!this.dataBridge) {
            console.error('❌ HomeComponent: DataBridgeService is undefined in ngOnInit!');
            return;
        }
        
        if (!this.dataBridge.data$) {
            console.error('❌ HomeComponent: DataBridgeService.data$ is undefined!');
            return;
        }
        
        // Subscribe to data from AngularJS
        this.dataSubscription = this.dataBridge.data$.subscribe(data => {
            if (data) {
                this.receivedData = data;
                console.log('🎉 HomeComponent: Received data from AngularJS:', data);
            }
        });
        
        console.log('✅ HomeComponent: Ready to receive data from AngularJS');
    }

    ngOnDestroy(): void {
        // Clean up subscription
        if (this.dataSubscription) {
            this.dataSubscription.unsubscribe();
        }
    }

    clearData(): void {
        this.receivedData = null;
        this.dataBridge.clearData();
    }
}
