import { Inject, Injectable, InjectionToken, Optional } from '@angular/core';
import { from, Observable } from 'rxjs';
import { take, tap } from 'rxjs/operators';
import * as lf from 'localforage';
import { AsyncStorageService } from './async-storage.service';
import { LogService } from '../log';

/** @internal */
// TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const localForage: any = 'defineDriver' in lf ? lf : lf['default'];
// TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const LOCAL_FORAGE_SERVICE_CONFIG_TOKEN = new InjectionToken<any>('LOCAL_FORAGE_SERVICE_CONFIG');

/**
 * localforage service, using the localForage javascript library
 * https://localforage.github.io/localForage
 */
@Injectable()
export class LocalForageService extends AsyncStorageService {
    static NAME = 'LocalForageService';

    constructor(
        // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        @Inject(LOCAL_FORAGE_SERVICE_CONFIG_TOKEN) @Optional() protected config: any,
        @Optional() protected log: LogService,
    ) {
        super();
        // configure localforage, if specified
        if (config) {
            localForage.config(config);
        }
    }

    /**
     * the name of the storage service
     */
    name(): string {
        return LocalForageService.NAME;
    }

    /**
     * reflects the readiness of the storage
     * @returns one time emission Observable<void>
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ready(): Observable<any> {
        return from(localForage.ready()).pipe(
            take(1),
            tap({
                next: () => { /* empty */ },
                error: (err) => {
                    if (this.log) {
                        this.log.error(this.name(), 'ready', err);
                    }
                },
            }),
        );
    }

    /**
     * retrieve an object from localforage
     * @param key the associated key
     * @returns one time emission Observable of value
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    get(key: string): Observable<any> {
        return from(localForage.getItem(key)).pipe(
            take(1),
            tap({
                next: () => { /* empty */
                },
                error: (err) => {
                    if (this.log) {
                        this.log.error(this.name(), 'get', err);
                    }
                },
            }),
        );
    }

    /**
     * sets an object in localforage
     * @param key the associated key
     * @param value the value to set
     * @returns one time emission Observable
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    set(key: string, value: any): Observable<any> {
        return from(localForage.setItem(key, value)).pipe(
            take(1),
            tap({
                next: () => { /* empty */
                },
                error: (err) => {
                    if (this.log) {
                        this.log.error(this.name(), 'set', err);
                    }
                },
            }),
        );
    }

    /**
     * removes an object from localforage
     * @param key the associated key
     * @returns one time emission Observable
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    remove(key: string): Observable<any> {
        return from(localForage.removeItem(key)).pipe(
            take(1),
            tap({
                next: () => { /* empty */ },
                error: (err) => {
                    if (this.log) {
                        this.log.error(this.name(), 'remove', err);
                    }
                },
            }),
        );
    }
}
