import { NgModule, Directive, HostListener, OnInit, Input, booleanAttribute, numberAttribute, inject } from '@angular/core';
import { DOCUMENT } from '@angular/common';

@Directive({
    selector: '[euiScrollHandler]',
})
export class EuiScrollHandlerDirective implements OnInit {
    navIsFixed = false;
    appHeaderHeight = 0;

    @Input({ transform: booleanAttribute }) euiScrollHandler = false;

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private appWrapper: any;
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private appHeader: any;
    private document = inject<Document>(DOCUMENT);

    ngOnInit(): void {
        this.appWrapper = this.document.getElementById('app-wrapper');
        this.appHeader = this.document.getElementById('app-header');
        if (this.appHeader) {
            this.appHeaderHeight = this.appHeader.scrollHeight;
        }
    }

    @HostListener('window:scroll', [])
    onWindowScroll(): void {
        if (this.euiScrollHandler && this.appHeaderHeight !== 0) {
            const number = this.document.body.scrollTop || this.document.documentElement.scrollTop; // Chrome || IE/FF

            if (number > this.appHeaderHeight) {
                this.navIsFixed = true;
                this.appWrapper.classList.add('shrink-header-active');
            } else if (this.navIsFixed && number < this.appHeaderHeight) {
                this.navIsFixed = false;
                this.appWrapper.classList.remove('shrink-header-active');
            }
        }
    }
}

@Directive({
    selector: '[euiScrollHandlerElement]',
})
export class EuiScrollHandlerElementDirective {
    @Input() euiScrollHandlerElement: string;
    @Input() toggleClass: string;
    @Input({ transform: numberAttribute }) toggleActiveHeight: number;

    public navIsFixed = false;
    private document = inject<Document>(DOCUMENT);

    @HostListener('window:scroll', [])
    onWindowScroll(): void {
        const element = this.document.getElementById(this.euiScrollHandlerElement);
        const number = this.document.body.scrollTop || this.document.documentElement.scrollTop; // Chrome || IE/FF

        if (number > this.toggleActiveHeight) {
            this.navIsFixed = true;
            element.classList.add(this.toggleClass);
        } else if (this.navIsFixed && number < this.toggleActiveHeight) {
            this.navIsFixed = false;
            element.classList.remove(this.toggleClass);
        }
    }
}

/**
 * @deprecated Use {@link EuiScrollHandlerDirective} and {@link EuiScrollHandlerElementDirective} instead.
 */
@NgModule({
    imports: [EuiScrollHandlerDirective, EuiScrollHandlerElementDirective],
    exports: [EuiScrollHandlerDirective, EuiScrollHandlerElementDirective],
})
export class EuiScrollHandlerDirectiveModule {}
