import { Inject, Injectable, Optional, PLATFORM_ID } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { BehaviorSubject, defer, firstValueFrom, Observable } from 'rxjs';
import { EuiEuLanguages, GlobalConfig, getActiveLang, EuiLanguage, EuiMenuItem } from '@eui/base';
import { GLOBAL_CONFIG_TOKEN } from './config/tokens';
import { I18nService } from './i18n';
import { Router, NavigationEnd } from '@angular/router';
import { StoreService } from './store/store.service';
import { distinctUntilChanged, filter, map } from 'rxjs/operators';
import { isEqual, get } from 'lodash-es';
import { CssUtils } from '../helpers/css-utils';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface UIState<BP = any, DI = any, AMD =any, BPV = any> {
    // app state
    appName?: string;
    appShortName?: string;
    appSubTitle?: string;
    appBaseFontSize?: string;

    // Sidebar state
    isSidebarOpen?: boolean;
    isSidebarActive?: boolean;
    hasSidebar?: boolean;
    hasBreadcrumb?: boolean;
    hasHeader?: boolean;
    hasHeaderLogo?: boolean;
    hasHeaderEnvironment?: boolean;
    hasToolbar?: boolean;
    hasToolbarMenu?: boolean;
    environmentValue?: string;
    isSidebarHidden?: boolean;
    hasSidebarCollapsedVariant?: boolean;
    hasTopMessage?: boolean;

    // window state
    windowWidth?: number;
    windowHeight?: number;
    mainContentHeight?: number;
    pageHeaderHeight?: number;
    breakpoint?: string;
    wrapperClasses?: string;
    breakpoints?: BP;
    breakpointValues?: BPV;

    // navigation state
    menuLinks?: EuiMenuItem[];
    sidebarLinks?: EuiMenuItem[];
    combinedLinks?: EuiMenuItem[];

    // other states
    isBlockDocumentActive?: boolean;

    // device info
    deviceInfo: DI;

    // language infos
    activeLanguage: string;
    languages: (string | EuiLanguage)[];

    // app metadata
    appMetadata: AMD;

    // various dynamic state
    hasModalActive?: boolean;
    isDimmerActive?: boolean; // Usage: map to eui base directive input coerce euiHighlighted
}

const initialState: UIState = {
    appName: '',
    appShortName: '',
    appSubTitle: '',
    appBaseFontSize: '',

    isSidebarOpen: true,
    isSidebarActive: false,
    hasSidebar: false,
    hasHeader: false,
    hasBreadcrumb: false,
    hasHeaderLogo: false,
    hasHeaderEnvironment: false,
    hasToolbar: false,
    hasToolbarMenu: false,
    environmentValue: '',
    isSidebarHidden: false,
    hasSidebarCollapsedVariant: false,
    hasTopMessage: false,
    windowWidth: 0,
    windowHeight: 0,
    mainContentHeight: 0,
    pageHeaderHeight: 0,
    wrapperClasses: '',
    breakpoint: '',
    breakpoints: {
        isMobile: false,
        isTablet: false,
        isLtLargeTablet: false,
        isLtDesktop: false,
        isDesktop: false,
        isXL: false,
        isXXL: false,
        isFHD: false,
        is2K: false,
        is4K: false,
    },
    breakpointValues: [],
    menuLinks: [],
    sidebarLinks: [],
    combinedLinks: [],
    isBlockDocumentActive: false,
    deviceInfo: null,
    activeLanguage: 'en',
    languages: EuiEuLanguages.getLanguages(),
    appMetadata: null,
    hasModalActive: false,
    isDimmerActive: false,
};

@Injectable({
    providedIn: 'root',
})
export class EuiAppShellService {
    navigationStartCustomHandler: () => void;
    navigationEndCustomHandler: () => void;

    // -------------------
    get state$(): Observable<UIState> {
        return this._state$.asObservable();
    }

    // -------------------
    // exposed observables

    get breakpoint$(): Observable<string> {
        return this._breakpoint$.asObservable();
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    get breakpoints$(): Observable<any> {
        return this._breakpoints$.asObservable();
    }

    // ----------------
    // state operations
    // ----------------
    get state(): UIState {
        return this._state$.getValue();
    }

    // ----------------------------
    // public setters and functions
    // ----------------------------
    set isSidebarOpen(isOpen: boolean) {
        this.setState({
            ...this.state,
            isSidebarOpen: isOpen,
        });
    }

    get isSidebarOpen(): boolean {
        return this.state.isSidebarOpen;
    }

    set isSidebarActive(isActive: boolean) {
        this.setState({
            ...this.state,
            isSidebarActive: isActive,
        });
    }

    set sidebarLinks(links: EuiMenuItem[]) {
        this.setState({
            ...this.state,
            sidebarLinks: links,
        });
    }

    set hasSidebarCollapsedVariant(isActive: boolean) {
        this.setState({
            ...this.state,
            hasSidebarCollapsedVariant: isActive,
        });
        CssUtils.activateSidebarCssVars(this.document, this.platformId, isActive);
    }

    set menuLinks(links: EuiMenuItem[]) {
        this.setState({
            ...this.state,
            menuLinks: links,
        });
    }

    set isBlockDocumentActive(isActive: boolean) {
        this.setState({
            ...this.state,
            isBlockDocumentActive: isActive,
        });
    }

    get hasHeader(): boolean {
        return this.state.hasHeader;
    }

    // Edit mode
    get isDimmerActive(): boolean {
        return this.state.isDimmerActive;
    }

    set isDimmerActive(isActive: boolean) {
        this.setState({
            ...this.state,
            isDimmerActive: isActive,
        });
    }

    private _state$: BehaviorSubject<UIState>;
    private _breakpoint$: BehaviorSubject<string>;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private _breakpoints$: BehaviorSubject<any>;

    constructor(
        @Optional() @Inject(GLOBAL_CONFIG_TOKEN) protected config: GlobalConfig,
        private http: HttpClient,
        @Inject(PLATFORM_ID) private platformId: object,
        @Inject(DOCUMENT) private document: Document,
        private router: Router,
        private storeService: StoreService,
        @Optional() private i18nService: I18nService,
    ) {
        let stateWithConfig = initialState;
        const languages = config?.i18n?.i18nService?.languages || initialState.languages;
        const defaultLanguage = config?.i18n?.i18nService?.defaultLanguage || initialState.activeLanguage;
        stateWithConfig = {
            ...stateWithConfig,
            ...{
                languages,
                activeLanguage: defaultLanguage,
            },
        };
        this._state$ = new BehaviorSubject(stateWithConfig);
        this._breakpoint$ = new BehaviorSubject('');
        this._breakpoints$ = new BehaviorSubject({});
        this.bindActiveLanguageToAppShellState();
    }

    setState(nextState: UIState, updateI18 = true): void {
        let breakpoint, breakpoints;
        let combinedLinks;

        const state = this.state;

        // check if window width has been updated from previous state
        if (this.state.windowWidth !== nextState.windowWidth) {
            breakpoint = this.getBreakpoint(nextState.windowWidth);
            breakpoints = this.getBreakpoints(breakpoint);

            this._breakpoint$.next(breakpoint);
            this._breakpoints$.next(breakpoints);

            // if not propagate the old ones without doing any calculations
        } else {
            breakpoint = state.breakpoint;
            breakpoints = state.breakpoints;
        }

        // finally get the wrapper classes when both the state and breakpoint are known
        const wrapperClasses = this.getWrapperClasses(nextState, breakpoint);

        // check if the menuLinks or sidebarLinks have changed from previous state
        if (this.state.menuLinks !== nextState.menuLinks || this.state.sidebarLinks !== nextState.sidebarLinks) {
            combinedLinks = [...nextState.menuLinks, ...nextState.sidebarLinks];
        } else {
            combinedLinks = this.state.combinedLinks;
        }

        const stateBeforeUpdate = { ...this.state };

        // we put it all together with the calculated properties
        this._state$.next({
            ...nextState,
            wrapperClasses,
            breakpoint,
            breakpoints,
            combinedLinks,
        });

        // update the Store Language
        if (updateI18 && nextState.activeLanguage !== stateBeforeUpdate.activeLanguage) {
            this.i18nService.updateState({ activeLang: nextState.activeLanguage });
        }
    }

    /**
     * Emits a slice from the state whether that changes
     *
     * @param key can be 'key' or 'key.sub.sub'
     */
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    getState<T = any>(key?: string): Observable<T> {
        return defer(() =>
            // check if key exists
            key
                ? this.state$.pipe(
                      map((state) => get(state, key)),
                      // filter((state) => state),
                      distinctUntilChanged((x, y) => isEqual(x, y)),
                  )
                : this.state$,
        );
    }

    public sidebarToggle(): void {
        this.isSidebarOpen = !this.state.isSidebarOpen;
    }

    // Edit mode
    public dimmerActiveToggle(): void {
        const isActive = this.isDimmerActive;
        this.setState({
            ...this.state,
            isDimmerActive: !isActive,
        });
        CssUtils.activateEditModeCssVars(!isActive, this.document);
    }

    public setDimmerActiveState(activeState: boolean): void {
        this.setState({
            ...this.state,
            isDimmerActive: activeState,
        });
        CssUtils.activateEditModeCssVars(activeState, this.document);
    }

    // --------------
    // public methods
    // --------------
    public fetchAppMetadata(metadataFilePath = 'assets/app-metadata.json'): void {
        this.getJson(metadataFilePath).then((data) => {
            this.setState({
                ...this.state,
                appMetadata: data,
            });
        });
    }

    public activateSidebar(): void {
        this.setState({
            ...this.state,
            hasSidebar: true,
        });

        if (!this.state.isSidebarHidden) {
            CssUtils.activateSidebarCssVars(this.document, this.platformId, this.state.hasSidebarCollapsedVariant);
        }
    }

    public activateSidebarHeader(): void {
        CssUtils.activateSidebarHeaderCssVars(this.document, this.platformId);
    }

    public activateSidebarFooter(): void {
        CssUtils.activateSidebarFooterCssVars(this.document, this.platformId);
    }

    public activateHeader(): void {
        this.setState({
            ...this.state,
            hasHeader: true,
        });
        CssUtils.activateHeaderCssVars(this.document, this.platformId);
    }

    public activateBreadcrumb(): void {
        this.setState({
            ...this.state,
            hasBreadcrumb: true,
        });
        CssUtils.activateBreadcrumbCssVars(this.document, this.platformId);
    }

    public activateTopMessage(height: number): void {
        this.setState({
            ...this.state,
            hasTopMessage: true,
        });
        CssUtils.activateTopMessageCssVars(height, this.document);
    }

    public activateToolbar(): void {
        this.setState({
            ...this.state,
            hasToolbar: true,
        });
        CssUtils.activateToolbarCssVars(this.document, this.platformId);
    }

    public activateToolbarMenu(): void {
        this.setState({
            ...this.state,
            hasToolbarMenu: true,
        });
    }

    /**
     * Returns the current value of --eui-f-size-base CSS variable
     */
    public getBaseFontSize(): string {
        return this.state.appBaseFontSize || CssUtils.getCssVarValue('--eui-f-size-base', this.document, this.platformId);
    }

    /**
     * Updates the current value of --eui-f-size-base CSS variable and the UIState appBaseFontSize
     */
    public setBaseFontSize(newsize: string): void {
        this.setState(
            {
                ...this.state,
                appBaseFontSize: newsize,
            },
            false,
        );
        CssUtils.setCssVarValue('--eui-f-size-base', newsize, this.document);
    }

    // ---------------
    // private getters
    // ---------------
    private getWrapperClasses(state: UIState, breakpoint: string): string {
        const classes: string[] = [];

        classes.push(breakpoint);

        if (state.hasSidebar) {
            if (state.isSidebarHidden) {
                classes.push('sidebar--hidden');
            }
            if (state.isSidebarOpen) {
                classes.push('sidebar--open');
            } else {
                classes.push('sidebar--close');
            }
        }
        if (state.deviceInfo?.isFF) {
            classes.push('ff');
        }
        if (state.deviceInfo?.isIE) {
            classes.push('ie');
        }
        if (state.deviceInfo?.isChrome) {
            classes.push('chrome');
        }
        return classes.join(' ');
    }

    private getBreakpoint(windowWidth: number): string {
        let bkp = '';

        if (this.state.breakpointValues.length === 0) {
            this.setState({
                ...this.state,
                breakpointValues: CssUtils.getBreakpointValues(this.document, this.platformId),
            });
        }

        this.state.breakpointValues.forEach((b, i) => {
            if (i < this.state.breakpointValues.length) {
                if (windowWidth >= b.value && windowWidth < this.state.breakpointValues[i+1]?.value) {
                    bkp = b.bkp;
                }
            } else if(windowWidth >= b.value) {
                bkp = b.bkp;
            }
        });

        return bkp;
    }

    private getBreakpoints(bkp: string): object {
        return {
            isMobile: bkp === 'xs' || bkp === 'sm',
            isTablet: bkp === 'md',
            isLtLargeTablet: bkp === 'xs' || bkp === 'sm' || bkp === 'md' || bkp === 'lg',
            isLtDesktop: bkp === 'xs' || bkp === 'sm' || bkp === 'md' || bkp === 'lg' || bkp === 'xl',
            isDesktop: bkp === 'xxl',
            isXL: bkp === 'xl',
            isXXL: bkp === 'xxl',
            isFHD: bkp === 'fhd',
            is2K: bkp === '2k',
            is4K: bkp === '4k',
        };
    }

    private getJson(url: string): Promise<object> {
        return firstValueFrom(this.http.get(url)).then(this.extractData).catch(this.handleError);
    }

    private extractData(res: Response): object {
        const body = res;
        return body || {};
    }

    private handleError<T extends Error>(error: T): Promise<T> {
        console.error('An error occurred', error);
        return Promise.reject(error.message || error);
    }

    private bindActiveLanguageToAppShellState(): void {
        this.i18nService.getState((s) => s.activeLang).subscribe((activeLang) => {
            if (activeLang !== this.state.activeLanguage) {
                this.setState(
                    {
                        ...this.state,
                        activeLanguage: activeLang,
                    },
                    false,
                );
            }
        });
    }
}
