import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';
import { Dependency, Policy, Status } from './eui-loader.model';
import { filter, map } from 'rxjs/operators';

/**
 *  A service for loading external dependencies dynamically to the DOM and keeping track of their status. Dependencies
 *  can be loaded in any order and can have prerequisites. The service will load the prerequisites first and then load
 *  the dependency. If a dependency fails to load, the service will retry loading it according to the retry policy.
 *  The service will emit the status of the dependency when it changes. This is useful for showing a loading indicator
 *  while the dependency is loading. In scenarios where the dependency is not required for the application to function,
 *  the service will not block the application from loading if the dependency fails to load. The service will also
 *  remove the dependency from the DOM if it is removed from the list. This is useful for scenarios where the dependency
 *  is only required for a specific component, might be removed from the list when the component is destroyed, and it
 *  will not affect the bundle size.
 *
 *  @example
 *  // Add a dependency
 *  loader.addDependency('Quill', 'https://cdn.quilljs.com/1.3.6/quill.js', 'js');
 *  // Get the status of a dependency
 *  loader.getDependencyStatus('Quill');
 *  // Listen for status changes
 *  loader.statusChanges('Quill').subscribe((status: Status) => {
 *    console.log(status);
 *  });
 *  // Remove a dependency
 *  loader.removeDependency('Quill');
 *  // Set the retry policy
 *  loader.setRetryPolicy(3, 1000);
 *  // Set the timeout policy
 *  loader.setTimeoutPolicy(5000);
 *  // Load a dependency with prerequisites
 *  loader.addDependency('Quill', 'https://cdn.quilljs.com/1.3.6/quill.js', 'js', ['QuillStyle']);
 *  loader.addDependency('QuillStyle', 'https://cdn.quilljs.com/1.3.6/quill.snow.css', 'css');
 *  // Load a dependency with prerequisites and retry logic
 *  loader.setRetryPolicy(3, 1000);
 *  loader.setTimeoutPolicy(5000);
 *  loader.addDependency('Quill', 'https://cdn.quilljs.com/1.3.6/quill.js', 'js', ['QuillStyle']);
 *  loader.addDependency('QuillStyle', 'https://cdn.quilljs.com/1.3.6/quill.snow.css', 'css');
 */
@Injectable({
    providedIn: 'root',
})
export class EuiLoaderService {
    /**
     * Stores the status and details of each dependency
     */
    private dependencies: Dependency[] = [];

    /** Observable that emits the name of the dependency when its status changes */
    private onStatusChange: Subject<string> = new Subject<string>();

    /**
     * Configuration for policies such as Retry and timeout for failed loads
     */
    private policy: Policy = {
        maxAttempts: 3,
        retryInterval: 1000,
        timeout: 5000,
    };

    /**
     * Add a dependency with its type (JS or CSS) and dependencies
     *
     * @param name The name of the dependency
     * @param url The URL of the dependency
     * @param type The type of the dependency (JS or CSS)
     * @param requires The dependencies that must be loaded before this one (optional)
     */
    addDependency(name: string, url: string, type: 'js' | 'css', requires: string[] = []): void {
        // if the dependency is not already in the list
        if (!this.dependencies.find(d => d.name === name)) {
            // Add the dependency to the list
            this.dependencies.push({
                name,
                url,
                type,
                requires,
                status: Status.LOADING,
                retries: 0,
            });
            // Load the dependency to the DOM
            this.loadDependency(name);
        }
    }

    /**
     * Remove a dependency from the DOM
     *
     * @param name The name of the dependency
     */
    removeDependency(name: string): void {
        const index = this.dependencies.findIndex(d => d.name === name);
        if (index === -1) {
            return;
        }
        const dependency: Dependency = this.dependencies.at(index);
        let element: HTMLScriptElement | HTMLLinkElement | null = null;

        if (dependency.type === 'js') {
            element = this.getScript(dependency.url);
        } else {
            element = this.getStyle(dependency.url);
        }

        if (element) {
            element.remove(); // Remove the element from the DOM
        } else {
            console.warn(`Dependency ${name} not found in DOM.`);
        }
        this.dependencies.splice(index, 1); // Remove the dependency from the list
    }

    /**
     * Allow users to configure the retry policy
     *
     * @param maxAttempts The maximum number of retry attempts
     * @param retryInterval The time between retries in milliseconds
     */
    setRetryPolicy(maxAttempts: number, retryInterval: number): void {
        this.policy.maxAttempts = maxAttempts;
        this.policy.retryInterval = retryInterval;
    }

    /**
     * Allow users to configure the timeout policy
     *
     * @param time The time in milliseconds before considering a load attempt as failed
     * @see setRetryPolicy
     * @see statusChanges
     */
    setTimeoutPolicy(time: number): void {
        this.policy.timeout = time;
    }

    /**
     * Get the status of a dependency
     *
     * @param name The name of the dependency
     * @returns The status of the dependency
     * @deprecated Prefer using statusChanges instead
     * @see statusChanges
     */
    getDependencyStatus(name: string): Status | null {
        const dependency: Dependency = this.dependencies.find(d => d.name === name);
        return dependency?.status || null;
    }

    /**
     * Get the status of a dependency as an observable
     *
     * @param name The name of the dependency
     */
    statusChanges(name: string): Observable<Status> {
        return this.onStatusChange.asObservable()
            .pipe(
                filter((loadedName: string) => loadedName === name),
                map(() => this.dependencies.find(d => d.name === name)?.status),
            );
    }

    /**
     * Load a dependency and its prerequisites
     *
     * @param name The name of the dependency
     * @see loadDependency
     */
    private loadDependency(name: string): void {
        const dependency: Dependency = this.dependencies.find(d => d.name === name);
        if(dependency === undefined) {
            console.error(`Dependency ${name} not found in list.`);
            return;
        }
        if (dependency?.requires.length) {
            // Load all prerequisites first
            dependency.requires.forEach((dep) => {
                // If the dependency is not already loaded or in the list, load it
                if (!this.dependencies.find(d => d.name === dep && d.status === Status.LOADED)) {
                    this.loadDependency(dep);
                }
            });
        }

        // Load the actual dependency
        if (dependency?.type === 'js' && this.getScript(dependency?.url) === null) {
            this.loadScript(dependency);
        } else if (this.getStyle(dependency?.url) === null) {
            this.loadStyle(dependency);
        }
    }

    /**
     * Load a JS script and append it to the root of the DOM
     * @param dependency
     */
    private loadScript(dependency: Dependency): void {
        const script: HTMLScriptElement = document.createElement('script');
        script.src = dependency.url;
        script.type = 'module';
        // script.defer = true; #Consider this to ensure scripts are loaded in order

        script.onload = (): void => {
            dependency.status = Status.LOADED;
            this.onStatusChange.next(dependency.name);
        };

        script.onerror = (): void => {
            this.handleError(dependency.name, 'Failed to load script');
        };

        // Append to the root of the DOM
        document.body.append(script);
    }

    /**
     * Load a CSS style and append it to the head of the document
     * @param dependency
     */
    private loadStyle(dependency: Dependency): void {
        const link: HTMLLinkElement = document.createElement('link');
        link.type = 'text/css';
        link.rel = 'stylesheet';
        link.href = dependency.url;

        link.onload = (): void => {
            dependency.status = Status.LOADED;
            this.onStatusChange.next(dependency.name);
        };

        link.onerror = (): void => {
            this.handleError(dependency.name, 'Failed to load stylesheet');
        };

        // Append to the head, which is conventionally used for stylesheets
        document.head.append(link);
    }

    /**
     * Error handling for a failed load
     * @param name
     * @param error
     */
    private handleError(name: string, error: string): void {
        const dependency: Dependency = this.dependencies.find(d => d.name === name);
        console.error(`Error loading ${name}: ${error}`);
        if (dependency.status !== Status.ERROR) {
            dependency.status = Status.ERROR;
            this.onStatusChange.next(dependency.name);
            // Retry logic
            if (dependency?.retries < this.policy.maxAttempts) {
                setTimeout(() => {
                    console.log(`Retrying to load ${name}, attempt ${dependency.retries + 1}`);
                    dependency.retries++;
                    this.reloadDependency(dependency);
                }, this.policy.retryInterval);
            } else {
                console.error(`Failed to load ${name} after ${this.policy.maxAttempts} attempts`);
            }
        }
    }

    /**
     * Get the script element from the DOM
     *
     * @param url
     * @private
     */
    private getScript(url: string): HTMLScriptElement | null {
        return document.querySelector(`script[src="${url}"]`);
    }

    /**
     * Get the style element from the DOM
     *
     * @param url
     * @private
     */
    private getStyle(url: string): HTMLLinkElement | null {
        return document.querySelector(`link[href="${url}"]`);
    }

    /**
     * Reload a dependency which can be either a script or a style. First remove
     * the element from the DOM and then load it again.
     *
     * @param dependency
     * @private
     */
    private reloadDependency(dependency: Dependency): void {
        if (dependency.type === 'js') {
            const script = this.getScript(dependency.url);
            script.remove();
            this.loadScript(dependency);
        } else {
            const style = this.getStyle(dependency.url);
            style.remove();
            this.loadStyle(dependency);
        }
    }
}
