import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    Input,
    ElementRef,
    booleanAttribute,
    inject,
} from '@angular/core';
import { FocusableOption, Highlightable } from '@angular/cdk/a11y';

import { EuiDropdownComponent } from '../eui-dropdown.component';
import { EUI_ICON } from '@eui/components/eui-icon';

@Component({
    selector: 'eui-dropdown-item, [euiDropdownItem]',
    templateUrl: './eui-dropdown-item.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_ICON,
    ],
})
export class EuiDropdownItemComponent implements Highlightable, FocusableOption {
    elementRef = inject(ElementRef);

    @Input() subDropdown: EuiDropdownComponent;

    @HostBinding('attr.role') role = 'menuitem';
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-dropdown-item',
            this.isActive ? 'eui-dropdown-item--active' : '',
            this.isFocus ? 'eui-dropdown-item--focused' : '',
            this.subDropdown ? 'eui-dropdown-item--has-subdropdown' : '',
        ]
            .join(' ')
            .trim();
    }

    @Input({ transform: booleanAttribute }) isActive: boolean;
    @Input({ transform: booleanAttribute }) isFocus: boolean;

    public setActiveStyles(): void {
        this.isFocus = true;
    }

    public setInactiveStyles(): void {
        this.isFocus = false;
    }

    public focus(): void {
        this.elementRef.nativeElement.focus();
    }

    public click(): void {
        this.elementRef.nativeElement.click();
    }

    public mouseenter(): void {
        const mouseenterEvent = new Event('mouseenter');
        this.elementRef.nativeElement.dispatchEvent(mouseenterEvent);
    }
}
