import {
    booleanAttribute,
    ChangeDetectionStrategy,
    Component,
    EventEmitter,
    HostBinding,
    Input,
    Output,
    ViewEncapsulation,
} from '@angular/core';
import { EUI_BADGE } from '@eui/components/eui-badge';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_OVERLAY } from '@eui/components/eui-overlay';
import { consumeEvent, UxLinkLegacy } from '@eui/core';
import { TranslateModule } from '@ngx-translate/core';
import { EuiNotificationItemV2Component } from './eui-notification-item.component';
import { EUI_BUTTON } from '@eui/components/eui-button';

@Component({
    selector: 'eui-notifications-v2',
    templateUrl: './eui-notifications.component.html',
    styleUrls: ['./styles/_index.scss'],
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        TranslateModule,
        EuiNotificationItemV2Component,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
        ...EUI_BADGE,
        ...EUI_OVERLAY,
        ...EUI_BUTTON,
    ],
})
export class EuiNotificationsV2Component {
    @Output() refreshClick: EventEmitter<Event> = new EventEmitter<Event>();
    @Output() notificationsClick: EventEmitter<KeyboardEvent | MouseEvent> = new EventEmitter<KeyboardEvent | MouseEvent>();
    @Output() viewAllClick: EventEmitter<Event> = new EventEmitter<Event>();
    // @Output() settingsClick: EventEmitter<any> = new EventEmitter<any>();
    @Output() markAllAsReadClick: EventEmitter<MouseEvent> = new EventEmitter<MouseEvent>();
    @Output() noNotificationFoundClick: EventEmitter<void> = new EventEmitter<void>();
    @Output() itemClick: EventEmitter<UxLinkLegacy> = new EventEmitter<UxLinkLegacy>();
    @Output() itemMarkAsReadClick: EventEmitter<UxLinkLegacy> = new EventEmitter<UxLinkLegacy>();

    isOverlayActive = false;
    currentDayNotifications = [];
    oldestNotifications = [];
    unreadNotifications = [];
    today: Date = new Date();

    @HostBinding('class') string = 'eui-notifications-v2';

    @Input() count: number = null;
    @Input() unreadCount: number = null;
    @Input() unreadSinceLastCheckCount: number = null;
    @Input() items = [];
    @Input() unreadLabel: string = null;
    @Input() totalLabel: string = null;
    @Input() markAsReadLabel: string = null;
    @Input() markAsUnReadLabel: string = null;
    @Input() markAllAsReadLabel: string = null;
    @Input() settingsLabel: string = null;
    @Input() refreshLabel: string = null;
    @Input() viewAllNotificationsLabel: string = null;
    @Input() headerTitleLabel: string = null;
    @Input() headerHideLabel: string = null;
    @Input() headerUnreadSinceLastCheckCountLabel: string = null;
    @Input() headerUnreadCountLabel: string = null;
    @Input() noNotificationFoundLabel: string = null;
    @Input() dateFormat = 'dd/MM/YYYY';
    @Input({ transform: booleanAttribute }) noNotificationFoundLink = false;
    @Input({ transform: booleanAttribute }) isShowMarkAsRead = true;
    @Input({ transform: booleanAttribute }) isShowViewAllAction = true;
    @Input({ transform: booleanAttribute }) isHidePanelOnViewAllAction = true;
    @Input({ transform: booleanAttribute }) isShowMarkAllAsReadButton = true;
    @Input({ transform: booleanAttribute }) isShowSettingsButton = true;
    @Input({ transform: booleanAttribute }) isShowRefreshButton = true;

    get isShowUnreadSinceLastCheckCount(): boolean {
        return this.unreadSinceLastCheckCount && this.unreadSinceLastCheckCount > 0;
    }

    onHide(): void {
        this.isOverlayActive = false;
    }

    onClicked(event: Event): void {
        this.notificationsClick.emit();
        consumeEvent(event);
        this.isOverlayActive = !this.isOverlayActive;
    }

    onRefresh(event: Event): void {
        this.refreshClick.emit();
        consumeEvent(event);
    }

    onItemClick(link: UxLinkLegacy): void {
        this.itemClick.emit(link);
        consumeEvent(event);
    }

    onViewAllClick(event: Event): void {
        this.viewAllClick.emit();
        if (!this.isHidePanelOnViewAllAction) {
            consumeEvent(event);
        }
    }

    onNoNotificationFoundClick(): void {
        this.noNotificationFoundClick.emit();
    }

    onItemMarkAsRead(link: UxLinkLegacy): void {
        this.itemMarkAsReadClick.emit(link);
    }

    onMarkAllAsRead(e: MouseEvent): void {
        this.markAllAsReadClick.emit(e);
        consumeEvent(e);
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    trackByFn(index: number, item: any): void {
        return item.id;
    }

    protected updateActiveState(isActive: boolean): void {
        this.isOverlayActive = isActive;
    }

    protected getAriaLabel(): string {
        if (this.count) {
            return this.count > 1
                ? ` You have ${this.count} notifications`
                : `You have ${this.count} notification`;
        }
        return 'Open notifications panel';
    }
}
