import {
    Component,
    HostBinding,
    Input,
    ChangeDetectionStrategy,
    forwardRef,
    ContentChildren,
    QueryList,
    AfterContentInit,
    Output,
    EventEmitter,
    ViewChild,
    ElementRef,
    booleanAttribute,
    inject,
} from '@angular/core';

import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_ICON, EuiIconSvgComponent } from '@eui/components/eui-icon';

import { EuiChip } from './models/eui-chip.model';

import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';

/**
 * @description
 * Chips are compact elements that allow users to enter information, select a choice, filter content or trigger an action.
 * The eui-chip component can also be displayed dynamically as a group of multiple interactive elements, see eui-chip-list.
 */
@Component({
    templateUrl: './eui-chip.component.html',
    selector: 'eui-chip, span[euiChip], li[euiChip]',
    styleUrl: './eui-chip.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiVariant',
                'euiSizeS',
                'euiSizeVariant',
                'euiOutline',
                'euiDisabled',
            ],
        },
    ],
})
export class EuiChipComponent implements AfterContentInit {
    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-chip'),
            this.isChipRemovable ? 'eui-chip--removable' : '',
            this.isFilled ? 'eui-chip--filled': '',
        ].join(' ').trim();
    }

    /**
     * Sets the `role` attribute for the host element.
     *
     * @default 'status'
     */
    @HostBinding('attr.role') role = 'status';
    /**
     * Sets the `aria-label` attribute for the host element.
     *
     * @default 'Chip content'
     */
    @Input() @HostBinding('attr.aria-label') ariaLabel = 'Chip content';

    /**
     * Sets the `data-e2e` attribute for the host element.
     *
     * @default 'eui-chip'
     */
    @HostBinding('attr.data-e2e')
    @Input()
    e2eAttr = 'eui-chip';

    /**
     * Sets the euiInternalId of the chip.
     *
     * @default null
     */
    @Input() euiInternalId: string = null;
    /**
     * Sets the label of the tooltip to diaply on hover.
     */
    @Input() tooltipMessage: string;
    /**
     * Sets the id of the chip.
     */
    @Input() id: string | number;
    /**
     * Sets the data of the chip like tooltip configuration.
     */
    // TODO: type should be specific
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    @Input() data: any = {
        id: crypto.randomUUID(),
        tooltip: {
            color: 'euiTooltipPrimary',
            contentAlignment: null,
            position: 'above',
        },
    };

    /**
     * Wether the chip can be removed.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipRemovable = false;
    /**
     * @deprecated This option is not applicable anymore to comply design System.
     */
    @Input({ transform: booleanAttribute }) isSquared = false;
    /**
     * Wether the chip is filled with color.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isFilled = false;

    /**
     * Event emitted when the chip is removed.
     */
    @Output() remove = new EventEmitter<EuiChipComponent | EuiChip | { chip: EuiChipComponent | EuiChip; event?: Event }>();

    /**
     * Icon declares by user in the chip
     */
    @ContentChildren(forwardRef(() => EuiIconSvgComponent)) euiIcons: QueryList<EuiIconSvgComponent>;
    @ViewChild('chipLabel') chipLabel: ElementRef<HTMLInputElement>;
    baseStatesDirective = inject(BaseStatesDirective);
    private _elementRef = inject(ElementRef);

    ngAfterContentInit(): void {
        if (!this.data.id && this.id) {
            this.data = Object.assign(this.data, { id: this.id });
        }

        if (this._elementRef.nativeElement.parentElement?.classList.contains('eui-chip-list__chip-container')) {
            this.role = 'listitem'
        }
    }

    /**
     * Remove chip handler
     *
     * @param event Click event
     */
    public onRemove(event?: Event): void {
        if (event instanceof KeyboardEvent && (event as KeyboardEvent).code === 'Backspace') {
            this.remove.emit({ chip: this.data, event });
        } else {
            this.remove.emit(this.data);
        }
    }
}
