import {
    Component,
    Directive,
    ViewEncapsulation,
    HostBinding,
    OnInit,
    OnDestroy,
    Input,
    ContentChild,
    forwardRef,
    OnChanges,
    SimpleChanges,
    ChangeDetectorRef,
    AfterContentInit,
    inject,
    PLATFORM_ID,
    booleanAttribute,
} from '@angular/core';
import { AsyncPipe, DOCUMENT, isPlatformBrowser } from '@angular/common';

import { Subject, fromEvent } from 'rxjs';
import { debounceTime, takeUntil } from 'rxjs/operators';

import { EuiAppShellService, EuiGrowlService } from '@eui/core';
import { CssUtils } from '@eui/core';
import { EUI_DIMMER } from '@eui/components/eui-dimmer';
import { RouterOutlet } from '@angular/router';
import { EUI_GROWL } from '@eui/components/eui-growl';
import { EUI_BLOCK_DOCUMENT } from '@eui/components/eui-block-document';

import { EUI_APP_SIDEBAR, EuiAppSidebarComponent } from './eui-app-sidebar';
import { EUI_APP_TOOLBAR, EuiAppToolbarComponent } from './eui-app-toolbar';
import { EUI_TOOLBAR } from '../eui-toolbar';
import { EUI_USER_PROFILE } from '@eui/components/eui-user-profile';

@Component({
    selector: 'eui-app',
    templateUrl: './eui-app.component.html',
    styleUrl: './_styles/_index.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        RouterOutlet,
        AsyncPipe,
        ...EUI_APP_SIDEBAR,
        ...EUI_APP_TOOLBAR,
        ...EUI_TOOLBAR,
        ...EUI_USER_PROFILE,
        ...EUI_GROWL,
        ...EUI_DIMMER,
        ...EUI_BLOCK_DOCUMENT,
    ],
})
export class EuiAppComponent implements OnInit, OnDestroy, OnChanges, AfterContentInit {
    @HostBinding('class') cssClasses = 'eui-app';

    @Input() appSubTitle = '';
    @Input() themeClass = '';

    hasNoPageWrapper = false;

    isViewLoaded: boolean;

    @Input({ transform: booleanAttribute }) isSidebarOpen = true;
    @Input({ transform: booleanAttribute }) isShrinkHeaderActive = true;
    @Input({ transform: booleanAttribute }) isSidebarHidden = false;
    
    @ContentChild(forwardRef(() => EuiAppSidebarComponent))
    appSidebar: EuiAppSidebarComponent;

    @ContentChild(forwardRef(() => EuiAppPageWrapperDirective))
    customPageWrapper: EuiAppPageWrapperDirective;

    @ContentChild(forwardRef(() => EuiAppToolbarComponent))
    appToolbar: EuiAppToolbarComponent;

    asService = inject(EuiAppShellService);
    euiGrowlService = inject(EuiGrowlService);
    private destroy$: Subject<boolean> = new Subject<boolean>();
    private cdRef = inject(ChangeDetectorRef);
    private platformId = inject(PLATFORM_ID);
    private document = inject<Document>(DOCUMENT);

    ngAfterContentInit(): void {
        this.hasNoPageWrapper = !this.customPageWrapper;
        this.isViewLoaded = true;
    }

    ngOnInit(): void {
        this.isViewLoaded = false;

        CssUtils.initCssVars(this.document, this.platformId);

        CssUtils.setHtmlClass('eui-19', this.document);

        if(isPlatformBrowser(this.platformId)) {
            const browserAgent = window.navigator.userAgent.toLowerCase();

            this.asService.setState({
                ...this.asService.state,
                windowHeight: window.innerHeight,
                windowWidth: window.innerWidth,
                hasHeader: false,
                hasSidebar: false,
                deviceInfo: {
                    isChrome: browserAgent.indexOf('chrome') > -1,
                    isIE: browserAgent.indexOf('trident') > -1,
                    isFF: browserAgent.indexOf('firefox') > -1,
                },
                appBaseFontSize: this.asService.getBaseFontSize(),
            });
        }

        this.asService
            .getState('wrapperClasses')
            .pipe(takeUntil(this.destroy$))
            .subscribe((state: string) => {
                this.cdRef.detach();
                this.cssClasses = ['eui-app', state].join(' ');
                this.cdRef.reattach();
                this.cdRef.detectChanges();
            });

        if(isPlatformBrowser(this.platformId)) {
            fromEvent(window, 'resize')
                .pipe(debounceTime(50), takeUntil(this.destroy$))
                .subscribe(() => {
                    this.asService?.setState({
                        ...this.asService.state,
                        windowHeight: window.innerHeight,
                        windowWidth: window.innerWidth,
                    });
                    CssUtils.setAppViewportCssVars(this.platformId);
                });
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.isSidebarHidden) {
            this.asService.setState({
                ...this.asService.state,
                isSidebarHidden: changes.isSidebarHidden.currentValue,
            });
        }
        if (changes.isSidebarOpen) {
            this.asService.setState({
                ...this.asService.state,
                isSidebarOpen: changes.isSidebarOpen.currentValue,
            });
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }
}

/* eslint-disable */
@Directive({ selector: 'eui-app-page-wrapper' })
export class EuiAppPageWrapperDirective { }

