import {
    EuiAppConfig,
    EuiAppHandlersConfig,
    EuiAppJsonConfig,
    EuiConfig,
    LogConfig,
    ModuleConfig,
    GlobalConfig,
    HttpErrorHandlerConfig,
    ConnectionStatus,
} from '@eui/base';
import * as extendProxy from 'extend';

const extend = (<{default: unknown}>extendProxy).default || extendProxy;

import { InjectionToken } from '@angular/core';
import { DEFAULT_EUI_CONFIG } from './defaults';

export const EUI_CONFIG_TOKEN = new InjectionToken<EuiConfig>('EuiConfig');
export const MODULE_NAME_TOKEN = new InjectionToken<string>('moduleName');
export const MODULE_CONFIG_TOKEN = new InjectionToken<ModuleConfig>('moduleConfig');
export const CONFIG_TOKEN = new InjectionToken<EuiAppConfig>('finalConfigToken');
export const GLOBAL_CONFIG_TOKEN = new InjectionToken<GlobalConfig>('globalConfig');
export const BASE_NAME_TOKEN = new InjectionToken<string>('baseName');
export const ROOT_LOG_CONFIG_TOKEN = new InjectionToken<LogConfig>('logConfig');
export const SHOW_CONNECTION_STATUS_TOKEN = new InjectionToken<boolean>('SHOW_CONNECTION_STATUS');

export const HTTP_ERROR_HANDLER_CONFIG_TOKEN = new InjectionToken<HttpErrorHandlerConfig>('HTTP_ERROR_HANDLER_CONFIG');

export function getGlobalConfig(appConfig: EuiAppConfig): GlobalConfig {
    return Object.assign(DEFAULT_EUI_CONFIG.appConfig.global, appConfig && appConfig.global);
}

export function getShowConnectionStatus(globalConfig: GlobalConfig): ConnectionStatus {
    return Object.assign({}, DEFAULT_EUI_CONFIG.appConfig.global.showConnectionStatus, globalConfig && globalConfig.showConnectionStatus);
}

export function getModuleConfig(appConfig: EuiAppConfig, moduleName: string): ModuleConfig {
    return Object.assign({}, appConfig && appConfig.modules && appConfig.modules[moduleName]);
}

export function getHttpErrorHandlingConfig(appConfig: EuiAppConfig): HttpErrorHandlerConfig {
    return Object.assign({}, appConfig && appConfig.httpErrorHandler);
}

export function getRootLogConfig(appConfig: EuiAppConfig): LogConfig {
    return Object.assign({}, appConfig && appConfig.log);
}

export function prepareEuiAppConfigToken(euiConfig: EuiConfig): EuiAppConfig {
    const environment = euiConfig && euiConfig.environment;
    const merge: Array<string> =
        environment.envDynamicConfig && environment.envDynamicConfig.merge && Array.isArray(environment.envDynamicConfig.merge)
            ? environment.envDynamicConfig.merge
            : [];
    const isDeepMerge: boolean =
        environment.envDynamicConfig && environment.envDynamicConfig.deepMerge ? environment.envDynamicConfig.deepMerge : false;
    const envAppJsonConfig: EuiAppJsonConfig = environment && environment.loadedEnvDynamicConfig;
    const initialAppConfig = euiConfig && euiConfig.appConfig;
    const envAppHandlersConfig: EuiAppHandlersConfig = environment && environment.envAppHandlersConfig;

    const envHandlersMergedAppConfig = mergeAppHandlerConfigToAppConfig(initialAppConfig, envAppHandlersConfig);
    const finalConfig = mergeAppJsonConfigToAppConfig(envHandlersMergedAppConfig, envAppJsonConfig, merge, isDeepMerge);
    return finalConfig;
}

export function mergeAppHandlerConfigToAppConfig(euiAppConfig: EuiAppConfig, envAppHandler: EuiAppHandlersConfig): EuiAppConfig {
    return Object.assign({}, euiAppConfig, envAppHandler);
}

export function mergeAppJsonConfigToAppConfig(
    euiAppConfig: EuiAppConfig,
    envAppJsonConfig: EuiAppJsonConfig,
    merge: Array<string>,
    isDeepMerge: boolean,
): EuiAppConfig {
    const deepMerged = {};
    if (merge && merge.length > 0) {
        merge.forEach((key) => {
            if (
                envAppJsonConfig != null &&
                envAppJsonConfig[key] &&
                typeof envAppJsonConfig[key] === 'object' &&
                euiAppConfig != null &&
                euiAppConfig[key] &&
                typeof euiAppConfig[key] === 'object'
            ) {
                if (isDeepMerge) {
                    deepMerged[key] = {};
                    extend(true, deepMerged[key], euiAppConfig[key], envAppJsonConfig[key]);
                } else {
                    envAppJsonConfig[key] = {
                        ...euiAppConfig[key],
                        ...envAppJsonConfig[key],
                    };
                }
            }
        });
    }
    return Object.assign({}, euiAppConfig, envAppJsonConfig, deepMerged);
}
