import {
    Inject,
    Injectable,
    InjectionToken,
    LOCALE_ID,
    OnDestroy,
    Optional,
    Signal,
} from '@angular/core';
import { getLocaleId } from '@angular/common';
import {
    DeepPartial,
    EuiService,
    EuiServiceStatus,
    getLocaleServiceConfigFromBase,
    GlobalConfig,
    I18nState,
    LocaleServiceConfig,
    LocaleState,
    Logger,
} from '@eui/base';
import { BehaviorSubject, Observable, of, Subject } from 'rxjs';
import { distinctUntilChanged, filter, map, switchMap, take, takeUntil, tap } from 'rxjs/operators';
import { StoreService } from '../store';
import { LogService } from '../log';
import { I18nService } from '../i18n';
import { GLOBAL_CONFIG_TOKEN } from '../config/tokens';
import { isEqual } from 'lodash-es';
import { toSignal } from '@angular/core/rxjs-interop';

export type LocaleMapper = (locale: string) => string;
export const LOCALE_ID_MAPPER = new InjectionToken<LocaleMapper>('localeIdMapper');

/**
 * LocaleService is responsible for managing locale states and configurations in an Angular application.
 * It utilizes the CLDR library to load and construct the locale for each region. This service allows
 * for dynamic loading of locales upon request and updates the state of the EUI app accordingly.
 *
 * Key functionalities include:
 *  - Binding to a translation service for locale changes.
 *  - Updating the Angular LOCALE_ID token.
 *
 * @template T - Extends LocaleState, representing the state structure for locales.
 * @template L - The type of the locale data.
 * @extends EuiService<T | LocaleState>
 */
@Injectable({
    providedIn: 'root',
})
export class LocaleService<T extends LocaleState = LocaleState> extends EuiService<T | LocaleState> implements OnDestroy {
    private static readonly DEFAULT_STATE: LocaleState = { id: 'en-US' };

    private readonly logger: Logger;
    private subNotifier: Subject<void> = new Subject();
    protected config: LocaleServiceConfig;

    /**
     * a single signal holding the state - initial state is null
     */
    private state: Signal<T>;
    /**
     * a BehaviorSubject holding the state - initial state is null
     * This is the main source of truth for the state
     */
    private stateSubject: BehaviorSubject<T>;

    constructor(
        protected store: StoreService,
        @Inject(GLOBAL_CONFIG_TOKEN) protected baseGlobalConfig: GlobalConfig,
        @Inject(LOCALE_ID) protected locale_id: string,
        @Optional() @Inject(LOCALE_ID_MAPPER) private localeMapper: LocaleMapper,
        @Optional() private i18n: I18nService,
        @Optional() private log: LogService,
    ) {
        super({ id: locale_id || Intl.DateTimeFormat().resolvedOptions().locale || LocaleService.DEFAULT_STATE.id } as T);
        if (log) {
            this.logger = log.getLogger('core.LocaleService');
        }

        // Create a BehaviorSubject with the initial state
        this.stateSubject = new BehaviorSubject<T>(this.stateInstance as T);

        // Initialize signal with base state
        this.state = toSignal(this.stateSubject, { equal: isEqual });

        // Subscribe to base class state changes
        this.onStateChange.subscribe((newState) => {
            // const clonedState = structuredClone(newState as T);
            this.stateSubject.next(newState as T);
        });

        this.config = getLocaleServiceConfigFromBase(this.baseGlobalConfig);
        // in case no localeMapper provided, set the angular getLocaleId as default
        if (!this.localeMapper) {
            this.localeMapper = getLocaleId;
            // TODO: replace deprecated method with new one
            // this.localeMapper = (locale: string) => new Intl.Locale(locale).baseName;
        }
    }

    ngOnDestroy(): void {
        this.subNotifier.next(void 0);
        this.subNotifier.complete();
    }

    getState(): Observable<T>;
    /**
     * Retrieves the state of the locale service. This method is overloaded to allow different ways of accessing the state.
     *
     * @template K - The type of the value to be returned. Defaults to the type of the locale state (T).
     *
     * @param {((state: T) => K)} [mapFn] - A function that maps the state to a specific form.
     *                                      Takes the current state as an argument and returns the transformed state.
     * @returns {Observable<K>} - An observable that emits the transformed state.
     */
    getState<K = T>(mapFn?: (state: T) => K): Observable<K>;
    /**
     * @template a - A key that extends the keys of the state type T.
     * @param {a} [key] - A specific key to access a part of the state.
     *                    The key should be a property name of the state object.
     * @returns {Observable<Partial<a>>} - An observable that emits the value of the specified key in the state.
     * @param key
     */
    getState<a extends keyof DeepPartial<T>>(key?: a): Observable<DeepPartial<a>>;
    /**
     * @param {((state: T) => K) | string} [keyOrMapFn] - Either a mapping function or a string key.
     *                                                    If a string is provided, it uses dot notation to access nested properties.
     * @returns {Observable<Partial<K>>} - An observable that emits the selected or transformed state.
     *
     * If no parameter is provided, the method returns the entire state.
     * @param keyOrMapFn
     */
    getState<K = T>(keyOrMapFn?: ((state: T) => K) | string): Observable<DeepPartial<K>> {
        if (!keyOrMapFn) {
            return this.stateSubject.asObservable().pipe(
                distinctUntilChanged((x, y) => isEqual(x, y)),
            ) as Observable<DeepPartial<K>>;
        }

        if (typeof keyOrMapFn === 'function') {
            return this.stateSubject.asObservable().pipe(
                map(state => keyOrMapFn(state)),
                distinctUntilChanged((x, y) => isEqual(x, y)),
            );
        }

        return this.stateSubject.asObservable().pipe(
            map(state => {
                const keys = (keyOrMapFn as string).split('.');

                // Traverse the object based on the dot notation
                return keys.reduce((acc, currKey) => {
                    return acc && acc[currKey] !== undefined ? acc[currKey] : undefined;
                }, state as DeepPartial<T>);
            }),
            distinctUntilChanged((x, y) => isEqual(x, y)),
        );
    }

    /**
     * Initializes the LocaleService with necessary configurations and state.
     * Binds language changes to the state and dynamically loads the appropriate locales.
     *
     * @param {LocaleState} [state] - Optional initial state for the locale service.
     * @returns {Observable<EuiServiceStatus>} - Observable emitting the status of the initialization.
     */
    init(state?: LocaleState): Observable<EuiServiceStatus> {
        super.initEuiService();

        state = state || { id: this.currentLocale };

        // bind language changes to locale changes
        if (this.config?.bindWithTranslate) {
            this.bindTranslateServiceLangChangeToState();
        }

        return of({ success: true })
            .pipe(tap(() => this.updateState(state as Partial<T>)));
    }

    /**
     * This method is used to update the state of the service with a new state.
     *
     * @param state
     */
    updateState(state: DeepPartial<T>): void;
    /**
     * Updates the locale state within the application. If the new state is not available,
     * it throws an error. Also updates the global LOCALE_ID token if configured to do so.
     *
     * @param {LocaleState} state - The new state to be set for the locale.
     * @throws Will throw an error if the locale for the given state id is not available.
     */
    updateState<K extends T>(state: DeepPartial<K>): void {
        const prevState = structuredClone(this.stateInstance);
        if(state?.id) {
            // check if locale is available otherwise throw error
            try {
                const id = this.localeMapper(state.id as string);
                this.stateInstance = super.deepMerge(this.stateInstance as T, { ...state, id });
            } catch (e) {
                const message = `Locale for '${state.id}' is not available.\n` +
                 `Please use addLocale('${state.id}') first`;
                if (this.log) {
                    this.logger.info(message, e);
                }
                throw new Error(message);
            }
        } else {
            this.stateInstance = super.deepMerge(this.stateInstance as T, { ...state });
        }
        // Emit state change
        this.onStateChange.next(this.stateInstance);
        // set previous state of service
        this.prevStateInstance = prevState;
    }

    /**
     * This method is used to get the state as readonly signal.
     */
    getSignal(): Signal<T> {
        return this.state;
    }

    /**
     * Retrieves the previous locale used in the application.
     *
     * @returns {string} - The previous locale identifier.
     */
    get previousLocale(): string {
        return this.prevStateInstance?.id || this.currentLocale;
    }

    /**
     * Retrieves the current locale used in the application.
     *
     * @returns {string} - The current locale identifier.
     */
    get currentLocale(): string {
        return this.stateInstance?.id;
    }

    /**
     * Listens for language changes and dynamically sets the locale accordingly.
     *
     * @private
     */
    private bindTranslateServiceLangChangeToState(): void {
        if (this.i18n) {
            this.i18n.onStateChange
                .pipe(
                    takeUntil(this.subNotifier),
                    // Only processes state changes when the language actually changes
                    // Example: With activeLang='en', ignores changes between 'en-US' and 'en-GB'
                    // Checks: activeLang exists, has 2+ chars, and differs from current locale's primary language
                    filter((state: I18nState) => state?.activeLang !== null &&
                        state?.activeLang !== undefined &&
                        state?.activeLang.length > 1 &&
                        state.activeLang.toLowerCase() !== this.stateInstance?.id.slice(0, 2).toLowerCase()),
                    // to check if registration of locale otherwise register it
                    map((state: I18nState) => this.localeMapper(state.activeLang)),
                    // update the "available" array attribute with newly registered
                    switchMap((id: string) =>
                        this.getState().pipe(
                            take(1),
                            map((state: LocaleState) => {
                                const available = state['available'] ? state['available'] : [];
                                return { ...state, id, available: Array.from(new Set([...available, id])) };
                            }),
                        ),
                    ),
                )
                .subscribe((state: LocaleState) => {
                    return this.updateState(state as Partial<T>);
                });
        }
    }
}
