export class EuiChip {
    id: string | number;
    euiInternalId: string;
    label: string;
    isRemovable = false;
    isOutline = false;
    isRounded = false;
    isDisabled = false;
    typeClass: 'primary' | 'secondary' | 'info' | 'success' | 'warning' | 'danger' | 'accent' = 'primary';
    tooltip: EuiChipTooltip = new EuiChipTooltip();
    iconClass?: string;
    iconSvgName?: string;

    constructor(values = {}) {
        Object.assign(this, values);
    }
}

export class EuiChipTooltip {
    tooltipMessage: string;
    position?: 'above' | 'below' | 'left' | 'right' | 'before' | 'after' = 'above';
    contentAlignment?: 'center' | 'left' | 'right' | 'justify' = 'center';
    delay? = 0;

    constructor(values = {}) {
        Object.assign(this, values);
    }
}
