import { ApiQueue } from '../models';
import { ModulesConfig } from '../../eui-config';

// TODO: on v18 replace any with no object as a type and declare it as breaking change
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface AppState<T = any> {
    version?: string;
    /** flag to indicate if the application is online/offline. Default: true */
    connected?: boolean;
    loadedConfigModules?: LoadedConfigModules;

    status?: string;
    currentModule?: string;
    apiQueue?: ApiQueue;

    [key: string]: string | boolean | LoadedConfigModules | ApiQueue | T;
}

export const initialAppState: AppState = Object.assign(
    {},
    {
        version: '0.0.0',
        connected: true,
        loadedConfigModules: {
            modulesConfig: {},
        },
        status: 'idle',
        currentModule: '',
        apiQueue: {},
    },
);

/**
 * LoadedConfigModules
 * @property lastAddedModule - the last module added to the store
 * @property modulesConfig - the modules configuration
 */
export interface LoadedConfigModules {
    lastAddedModule?: string;
    modulesConfig: ModulesConfig;
}
