import { Injectable } from '@angular/core';
import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest, HttpResponse, HttpResponseBase } from '@angular/common/http';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

interface body {
    success: boolean;
    status: string;
    code: number;
    message: string;
}

// The EuLoginSessionTimeoutHandlingInterceptor assumes that the EU login client is configured with:
// <redirectionInterceptor>eu.cec.digit.ecas.client.http.ajax.JsonAjaxRedirectionInterceptor</redirectionInterceptor>
// WARNING: The default EU login client behaviour that provides the JSON-un-parsable login HTML page, is no longer supported!
@Injectable()
export class EuLoginSessionTimeoutHandlingInterceptor implements HttpInterceptor {
    intercept<T extends body>(request: HttpRequest<T>, next: HttpHandler): Observable<HttpEvent<T>> {
        return next.handle(request).pipe(
            tap({
                next: (event) => {
                    this.checkRequestSuccessForEULoginSessionTimeout(request, event);
                    return event;
                },
                error: (error) => {
                    this.checkRequestErrorForEULoginSessionTimeout(request, error);
                },
            }),
        );
    }

    protected checkRequestSuccessForEULoginSessionTimeout<T extends body, E>(request: HttpRequest<T>, event: HttpEvent<E>): void {
        if (event instanceof HttpResponse) {
            if (this.isSsoResponse((<HttpResponse<string | body>>event).body)) {
                this.reauthenticate();
            }
        }
    }

    protected checkRequestErrorForEULoginSessionTimeout<T = unknown>(request: HttpRequest<T>, response: HttpResponseBase): void {
        /* intentionally blank; meant for overriding */
    }

    protected isSsoResponse(body: string | body): boolean {
        if (body) {
            if (typeof body !== 'string') {
                return (
                    body.success === false &&
                    body.status === 'ECAS_AUTHENTICATION_REQUIRED' &&
                    body.code === 303 &&
                    body.message === 'session expired'
                );
            } else {
                const html = body;
                try {
                    return (
                        (html.indexOf('<meta name="Keywords" content="EU Login, ECAS, Authentication, Security" />') >= 0 &&
                            html.indexOf('<meta name="Description" content="EU Login" />') >= 0) ||
                        html.indexOf('<meta name="Description" content="European Commission Authentication Service" />') >= 0 ||
                        html.indexOf('<title>Mock Login Form</title>') >= 0 ||
                        html.indexOf('<title>Redirecting To ECAS</title>') >= 0 ||
                        html === '{ success : false, status : "ECAS_AUTHENTICATION_REQUIRED", code : 303, message : "session expired" }' ||
                        // eslint-disable-next-line max-len
                        JSON.stringify(JSON.parse(html)) ===
                            JSON.stringify({
                                success: false,
                                status: 'ECAS_AUTHENTICATION_REQUIRED',
                                code: 303,
                                message: 'session expired',
                            })
                    );
                } catch (e) {
                    return false;
                }
            }
        } else {
            return false;
        }
    }

    protected reauthenticate(): void {
        document.location.reload();
    }
}
