import {
    Injectable,
    Optional,
    Inject,
    PLATFORM_ID,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Observable, BehaviorSubject } from 'rxjs';
import { debounceTime, distinctUntilChanged, filter, map } from 'rxjs/operators';

import { LogService } from '../log';
import { CoreState, DeepPartial, initialCoreState } from '@eui/base';
import { isEqual } from 'lodash-es';
import { loadState } from './reducers';

export enum BrowserStorageType {
    local,
    session,
}

export type Handler<T> = (state: T[keyof T]) => Partial<T[keyof T]>

// todo should stay here but all the store directory should be moved upper level
@Injectable({
    providedIn: 'root',
})
// TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export class StoreService<T = any> {
    /**
     * autoSave handlers to call before saving in local Storage
     */
    protected _autoSaveHandlers: { [key: string]: Handler<T> } = {};
    /** storage instance e.g. localStorage, sessionStorage */
    private _storage: Storage;
    private state: BehaviorSubject<T>;
    private isHandlingAutoSave = false;

    constructor(
        @Optional() protected logService: LogService,
        @Inject(PLATFORM_ID) private platformId: unknown,
    ) {
        if (isPlatformBrowser(this.platformId)) {
            this._storage = localStorage;
        }

        const initialState = {} as T;
        this.state = new BehaviorSubject<T>(initialState);

        // Subscribe to signal changes for auto-save
        this.state.asObservable()
            .pipe(
                filter(() => this.isHandlingAutoSave),
                debounceTime(1000),
                distinctUntilChanged((prev, curr) => isEqual(prev, curr)),
            )
            .subscribe((state) => {
                this.saveState(state as CoreState);
            });

    }

    init(version?: string, storageType?: BrowserStorageType): void {
        if (isPlatformBrowser(this.platformId)) {
            // This action must be dispatched from an app initializer
            // We load the state from a storage and compare the version and userId with the provided ones.
            // If they are the same, we merge the local state into the initial state.
            // If there is a mismatch, we don't merge the local state, but update only the initial state.

            this._storage = storageType === BrowserStorageType.session ? sessionStorage : localStorage;

            // load the state from the localStorage
            let localState: CoreState = loadState<T>(this._storage) as CoreState;
            localState = { ...localState, app: { ...localState?.app, version } };

            const mergedState = this.deepMerge(localState, { ...initialCoreState }) as T;
            this.updateState(mergedState);
        }
    }

    /**
     * Add an autoSave handler for a specific state slice
     * @param stateSlice
     * @param handler
     * @deprecated it will be removed in the next major version
     */
    addAutoSaveHandler(stateSlice: string, handler: Handler<T>): void {
        this._autoSaveHandlers[stateSlice] = handler;
    }

    handleAutoSave(): void {
        this.isHandlingAutoSave = true;
    }

    /**
     * Proxy to NGRX store.dispatch()
     * that allows to intercept if the store is present
     *
     * @deprecated it will be removed in the next version support of NGRX will cease
     */
    dispatch(action: unknown): void {
        console.warn('eUI does not PROXY to NGRX store.dispatch() anymore');
    }

    /**
     * This method is used to update the state of the service with a new state.
     *
     * @param state
     */
    updateState(state: DeepPartial<T>): void;
    /**
     * @deprecated it will be removed in next version. Use updateState(partialState: DeepPartial<T>) instead
     * @param slice
     * @param reducer
     */
    updateState(slice: DeepPartial<T>, reducer: (state: T, action: DeepPartial<T>) => T): void;
    updateState<K extends T>(state: DeepPartial<K>, reducer?: (state: T, action: DeepPartial<K>) => T): void {
        const currentState = this.state.getValue();
        let newState: T;

        if (reducer) {
            newState = reducer(currentState, { ...state });
        } else {
            newState = this.deepMerge<T>(currentState, { ...state });
        }
        this.state.next(newState);
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    select(key?: any): Observable<T[any]>;
    select<K>(keyOrMapFn?: ((state: T) => K) | string): Observable<Partial<K> | K> {
        const baseObservable: Observable<T | K> = this.state.asObservable();

        if (!keyOrMapFn) {
            return baseObservable as Observable<K>;
        }

        if (typeof keyOrMapFn === 'function') {
            return baseObservable.pipe(
                map(state => keyOrMapFn(state as T)),
                distinctUntilChanged((x, y) => isEqual(x, y)),
            );
        }

        return baseObservable.pipe(
            map(state => {
                if (!keyOrMapFn) {
                    return state;
                }

                const keys = keyOrMapFn.split('.');
                return keys.reduce((acc, currKey) => {
                    return acc && acc[currKey] !== undefined ? acc[currKey] : undefined;
                }, state);
            }),
            distinctUntilChanged((x, y) => isEqual(x, y)),
        );
    }

    /**
     * filters and save the state with the Browser storage
     * @param state type of CoreState
     */
    protected saveState(state: CoreState): void {
        let stateToSave: CoreState = {
            app: state.app,
        };

        if (state.user) {
            const { userId, preferences } = state.user;
            stateToSave.user = { userId, preferences };
        }

        Object.keys(this._autoSaveHandlers).forEach((sliceState: string) => {
            const handler = this._autoSaveHandlers[sliceState];
            stateToSave = Object.assign(stateToSave, { [sliceState]: handler(state[sliceState]) });
        });

        try {
            const serializedState = JSON.stringify(stateToSave);
            this._storage?.setItem('state', serializedState);
        } catch (err) {
            // Ignore write errors.
        }
    }

    /**
     * deep merge two objects
     * @param target the object that will be merged into
     * @param source the object that will be merged from
     */
    private deepMerge<T>(target: T, source: DeepPartial<T>): T {
        const output = Object.assign({}, target);
        if (this.isObject(target) && this.isObject(source)) {
            Object.keys(source).forEach(key => {
                if (this.isObject(source[key])) {
                    if (!(key in target)) {
                        Object.assign(output, { [key]: source[key] });
                    } else {
                        output[key] = this.deepMerge(target[key], source[key]);
                    }
                } else {
                    Object.assign(output, { [key]: source[key] });
                }
            });
        }
        return output;
    }

    /**
     * checks if the given item is an object
     * @param item the item that will be checked
     */
    private isObject(item: unknown): item is object {
        return item && typeof item === 'object' && !Array.isArray(item);
    }

}
