import { Component, HostBinding, ViewEncapsulation, Input, ChangeDetectionStrategy, inject } from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';

@Component({
    selector: 'eui-page-footer',
    template: '<ng-content/>',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiHighlighted',
            ],
        },
    ],
})
export class EuiPageFooterComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return this.baseStatesDirective.getCssClasses('eui-page-footer');
    }

    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-page-footer';
    protected baseStatesDirective = inject(BaseStatesDirective);
}
