import { Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, Input, booleanAttribute, inject } from '@angular/core';

import { BaseStatesDirective } from '@eui/components/shared';

/**
 * @description
 * Component used internally by `eui-autocomplete` to display the options in the panel.
 */
@Component({
    selector: 'eui-autocomplete-option',
    template: '<ng-content/>',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiVariant',
            ],
        },
    ],
})
export class EuiAutocompleteOptionComponent {
    /**
     * ARIA role for the host element to ensure proper accessibility.
     * @default 'option'
     */
    @HostBinding('attr.role') role = 'option';

    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-autocomplete-option'),
            this.isActive ? 'eui-autocomplete-option--active' : '',
            this.isDisabled ? 'eui-autocomplete-option--disabled' : '',
            this.isGroupItem ? 'eui-autocomplete-option--group-item' : '',
        ]
            .join(' ')
            .trim();
    }

    /**
     * Whether the option is active in the panel.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isActive = false;
    /**
     * Whether the option is disabled in the panel.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isDisabled = false;
    /**
     * Whether the option is displayed inside a group.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isGroupItem = false;
    private baseStatesDirective = inject(BaseStatesDirective);
}
