import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Input,
    forwardRef,
    QueryList,
    ContentChildren,
    ViewChild,
    booleanAttribute,
    AfterContentInit,
    AfterViewInit,
} from '@angular/core';
import { EuiUserProfileMenuComponent, EuiUserProfileComponent, EUI_USER_PROFILE } from '@eui/components/eui-user-profile';

@Component({
    selector: 'eui-header-user-profile',
    templateUrl: './header-user-profile.component.html',
    styleUrl: './header-user-profile.component.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_USER_PROFILE,
    ],
})
export class EuiHeaderUserProfileComponent implements AfterContentInit, AfterViewInit {
    @HostBinding('class') cssClass = 'eui-header-user-profile';

    @ContentChildren(forwardRef(() => EuiUserProfileMenuComponent), { descendants: true })
    hasMenuContent: QueryList<EuiUserProfileMenuComponent>;

    @ViewChild('userProfile') userProfile: EuiUserProfileComponent;

    @Input({ transform: booleanAttribute }) isShowUserInfos = true;
    @Input({ transform: booleanAttribute }) hasWelcomeLabel = true;
    @Input({ transform: booleanAttribute }) isShowAvatarInitials = false;
    @Input({ transform: booleanAttribute }) hasTabNavigation = false;

    @Input() welcomeLabel = 'Welcome';
    @Input() impersonateLabel = 'acting as';
    @Input() avatarUrl: string;
    @Input() subInfos: string;

    protected hasMenu = false;

    /**
     * @description
     * Closes the user profile dropdown menu if it is open.
     *
     * Ensure calling this after the ngAfterViewInit lifecycle hook to ensure the userProfile component is initialized.
     */
    public closeUserProfileDropdown(): void {
        this.userProfile.closeDropdown();
    }

    ngAfterContentInit(): void {
        this.hasMenu = this.hasMenuContent.length !== 0;
    }

    ngAfterViewInit(): void {
        // Pass the reference to the userProfile component to each menu component
        if (this.userProfile && this.hasMenuContent) {
            this.hasMenuContent.forEach(menu => {
                // Ensure the menu has a reference to the userProfile component
                menu.parent = this.userProfile;
                /**
                 * Subscribe to the parent component to handle any necessary logic While the ngAfterViewInit of
                 * EuiUserProfileComponent has been called before the parent injection did not exist.
                 *
                 * Thus, we need to manually subscribe to the parent component after the view has been initialized,
                 * and we manually set the parent property before subscribing.
                 */
                menu.subscribeToParent();
            });
        }
    }
}
