import {
    Component,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    OnInit,
    OnDestroy,
    OnChanges,
    SimpleChanges,
    HostBinding,
    AfterViewInit,
    ViewContainerRef,
    ViewChild,
    TemplateRef,
    ElementRef,
    Input,
    EventEmitter,
    Output,
    ChangeDetectorRef,
    ContentChildren,
    QueryList,
    booleanAttribute,
    numberAttribute,
    inject,
    PLATFORM_ID,
    DoCheck,
} from '@angular/core';
import { AsyncPipe, isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { ControlValueAccessor, FormControl, NgControl, ReactiveFormsModule, Validators } from '@angular/forms';
import { BehaviorSubject, Subject, Subscription, filter, fromEvent, takeUntil } from 'rxjs';
import { TemplatePortal } from '@angular/cdk/portal';
import {
    ConnectionPositionPair,
    FlexibleConnectedPositionStrategyOrigin,
    Overlay,
    OverlayModule,
    OverlayRef,
    PositionStrategy,
    RepositionScrollStrategy,
} from '@angular/cdk/overlay';
import { CdkScrollable, CdkVirtualScrollViewport, ScrollDispatcher, ScrollingModule } from '@angular/cdk/scrolling';
import { A11yModule, LiveAnnouncer } from '@angular/cdk/a11y';

import { EuiAppShellService } from '@eui/core';
import { EUI_CHIP_LIST, EuiChipDragDrop } from '@eui/components/eui-chip-list';
import { EUI_CHIP, EuiChip, EuiChipTooltip } from '@eui/components/eui-chip';
import { EuiTemplateDirective } from '@eui/components/directives';
import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_INPUT_TEXT } from '@eui/components/eui-input-text';

import { EuiAutoCompleteItem } from './models/eui-autocomplete-item.model';
import { panelAnimation } from './animations/animations';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EuiAutocompleteOptionComponent } from './eui-autocomplete-option/eui-autocomplete-option.component';
import {
    EuiAutocompleteOptionGroupComponent,
} from './eui-autocomplete-option-group/eui-autocomplete-option-group.component';

/**
 * @description
 * `eui-autocomplete` is a text input showing some suggestions when the user types letters. It can be enhanced with chips to allow user to select multiple values.
 *
 */
@Component({
    templateUrl: './eui-autocomplete.component.html',
    selector: 'eui-autocomplete, input[euiAutocomplete]',
    styleUrl: './eui-autocomplete.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgTemplateOutlet,
        AsyncPipe,
        ReactiveFormsModule,
        OverlayModule,
        ScrollingModule,
        A11yModule,
        EuiAutocompleteOptionComponent,
        EuiAutocompleteOptionGroupComponent,
        ...EUI_INPUT_TEXT,
        ...EUI_CHIP_LIST,
        ...EUI_CHIP,
        ...EUI_ICON,
    ],
    animations: [panelAnimation],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
            ],
        },
    ],
})
export class EuiAutocompleteComponent implements OnInit, OnDestroy, ControlValueAccessor, OnChanges, AfterViewInit, DoCheck {
    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-autocomplete'),
            'eui-autocomplete--chips-position-' + this.chipsPosition,
        ]
            .join(' ')
            .trim();
    }
    /**
     * Sets the id on the text input.
     */
    @Input() inputId: string;
    /**
     * Datas to be used in the autocomplete.
     */
    @Input() autocompleteData: EuiAutoCompleteItem[] = [];
    /**
     * Sets the maximum number of options that will be visible in the autocomplete panel.
     *
     * @default 5
     */
    @Input() visibleOptions = 5;
    /**
     * Sets the way the options should be retrieved.
     *
     * @default 'contains'
     */
    @Input() matching: 'startWith' | 'contains' = 'contains';
    /**
     * Sets the placeholder of the text input.
     */
    @Input() placeholder = '';
    /**
     * Sets the options that will be selected by default.
     */
    @Input() autocompleteDataSelected: EuiAutoCompleteItem[] = [];
    /**
     * Sets the sort criteria of the chips.
     *
     * @type {('ASC' | 'DESC')}
     * @default 'ASC'
     */
    @Input() chipsSortOrder: 'ASC' | 'DESC' = 'ASC';
    /**
     * In combination with `isChipsSorted`. Sets the sort criteria of the options in the panel.
     *
     * @type {('ASC' | 'DESC')}
     * @default 'ASC'
     */
    @Input() itemsSortOrder: 'ASC' | 'DESC' = 'ASC';
    /**
     * In Combination with `isItemsSorted`. Sets the position of the chips relative to the text input.
     *
     * @type {('top' | 'bottom' | 'inside')}
     * @default 'top''
     */
    @Input() chipsPosition: 'top' | 'bottom' | 'inside' = 'top';
    /**
     * Sets a grouping among the options.
     */
    @Input() groupBy: string;
    /**
     * In combination with `maxVisibleChipsCount`, sets the label of the 'more label' button, if not provided an arrow right icon will be displayed only.
     */
    @Input() toggleLinkMoreLabel: string = null;
    /**
     * In combination with `maxVisibleChipsCount`, sets the label of the 'less label' button, if not provided an arrow left icon will be displayed only.
     */
    @Input() toggleLinkLessLabel: string = null;
    /**
     * Sets a CSS class to be added on the options panel container.
     */
    @Input() classList: string = null;
    /**
     * Sets the width of the options panel.
     *
     * @type {(string | number)}
     */
    @Input() panelWidth: string | number;
    /**
     * In combination with `isChipsDragAndDrop`, sets the name to the chips source.
     */
    @Input() dragAndDropSourceName: string;
    /**
     * In combination with `isChipsDragAndDrop`, sets the name to the chips source with which a drag and drop will be done.
     */
    @Input() dragAndDropConnectedTo: string[] = [];

    /**
     * In combination with `hasChips`. Whether the user can add a value, which is not part of the options, to craete a chip.
     *
     * @default true
     */
    @Input({ transform: booleanAttribute }) isFreeValueAllowed = true;
    /**
     * Whether autocomplete is in readonly mode.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isReadonly = false;
    /**
     * Whether loading spinner is displayed in text input.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isLoading = false;
    /**
     * Whether autocomplete will display the selected values with chips.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) hasChips = false;
    /**
     * Whether autocomplete will get the data asynchronously.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isAsync = false;
    /**
     * Whether this chip is sorted on their label.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipsSorted = false;
    /**
     * Whether this item in the panel is sorted on their label.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isItemsSorted = false;
    /**
     * Whether the chip can be removed from the selection.
     * When a chip is removed, its value goes back in the panel.
     *
     * @default true
     */
    @Input({ transform: booleanAttribute }) isChipsRemovable = true;
    /**
     * Whether the chips can have multiple times the same value.
     * With this option, the value is not removed from the panel when choosen.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isDuplicateValueAllowed = false;
    /**
     * In combination with `hasChips`. Whether the chip is added when the text input is blurred.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isAddOnBlur  = false;
    /**
     * In combination with `hasChips` and `isFreeValueAllowed=false`. Whether the text input is empty after blurring when no value has been selected in the panel.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isForceSelection = false;
    /**
     * Whether a limited amount, defined by this option, is used to display the chips.
     */
    @Input({ transform: numberAttribute }) maxVisibleChipsCount = null;
    /**
     * Whether the chips label length is limited by the value of this option.
     */
    @Input({ transform: numberAttribute }) chipsLabelTruncateCount = null;
    /**
     * In combination with `maxVisibleChipsCount`. Whether all chips are shown by default.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isMaxVisibleChipsOpened = false;
    /**
     * Whether the chips can be drag and dropped.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipsDragAndDrop = false;

    public autocompleteOptions = new BehaviorSubject<EuiAutoCompleteItem[]>(this.autocompleteData);
    public selectedOptionIndex = 0;
    public autocompleteControl = new FormControl<string>('');
    public isDisabled = false;
    public chips: EuiChip[] = [];
    public distinctOptionGroups: string[];
    public groupedOptions = new BehaviorSubject<{ [id: string]: { options: EuiAutoCompleteItem[], ancestorLength: number } }>({});
    public globalOptionIndex = 0;
    public itemSize = 40;
    public autocompleteOptionTemplate: TemplateRef<{ $implicit: EuiAutoCompleteItem }>;
    public autocompleteOptGroupTemplate: TemplateRef<{ $implicit: { label: string } }>;

    @ContentChildren(EuiTemplateDirective) templates: QueryList<EuiTemplateDirective>;

    @ViewChild('templatePortalContent') templatePortalContent: TemplateRef<ElementRef>;
    @ViewChild('inputContainerRef') inputContainerRef: ElementRef;
    @ViewChild('virtualScrolling') virtualScrolling: CdkVirtualScrollViewport;
    @ViewChild('input', { read: ElementRef }) input: ElementRef;

    /**
     * Event emitted when the panel is closed.
     */
    @Output() panelClose = new EventEmitter();
    /**
     * Event emitted when the panel is opened.
     */
    @Output() panelOpen = new EventEmitter();
    /**
     * Event emitted when the text input gets the focus.
     */
    @Output() inputFocus = new EventEmitter();
    /**
     * Event emitted when the text input is blurred.
     */
    @Output() inputBlur = new EventEmitter();
    /**
     * Event emitted when the text input is cleared.
     */
    @Output() clear = new EventEmitter();
    /**
     * Event emitted when an option is selected or when the selection is modified.
     */
    @Output() selectionChange = new EventEmitter<EuiAutoCompleteItem[]>();
    /**
     * Event emitted when an option is selected.
     */
    @Output() itemAdd = new EventEmitter<EuiAutoCompleteItem>();
    /**
     * Event emitted when an option is removed.
     */
    @Output() itemRemove = new EventEmitter<EuiAutoCompleteItem>();
    /**
     * Event emitted when the value of the text input changes.
     */
    @Output() inputChange = new EventEmitter<string>();
    /**
     * Event emitted when a chip drag starts.
     */
    @Output() chipDragStart = new EventEmitter<EuiChipDragDrop>();
    /**
     * Event emitted when a chip drag is released.
     */
    @Output() chipDragRelease = new EventEmitter<EuiChipDragDrop>();
    /**
     * Event emitted when a chip is dropped.
     */
    @Output() chipDrop = new EventEmitter<EuiChipDragDrop>();

    protected hasAriaRequiredAttribute: boolean;
    private destroy$: Subject<boolean> = new Subject<boolean>();
    private overlayRef: OverlayRef;
    private isOpen$ = new BehaviorSubject<boolean>(false);
    private templatePortal: TemplatePortal<unknown>;
    private keyboardOptionSelectorHandlerSubscription = new Subscription();
    private addOnBlurClickHandlerSubscription = new Subscription();
    private isForceSelectionSubscription = new Subscription();
    private keyboardSubscription = new Subscription();
    private autocompleteOptionsSubscription = new Subscription();
    private scrollDispatcherSubscription = new Subscription();
    private windowResizeSubscription = new Subscription();
    private value: EuiAutoCompleteItem | EuiAutoCompleteItem[] = null;
    private TOP = new ConnectionPositionPair({ originX: 'start', originY: 'top' }, { overlayX: 'start', overlayY: 'bottom' }, 0, 0, [
        'eui-autocomplete-position',
        'eui-autocomplete-position--top',
    ]);
    private BOTTOM = new ConnectionPositionPair({ originX: 'start', originY: 'bottom' }, { overlayX: 'start', overlayY: 'top' }, 0, 0, [
        'eui-autocomplete-position',
        'eui-autocomplete-position--bottom',
    ]);
    private preferredPositons: ConnectionPositionPair[] = [this.BOTTOM, this.TOP];
    private overlay = inject(Overlay);
    private cd = inject(ChangeDetectorRef);
    private viewContainerRef = inject(ViewContainerRef);
    private elementRef = inject(ElementRef);
    private liveAnnouncer = inject(LiveAnnouncer);
    private scrollDispatcher = inject(ScrollDispatcher);
    private euiAppShellService = inject(EuiAppShellService);
    private baseStatesDirective = inject(BaseStatesDirective);
    private control = inject(NgControl, { self: true, optional: true })!;
    private platformId = inject(PLATFORM_ID);

    constructor() {
        if (this.control) {
            this.control.valueAccessor = this;
        }
    }

    ngOnChanges(c: SimpleChanges): void {
        if (c && c.autocompleteData) {
            this.setOptions('', this.isItemsSorted);
        }

        if (c && c.autocompleteDataSelected && this.hasChips) {
            this.autocompleteDataSelected = c.autocompleteDataSelected.currentValue.map((s: EuiAutoCompleteItem) => ({ ...s, euiInternalId: crypto.randomUUID() }));
            this.chips = this.mapToChip(this.autocompleteDataSelected);
            this.setOptions('', this.isItemsSorted);
        }
    }

    ngOnInit(): void {
        this.euiAppShellService.state$.pipe(takeUntil(this.destroy$)).subscribe((state) => {
            this.itemSize = state.appBaseFontSize === '16px' ? 40 : 35;
        });

        if (this.control) {
            this.updateInputAriaRequiredAttribute(this.control);
            this.control.valueChanges.pipe(takeUntil(this.destroy$)).subscribe((value) => {
                this.updateInputAriaRequiredAttribute(this.control);
            });
        }

        this.autocompleteControl.valueChanges.pipe(takeUntil(this.destroy$)).subscribe((value: string) => {
            this.selectedOptionIndex = 0;
            if (!this.isOpen) {
                this.openPanel();
            }

            this.setOptions(value, this.isItemsSorted);

            if (this.hasChips) {
                if (!value) {
                    this.onChange(this.autocompleteDataSelected.length > 0 ? this.autocompleteDataSelected : null);
                }
            } else {
                if (typeof value === 'string') {
                    const foundItem = this.autocompleteData.find((d) => d.label.toLowerCase().trim() === value.toLowerCase().trim());

                    if (foundItem) {
                        this.onChange(foundItem);
                    } else {
                        // eslint-disable-next-line
                        value ? this.onChange({ label: value }) : this.onChange(null);
                    }
                } else {
                    this.onChange(value === undefined ? null : value);
                    if (!value) {
                        this.setOptions('', this.isItemsSorted);
                    }
                }
            }

            this.inputChange.emit(value as string);
        });

        if (!this.isAsync) {
            this.setOptions(Array.isArray(this.value) ? '' : this.value?.label, this.isItemsSorted);
        }
    }

    ngDoCheck(): void {
        if (this.control) {
            // eslint-disable-next-line
            this.control.touched ? this.autocompleteControl.markAsTouched() : this.autocompleteControl.markAsUntouched();
            // eslint-disable-next-line
            this.control.invalid ? this.autocompleteControl.setErrors(this.control.errors) : this.autocompleteControl.setErrors(null);
            this.cd.detectChanges();
        }
    }

    ngAfterViewInit(): void {
        this.templatePortal = new TemplatePortal(this.templatePortalContent, this.viewContainerRef);

        this.templates.forEach((item) => {
            if (item.getType() === 'dropdownOption') {
                this.autocompleteOptionTemplate = item.template;
            }
            if (item.getType() === 'dropdownOptGroup') {
                this.autocompleteOptGroupTemplate = item.template;
            }
        });
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
        this.keyboardOptionSelectorHandlerSubscription.unsubscribe();
        this.addOnBlurClickHandlerSubscription.unsubscribe();
        this.isForceSelectionSubscription.unsubscribe();
        this.keyboardSubscription.unsubscribe();
        this.autocompleteOptionsSubscription.unsubscribe();
        this.windowResizeSubscription.unsubscribe();
    }

    /**
     * Calculates the height that the virtual scroll need to have.
     *
     * @type {number}
     */
    get cdkVirtualScrollViewport(): number {
        if (this.groupBy) {
            const filteredOptionGroups: string[] = this.autocompleteOptions.value
                .map(item => this.groupBy.split('.').reduce((prev, curr) => (prev ? prev[curr] : null), item || self))
                .filter((optionGroup: string) => {
                    return (
                        this.autocompleteOptions.value.some(
                            (option) => this.groupBy.split('.').reduce((prev, curr) => (prev ? prev[curr] : null), option || self) === optionGroup,
                        )
                    );
                })
                .filter((optionGroup: string, index, array: string[]) => array.indexOf(optionGroup) === index);

            if (this.autocompleteOptions.value.length >= this.visibleOptions) {
                return this.visibleOptions * this.itemSize;
            } else {
                const scrollItems = this.autocompleteOptions.value.length + filteredOptionGroups.length;
                return (scrollItems > this.visibleOptions ? this.visibleOptions : scrollItems) * this.itemSize;
            }
        } else {
            return this.autocompleteOptions.value.length >= this.visibleOptions ?
                this.visibleOptions * this.itemSize :
                this.autocompleteOptions.value.length * this.itemSize;
        }
    }

    /**
     * Returns the opening state of the panel.
     *
     * @type {boolean}
     */
    get isOpen(): boolean {
        return this.isOpen$.value;
    }

    /**
     * Checks if autocomplete options are available.
     *
     * @returns {boolean} `true` if options are present, otherwise `false`.
     */
    get hasOptionsResult(): boolean {
        return this.autocompleteOptions.value.length > 0;
    }

    /**
     * Method that creates and opens the panel containing autocomplete options.
     */
    public openPanel(): void {
        if (!this.isOpen && !this.isReadonly) {
            this.scrollDispatcherSubscription = this.scrollDispatcher
                .ancestorScrolled(this.input)
                .pipe(takeUntil(this.destroy$))
                .subscribe((event: CdkScrollable) => {
                    if(isPlatformBrowser(this.platformId)) {
                        const scrollableParent = event ? event.getElementRef().nativeElement : document.querySelector('body');
                        if (!this.isVisible(this.input.nativeElement, scrollableParent)) {
                            this.closePanel();
                        }
                    }
                });

            this.windowResizeSubscription = fromEvent(window, 'resize')
                .pipe(takeUntil(this.destroy$))
                .subscribe(() => {
                    if (this.overlayRef && this.overlayRef.hasAttached() && !this.panelWidth) {
                        this.overlayRef.updateSize({
                            width: this.inputContainerRef.nativeElement.clientWidth,
                        });
                    }
                });

            const positionStrategy = this.getPositionStrategy();
            const scrollStrategy = this.getScrollStrategy();

            this.overlayRef = this.overlay.create({
                hasBackdrop: false,
                positionStrategy,
                scrollStrategy,
                disposeOnNavigation: true,
                width: this.panelWidth ? this.panelWidth : this.inputContainerRef.nativeElement.clientWidth,
                panelClass: ['eui-autocomplete__panel-container', this.classList],
            });
            this.overlayRef.attach(this.templatePortal);

            document.querySelectorAll('.cdk-overlay-container')?.forEach(el => {
                if (!el.classList.contains('eui-19')) {
                    el.classList.add('eui-19');
                }
            });

            this.overlayRef
                .outsidePointerEvents()
                .pipe(takeUntil(this.destroy$))
                .subscribe((e) => {
                    const targetElement = e.target as HTMLElement;
                    const clearElement = this.elementRef.nativeElement.querySelector('.eui-sprite-eui-close');
                    const isElementOrChildOfElement = (element: HTMLElement, parentElement: HTMLElement): boolean => {
                        while (element) {
                            if (element === parentElement) {
                                return true;
                            }
                            element = element.parentElement;
                        }
                        return false;
                    };

                    const isClearableButton = targetElement.classList.contains('eui-sprite-eui-close');
                    const isInput = targetElement.classList.contains('eui-autocomplete__input');

                    if (!isClearableButton && !isInput && !isElementOrChildOfElement(targetElement, clearElement)) {
                        this.closePanel();
                    }

                    if (isClearableButton && !this.elementRef.nativeElement.contains(targetElement)) {
                        this.closePanel();
                    }

                    if (isInput && !this.elementRef.nativeElement.contains(targetElement)) {
                        this.closePanel();
                    }

                    if ((e.target as HTMLElement).classList.contains('eui-autocomplete__input')) {
                        e.stopPropagation();
                    }
                });
            this.overlayRef
                .keydownEvents()
                .pipe(takeUntil(this.destroy$))
                .subscribe((keyboardEvent) => {
                    if (keyboardEvent.key?.toLowerCase() === 'escape') {
                        this.closePanel();
                    }
                });

            this.autocompleteOptionsSubscription = this.autocompleteOptions.subscribe((autocompleteOptions) => {
                this.overlayRef.removePanelClass('eui-autocomplete__panel-container--no-option');
                if (autocompleteOptions.length === 0) {
                    this.selectedOptionIndex = 0;
                    this.overlayRef.addPanelClass('eui-autocomplete__panel-container--no-option');
                }
            });

            const liveAnnouncerSource = this.groupBy ? Object.values(this.groupedOptions.value).flatMap(group => group.options) : this.autocompleteOptions.value;

            this.liveAnnouncer.clear();
            this.liveAnnouncer.announce(liveAnnouncerSource[0]?.label);

            let visibleRangeStart = 0;
            let visibleRangeEnd = this.visibleOptions - 1;
            this.keyboardOptionSelectorHandlerSubscription = fromEvent(this.input.nativeElement, 'keydown')
                .pipe(
                    filter((e: KeyboardEvent) => e.code === 'ArrowDown' || e.code === 'ArrowUp' || e.code === 'Enter' || e.code === 'Tab'),
                    takeUntil(this.destroy$),
                )
                .subscribe((e: KeyboardEvent) => {
                    if (e) {
                        if (e.code === 'ArrowDown' && this.selectedOptionIndex < this.autocompleteOptions.value.length - 1) {
                            this.selectedOptionIndex++;
                            this.cd.detectChanges();

                            const liveAnnouncerSource = this.groupBy ? Object.values(this.groupedOptions.value).flatMap(group => group.options) : this.autocompleteOptions.value;

                            this.liveAnnouncer.clear();
                            this.liveAnnouncer.announce(liveAnnouncerSource[this.selectedOptionIndex].label);

                            e.preventDefault();
                        }
                        if (e.code === 'ArrowUp' && this.selectedOptionIndex > 0) {
                            this.selectedOptionIndex--;
                            this.cd.detectChanges();

                            const liveAnnouncerSource = this.groupBy ? Object.values(this.groupedOptions.value).flatMap(group => group.options) : this.autocompleteOptions.value;

                            this.liveAnnouncer.clear();
                            this.liveAnnouncer.announce(liveAnnouncerSource[this.selectedOptionIndex].label);

                            e.preventDefault();
                        }

                        const cIndex = this.selectedOptionIndex - this.virtualScrolling?.getRenderedRange().start;

                        if (e.code === 'ArrowDown' && cIndex > visibleRangeEnd - visibleRangeStart - visibleRangeEnd) {
                            let nbOptionsGroup = 0;
                            const nbOptions = this.autocompleteOptions.value.length;
                            if (this.groupBy) {
                                Object.keys(this.groupedOptions.value).forEach(groupedOption => {
                                    if (this.groupedOptions.value[groupedOption].options.length > 0 &&
                                        this.selectedOptionIndex > this.groupedOptions.value[groupedOption].ancestorLength - 1) {
                                        nbOptionsGroup ++;
                                    }
                                });
                            }

                            if ((this.selectedOptionIndex + nbOptionsGroup) > visibleRangeEnd && visibleRangeEnd <= (nbOptions + nbOptionsGroup)) {
                                this.virtualScrolling.scrollToIndex((this.selectedOptionIndex + nbOptionsGroup) - visibleRangeEnd + visibleRangeStart);
                                visibleRangeStart++;
                                visibleRangeEnd++;
                            }
                        }
                        if (e.code === 'ArrowUp' && cIndex < visibleRangeStart) {
                            if (this.selectedOptionIndex < visibleRangeStart) {
                                this.virtualScrolling.scrollToIndex(this.selectedOptionIndex);
                                visibleRangeStart--;
                                visibleRangeEnd--;
                            }
                        }
                        if (e.code === 'Enter') {
                            if (this.hasOptionsResult) {
                                if (this.groupBy) {
                                    const options = [].concat(...Object.values(this.groupedOptions.value).map(group => group.options));
                                    this.onOptionSelected(options[this.selectedOptionIndex]);
                                } else {
                                    this.onOptionSelected(this.autocompleteOptions.value[this.selectedOptionIndex]);
                                }
                            } else if (this.hasChips && this.isFreeValueAllowed) {
                                this.add(this.autocompleteControl.value);
                            }
                        }
                        if (e.code === 'Tab') {
                            if (this.isOpen) {
                                if (this.isAddOnBlur  && this.hasChips && this.autocompleteControl.value?.trim().length > 0) {
                                    this.add(this.autocompleteControl.value.trim());
                                }
                                if (this.isForceSelection) {
                                    const foundItem = this.autocompleteData.find((d) => d.label.toLowerCase().trim() === this.autocompleteControl.value?.toLowerCase().trim());
                                    if (this.hasChips || (!this.hasChips && !foundItem)) {
                                        this.input.nativeElement.value = '';
                                        this.autocompleteControl.setValue(null, { emitEvent: false });
                                        this.setOptions('', this.isItemsSorted);

                                        if (!this.hasChips) {
                                            this.autocompleteDataSelected = [];
                                        }
                                    }
                                }
                                this.closePanel();
                            }
                        }
                    }
                });

            this.addOnBlurClickHandlerSubscription.unsubscribe();
            if (this.isAddOnBlur) {
                this.addOnBlurClickHandlerSubscription = fromEvent(document, 'click').pipe(takeUntil(this.destroy$)).subscribe((event: PointerEvent) => {
                    if (!(event.target as HTMLElement).classList.contains('eui-autocomplete-option') && this.hasChips && this.autocompleteControl.value?.trim().length > 0) {
                        this.add(this.autocompleteControl.value.trim());
                    }
                });
            }

            this.isForceSelectionSubscription.unsubscribe();
            if (this.isForceSelection) {
                this.isForceSelectionSubscription = fromEvent(document, 'click').pipe(takeUntil(this.destroy$)).subscribe((event: PointerEvent) => {
                    if (!(event.target as HTMLElement).classList.contains('eui-autocomplete-option')) {
                        const foundItem = this.autocompleteData.find((d) => d.label.toLowerCase().trim() === this.autocompleteControl.value?.toLowerCase().trim());
                        if (this.hasChips || (!this.hasChips && !foundItem)) {
                            this.input.nativeElement.value = '';
                            this.autocompleteControl.setValue(null, { emitEvent: false });
                            this.setOptions('', this.isItemsSorted);

                            if (!this.hasChips) {
                                this.autocompleteDataSelected = [];
                            }
                        } 
                    }
                });
            }

            this.isOpen$.next(true);
            this.panelOpen.emit();
        }
    }

    /**
     * Closes the autocomplete panel.
     */
    public closePanel(): void {
        this.selectedOptionIndex = 0;
        this.overlayRef.dispose();
        this.overlayRef = null;
        this.isOpen$.next(false);
        this.cd.detectChanges();
        this.keyboardOptionSelectorHandlerSubscription.unsubscribe();
        this.autocompleteOptionsSubscription.unsubscribe();
        this.scrollDispatcherSubscription.unsubscribe();
        this.windowResizeSubscription.unsubscribe();
        this.panelClose.emit();
    }

    /**
     * Method called when an option is selected.
     *
     * @param e Selected option
     */
    public onOptionSelected(e: EuiAutoCompleteItem): void {
        if (!e.isDisabled) {
            if (this.hasChips) {
                this.autocompleteDataSelected.push({ ...e, euiInternalId: crypto.randomUUID() });
                this.chips = this.mapToChip(this.autocompleteDataSelected);
                this.input.nativeElement.value = '';
                this.autocompleteControl.setValue(null);
                this.setOptions('', this.isItemsSorted);
            } else {
                this.autocompleteDataSelected = [e];
                this.input.nativeElement.value = e.label;
                this.autocompleteControl.setValue(e.label);
            }

            this.addOnBlurClickHandlerSubscription.unsubscribe();
            this.isForceSelectionSubscription.unsubscribe();

            this.selectionChange.emit(this.autocompleteDataSelected);
            this.itemAdd.emit(e);
            this.closePanel();
        }
    }

    /**
     * Method called when an option is added through the text input.
     *
     * @param value Value to add
     */
    public add(value: string): void {
        if (!value || (!this.isFreeValueAllowed && !this.autocompleteData.find(a => a.label === value.trim()))) {
            return;
        }

        if (!this.isDuplicateValueAllowed && this.autocompleteDataSelected.some(s => s.label.trim() === value.trim())) {
            return;
        }

        const item = this.autocompleteData.find(a => a.label === value.trim()) || { label: value.trim(), euiInternalId: crypto.randomUUID() };

        this.autocompleteDataSelected.push(item);
        this.chips = this.mapToChip(this.autocompleteDataSelected);
        this.input.nativeElement.value = '';
        this.autocompleteControl.setValue(null);
        this.closePanel();

        this.addOnBlurClickHandlerSubscription.unsubscribe();
        this.isForceSelectionSubscription.unsubscribe();

        this.selectionChange.emit(this.autocompleteDataSelected);
        this.itemAdd.emit(item);
    }

    public optionsTrackByFn(index: number, item: EuiAutoCompleteItem): string | number {
        return item.id;
    }

    public writeValue(value: EuiAutoCompleteItem | EuiAutoCompleteItem[]): void {
        this.value = value;

        if (this.hasChips) {
            this.autocompleteDataSelected = value ? ([...value as EuiAutoCompleteItem[]]) : [];
            this.chips = this.mapToChip(this.autocompleteDataSelected);
            this.autocompleteControl.patchValue(null, { emitEvent: false });
            this.setOptions('', this.isItemsSorted);
        } else {
            this.autocompleteControl.patchValue(value ? (value as EuiAutoCompleteItem).label : null, { emitEvent: false });
            const inputValue = value ? (value as EuiAutoCompleteItem).label : null;
            this.setOptions(inputValue, this.isItemsSorted);
        }
    }

    public setDisabledState(isDisabled: boolean): void {
        // eslint-disable-next-line
        this.isDisabled = isDisabled;
        // eslint-disable-next-line
        isDisabled ? this.autocompleteControl.disable() : this.autocompleteControl.enable();

        if (this.isOpen) {
            this.closePanel();
        }

        this.cd.detectChanges();
    }

    public registerOnChange(fn: () => void): void {
        this.onChange = fn;
    }

    public registerOnTouched(fn: () => void): void {
        this.onTouch = fn;
    }

    public onClear(): void {
        this.clear.emit();
    }

    /**
     * Text input focus handler.
     */
    public onFocus(): void {
        this.keyboardSubscription = fromEvent(this.input.nativeElement, 'keydown')
            .pipe(
                filter((event: KeyboardEvent) =>
                    /^[a-zA-Z0-9]$/.test(event.key) ||
                    event.key === 'Space' ||
                    event.key === 'ArrowDown' ||
                    event.key === 'Backspace',
                    ),
                )
            .subscribe((event: KeyboardEvent) => {
                if (!this.isOpen) {
                    this.openPanel();
                    event.stopPropagation();
                }

                if (this.chipsPosition === 'inside' && event.key === 'Backspace' && (!this.autocompleteControl.value || this.autocompleteControl.value.length === 0)) {
                    const removed = this.chips.pop();
                    this.onChipRemove({ chips: [...this.chips], removed });

                    this.cd.detectChanges();

                    this.overlayRef.updateSize({ width: this.inputContainerRef.nativeElement.clientWidth });
                    this.overlayRef.updatePosition();
                }
            });

        if (!this.isOpen) {
            this.openPanel();
        }

        this.inputFocus.emit();
    }

    /**
     * Text input blur handler.
     */
    public onBlur(): void {
        this.keyboardSubscription.unsubscribe();
        this.inputBlur.emit();
        this.onTouch();
    }

    /**
     * Called when a chip is removed.
     *
     * @param e Object containing the chip to remove.
     */
    public onChipRemove(e: { chips: EuiChip[]; removed: EuiChip | { chip: EuiChip; event: Event } }): void {
        const event = e as { chips: EuiChip[]; removed: EuiChip };
        const itemRemoved = this.autocompleteDataSelected.find(i => i.id === event.removed.id);

        this.autocompleteDataSelected = this.autocompleteDataSelected
            .filter(i => event.chips.find(c => c.id === i.id))
            .filter(i => event.chips.find(c => c.euiInternalId === i.euiInternalId));
        this.chips = this.mapToChip(this.autocompleteDataSelected);

        this.setOptions('', this.isItemsSorted);

        this.onChange(this.autocompleteDataSelected.length > 0 ? this.autocompleteDataSelected : null);
        this.selectionChange.emit(this.autocompleteDataSelected);
        this.itemRemove.emit(itemRemoved);
    }

    /**
     * Called when a chip is dropped for reordering or from a source to another.
     *
     * @param e Object containing the chip dropped.
     */
    public onChipDropped(e: EuiChipDragDrop): void {
        const data = this.autocompleteData;
        this.autocompleteDataSelected = e.chips.map(c => data.find((a) => a.id === c.id));

        this.chips = this.mapToChip(this.autocompleteDataSelected);
        this.autocompleteOptions.next(this.filterOptions(''));

        this.onChange(this.autocompleteDataSelected.length > 0 ? this.autocompleteDataSelected : null);
        this.selectionChange.emit(this.autocompleteDataSelected);

        this.chipDrop.emit(e);
    }

    /**
     * Called when a chip is dragged for reordering or from a source to another.
     *
     * @param e Object containing the chip dragged.
     */
    public onChipDragStarted(e: EuiChipDragDrop): void {
        this.chipDragStart.emit(e);
    }

    /**
     * Called when a chip is released for reordering or from a source to another.
     *
     * @param e Object containing the chip released.
     */
    public onChipDragReleased(e: EuiChipDragDrop): void {
        this.chipDragRelease.emit(e);
    }

    /**
     * Calculates the item size for virtual scrolling.
     *
     * @returns a number representing the item size.
     */
    private getItemSize(): number {
        const optionHeight = this.overlayRef?.hostElement?.querySelector('.eui-autocomplete__panel')?.querySelectorAll('.eui-autocomplete-option')[0]?.clientHeight + 1;
        return optionHeight || 48;
    }

    /**
     * Re-order options panel based on the input valuea and sort order.
     *
     * @param value Value to filter the options.
     * @param isItemsSorted If the items are sorted.
     */
    private setOptions(value: string, isItemsSorted: boolean): void {
        this.autocompleteOptions.next(isItemsSorted ? (this.orderArray(this.filterOptions(value), this.itemsSortOrder)) : this.filterOptions(value));

        if (this.groupBy) {
            const { groupedOptions, distinctOptionGroups } = this.groupingHandler(this.autocompleteOptions.value, this.groupBy);

            this.groupedOptions.next(groupedOptions);
            this.distinctOptionGroups = distinctOptionGroups;
        }
    }

    /**
     * Return the position strategy for the panel.
     *
     * @returns A CDK position strategy.
     */
    private getPositionStrategy(): PositionStrategy {
        return this.overlay
            .position()
            .flexibleConnectedTo(this.inputContainerRef.nativeElement as FlexibleConnectedPositionStrategyOrigin)
            .withPositions(this.preferredPositons)
            .withFlexibleDimensions(false)
            .withLockedPosition(true);
    }

    /**
     * Return the scroll strategy for the panel.
     *
     * @returns A CDK scroll strategy.
     */
    private getScrollStrategy(): RepositionScrollStrategy {
        return this.overlay.scrollStrategies.reposition({ scrollThrottle: 10 });
    }

    /**
     * Refine the options based on the input value.
     *
     * @param inputValue Value to filter the options.
     * @returns An array of options.
     */
    private filterOptions(inputValue: string): EuiAutoCompleteItem[] {
        let data: EuiAutoCompleteItem[] = [];
        if (inputValue) {
            data = this.autocompleteData.filter((autocompleteItem) => {
                if (
                    this.matching === 'contains' &&
                    autocompleteItem.label.toLowerCase().indexOf(inputValue.toString().toLowerCase()) !== -1
                ) {
                    return autocompleteItem;
                }
                if (
                    this.matching === 'startWith' &&
                    autocompleteItem.label.toLowerCase().substr(0, inputValue.toString().length) === inputValue.toLowerCase()
                ) {
                    return autocompleteItem;
                }
            });
        } else {
            data = this.autocompleteData;
        }

        if (this.hasChips) {
            data = data.filter(d => !this.isDuplicateValueAllowed ? !this.autocompleteDataSelected.some(selectedItem => d.id === selectedItem.id) : true);
        }

        if (this.isItemsSorted) {
            data = this.orderArray(data, this.itemsSortOrder);
        }

        return data;
    }

    /**
     * Converts EuiAutoCompleteItem array to EuiChip array.
     *
     * @param items Array of EuiAutoCompleteItem.
     * @returns An array of EuiChip
     */
    private mapToChip(items: EuiAutoCompleteItem[]): EuiChip[] {
        const chips = items.map((selected) => {
            return new EuiChip({
                id: selected.id,
                euiInternalId: selected.euiInternalId,
                label: selected.label,
                typeClass: selected.typeClass,
                isOutline: selected.isOutline,
                isRounded: selected.isRounded,
                sizeClass: selected.sizeClass,
                isRemovable: selected.isRemovable,
                tooltipMessage: selected.tooltip?.tooltipMessage,
                tooltip: new EuiChipTooltip(selected.tooltip),
                iconClass: selected.iconClass,
                iconSvgName: selected.iconSvgName,
            });
        });

        return this.isChipsSorted && chips.length > 0 ? (this.orderArray(chips, this.chipsSortOrder) as EuiChip[]) : chips;
    }

    /**
     * Sort an array of objects based on their label.
     *
     * @param tab Array to order
     * @param sortOrder Sort order criteria
     * @returns A sorted array
     */
    private orderArray<T extends { label: string; }>(tab: T[], sortOrder: 'ASC' | 'DESC'): T[] {
        tab.sort((a: T, b: T) => {
            const aObj = a.label.toLowerCase();
            const bObj = b.label.toLowerCase();

            if (sortOrder === 'ASC') {
                if (aObj < bObj) {
                    return -1;
                }
                if (aObj > bObj) {
                    return 1;
                }
                return 0;
            } else {
                if (aObj > bObj) {
                    return -1;
                }
                if (aObj < bObj) {
                    return 1;
                }
                return 0;
            }
        });

        return tab;
    }

    /**
     * Transforms array of EuiAutoCompleteItem into a grouped object.
     *
     * @param options Array of EuiAutoCompleteItem
     * @param groupBy Label of the group
     * @returns An object containing the grouped options and the distinct option groups.
     */
    private groupingHandler(options: EuiAutoCompleteItem[], groupBy: string):
    { groupedOptions: { [id: string]: { options: EuiAutoCompleteItem[], ancestorLength: number } }, distinctOptionGroups: string[] } {
        const distinctGroups: string[] = this.autocompleteData.map(item => groupBy.split('.').reduce((prev, curr) => (prev ? prev[curr] : null), item || self));
        const distinctOptionGroups: string[] = [...new Set(distinctGroups)].sort((a: string, b: string) => (a > b ? 1 : -1));
        const groupedOptions: { [id: string]: { options: EuiAutoCompleteItem[], ancestorLength: number } } = {};

        let ancestorLength = 0;
        for (const group of distinctOptionGroups) {
            let o = options.filter(option => groupBy.split('.').reduce((prev, curr) => (prev ? prev[curr] : null), option || self) === group);
            if (this.isItemsSorted) {
                o = this.orderArray(o, this.itemsSortOrder) as EuiAutoCompleteItem[];
            }

            groupedOptions[group] = { options: o, ancestorLength };
            ancestorLength += o.length;
        }

        return { groupedOptions, distinctOptionGroups };
    }

    /**
     * Indicates if the origin element is visible in the scrollable parent.
     *
     * @param origin Origin of the autocomplete
     * @param scrollableParent Scrollable container
     * @returns A boolean, true if visible else false.
     */
    private isVisible(origin: HTMLElement, scrollableParent: HTMLElement): boolean {
        const originY = origin.getBoundingClientRect().y;
        const scrollableParentY = Math.abs(scrollableParent.getBoundingClientRect().y);
        const scrollableParentHeight = scrollableParent.getBoundingClientRect().height - 55;

        return (
            (originY > 0 && originY < scrollableParentHeight) ||
            (originY - scrollableParentY > 0 && originY < scrollableParentY + scrollableParentHeight)
        );
    }

    private onChange = <T>(change?: T): void => {
        /** empty */
    };

    private onTouch = (): void => {
        /** empty */
    };

    /**
     * Updates the `aria-required` attribute on the input element.
     * @private
     */
    private updateInputAriaRequiredAttribute(control: NgControl): void {
        this.hasAriaRequiredAttribute = control?.control?.hasValidator(Validators.required);
        this.cd.markForCheck();
    }
}
