import { Pipe, PipeTransform, NgModule } from '@angular/core';

@Pipe({
    name: 'euiTruncate',
})
export class EuiTruncatePipe implements PipeTransform {
    transform(value: string, limit = 40, trail = '\u2026'): string {
        if (value) {
            if (limit < 0) {
                limit *= -1;
                return value.length > limit ? trail + value.substring(value.length - limit, value.length) : value;
            } else {
                return value.length > limit ? value.substring(0, limit) + trail : value;
            }
        }
        return;
    }
}

/**
 * @description
 * Module that provides the EuiTruncatePipe pipe.
 *
 * @deprecated Use {@link EuiTruncatePipe} instead.
 */
@NgModule({
    imports: [EuiTruncatePipe],
    exports: [EuiTruncatePipe],
})
export class EuiTruncatePipeModule {}
