import { Action } from '../ngrx_kit';
import {
    CoreUserActionTypes,
    CoreUserActions,
    UpdateUserDashboardAction,
    UpdateUserStateAction,
    UpdateUserDetailsAction,
    UpdateUserPreferencesAction,
    UpdateUserRightsAction,
} from '../actions';
import { UserState, initialUserState, UserPreferences } from '@eui/base';

const updateUser = (state: UserState, action: UpdateUserStateAction): UserState => {
    let fullName = action.payload.fullName;
    if (!fullName) {
        fullName = `${action.payload.firstName || ''} ${action.payload.lastName || ''}`.trim();
    }
    return Object.assign({}, state, action.payload, { fullName });
};

const updateUserDetails = (state: UserState, action: UpdateUserDetailsAction): UserState => {
    let fullName = action.payload.fullName;
    if (!fullName) {
        fullName = `${action.payload.firstName || ''} ${action.payload.lastName || ''}`.trim();
    }
    // todo should be checked if state.details is really there
    const details = Object.assign({}, state['details'], action.payload, { fullName });
    return Object.assign({}, state, details);
};

const updateUserPreferences = (state: UserState, action: UpdateUserPreferencesAction): UserState => {
    const preferences = Object.assign({}, state.preferences, action.payload);
    return Object.assign({}, state, { preferences });
};

const updateUserRights = (state: UserState, action: UpdateUserRightsAction): UserState =>
    Object.assign({}, state, { rights: [...action.payload] });

const updateUserDashboard = (state: UserState, action: UpdateUserDashboardAction): UserState & { preferences: UserPreferences } => {
    // apply the dashboard to preferences
    const preferences = Object.assign({}, state.preferences, { dashboard: action.payload });
    // update the state
    return { ...state, preferences };
};

const actionToReducerMap: { [key: string]: (state: UserState, action: CoreUserActions) => UserState } = {
    [CoreUserActionTypes.UPDATE_USER_DETAILS]: updateUserDetails,
    [CoreUserActionTypes.UPDATE_USER_PREFERENCES]: updateUserPreferences,
    [CoreUserActionTypes.UPDATE_USER_STATE]: updateUser,
    [CoreUserActionTypes.UPDATE_USER_RIGHTS]: updateUserRights,
    [CoreUserActionTypes.UPDATE_USER_DASHBOARD]: updateUserDashboard,
};

/**
 * @deprecated it will be removed in the next major version
 */
export const coreUserReducers: (state: UserState, action: Action) => UserState = (state = initialUserState, action: CoreUserActions) => {
    if (actionToReducerMap[action.type]) {
        return actionToReducerMap[action.type](state, action);
    }
    return state;
};
