import {
    Component,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    OnInit,
    ComponentRef,
    inject,
    Injector,
    StaticProvider,
    OnDestroy,
    HostBinding,
    ChangeDetectorRef,
} from '@angular/core';
import {
    CdkPortalOutletAttachedRef,
    ComponentPortal,
    ComponentType,
    PortalModule,
    TemplatePortal,
} from '@angular/cdk/portal';
import { BehaviorSubject, Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

import { DIALOG_CONTAINER_CONFIG } from '../services/eui-dialog.token';
import { EuiDialogInterface, EuiDialogComponentInstances } from '../models/eui-dialog.config';
import { DIALOG_COMPONENT_CONFIG } from '../services/eui-dialog.token';
import { TranslateModule } from '@ngx-translate/core';
import { OverlayModule } from '@angular/cdk/overlay';
import { A11yModule } from '@angular/cdk/a11y';
import { DragDropModule } from '@angular/cdk/drag-drop';
import { CdkScrollableModule } from '@angular/cdk/scrolling';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_ICON_STATE } from '@eui/components/eui-icon-state';
import { AsyncPipe } from '@angular/common';

@Component({
    selector: 'eui-dialog-container',
    templateUrl: './eui-dialog-container.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    styleUrl: '../eui-dialog.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        TranslateModule,
        PortalModule,
        OverlayModule,
        A11yModule,
        DragDropModule,
        CdkScrollableModule,
        ...EUI_BUTTON,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
        ...EUI_ICON_STATE,
    ],
})
export class EuiDialogContainerComponent<HC, HCC, BC, BCC, FC, FCC> implements OnInit, OnDestroy {
    cd = inject(ChangeDetectorRef);
    dialogContainerConfig = inject<EuiDialogInterface<HC, HCC, BC, BCC, FC, FCC>>(DIALOG_CONTAINER_CONFIG);
    public isHeaderTemplatePortal = false;
    public isBodyTemplatePortal = false;
    public isFooterTemplatePortal = false;

    public isHeaderComponentPortal = false;
    public isBodyComponentPortal = false;
    public isFooterComponentPortal = false;

    public headerComponentPortal: ComponentPortal<HC>;
    public bodyComponentPortal: ComponentPortal<BC>;
    public footerComponentPortal: ComponentPortal<FC>;

    public componentInstances = new EuiDialogComponentInstances<HC, BC, FC>();
    public acceptButtonDisabled$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
    public dismissButtonDisabled$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);

    @HostBinding('class') string = 'eui-dialog-container';
    @HostBinding('attr.aria-modal') ariaModal = true;

    private destroy$: Subject<boolean> = new Subject<boolean>();
    private injector = inject(Injector);

    ngOnInit(): void {
        if (this.dialogContainerConfig.header instanceof TemplatePortal) {
            this.isHeaderTemplatePortal = true;
        }
        if (this.dialogContainerConfig.content instanceof TemplatePortal) {
            this.isBodyTemplatePortal = true;
        }
        if (this.dialogContainerConfig.footer instanceof TemplatePortal) {
            this.isFooterTemplatePortal = true;
        }

        if (this.dialogContainerConfig.headerComponent?.component) {
            this.isHeaderComponentPortal = true;
            this.headerComponentPortal = this.createComponentPortal(
                this.dialogContainerConfig.headerComponent.component,
                this.dialogContainerConfig.headerComponent.config,
            ) as ComponentPortal<HC>;
        }
        if (this.dialogContainerConfig.bodyComponent?.component) {
            this.isBodyComponentPortal = true;
            this.bodyComponentPortal = this.createComponentPortal(
                this.dialogContainerConfig.bodyComponent.component,
                this.dialogContainerConfig.bodyComponent.config,
            ) as ComponentPortal<BC>;
        }
        if (this.dialogContainerConfig.footerComponent?.component) {
            this.isFooterComponentPortal = true;
            this.footerComponentPortal = this.createComponentPortal(
                this.dialogContainerConfig.footerComponent.component,
                this.dialogContainerConfig.footerComponent.config,
            ) as ComponentPortal<FC>;
        }

        this.dialogContainerConfig.open();
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    get getComponentInstances(): EuiDialogComponentInstances<HC, BC, FC> {
        return this.componentInstances;
    }

    get getPortalOutlet(): TemplatePortal | null {
        return this.dialogContainerConfig.content as TemplatePortal;
    }

    get dialogContainerConfigContent(): string {
        return this.dialogContainerConfig.content as string;
    }

    public portalAttached(
        attachedRef: CdkPortalOutletAttachedRef,
        component: 'headerComponent' | 'bodyComponent' | 'footerComponent',
    ): void {
        const componentRef = attachedRef as ComponentRef<HC | BC | FC>;

        componentRef.instance['overlayRef'] = this.dialogContainerConfig.overlayRef;

        this.componentInstances = {
            ...this.componentInstances,
            [component]: componentRef.instance,
        };

        this.dialogContainerConfig.init(this.componentInstances);

        if (this.dialogContainerConfig[component].config) {
            Object.keys(this.dialogContainerConfig[component].config).forEach((c) => {
                if (typeof this.dialogContainerConfig[component].config[c] === 'function') {
                    if (componentRef.instance[c] && typeof componentRef.instance[c] !== 'function') {
                        // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
                        // eslint-disable-next-line @typescript-eslint/no-explicit-any
                        componentRef.instance[c].pipe(takeUntil(this.destroy$)).subscribe((args: any) => {
                            this.dialogContainerConfig[component].config[c].apply(componentRef.instance[c], [args]);
                        });
                    }
                } else {
                    componentRef.instance[c] = this.dialogContainerConfig[component].config[c];
                }
            });
        }
    }

    public closeDialog(): void {
        this.dialogContainerConfig.close(this.componentInstances);
    }

    public onDismiss(): void {
        this.dialogContainerConfig.dismiss(this.componentInstances);
        if (!this.dialogContainerConfig.isHandleCloseOnDismiss) {
            this.closeDialog();
        }
    }

    public onAccept(): void {
        this.dialogContainerConfig.accept(this.componentInstances);
        if (!this.dialogContainerConfig.isHandleCloseOnAccept) {
            this.closeDialog();
        }
    }

    /**
     * Based on certain conditions returns the id of the body content to the aria-describedby attr of the container
     */
    public getContentId(): string {
        if(!this.isBodyTemplatePortal && !this.isBodyComponentPortal) {
            return 'containerConfigId';
        } else if (this.isBodyTemplatePortal && !this.isBodyComponentPortal) {
            return 'bodyTemplatePortalId';
        } else if(this.isBodyComponentPortal) {
            return 'bodyComponentPortalId'
        }
    }

    /**
     * Disable Accept button of default eui-dialog footer.
     */
    public disableAcceptButton(): void {
        this.acceptButtonDisabled$.next(true);
    }

    /**
     * Enable Accept button of default eui-dialog footer.
     */
    public enableAcceptButton(): void {
        this.acceptButtonDisabled$.next(false);
    }

    /**
     * Disable Dismiss button of default eui-dialog footer.
     */
    public disableDismissButton(): void {
        this.dismissButtonDisabled$.next(true);
    }

    /**
     * Enable Dismiss button of default eui-dialog footer.
     */
    public enableDismissButton(): void {
        this.dismissButtonDisabled$.next(false);
    }

    public onScroll(): void {
        this.cd.detectChanges();
    }

    public scrollToBottom(): void {
        const el = document.querySelector('.eui-dialog__body');
        if (el) {
            el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
        }
    }

    public scrollToTop(): void {
        const el = document.querySelector('.eui-dialog__body');
        if (el) {
            el.scrollTo({ top: 0, behavior: 'smooth' });
        }
    }

    private createComponentPortal(component: ComponentType<HC | BC | FC>, config: HCC | BCC | FCC): ComponentPortal<HC | BC | FC> {
        const extendedConfig = { ...config, id: this.dialogContainerConfig.dialogId, overlayRef: this.dialogContainerConfig.overlayRef };
        return new ComponentPortal(component, null, this.createInjector(extendedConfig));
    }

    private createInjector(data: HCC | BCC | FCC): Injector {
        const injectorTokens: StaticProvider = [{ provide: DIALOG_COMPONENT_CONFIG, useValue: data }];
        return Injector.create({
            parent: this.injector,
            providers: injectorTokens,
        });
    }
}
