import { Injectable } from '@angular/core';
import { CdkDropList } from '@angular/cdk/drag-drop';
import { BehaviorSubject } from 'rxjs';

/**
 * @description
 * Service used internally by `eui-chip-list` for the drag and drop feature.
 */
@Injectable()
export class EuiChipListDragService {
    public componentConnector: CdkDropList[] = [];
    public droppableArea: CdkDropList[] = [];
    public removedFromDroppable = new BehaviorSubject(null);

    /**
     * Creates a source with a name provided in chip-list component
     * 
     * @param sourceName Name of the source
     */
    public setComponentConnector(sourceName: string): void {
        if (!this.componentConnector[sourceName]) {
            this.componentConnector[sourceName] = [];
        }
    }

    /**
     * Creates an area in which the chips can be dropped.
     * 
     * @param componentRef Reference to the area.
     * @param sourceNames Possible source that can be dropped.
     */
    public setDroppableArea(componentRef: CdkDropList, sourceNames: string[]): void {
        sourceNames.forEach((sourceName) => {
            if (!this.droppableArea[sourceName]) {
                this.droppableArea[sourceName] = [];
            }

            this.droppableArea[sourceName].push(componentRef);

            if (!this.componentConnector[sourceName]) {
                this.setComponentConnector(sourceName);
            }

            this.componentConnector[sourceName].push(componentRef);
        });
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public removeFromDroppable(item: any | null): void {
        this.removedFromDroppable.next(item);
    }

    /**
     * Reset the service when `OnDestroy` hook of the component is called.
     */
    public resetConnector(): void {
        this.componentConnector = [];
        this.droppableArea = [];
    }
}
