import { Component, HostBinding, ViewEncapsulation, ElementRef, inject } from '@angular/core';
import { FocusableOption } from '@angular/cdk/a11y';

@Component({
    selector: 'eui-user-profile-menu-item',
    template: '<ng-content/>',
    encapsulation: ViewEncapsulation.None,
})
export class EuiUserProfileMenuItemComponent implements FocusableOption {
    @HostBinding('class') class = 'eui-user-profile-menu-item';
    @HostBinding('attr.tabindex') tabindex = '-1';
    @HostBinding('attr.role') role = 'menuitem';
    private element = inject(ElementRef);

    focus(): void {
        this.element.nativeElement.focus();
    }
}
