import { LogEvent, LogLevel, LogLevelName } from './log.model';
import { LogAppender } from './log.appender';

/**
 * Logger
 */
export class Logger {
    constructor(protected name: string, protected level: LogLevel, protected appenders: LogAppender[]) {}

    static isEnabledFor(enabledFromLevel: LogLevel, level: LogLevel): boolean {
        return enabledFromLevel >= level;
    }

    /**
     * Gets the logger name
     *
     * @returns the logger name
     */
    getName(): string {
        return this.name;
    }

    /**
     * Gets the log level
     *
     * @returns the log level
     */
    getLevel(): LogLevel {
        return this.level;
    }

    /**
     * Sets the log level
     *
     * @param level log level
     */
    setLevel(level: LogLevel): void {
        this.level = level;
    }

    /**
     * Fatal log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    fatal<T, S>(message: T, ...additionalMessages: S[]): void {
        return this.log({
            level: LogLevel.FATAL,
            levelName: LogLevelName.FATAL,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    /**
     * Error log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    error<M, A>(message: M, ...additionalMessages: A[]): void {
        return this.log({
            level: LogLevel.ERROR,
            levelName: LogLevelName.ERROR,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    /**
     * Warning log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    warn<M, A>(message: M, ...additionalMessages: A[]): void {
        return this.log({
            level: LogLevel.WARN,
            levelName: LogLevelName.WARN,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    /**
     * Info log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    info<M, A>(message: M, ...additionalMessages: A[]): void {
        return this.log({
            level: LogLevel.INFO,
            levelName: LogLevelName.INFO,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    /**
     * Debug log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    debug<M, A>(message: M, ...additionalMessages: A[]): void {
        return this.log({
            level: LogLevel.DEBUG,
            levelName: LogLevelName.DEBUG,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    /**
     * Trace log
     *
     * @param message mandatory message
     * @param additionalMessages optional messages
     */
    trace<M, A>(message: M, ...additionalMessages: A[]): void {
        return this.log({
            level: LogLevel.TRACE,
            levelName: LogLevelName.TRACE,
            loggerName: this.name,
            timestamp: new Date(),
            messages: [message, ...additionalMessages],
        });
    }

    isDisabled = (): boolean => this.level === LogLevel.OFF;
    isEnabledFor = (level: LogLevel): boolean => Logger.isEnabledFor(this.level, level);
    isFatalEnabled = (): boolean => this.isEnabledFor(LogLevel.FATAL);
    isErrorEnabled = (): boolean => this.isEnabledFor(LogLevel.ERROR);
    isWarnEnabled = (): boolean => this.isEnabledFor(LogLevel.WARN);
    isInfoEnabled = (): boolean => this.isEnabledFor(LogLevel.INFO);
    isDebugEnabled = (): boolean => this.isEnabledFor(LogLevel.DEBUG);
    isTraceEnabled = (): boolean => this.isEnabledFor(LogLevel.TRACE);
    isAllEnabled = (): boolean => this.isEnabledFor(LogLevel.ALL);

    /**
     * Generic log method, checking the log level and calling the specified appenders
     *
     * @param event the log event
     */
    protected log(event: LogEvent): void {
        this.appenders
            // filter the appender by their custom logLevel or the logger (main) logLevel
            .filter((appender) => Logger.isEnabledFor(appender.getConfig().logLevel || this.level, event.level), this)
            // execute the remaining appenders
            .forEach((appender) => appender.append(event));
    }
}
