import { ActivatedRoute } from '@angular/router';
import { Action } from '../ngrx_kit';
import { ModuleConfig, ApiQueueItem } from '@eui/base';

/**
 * @deprecated it will be removed in the next major version
 */
export enum CoreAppActionTypes {
    INIT_STORE = '[App] Init store',
    UPDATE_APP_VERSION = '[App] Update version',
    UPDATE_APP_CONNECTION = '[App] Update connection',
    ADD_APP_LOADED_CONFIG_MODULES = '[App] Update app loaded config modules',
    UPDATE_APP_STATUS = '[App] Update status',
    UPDATE_CURRENT_MODULE = '[App] Update current module',
    ACTIVATED_ROUTE = '[App] Activated route',
    ADD_API_QUEUE_ITEM = '[App] Add API queue item',
    REMOVE_API_QUEUE_ITEM = '[App] Remove API queue item',
    EMPTY_API_QUEUE = '[App] empty API queue',
}

/**
 * @deprecated it will be removed in the next major version
 */
export class InitStoreAction implements Action {
    type = CoreAppActionTypes.INIT_STORE;

    constructor(public payload: { version?: string }) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class UpdateAppVersionAction implements Action {
    type = CoreAppActionTypes.UPDATE_APP_VERSION;

    constructor(public payload: string) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class UpdateAppConnectionAction implements Action {
    type = CoreAppActionTypes.UPDATE_APP_CONNECTION;

    constructor(public payload: boolean) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class AddAppLoadedConfigModulesAction implements Action {
    type = CoreAppActionTypes.ADD_APP_LOADED_CONFIG_MODULES;

    constructor(public payload: { moduleName: string; moduleConfig: ModuleConfig }) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class UpdateAppStatusAction implements Action {
    type = CoreAppActionTypes.UPDATE_APP_STATUS;

    constructor(public payload: string) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class UpdateCurrentModuleAction implements Action {
    type = CoreAppActionTypes.UPDATE_CURRENT_MODULE;

    constructor(public payload: string) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class ActivatedRouteAction implements Action {
    type = CoreAppActionTypes.ACTIVATED_ROUTE;

    constructor(public payload: ActivatedRoute) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class AddApiQueueItemAction implements Action {
    type = CoreAppActionTypes.ADD_API_QUEUE_ITEM;

    constructor(public payload: { id: string; item: ApiQueueItem }) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class RemoveApiQueueItemAction implements Action {
    type = CoreAppActionTypes.REMOVE_API_QUEUE_ITEM;

    constructor(public payload: string) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export class EmptyApiQueueAction implements Action {
    type = CoreAppActionTypes.EMPTY_API_QUEUE;

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    constructor(public payload: any) {}
}

/**
 * @deprecated it will be removed in the next major version
 */
export type CoreAppActions =
    | InitStoreAction
    | UpdateAppVersionAction
    | UpdateAppConnectionAction
    | AddAppLoadedConfigModulesAction
    | UpdateAppStatusAction
    | UpdateCurrentModuleAction
    | ActivatedRouteAction
    | AddApiQueueItemAction
    | RemoveApiQueueItemAction;
