import { GlobalPositionStrategy, Overlay, OverlayRef } from '@angular/cdk/overlay';
import { ComponentPortal } from '@angular/cdk/portal';
import { ComponentRef, Injectable, Injector, OnDestroy, StaticProvider, inject } from '@angular/core';
import { Subject, BehaviorSubject, Observable } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

import { EuiDialogContainerComponent } from '../container/eui-dialog-container.component';
import { EuiDialogInterface, EuiDialogComponentInstances, EuiDialogConfig } from '../models/eui-dialog.config';
import { OpenedDialog } from '../models/opened-dialog.model';
import { DIALOG_CONTAINER_CONFIG } from './eui-dialog.token';
import { EuiDialogVerticalPosition } from '../models/eui-dialog-alignment';

@Injectable()
export class EuiDialogService implements OnDestroy {
    private overlay = inject(Overlay);
    private injector = inject(Injector);
    private overlayRef: OverlayRef;
    private openedDialogs$: BehaviorSubject<OpenedDialog[]> = new BehaviorSubject<OpenedDialog[]>([]);
    private destroy$: Subject<boolean> = new Subject<boolean>();

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
        this.overlayRef?.dispose();
        this.overlayRef = null;
        this.openedDialogs$.next(null);
    }

    /**
     * Open a dialog.
     *
     * @param config Configuration applied to the dialog.
     * @returns A dialog object of type `OpenedDialog`
     */
    public openDialog<HC, HCC, BC, BCC, FC, FCC>(config: EuiDialogInterface<HC, HCC, BC, BCC, FC, FCC> = {}): OpenedDialog {
        const positionStrategy = this.getPositionStrategy(config.verticalPosition);
        const scrollStrategy = this.overlay.scrollStrategies.block();
        const hasClosedOnEscape = config.hasClosedOnEscape;
        const hasCloseButton = config.hasCloseButton;
        const dialogConfig = new EuiDialogConfig({
            ...config,
            hasClosedOnEscape,
            hasCloseButton,
            width: config.isFullScreen ? '98vw' : config.width,
            height: config.isFullScreen ? '97vh' : config.height,
        });
        const dialogId = 'eui-dialog-' + Math.floor(Math.random() * 10000);
        const overlayRef = this.overlay.create({
            backdropClass: ['eui-dialog__backdrop', dialogId + '__backdrop'],
            hasBackdrop: true,
            height: dialogConfig.height,
            width: dialogConfig.width,
            positionStrategy,
            scrollStrategy,
            disposeOnNavigation: true,
            panelClass: config.classList,
        });

        this.overlayRef = overlayRef;
        let openedDialog = new OpenedDialog({
            id: dialogId,
            order: this.openedDialogs$.value.length + 1,
            overlayRef,
            containerRef: null,
        });

        const extendedConfig: EuiDialogInterface<HC, HCC, BC, BCC, FC, FCC> = {
            ...dialogConfig,
            dialogId,
            overlayRef,
            init: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                config.init?.(instances);
            },
            open: () => {
                config.open?.();
            },
            clickOutside: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                config.clickOutside?.(instances);
            },
            escape: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                config.escape?.(instances);
            },
            close: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                if(!config.isHandleCloseOnClose) {
                    this.closeDialog(dialogId);
                }
                config.close?.(instances);
            },
            dismiss: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                config.dismiss?.(instances);
            },
            accept: (instances: EuiDialogComponentInstances<HC, BC, FC>) => {
                config.accept?.(instances);
            },
        };
        const containerPortal = new ComponentPortal<EuiDialogContainerComponent<HC, HCC, BC, BCC, FC, FCC>>(
            EuiDialogContainerComponent,
            null,
            this.createInjector(extendedConfig),
        );
        const containerRef: ComponentRef<EuiDialogContainerComponent<HC, HCC, BC, BCC, FC, FCC>> =
            openedDialog.overlayRef.attach(containerPortal);
        openedDialog = { ...openedDialog, containerRef };

        openedDialog.overlayRef
            .backdropClick()
            .pipe(takeUntil(this.destroy$))
            .subscribe(() => {
                if (extendedConfig.hasClosedOnClickOutside) {
                    config.clickOutside?.(containerRef.instance.componentInstances);
                    if (!config.isHandleCloseOnClickOutside) {
                        containerRef.instance.closeDialog();
                    }
                }
            });

        if (extendedConfig.hasClosedOnEscape) {
            openedDialog.overlayRef
                .keydownEvents()
                .pipe(takeUntil(this.destroy$))
                .subscribe((keyboardEvent) => {
                    if (keyboardEvent.key?.toLowerCase() === 'escape') {
                        config.escape?.(containerRef.instance.componentInstances);
                        if (!config.isHandleCloseOnEscape) {
                            containerRef.instance.closeDialog();
                        }
                    }
                });
        }

        this.openedDialogs$.next([...this.openedDialogs$.value, openedDialog]);

        return openedDialog;
    }

    /**
     * Close a dialog
     *
     * @param dialogId The id of the dialog to close. If not provided the last opened one will be closed.
     */
    public closeDialog(dialogId?: string): void {
        if (dialogId) {
            this.openedDialogs$.value.find((o) => o.id === dialogId).overlayRef.dispose();
            this.openedDialogs$.next(this.openedDialogs$.value.filter((o) => o.id !== dialogId));
            this.overlayRef =
                this.openedDialogs$.value.length > 0 ? this.openedDialogs$.value[this.openedDialogs$.value.length - 1].overlayRef : null;
        } else {
            this.overlayRef?.dispose();
            this.openedDialogs$.next(this.openedDialogs$.value.filter((o, i) => i < this.openedDialogs$.value.length - 1));
            this.overlayRef =
                this.openedDialogs$.value.length > 0 ? this.openedDialogs$.value[this.openedDialogs$.value.length - 1].overlayRef : null;
        }
    }

    /**
     * Close all the dialogs.
     */
    public closeAllDialogs(): void {
        this.openedDialogs$.value.forEach((dialog) => {
            dialog.containerRef.instance.dialogContainerConfig.close?.(dialog.containerRef.instance.getComponentInstances);
        });
    }

    /**
     * Returns an `Observable` with all opened windows.
     *
     * @returns `Observable` of `OpenedDialog[]`.
     */
    public getOpenedDialog(): Observable<OpenedDialog[]> {
        return this.openedDialogs$;
    }

    /**
     * Returns an `Object` with a dialog
     *
     * @param dialogId id of the dialog to be returned
     * @returns `OpenedDialog`
     */
    public getDialog(dialogId: string): OpenedDialog {
        return this.openedDialogs$.value.find((o) => o.id === dialogId);
    }

    /**
     * Disable Accept button of default eui-dialog footer.
     */
    public disableAcceptButton(): void {
        this.openedDialogs$.value[this.openedDialogs$.value.length - 1].containerRef.instance.disableAcceptButton();
    }

    /**
     * Enable Accept button of default eui-dialog footer.
     */
    public enableAcceptButton(): void {
        this.openedDialogs$.value[this.openedDialogs$.value.length - 1].containerRef.instance.enableAcceptButton();
    }

    /**
     * Disable Dismiss button of default eui-dialog footer.
     */
    public disableDismissButton(): void {
        this.openedDialogs$.value[this.openedDialogs$.value.length - 1].containerRef.instance.disableDismissButton();
    }

    /**
     * Enable Dismiss button of default eui-dialog footer.
     */
    public enableDismissButton(): void {
        this.openedDialogs$.value[this.openedDialogs$.value.length - 1].containerRef.instance.enableDismissButton();
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private createInjector(data: any): Injector {
        const injectorTokens: StaticProvider = [{ provide: DIALOG_CONTAINER_CONFIG, useValue: data }];
        return Injector.create({
            parent: this.injector,
            providers: injectorTokens,
        });
    }

    private getPositionStrategy(verticalPosition: EuiDialogVerticalPosition): GlobalPositionStrategy {
        const positionStrategy = this.overlay.position().global().centerHorizontally().centerVertically();
        if (verticalPosition === 'top') {
            positionStrategy.top();
        }
        return positionStrategy;
    }
}
