/** Log level */
export enum LogLevel {
    OFF = 0,
    FATAL = 1,
    ERROR = 2,
    WARN = 3,
    INFO = 4,
    DEBUG = 5,
    TRACE = 6,
    ALL = 7,
}

/** Associated log level names */
export enum LogLevelName {
    FATAL = 'FATAL',
    ERROR = 'ERROR',
    WARN = 'WARNING',
    INFO = 'INFO',
    DEBUG = 'DEBUG',
    TRACE = 'TRACE',
}

/** The code position from where the log has been triggered */
export interface LogPosition {
    file: string;
    line: number;
    column: number;
}

/** The log event sent to the log appenders */
export interface LogEvent<MESSAGES = unknown> {
    /** event's log level */
    level: LogLevel;
    /** event's log level name */
    levelName: string;
    /** the name of the logger who triggered the event */
    loggerName: string;
    /** event's timestamp */
    timestamp: Date;
    /** log messages */
    messages: MESSAGES[];
}
