import {
    Component,
    HostBinding,
    ViewEncapsulation,
    forwardRef,
    ContentChild,
    booleanAttribute,
    Input,
    ElementRef,
    AfterViewInit,
    OnInit,
    inject,
} from '@angular/core';
import { EuiToolbarMenuComponent } from './toolbar-menu/toolbar-menu.component';
import { EuiAppShellService } from '@eui/core';
import { AsyncPipe, NgTemplateOutlet } from '@angular/common';
import { EuiToolbarLogoComponent } from './toolbar-logo/toolbar-logo.component';
import { EuiToolbarEnvironmentComponent } from './toolbar-environment/toolbar-environment.component';
import { EuiToolbarAppComponent } from './toolbar-app/toolbar-app.component';
import { EuiToolbarItemsComponent } from './toolbar-items/toolbar-items.component';
import { EuiToolbarItemComponent } from './toolbar-item/toolbar-item.component';
import { EUI_USER_PROFILE } from '@eui/components/eui-user-profile';

@Component({
    selector: 'eui-toolbar',
    templateUrl: './toolbar.component.html',
    styleUrl: './toolbar.component.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        NgTemplateOutlet,
        EuiToolbarLogoComponent,
        EuiToolbarEnvironmentComponent,
        EuiToolbarAppComponent,
        EuiToolbarItemsComponent,
        EuiToolbarItemComponent,
        ...EUI_USER_PROFILE,
    ],
})
export class EuiToolbarComponent implements OnInit, AfterViewInit {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-toolbar',
            this.euiSecondary ? 'eui-toolbar--secondary eui--secondary' : '',
            this.euiPrimary ? 'eui-toolbar--primary eui--primary' : '',
        ].join(' ').trim();
    }

    @Input({ transform: booleanAttribute }) euiSecondary = false;
    @Input({ transform: booleanAttribute }) euiPrimary = true;

    @ContentChild(forwardRef(() => EuiToolbarMenuComponent))
    hasMenu: EuiToolbarMenuComponent;
    asService = inject(EuiAppShellService);
    private elRef = inject(ElementRef);

    ngOnInit(): void {
        if (this.euiSecondary) {
            this.euiPrimary = false;
        }
    }

    ngAfterViewInit(): void {
        const appToolbar = this.elRef.nativeElement.closest('eui-app-toolbar');
        setTimeout(() => {
            if (appToolbar && appToolbar.classList.contains('eui--secondary')) {
                this.euiSecondary = true;
                this.euiPrimary = false;
            }
        }, 1);
    }
}
