import { Action } from '../ngrx_kit';
import { NotificationsState, initialNotificationsState } from '@eui/base';
import { CoreNotificationsActionTypes, CoreNotificationsActions, UpdateNotificationsListAction } from '../actions';

const updateNotificationsList = (state: NotificationsState, action: UpdateNotificationsListAction): NotificationsState =>
    Object.assign({}, state, { list: [...action.payload] });

const actionToReducerMap: { [key: string]: (state: NotificationsState, action: CoreNotificationsActions) => NotificationsState } = {
    [CoreNotificationsActionTypes.UPDATE_NOTIFICATIONS_LIST]: updateNotificationsList,
};

/**
 * @deprecated it will be removed in the next major version
 */
export const coreNotificationsReducers: (state: NotificationsState, action: Action) => NotificationsState = (
    state = initialNotificationsState,
    action: CoreNotificationsActions,
) => {
    if (actionToReducerMap[action.type]) {
        return actionToReducerMap[action.type](state, action);
    }
    return state;
};
