import { coerceBooleanProperty, BooleanInput } from '@angular/cdk/coercion';
import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Input,
    EventEmitter,
    Output,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { EuiButtonModule } from '@eui/components/eui-button';
import { EuiIconModule } from '@eui/components/eui-icon';
import { EuiInputGroupModule } from '@eui/components/eui-input-group';
import { EuiInputTextModule } from '@eui/components/eui-input-text';

@Component({
    selector: 'eui-header-search',
    templateUrl: './header-search.component.html',
    styleUrl: './header-search.component.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        FormsModule,
        EuiIconModule,
        EuiButtonModule,
        EuiInputTextModule,
        EuiInputGroupModule,
    ],
})
export class EuiHeaderSearchComponent {
    @HostBinding('class') cssClass = 'eui-header-search';

    @Input() placeholder = 'Welcome';
    @Input() searchLabel = 'acting as';

    @Output() searchClick: EventEmitter<string> = new EventEmitter();

    protected inputValue: string;

    onSearch(): void {
        this.searchClick.emit(this.inputValue);
    }
}
