import { Inject, Injectable, InjectionToken } from '@angular/core';
import { LogAppender, Logger, LogLevel } from '@eui/base';

export const BASE_LOGGER_NAME_TOKEN = new InjectionToken<string>('BASE_LOGGER_NAME');
export const LOG_LEVEL_TOKEN = new InjectionToken<LogLevel>('LOG_LEVEL');
export const LOG_APPENDERS_TOKEN = new InjectionToken<LogAppender[]>('LOG_APPENDERS');

/**
 * Log service, responsible for getting or creating loggers. It itself acts as a base logger
 */
@Injectable()
export class LogService extends Logger {
    /** the list of persistent loggers */
    protected loggers = {};

    constructor(
        @Inject(BASE_LOGGER_NAME_TOKEN) protected override name: string,
        @Inject(LOG_LEVEL_TOKEN) protected override level: LogLevel,
        @Inject(LOG_APPENDERS_TOKEN) protected override appenders: LogAppender[],
    ) {
        super(name, level, appenders);
    }

    /**
     * Gets a logger by name. If the logger does not exist, it is created
     *
     * @param loggerName logger name
     * @param persist optional parameter. Set it to true if you want to reuse the logger. By default, it is set to false
     * @returns the logger
     */
    getLogger(loggerName: string, persist = false): Logger {
        // create the logger, if necessary
        const logger = (persist && <Logger>this.loggers[loggerName]) || new Logger(loggerName, this.level, this.appenders);

        // if the logger is persistent, add it to the list of persistent loggers
        if (persist) {
            this.loggers[loggerName] = logger;
        }

        return logger;
    }
}
