import { Component, HostBinding, Input, booleanAttribute } from '@angular/core';

@Component({
    selector: 'eui-toolbar-items',
    template: '<ng-content />',
})
export class EuiToolbarItemsComponent {
    @HostBinding('class')
    get cssClasses(): string {
        const rootClass = 'eui-toolbar-items';
        return [
            rootClass,
            this.euiEnd ? `${rootClass}--position-right` : '',
            this.euiPositionRight ? `${rootClass}--position-right` : '',
        ].join(' ').trim();
    }

    @Input({ transform: booleanAttribute }) euiEnd = false;
    @Input({ transform: booleanAttribute }) euiPositionRight = false;
}
