import { Optional, Inject, Injectable, LOCALE_ID } from '@angular/core';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { EuiServiceStatus, LocaleState } from '@eui/base';
import { LocaleService } from './locale.service';
import localeFr from '@angular/common/locales/fr';
import localeEl from '@angular/common/locales/el';
import { registerLocaleData } from '@angular/common';

@Injectable()
export class LocaleServiceMock<T extends LocaleState = LocaleState> extends LocaleService<T> {
    private DEFAULT_LOCALE = 'en';
    private stateSub: BehaviorSubject<T> = new BehaviorSubject<T>({ id: this.DEFAULT_LOCALE } as T);

    constructor(@Optional() @Inject(LOCALE_ID) protected override locale_id: string) {
        super(null, { locale: { } }, locale_id, null, null, null);
    }

    override getState(): Observable<T> {
        return this.stateSub.asObservable();
    }

    override updateState(state: T): void {
        this.DEFAULT_LOCALE = state.id || 'en';
        if (state.id === 'fr') {
            registerLocaleData(localeFr, 'fr');
        } else if (state.id === 'el') {
            registerLocaleData(localeEl, 'fr');
        }
        this.stateSub.next(state);
    }

    override init(state?: T): Observable<EuiServiceStatus> {
        this.DEFAULT_LOCALE = state.id || 'en';
        return of({ success: true });
    }
}
