import { DatePipe, NgClass } from '@angular/common';
import { booleanAttribute, Component, EventEmitter, HostBinding, Input, Output } from '@angular/core';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EuiTruncatePipe } from '@eui/components/pipes';
import { UxLinkLegacy } from '@eui/core';
import { consumeEvent } from '@eui/core';
import { TranslateModule } from '@ngx-translate/core';

export interface NotificationMetadata {
    read?: boolean;
    urlExternal?: string;
    urlExternalTarget?: string;
    important?: boolean;
    new?: boolean;
    url?: string;
    date?: Date | string | number;
}

@Component({
    selector: 'eui-notification-item',
    templateUrl: './eui-notification-item.component.html',
    imports: [
        NgClass,
        DatePipe,
        EuiTruncatePipe,
        TranslateModule,
        ...EUI_ICON,
    ],
})
export class EuiNotificationItemComponent {
    @HostBinding('class') string = 'eui-notification-item';
    @Output() itemClick: EventEmitter<UxLinkLegacy<NotificationMetadata>> = new EventEmitter<UxLinkLegacy<NotificationMetadata>>();
    @Output() itemMarkAsRead: EventEmitter<UxLinkLegacy<NotificationMetadata>> = new EventEmitter<UxLinkLegacy<NotificationMetadata>>();
    @Input() markAsReadLabel: string = null;
    @Input() item: UxLinkLegacy<NotificationMetadata>;
    @Input() dateFormat = 'dd/MM/YYYY';
    tooltipSize = 'auto';
    @Input({ transform: booleanAttribute })isShowMarkAsRead = true;

    onItemClick(): void {
        this.itemClick.emit(this.item);
    }

    onItemMarkAsRead(event: Event): void {
        if (this.item.metadata) {
            this.item.metadata.read = true;
        }
        this.itemMarkAsRead.emit(this.item);
        consumeEvent(event);
    }

    get iconColor(): string {
        return this.item.metadata?.read ? 'neutral-lightest' : 'neutral-light';
    }

}
