import { NgTemplateOutlet } from '@angular/common';
import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Input,
    ContentChild,
    forwardRef,
    QueryList,
    Output,
    EventEmitter,
    booleanAttribute,
} from '@angular/core';
import { EuiTooltipDirective } from '@eui/components/directives';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EuiPageHeaderBodyComponent } from './components/eui-page-header-body.component';

@Component({
    selector: 'eui-page-header',
    templateUrl: './eui-page-header.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        EuiTooltipDirective,
        NgTemplateOutlet,
        ...EUI_ICON,
        ...EUI_BUTTON,
    ],
})
export class EuiPageHeaderComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-page-header',
            this.isCollapsible ? 'eui-page-header--collapsible' : '',
            this.isCollapsed ? 'eui-page-header--collapsed' : '',
            this.isHeaderMultilines ? 'eui-page-header--multilines' : '',
        ]
            .join(' ')
            .trim();
    }

    @Input() label;
    @Input() subLabel;
    @Input() labelTooltip;
    @Input() subLabelTooltip;

    // conventions if boolean : is / has prefix
    // new v17 usage of transform / act like coerce and included in Angular natively now
    @Input({ transform: booleanAttribute }) isCollapsible = false;
    @Input({ transform: booleanAttribute }) isCollapsed = false;
    @Input({ transform: booleanAttribute }) isHeaderMultilines = false;

    /**
     * @deprecated Avoid using this property, use the `pageHeaderBodyContent` instead.
     */
    @ContentChild(forwardRef(() => EuiPageHeaderComponent)) headerBodyContent: QueryList<EuiPageHeaderComponent>;
    @ContentChild(forwardRef(() => EuiPageHeaderBodyComponent)) pageHeaderBodyContent: QueryList<EuiPageHeaderBodyComponent>;

    @Input() collapsedLabel = ''; // Expand
    @Input() expandedLabel = ''; // Collapse
    @Output() collapse = new EventEmitter<boolean>();

    public onToggle(): void {
        this.isCollapsed = !this.isCollapsed;
        this.collapse.emit(this.isCollapsed);
    }
}
