import { DOCUMENT } from '@angular/common';
import {
    Inject,
    Injectable,
    OnDestroy,
    Optional,
    Signal,
} from '@angular/core';
import { LangChangeEvent, TranslateService } from '@ngx-translate/core';
import { BehaviorSubject, forkJoin, Observable, of, Subject } from 'rxjs';
import {
    catchError,
    filter,
    map,
    take,
    tap,
    switchMap,
    takeUntil,
    distinctUntilChanged,
} from 'rxjs/operators';
import {
    GlobalConfig,
    EuiLazyService,
    EuiServiceStatus,
    getI18nServiceConfigFromBase,
    I18nLoaderConfig,
    I18nServiceConfig,
    I18nState,
    ModuleConfig,
    getBrowserDefaultLanguage,
    EuiEuLanguages,
    CoreState,
    DeepPartial,
} from '@eui/base';

import { I18nLoader, LoadedResources } from './i18n.loader';
import { GLOBAL_CONFIG_TOKEN } from '../config/tokens';
import { LogService } from '../log';
import { StoreService } from '../store';
import { DEFAULT_I18N_SERVICE_CONFIG } from '../config/defaults';
import { isEqual } from 'lodash-es';
import { Selector } from 'reselect';
import { toSignal } from '@angular/core/rxjs-interop';

export interface ModuleLoadEvent {
    ready: boolean;
    name: string;
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    error?: any;
}

const getLastAddedModule: Selector<CoreState, string> = (state: CoreState) => state.app.loadedConfigModules.lastAddedModule;

@Injectable({
    providedIn: 'root',
})
export class I18nService<T extends I18nState = I18nState> extends EuiLazyService<T | I18nState> implements OnDestroy {
    protected config: I18nServiceConfig;
    protected onModuleLoad: BehaviorSubject<ModuleLoadEvent>;

    private static readonly DEFAULT_STATE: I18nState = { activeLang: 'en' };
    /**
     * a single signal holding the state - initial state is null
     */
    private state: Signal<T>;
    /**
     * a BehaviorSubject holding the state - initial state is null
     * This is the main source of truth for the state
     */
    private stateSubject: BehaviorSubject<T>;
    private subNotifier: Subject<void> = new Subject();

    constructor(
        @Inject(GLOBAL_CONFIG_TOKEN) protected baseGlobalConfig: GlobalConfig,
        protected translateService: TranslateService,
        @Optional() protected logService: LogService,
        protected store: StoreService<T>,
        @Inject(DOCUMENT) private document: Document,
    ) {
        super(I18nService.DEFAULT_STATE as T);
        // Create a BehaviorSubject with the initial state
        this.stateSubject = new BehaviorSubject<T>(this.stateInstance as T);

        // Initialize signal with base state
        this.state = toSignal(this.stateSubject, { equal: isEqual });

        // Subscribe to base class state changes
        this.onStateChange.subscribe((newState) => {
            // const clonedState = structuredClone(newState as T);
            this.stateSubject.next(newState as T);
        });

        this.config = getI18nServiceConfigFromBase(this.baseGlobalConfig);
        this.onModuleLoad = new BehaviorSubject<ModuleLoadEvent>({ ready: false, name: null });
    }

    ngOnDestroy(): void {
        this.subNotifier.next(void 0);
        this.subNotifier.complete();
    }

    getState(): Observable<T>;
    /**
     * @deprecated this will be removed in a future version
     * @param mapFn
     */
    getState<K = T>(mapFn?: (state: T) => K): Observable<K>;
    getState<a extends keyof DeepPartial<T>>(key?: a): Observable<DeepPartial<a>>;
    getState<K = T>(keyOrMapFn?: ((state: T) => K) | string): Observable<DeepPartial<K>> {
        if (!keyOrMapFn) {
            return this.stateSubject.asObservable().pipe(
                takeUntil(this.subNotifier),
                distinctUntilChanged((x, y) => isEqual(x, y)),
            ) as Observable<DeepPartial<K>>;
        }

        if (typeof keyOrMapFn === 'function') {
            return this.stateSubject.asObservable().pipe(
                takeUntil(this.subNotifier),
                map(state => keyOrMapFn(state)),
                distinctUntilChanged((x, y) => isEqual(x, y)),
            );
        }

        return this.stateSubject.asObservable().pipe(
            takeUntil(this.subNotifier),
            map(state => {
                const keys = (keyOrMapFn as string).split('.');

                // Traverse the object based on the dot notation
                return keys.reduce((acc, currKey) => {
                    return acc && acc[currKey] !== undefined ? acc[currKey] : undefined;
                }, state as DeepPartial<T>);
            }),
            distinctUntilChanged((x, y) => isEqual(x, y)),
        );
    }

    updateState(state: DeepPartial<T>): void;
    /**
     * @deprecated it will be removed in next version. Use updateState(partialState: DeepPartial<T>) instead
     * @param slice
     * @param reducer
     */
    updateState(slice: DeepPartial<T>, reducer: (state: T, action: DeepPartial<T>) => T): void;
    updateState<K extends T>(state: DeepPartial<K>, reducer?: (state: T, action: DeepPartial<K>) => T): void {
        if(state.activeLang) {
            this.updateHTMLDOMLang(state.activeLang as string);
        }
        this.stateInstance = super.deepMerge(this.stateInstance as T, { ...state });
        // Emit state change
        this.onStateChange.next(this.stateInstance);
    }

    /**
     * This method is used to get the state as readonly signal.
     */
    getSignal(): Signal<T> {
        return this.state;
    }

    init(langState?: T): Observable<EuiServiceStatus> {
        const initLang = langState && langState.activeLang ? langState.activeLang : this.preparedDefaultLanguage();
        const initState = {
            ...langState,
            activeLang: initLang,
        };
        if (typeof initLang === 'string') {
            super.initEuiService(this.store);
            this.updateState(initState);
            return this.setup(initLang);
        }
        return of({ success: false, error: 'Initial active lang should be string' });
    }

    /**
     * A pipe function that could serve as a wrapper of another observable
     * e.g. ngx-translate i18n.onReady('my_module').pipe(switchMap(()=>translate.get('eui.KEY')));
     * WARNING: onReady will emit only once for a loaded Module, going to another and then going back will not result
     * into another emission.
     *
     * @param moduleName the name of the module that has been given through the eUI globalConfig. In case non provided
     * fetch module name from the state.
     */
    onReady(moduleName?: string): Observable<ModuleLoadEvent> {
        return this.onModuleLoad.pipe(
            switchMap((evt: ModuleLoadEvent) =>
                moduleName
                    ? of(evt)
                    : this.store.select(getLastAddedModule).pipe(
                          tap((m) => (moduleName = m)),
                          map(() => evt),
                      ),
            ),
            // emit only if event emitted matches the module name and is ready
            filter((evt: ModuleLoadEvent) => evt.ready === true && evt.name === moduleName),
            // make sure that observable completes
            take(1),
        );
    }

    public lazyLoad(config: I18nLoaderConfig): Observable<EuiServiceStatus> {
        const moduleId = Math.floor(Math.random() * 100000 + 1).toLocaleString();
        return this.addResources(config, moduleId);
    }

    lazyLoadInit(moduleConfig: ModuleConfig, moduleName?: string): Observable<EuiServiceStatus> {
        const i18nLoaderConfig = moduleConfig as I18nLoaderConfig;
        // add resources
        return this.addResources(i18nLoaderConfig, moduleName);
    }

    /**
     * Add resources based of a config loader
     *
     * @param config I18nLoaderConfig
     * @param moduleName
     * @return Promise<EuiServiceStatus> an EuiServiceStatus when translation has fully loaded
     */
    public addResources(config: I18nLoaderConfig, moduleName?: string): Observable<EuiServiceStatus> {
        // emit that module is loading
        this.onModuleLoad.next({ ready: false, name: moduleName });

        const loader = this.translateService.currentLoader;
        if (loader instanceof I18nLoader) {
            // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const langSubscription: Observable<any>[] = [];
            const i18nLoader = <I18nLoader>loader;

            // add the resources to the loader
            const resources = i18nLoader.addResources(config);

            // manually load the resources for the CURRENT language and add them to the translate service
            langSubscription.push(
                i18nLoader.loadResources(resources, this.translateService.currentLang).pipe(
                    take(1),
                    tap((loadedResources: LoadedResources) => {
                        // add the new set of translations to the current language
                        this.translateService.setTranslation(this.translateService.currentLang, loadedResources.translations, true);
                    }),
                ),
            );

            // if the current language is different from the DEFAULT language
            const defaultLang = this.config.defaultLanguage || this.translateService.defaultLang;
            if (this.translateService.currentLang !== defaultLang) {
                // manually load the resources for the default language and add them to the translation service
                langSubscription.push(
                    i18nLoader.loadResources(resources, defaultLang).pipe(
                        take(1),
                        tap((loadedResources: LoadedResources) => {
                            this.translateService.setTranslation(defaultLang, loadedResources.translations, true);
                        }),
                    ),
                );
            }

            return forkJoin(langSubscription).pipe(
                map((loadedResourcesArr: LoadedResources[]) =>
                    !loadedResourcesArr[0].hasError ? { success: true } : { success: false, error: loadedResourcesArr[0].errors },
                ),
                tap(() => {
                    // emit status of module loading progress
                    this.onModuleLoad.next({ ready: true, name: moduleName });
                }),
                catchError((error) => {
                    // emit status of module loading progress
                    this.onModuleLoad.next({ ready: true, name: moduleName, error });
                    return of({ success: false, error });
                }),
            );
        } else {
            return of({ success: false, error: 'currentLoader is not an I18nLoader.' });
        }
    }

    /**
     * Prepares the default language
     */
    private preparedDefaultLanguage(): string {
        const browserPref = getBrowserDefaultLanguage();
        // If user has browser preferred lang, and that language is part of the languages array
        if (browserPref && this.config.languages && EuiEuLanguages.getLanguageCodes(this.config.languages).includes(browserPref)) {
            return browserPref;
        }
        return this.config.defaultLanguage;
    }

    /**
     * @param initLanguage if given default language to override default language coming from the
     * configuration token.
     */
    private setup(initLanguage: string): Observable<EuiServiceStatus> {
        // use the default config as a reference base
        this.config = Object.assign({}, DEFAULT_I18N_SERVICE_CONFIG, this.config);
        // configure the translation config service
        if (this.config.languages) {
            this.translateService.addLangs(EuiEuLanguages.getLanguageCodes(this.config.languages));
            if (this.logService) {
                this.logService.info(`I18n accepted languages set to ${EuiEuLanguages.getLanguageCodes(this.config.languages)}`);
            }
        }
        // set the current language, causing to load translations
        return this.translateService.use(initLanguage).pipe(
            tap(() => {
                this.bindActiveLangStateToTranslateService();
                this.bindTranslateServiceLangChangeToState();
                if (this.config.defaultLanguage) {
                    this.setDefaultLanguage(this.config.defaultLanguage);
                }
            }),
            map(() => {
                if (this.translateService.currentLoader instanceof I18nLoader) {
                    const failedResources = this.translateService.currentLoader.getFailedResources();
                    if (failedResources.length > 0) {
                        return { success: false, error: failedResources };
                    }
                }
                return { success: true };
            }),
            catchError((error) => of({ success: false, error })),
        );
    }

    private bindActiveLangStateToTranslateService(): void {
        this.getState((s) => s.activeLang)
            .pipe(takeUntil(this.subNotifier))
            .subscribe((lang) => {
                if (lang !== null && this.translateService.currentLang !== lang) {
                    this.use(lang);
                }
            });
    }

    private bindTranslateServiceLangChangeToState(): void {
        this.translateService.onLangChange.subscribe((event: LangChangeEvent) => {
            if (this.stateInstance.activeLang !== event.lang) {
                this.updateState({ activeLang: event.lang } as Partial<T>);
            }
            if (this.logService) {
                this.logService.info(`I18n current language set to ${event.lang}`);
            }
        });
    }

    private setDefaultLanguage(defaultLanguage: string): void {
        // removed, current language is already calculated in init, setup function fill use it directly, not default
        // this.translateService.currentLang = default_language || this.config.defaultLanguage;
        this.translateService.setDefaultLang(defaultLanguage);
        if (this.logService) {
            this.logService.info(`I18n default language set to ${defaultLanguage}`);
        }
    }

    /**
     * change the currently used language
     *
     * @param lang is the language code based on the convention you used e.g. (en or en-EN)
     * @returns Observable that returns an object contain the object translation for given language after language
     * fully loaded.
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private use(lang: string): Observable<any> {
        return this.translateService.use(lang);
    }

    /**
     * updates the HTML element lang attribute
     *
     * @private
     */
    private updateHTMLDOMLang(lang: string): void {
        this.document.documentElement.lang = lang;
    }
}
