import { Injectable, NgZone } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface DataFromAngularJS {
  timestamp: number;
  source: string;
  data: any;
}

@Injectable({
  providedIn: 'root'
})
export class DataBridgeService {
  // Subject to hold the data from AngularJS
  private dataSubject = new BehaviorSubject<DataFromAngularJS | null>(null);
  
  // Observable that components can subscribe to
  public data$: Observable<DataFromAngularJS | null> = this.dataSubject.asObservable();

  constructor(private zone: NgZone) {
    this.setupListener();
  }

  /**
   * Setup listener for custom events from AngularJS
   */
  private setupListener(): void {
    window.addEventListener('angularjs-to-angular-data', (event: Event) => {
      const customEvent = event as CustomEvent;
      const detail = customEvent.detail;
      
      console.log('📥 Angular DataBridge: Received event from AngularJS:', detail);
      
      if (detail && detail.data) {
        // Run inside Angular zone to trigger change detection
        this.zone.run(() => {
          const wrappedData: DataFromAngularJS = {
            timestamp: Date.now(),
            source: detail.source || 'AngularJS',
            data: detail.data
          };
          
          this.dataSubject.next(wrappedData);
          console.log('✅ Angular DataBridge: Data updated:', wrappedData);
        });
      }
    });
    
    console.log('🎧 Angular DataBridge: Listening for AngularJS data...');
  }

  /**
   * Get the current data value (synchronous)
   */
  getCurrentData(): DataFromAngularJS | null {
    return this.dataSubject.value;
  }

  /**
   * Clear the current data
   */
  clearData(): void {
    this.zone.run(() => {
      this.dataSubject.next(null);
      console.log('🧹 Angular DataBridge: Data cleared');
    });
  }
}

