import { Component, HostBinding, Input, Output, EventEmitter, booleanAttribute, OnInit, inject } from '@angular/core';
import { EUI_ICON } from '@eui/components/eui-icon';
import { BaseStatesDirective } from '@eui/components/shared';

@Component({
    selector: 'eui-icon-button',
    templateUrl: './eui-icon-button.component.html',
    styleUrls: [ './eui-icon-button.component.scss' ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiVariant',
            ],
        },
    ],
    imports: [ ...EUI_ICON ],
})
export class EuiIconButtonComponent implements OnInit {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-icon-button'),
            this.hasNoPadding ? 'eui-icon-button--has-no-padding': '',
            this.hasOverflowHover ? 'eui-icon-button--has-overflow-hover': '',
            this.hasFocusHoverColor ? 'eui-icon-button--has-focus-hover-color': '',
            this.hasFocusHoverBg ? 'eui-icon-button--has-focus-hover-bg': '',
            this.euiRounded ? 'eui-icon-button--rounded': '',
            this.euiDisabled ? 'eui-icon-button--disabled': '',
        ]
            .join(' ')
            .trim();
    }

    @Input() icon: string;
    @Input() iconUrl: string;
    @Input() fillColor: string;
    @Input() size: '2xs' | 'xs' | 's' | 'm' | 'l' | 'xl' | '2xl' | '3xl' | '4xl' = 'm';
    @Input() ariaLabel = 'eUI Icon button';
    @Input() tabindex = 0;

    @Input({ transform: booleanAttribute }) hasNoPadding = false;
    @Input({ transform: booleanAttribute }) hasOverflowHover = false;
    @Input({ transform: booleanAttribute }) hasFocusHoverColor = false;
    @Input({ transform: booleanAttribute }) hasFocusHoverBg = true;
    @Input({ transform: booleanAttribute }) euiRounded = false;
    @Input({ transform: booleanAttribute }) euiDisabled = false;

    @Output() buttonClick = new EventEmitter<Event>();
    protected baseStatesDirective = inject(BaseStatesDirective);

    onClick(event: Event): void {
        this.buttonClick.emit(event);
    }

    ngOnInit(): void {
        if (this.hasFocusHoverColor) {
            this.hasFocusHoverBg = false;
        }
    }
}
