import {
    booleanAttribute,
    ChangeDetectionStrategy,
    Component,
    EventEmitter,
    HostBinding,
    Input,
    OnChanges,
    OnInit,
    Output,
    SimpleChanges,
    ViewEncapsulation,
} from '@angular/core';
import { consumeEvent } from '@eui/core';
import { UxLinkLegacy } from '@eui/base';
import { EuiNotificationItemComponent, NotificationMetadata } from './eui-notification-item.component';
import { TranslateModule } from '@ngx-translate/core';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_BADGE } from '@eui/components/eui-badge';
import { EUI_OVERLAY } from '@eui/components/eui-overlay';
import { EUI_BUTTON } from '@eui/components/eui-button';

@Component({
    selector: 'eui-notifications',
    templateUrl: './eui-notifications.component.html',
    styleUrls: ['./styles/_index.scss'],
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        TranslateModule,
        EuiNotificationItemComponent,
        ...EUI_ICON,
        ...EUI_ICON_BUTTON,
        ...EUI_BADGE,
        ...EUI_OVERLAY,
        ...EUI_BUTTON,
    ],
})
export class EuiNotificationsComponent implements OnInit, OnChanges {
    @Output() refreshClick: EventEmitter<void> = new EventEmitter<void>();
    @Output() notificationsClick: EventEmitter<void> = new EventEmitter<void>();
    @Output() viewAllClick: EventEmitter<void> = new EventEmitter<void>();
    @Output() settingsClick: EventEmitter<MouseEvent> = new EventEmitter<MouseEvent>();
    @Output() markAllAsReadClick: EventEmitter<MouseEvent> = new EventEmitter<MouseEvent>();
    @Output() noNotificationFoundClick: EventEmitter<void> = new EventEmitter<void>();
    @Output() itemClick: EventEmitter<UxLinkLegacy<NotificationMetadata>> = new EventEmitter<UxLinkLegacy<NotificationMetadata>>();
    @Output() itemMarkAsReadClick: EventEmitter<UxLinkLegacy<NotificationMetadata>> = new EventEmitter<UxLinkLegacy<NotificationMetadata>>();

    isOverlayActive = false;
    currentDayNotifications = [];
    oldestNotifications = [];
    unreadNotifications = [];
    today: Date = new Date();

    @HostBinding('class') string = 'eui-notifications';

    @Input() count: number = null;
    @Input() items = [];
    @Input() unreadLabel: string = null;
    @Input() totalLabel: string = null;
    @Input() markAsReadLabel: string = null;
    @Input() markAsUnReadLabel: string = null;
    @Input() markAllAsReadLabel: string = null;
    @Input() settingsLabel: string = null;
    @Input() refreshLabel: string = null;
    @Input() viewAllNotificationsLabel: string = null;
    @Input() headerTitleLabel: string = null;
    @Input() noNotificationFoundLabel: string = null;
    @Input() nbUnreadCount: number = null;
    @Input() dateFormat = 'dd/MM/YYYY';
    @Input({ transform: booleanAttribute }) noNotificationFoundLink = false;
    @Input({ transform: booleanAttribute }) isShowMarkAsRead = true;
    @Input({ transform: booleanAttribute }) isShowViewAllAction = true;
    @Input({ transform: booleanAttribute })isHidePanelOnViewAllAction = true;
    @Input({ transform: booleanAttribute }) customUnreadCount = false;
    @Input({ transform: booleanAttribute }) isShowMarkAllAsReadButton = true;
    @Input({ transform: booleanAttribute }) isShowSettingsButton = true;
    @Input({ transform: booleanAttribute }) isShowRefreshButton = true;

    onClicked(event: MouseEvent | Event): void {
        this.notificationsClick.emit();
        consumeEvent(event);
        this.isOverlayActive = !this.isOverlayActive;
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.customUnreadCount) {
            const customUnreadCount = changes.customUnreadCount.currentValue;
            if (!customUnreadCount) {
                this.nbUnreadCount = this._getUnreadCount();
            }
        }
    }

    ngOnInit(): void {
        if (!this.customUnreadCount) {
            this.nbUnreadCount = this._getUnreadCount();
        }
    }

    onRefresh(event: Event): void {
        this.refreshClick.emit();
        consumeEvent(event);
    }

    onItemClick(link: UxLinkLegacy<NotificationMetadata>): void {
        this.itemClick.emit(link);
        consumeEvent(event);
    }

    onViewAllClick(event: Event): void {
        this.viewAllClick.emit();
        if (!this.isHidePanelOnViewAllAction) {
            consumeEvent(event);
        }
    }

    onNoNotificationFoundClick(): void {
        this.noNotificationFoundClick.emit();
    }

    onItemMarkAsRead(link: UxLinkLegacy<NotificationMetadata>): void {
        this.itemMarkAsReadClick.emit(link);
    }

    onMarkAllAsRead(e: MouseEvent): void {
        this.markAllAsReadClick.emit(e);
        consumeEvent(e);
    }

    onSettings(e: MouseEvent): void {
        this.settingsClick.emit(e);
        consumeEvent(e);
    }

    protected trackByFn(index: number, item: UxLinkLegacy<NotificationMetadata>): string {
        return item.id;
    }

    protected updateActiveState(isActive: boolean): void {
        this.isOverlayActive = isActive;
    }

    protected getAriaLabel(): string {
        if (this.count) {
            return this.count > 1
                ? ` You have ${this.count} notifications`
                : `You have ${this.count} notification`;
        }
        return 'Open notifications panel';
    }

    private _getUnreadCount(): number {
        const unreadNotifications = this.items.filter((link) => {
            if (link.metadata) {
                return link.metadata.read === false;
            }
            return false;
        });
        return unreadNotifications.length;
    }
}
