import { AsyncPipe } from '@angular/common';
import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    OnInit,
    OnDestroy,
    inject,
} from '@angular/core';
import { RouterLink } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';

import { EuiAppShellService, EuiThemeService } from '@eui/core';
import { EuiConfig } from '@eui/core';
import { EUI_CONFIG_TOKEN } from '@eui/core';

@Component({
    selector: 'eui-header-logo',
    templateUrl: './header-logo.component.html',
    styleUrl: './header-logo.component.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        RouterLink,
        AsyncPipe,
        TranslateModule,
    ],
})
export class EuiHeaderLogoComponent implements OnInit, OnDestroy {
    @HostBinding('class') cssClass = 'eui-header-logo';

    @Input() homeUrl = '..';

    protected asService = inject(EuiAppShellService);
    protected euiThemeService = inject(EuiThemeService);
    private logo: string;
    private assetsBaseUrl: string;
    private config = inject<EuiConfig>(EUI_CONFIG_TOKEN, { optional: true })!;

    ngOnInit(): void {
        this.asService?.setState({
            ...this.asService.state,
            hasHeaderLogo: true,
        });
        this.asService?.getState('activeLanguage').subscribe((activeLanguage) => {
            this.logo = 'logo-ec--' + activeLanguage;
        });
        this.assetsBaseUrl = this.config?.appConfig?.global?.eui?.assetsBaseUrl || 'assets';
    }

    get svgUrl(): string {
        return `${this.assetsBaseUrl}/ecl/ec/logo/positive/${this.logo}.svg`;
    }

    get svgUrlDark(): string {
        return `${this.assetsBaseUrl}/ecl/ec/logo/negative/${this.logo}.svg`;
    }

    ngOnDestroy(): void {
        this.asService?.setState({
            ...this.asService.state,
            hasHeaderLogo: false,
        });
    }
}
