import { Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, OnInit, ElementRef, inject } from '@angular/core';
import { EuiAppShellService } from '@eui/core';

@Component({
    selector: 'eui-header-app-name',
    template: '<ng-content />',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiHeaderAppNameComponent implements OnInit {
    @HostBinding('class') string = 'eui-header-app-name';
    protected asService = inject(EuiAppShellService);
    private elRef = inject(ElementRef);

    ngOnInit(): void {
        this.asService?.setState({
            ...this.asService.state,
            appName: this.elRef.nativeElement.textContent,
        });
    }
}
