import { Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, Input, booleanAttribute } from '@angular/core';

@Component({
    selector: 'eui-footer',
    template: '<ng-content />',
    changeDetection: ChangeDetectionStrategy.Default,
    styleUrl: './footer.component.scss',
    encapsulation: ViewEncapsulation.None,
})
export class EuiFooterComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-footer',
            this.euiPrimary ? 'eui-footer--primary': '',
        ].join(' ').trim();
    }

    @Input({ transform: booleanAttribute }) euiPrimary = false;
}
