import {
    booleanAttribute,
    ComponentRef,
    Directive,
    ElementRef,
    HostBinding,
    Renderer2,
    ViewContainerRef,
    inject,
    input,
    effect,
    output,
    computed,
    OnDestroy,
} from '@angular/core';
import { EuiIconSvgComponent } from '@eui/components/eui-icon';

/**
 * @description
 * Metadata for the icon directive used in input elements.
 * This interface defines the properties that can be used to configure the icon,
 * including the icon name, aria label, and whether the icon is clickable.
 */
export interface InputIconMetadata {
    /**
     * @description
     * The icon name to be displayed. This should correspond to an icon in the icon set.
     */
    icon: string;
    /**
     * @description
     * The aria-label for the icon, used for accessibility purposes.
     * This should describe the icon's function or purpose.
     */
    ariaLabel?: string;
    /**
     * @description
     * Indicates whether the icon is clickable. If true, the icon will respond to click events.
     * If false, the icon will not respond to click events and will not have pointer events enabled.
     */
    clickable?: boolean;
    /**
     * @description
     * The color of the icon. This can be used to customize the appearance of the icon.
     * If not specified, the default color will be used.
     */
    colour?: string;
}

/**
 * @description
 * Directive to add an icon to an eui-input-text element, allowing for click events too.
 *
 * @example
 * <input euiInputText euiIcon="eye:filled">
 */
@Directive({
    selector: 'input[euiInputText][euiIcon]',
})
export class EuiIconDirective implements OnDestroy {
    euiIcon = input<InputIconMetadata>()
    readonly = input(null, { transform: booleanAttribute });
    iconClick = output()
    @HostBinding('class')
    public get cssClasses(): string {
        return [this._cssClasses, this.euiIcon()?.icon ? `${this._elementRef.nativeElement.rootClassName}--loading` : ''].join(' ').trim();
    }
    public set cssClasses(value: string) {
        this._cssClasses = value;
    }
    protected _icon: ComponentRef<EuiIconSvgComponent>;
    private _euiUFlexWrapper: HTMLDivElement;
    private _cssClasses: string;
    private _elementRef = inject(ElementRef);
    private _viewContainerRef = inject(ViewContainerRef);
    private _renderer = inject(Renderer2);
    @HostBinding('attr.readonly') private _readonly: string | null;
    private listeners: (() => void)[] = [];
    private clickable = computed(() => this.euiIcon()?.clickable ?? false);
    private icon = computed(() => this.euiIcon()?.icon);
    private iconColour = computed(() => this.euiIcon()?.colour);
    private readonly DEFAULT_ICON_COLOUR = 'neutral-lighter';

    constructor() {
        effect(() => {
            this._readonly = this.readonly() ? '' : null;
            if(this.readonly()) {
                this.removeIcon();
                this.removeFlexWrapper();
            } else if (this.euiIcon()?.icon && this.readonly() === false) {
                // create wrapper
                this.createFlexWrapper();

                // dynamically create the icon
                this.createIcon();
                this._renderer.appendChild(this._euiUFlexWrapper, this._icon.location.nativeElement);
            }
        });

        effect(() => {
            const icon = this.icon();
            if(!icon) {
                this.removeIcon();
                this.removeFlexWrapper();
            } else if (!this._icon && !this.readonly()) {
                this.createFlexWrapper();
                this.createIcon();
            } else if (this._icon) {
                this._icon.setInput('icon', icon);
            }
        });

        effect(() => {
            const clickable = this.clickable();
            if(!clickable) {
                this._renderer.removeAttribute(this._icon.location.nativeElement, 'tabindex');
                this._renderer.setStyle(this._icon.location.nativeElement, 'pointer-events', 'none');
            } else {
                this._renderer.setAttribute(this._icon.location.nativeElement, 'tabindex', '0');
                this._renderer.removeStyle(this._icon.location.nativeElement, 'pointer-events');
            }
        });

        effect(() => {
            const iconColour = this.iconColour();
            if (this._icon) {
                this._icon.setInput('fillColor', iconColour || this.DEFAULT_ICON_COLOUR);
            }
        })
    }

    ngOnDestroy(): void {
        // Clean up listeners
        this.listeners?.forEach(listener => listener());
        this.listeners = [];
    }

    /**
     * create a flex wrapper for the input to hold the icon
     *
     * @private
     */
    private createFlexWrapper(): void {
        if (!this._euiUFlexWrapper && !this.doesParentHasAFlexWrapper()) {
            this._euiUFlexWrapper = this._renderer.createElement('div');
            this._renderer.addClass(this._euiUFlexWrapper, 'eui-u-flex');
            this._renderer.setAttribute(this._euiUFlexWrapper, 'flexWrapper', null);
            this._renderer.setStyle(this._euiUFlexWrapper, 'position', 'relative');
            this._renderer.insertBefore(
                this._elementRef.nativeElement.parentElement,
                this._euiUFlexWrapper,
                this._elementRef.nativeElement,
            );
            this._renderer.appendChild(this._euiUFlexWrapper, this._elementRef.nativeElement);
        }
        if (!this._euiUFlexWrapper && this.doesParentHasAFlexWrapper()) {
            this._euiUFlexWrapper = this._elementRef.nativeElement.parentElement;
        }
    }

    /**
     * checks if the parent has a flexWrapper. This is used to avoid creating multiple flexWrappers
     *
     * @private
     */
    private doesParentHasAFlexWrapper(): boolean {
        return this._elementRef.nativeElement.parentElement.hasAttribute('flexWrapper');
    }

    /**
     * removes the flexWrapper while keeping the input element intact
     *
     * @private
     */
    private removeFlexWrapper(): void {
        if (this._euiUFlexWrapper) {
            this._renderer.insertBefore(this._euiUFlexWrapper.parentElement, this._elementRef.nativeElement, this._euiUFlexWrapper);
            this._renderer.removeChild(this._euiUFlexWrapper.parentElement, this._euiUFlexWrapper);
            this._euiUFlexWrapper.remove();
            this._euiUFlexWrapper = null;
        }
    }

    private registerIconClickListener(): void {
        this.listeners.push(
            this._renderer.listen(this._icon.location.nativeElement, 'click', this.onIconClicked.bind(this)),
            this._renderer.listen(this._icon.location.nativeElement, 'keydown.enter', this.onIconClicked.bind(this)),
            this._renderer.listen(this._icon.location.nativeElement, 'focus', () => {
                if (!this.readonly() && this.euiIcon()?.clickable) {
                    this._renderer.setStyle(this._icon.location.nativeElement, 'transition', 'none');
                    this._renderer.setStyle(this._icon.location.nativeElement, 'outline-offset', '-2px !important');
                    this._renderer.setStyle(this._icon.location.nativeElement, 'outline', '2px solid var(--eui-c-focus-visible) !important');
                }
            }),
            this._renderer.listen(this._icon.location.nativeElement, 'blur', () => {
                this._renderer.removeStyle(this._icon.location.nativeElement, 'outline');
                this._renderer.removeStyle(this._icon.location.nativeElement, 'outline-offset');
                this._renderer.removeStyle(this._icon.location.nativeElement, 'transition');
            }),
        );
    }

    /**
     * creates the icon component
     *
     * @private
     */
    private createIcon(): void {
        if (!this._icon) {
            this._icon = this._viewContainerRef.createComponent(EuiIconSvgComponent);
            this._icon.instance.isInputIcon = true;
            this._icon.instance.euiEnd = true;
            this._icon.instance.icon = this.euiIcon()?.icon;
            this._icon.instance.ariaLabel = this.euiIcon()?.ariaLabel;
            this._icon.instance.fillColor = this.euiIcon()?.colour || this.DEFAULT_ICON_COLOUR;
            this.registerIconClickListener();

            this._renderer.appendChild(this._euiUFlexWrapper, this._icon.location.nativeElement);
        }
    }

    /**
     * @description
     * Handles the click event on the icon.
     */
    private onIconClicked(): void {
        this.iconClick.emit();
    }

    /**
     * removes the icon component
     *
     * @private
     */
    private removeIcon(): void {
        if (this._icon) {
            const index = this._viewContainerRef.indexOf(this._icon.hostView);
            this._viewContainerRef.detach(index);
            this._icon = null;
            // Clean up listeners
            this.listeners.forEach(listener => listener());
            this.listeners = [];
        }
    }
}
