import {
    Component,
    ChangeDetectionStrategy,
    HostBinding,
    ViewEncapsulation,
    Input,
    OnInit,
    OnDestroy,
    AfterViewInit,
    ViewContainerRef,
    ViewChild,
    TemplateRef,
    ContentChildren,
    QueryList,
    ElementRef,
    Renderer2,
    booleanAttribute,
    EventEmitter,
    inject,
    PLATFORM_ID,
    Output,
    ChangeDetectorRef,
    signal,
} from '@angular/core';
import { DOCUMENT, isPlatformBrowser, isPlatformServer } from '@angular/common';
import {
    CdkScrollable,
    ConnectionPositionPair,
    FlexibleConnectedPositionStrategy,
    FlexibleConnectedPositionStrategyOrigin,
    GlobalPositionStrategy,
    Overlay,
    OverlayRef,
    ScrollDispatcher,
    OverlayModule,
} from '@angular/cdk/overlay';
import { A11yModule } from '@angular/cdk/a11y';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { ObserversModule } from '@angular/cdk/observers';
import { fromEvent, Subject, Subscription, takeUntil } from 'rxjs';
import { TemplatePortal } from '@angular/cdk/portal';
import { ActiveDescendantKeyManager, Highlightable } from '@angular/cdk/a11y';

import { openClose } from './animations/open-close';
import { EuiDropdownItemComponent } from './dropdown-item/eui-dropdown-item.component';
import { EuiDropdownService } from './eui-dropdown.service';

/**
 * @description
 * The eui-dropdown component is composed of a trigger, usually a button, which allows to display the dropdown content specified with the eui-dropdown-content.
 */
@Component({
    selector: 'eui-dropdown',
    templateUrl: './eui-dropdown.component.html',
    styleUrl: './eui-dropdown.scss',
    animations: [openClose],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        OverlayModule,
        ScrollingModule,
        A11yModule,
        ObserversModule,
    ],
    providers: [EuiDropdownService],
})
export class EuiDropdownComponent implements OnInit, OnDestroy, AfterViewInit {
    /**
     * Sets the `data-e2e` attribute for dropodown panel. Default: `eui-dropdown`.
     *
     * @default 'eui-dropdown'
     */
    @Input() e2eAttr = 'eui-dropdown';
    /**
     * Sets the `tabindex` attribute for a dropdown panel.
     *
     * @default -1
     */
    @Input() tabIndex = -1;
    /**
     * Sets the `width` attribute for the dropdown panel.
     *
     * @default 'auto'
     */
    @Input() width = 'auto';
    /**
     * Sets the `height` attribute for the dropdown panel.
     *
     * @default 'auto'
     */
    @Input() height = 'auto';
    /**
     * Sets the `position` attribute for the dropdown panel.
     *
     * @default 'bottom'
     */
    @Input() position: 'top' | 'right' | 'bottom' | 'left' = 'bottom';
    /**
     * Sets the `subDropdownPosition` attribute for a multi-level dropdown.
     *
     * @default 'right'
     */
    @Input() subDropdownPosition: 'right' | 'left' = 'right';
    /**
     * Sets the `isBlock` attribute in order for the dropdown to take the full width of the parent container.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isBlock = false;
    /**
     * Sets the `isDropDownRightAligned` attribute to align the menu panel on the right of the opening element.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isDropDownRightAligned = false;
    /**
     * Sets the `hasClosedOnClickInside` attribute which controls the auto-closing of the menu when clicking inside.
     *
     * @default true
     */
    @Input({ transform: booleanAttribute }) hasClosedOnClickInside = true;
    /**
     * Sets the `isLabelUpdatedFromSelectedItem` attribute which updates the label of the trigger with the selected item.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isLabelUpdatedFromSelectedItem = false;
    /**
     * Sets the `isExpandOnHover` attribute which opens the sub dropdown upon hover.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isExpandOnHover = false;
    /**
     * Sets the `hasTabNavigation` attribute to tab within the dropdown content when there is rich content.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) hasTabNavigation = false;
    /**
     * Sets the `isRightClickEnabled` attribute to trigger the menu using the right mouse click.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isRightClickEnabled = false;
    @Input({ transform: booleanAttribute }) euiDisabled = false;
    /**
     * Event emitted when the menu expands.
     */
    @Output() expand: EventEmitter<boolean> = new EventEmitter();
    @Output() isDropdownOpen: EventEmitter<boolean> = new EventEmitter();

    @ViewChild('templatePortalContent') templatePortalContent: TemplateRef<unknown>;
    @ViewChild('triggerRef') triggerRef: ElementRef<HTMLElement>;
    @ContentChildren(EuiDropdownItemComponent, { descendants: true }) euiDropdownItems: QueryList<Highlightable & EuiDropdownItemComponent>;

    public trapFocusAutoCapture = true;
    public parentDropdown: EuiDropdownComponent;

    public isOpened = signal(false);
    protected dropdownService = inject(EuiDropdownService);
    private mousePositionX = 0;
    private mousePositionY = 0;
    private initialScrollX = 0;
    private initialScrollY = 0;
    private originX: 'start' | 'end' | 'center' = 'start';
    private originY: 'top' | 'bottom' | 'center' = 'bottom';
    private overlayX: 'start' | 'end' | 'center' = 'start';
    private overlayY: 'top' | 'bottom' | 'center' = 'top';
    private templatePortal: TemplatePortal;
    private overlayRef: OverlayRef;
    private destroy$ = new Subject<boolean>();
    private scrollDispatcherSubscription = new Subscription();
    private keydownListenerSubscription = new Subscription();
    private euiDropdownItemsEventSubscriptions: Subscription[] = [];
    private activeDescendantKeyManagerChangeSubscription = new Subscription();
    private activeDescendantKeyManager: ActiveDescendantKeyManager<EuiDropdownItemComponent>;
    private origin: HTMLElement;
    private positionStrategy: FlexibleConnectedPositionStrategy;
    private scrollSubscription = new Subscription();
    private overlay = inject(Overlay);
    private viewContainerRef = inject(ViewContainerRef);
    private scrollDispatcher = inject(ScrollDispatcher);
    private cd = inject(ChangeDetectorRef);
    protected _renderer = inject(Renderer2);
    protected platformId = inject(PLATFORM_ID);
    private document = inject<Document>(DOCUMENT);
    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-dropdown',
            this.isBlock ? 'eui-dropdown--block' : '',
            this.isRightClickEnabled ? 'eui-dropdown--contextual-menu' : '',
        ].join(' ').trim();
    }

    ngOnInit(): void {
        // Currently, the `cdkTrapFocusAutoCapture` is only checked once on init.
        if (this.hasDropdownItems) {
            this.trapFocusAutoCapture = false;
        } else {
            this.trapFocusAutoCapture = true;
        }

        if (this.hasTabNavigation) {
            this.trapFocusAutoCapture = true;
            this.hasClosedOnClickInside = false;
        }

        if (this.isRightClickEnabled) {
            this.hasTabNavigation = false;  // UX wise, contextual menu contains only menu items accessible through arrow keys nav
        }

        this.setPosition();

        // TODO: Remove this in the future, when the `isDropdownOpen` signal is used instead.
        this.isDropdownOpen.subscribe(isOpen => this.dropdownService.isDropdownOpen.emit(isOpen));
    }

    ngAfterViewInit(): void {
        this.templatePortal = new TemplatePortal(this.templatePortalContent, this.viewContainerRef);

        if(this.triggerRef && this.triggerRef.nativeElement.firstElementChild) {
            this._renderer?.setAttribute(this.triggerRef.nativeElement.firstElementChild, 'aria-haspopup', 'true');
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
        this.euiDropdownItemsEventSubscriptions.forEach((euiDropdownItemsEventSubscription) => {
            euiDropdownItemsEventSubscription.unsubscribe();
        });
        this.keydownListenerSubscription.unsubscribe();
        this.scrollDispatcherSubscription.unsubscribe();
        this.activeDescendantKeyManagerChangeSubscription.unsubscribe();
        this.overlayRef?.dispose();
        this.overlayRef = null;
        this.activeDescendantKeyManager = null;
        this.scrollSubscription.unsubscribe();
    }

    /**
     * Whether the eui-dropdown is open.
     *
     * @deprecated This property will be removed in the future. Use `isOpened` signal instead.
     *
     * @usageNotes
     * ```html
     * <eui-dropdown #dropdown>
     *      <my-component *ngIf="dropdown.isOpen"></my-component>
     * </eui-dropdown>
     * ```
     * @returns A boolean with value `true` when open, otherwise `false`.
     */
    get isOpen(): boolean {
        return this.isOpened();
    }
    /**
     * Method fired upon clicking the dropdown trigger.
     *
     * @param e Event triggered when the dropdown trigger is clicked.
     */
    public onTriggerClicked(e: Event): void {
        if (
            !(e.target as HTMLElement).querySelector('.disabled') &&
            !(e.target as HTMLElement).querySelector(':disabled') &&
            !this.isOpened()
        ) {
            if (this.isBlock) {
                this.width = this.triggerRef.nativeElement.offsetWidth + 'px';
            }

            this.openDropdown(e.target as HTMLElement);
            this.expand.emit(true);
            e.stopPropagation();
        }
    }
    /**
     * Method fired upon right clicking the dropdown trigger in case of context menu.
     *
     * @param e Event triggered when the dropdown trigger is right clicked.
     */
    public onTriggerRightClicked(e: Event): void {
        if (
            !(e.target as HTMLElement).querySelector('.disabled') &&
            !(e.target as HTMLElement).querySelector(':disabled') &&
            !this.isOpened()
        ) {
            if (this.isBlock) {
                this.width = this.triggerRef.nativeElement.offsetWidth + 'px';
            }

            this.mousePositionX = (e as PointerEvent).clientX;
            this.mousePositionY = (e as PointerEvent).clientY;
            if(isPlatformBrowser(this.platformId)) {
                this.initialScrollX = window.pageXOffset;
                this.initialScrollY = window.pageYOffset;
            }

            this.openDropdown(e.target as HTMLElement);
            e.preventDefault();
            e.stopPropagation();
        }
    }
    /**
     * Method fired upon clicking the dropdown content.
     *
     */
    public onClick(): void {
        if (
            this.hasClosedOnClickInside &&
            !this.activeDescendantKeyManager?.activeItem.subDropdown &&
            !this.activeDescendantKeyManager?.activeItem.elementRef?.nativeElement?.disabled
        ) {
            this.closeDropdown(true);
        }
    }

    /**
     * Method fired when the dropdown is opened.
     *
     * @param origin Origin of the dropdown position
     * @param position Position of the dropdown
     * @param position.x X coordinate of the dropdown position
     * @param position.y Y coordinate of the dropdown position
     */
    public openDropdown(origin: HTMLElement, position?: { x: number, y: number }): void {
        this.origin = origin;

        if (position) {
            this.mousePositionX = position.x;
            this.mousePositionY = position.y;
            if(isPlatformBrowser(this.platformId)) {
                this.initialScrollX = window.pageXOffset;
                this.initialScrollY = window.pageYOffset;
            }
        }

        if (this.isRightClickEnabled) {
            this.scrollSubscription = fromEvent(window, 'scroll').subscribe((event: Event) => {
                this.overlayRef?.updatePositionStrategy(this.getContextualMenuPositionStrategy());
            });
        }

        if (!this.isTriggerFocusableOnClose(origin)) {
            this.origin = origin.closest('button:not([disabled])') || (this.triggerRef.nativeElement.firstChild as HTMLElement);

            if (!this.origin) {
                this.origin = origin.closest('a');
            }

            if (!this.origin) {
                this.origin = origin;
            }
        }

        if (!this.isOpened()) {
            this.scrollDispatcherSubscription = this.scrollDispatcher
                .ancestorScrolled(this.origin)
                .pipe(takeUntil(this.destroy$))
                .subscribe((event: CdkScrollable) => {
                    if (!this.isVisible(this.origin, event ? event.getElementRef().nativeElement : this.document.querySelector('body'))) {
                        this.closeDropdown();
                    }
                });

            const positionStrategy = this.isRightClickEnabled ? this.getContextualMenuPositionStrategy() : this.getPositionStrategy();
            const scrollStrategy = this.overlay.scrollStrategies.reposition({ scrollThrottle: 10 });

            this.overlayRef = this.overlay.create({
                hasBackdrop: false,
                backdropClass: 'eui-dropdown__backdrop',
                panelClass: ['eui-dropdown__panel', this.subDropdownPosition === 'right' ? 'eui-dropdown--subdropdown-position-right' : 'eui-dropdown--subdropdown-position-left'],
                positionStrategy,
                scrollStrategy,
                disposeOnNavigation: true,
            });
            this.overlayRef.attach(this.templatePortal);

            if (this.isRightClickEnabled) {
                this.overlayRef?.updatePositionStrategy(this.getContextualMenuPositionStrategy());
            }

            this.overlayRef
                .outsidePointerEvents()
                .pipe(takeUntil(this.destroy$))
                .subscribe(() => {
                    this.closeDropdown();
                });
            this.overlayRef
                .backdropClick()
                .pipe(takeUntil(this.destroy$))
                .subscribe(() => {
                    this.closeDropdown();
                });
            this.overlayRef
                .keydownEvents()
                .pipe(takeUntil(this.destroy$))
                .subscribe((keyboardEvent) => {
                    if (keyboardEvent.key?.toLowerCase() === 'escape') {
                        this.closeDropdown();
                    }
                });

            if (this.hasDropdownItems) {
                this.euiDropdownItems.toArray().forEach((euiDropdownItem, i) => {
                    if (this.isExpandOnHover) {
                        this.euiDropdownItemsEventSubscriptions[i] = fromEvent(
                            euiDropdownItem.elementRef.nativeElement,
                            'mouseenter',
                        ).pipe(takeUntil(this.destroy$)).subscribe((e: MouseEvent) => {
                            this.activeDescendantKeyManager.setActiveItem(euiDropdownItem);
                            if (this.activeDescendantKeyManager.activeItem?.subDropdown) {
                                this.activeDescendantKeyManager.activeItem?.subDropdown.setParentDropdown(this);
                                this.activeDescendantKeyManager.activeItem?.subDropdown.overlayRef.detachBackdrop();
                                this.keydownListenerSubscription.unsubscribe();
                            }

                            const triggerOutsidePointerEvents = (subDropdown: EuiDropdownComponent): void => {
                                subDropdown?.overlayRef?._outsidePointerEvents.next(e);

                                if (subDropdown?.hasDropdownItems) {
                                    subDropdown.euiDropdownItems.toArray().forEach((s) => {
                                        triggerOutsidePointerEvents(s.subDropdown);
                                    });
                                }
                            };

                            this.euiDropdownItems
                                .filter((item) => !item.isFocus)
                                .forEach((euiDropdownItemHavingSubDropdown) => {
                                    triggerOutsidePointerEvents(euiDropdownItemHavingSubDropdown.subDropdown);
                                });
                        });
                    } else {
                        this.euiDropdownItemsEventSubscriptions[i] = fromEvent(
                            euiDropdownItem.elementRef.nativeElement,
                            'click',
                        ).pipe(takeUntil(this.destroy$)).subscribe(() => {
                            this.activeDescendantKeyManager.setActiveItem(euiDropdownItem);
                            if (this.activeDescendantKeyManager.activeItem?.subDropdown) {
                                this.activeDescendantKeyManager.activeItem?.subDropdown.setParentDropdown(this);
                                this.activeDescendantKeyManager.activeItem?.subDropdown.overlayRef.detachBackdrop();
                                this.keydownListenerSubscription.unsubscribe();
                            }

                            const labelElement = this.triggerRef.nativeElement.querySelector('button .eui-label');
                            if (this.isLabelUpdatedFromSelectedItem && labelElement) {
                                (labelElement as HTMLElement).innerText = euiDropdownItem.elementRef.nativeElement.innerText;
                            }
                        });
                    }
                });

                this.activeDescendantKeyManager = new ActiveDescendantKeyManager(this.euiDropdownItems)
                    .withHomeAndEnd(true)
                    .withVerticalOrientation(true)
                    .withWrap();
                this.activeDescendantKeyManager.setFirstItemActive();
            }

            this.createKeyboardHandlerSubscription();
            this.isOpened.set(true);
            this.isDropdownOpen.emit(true);
        }
    }

    /**
     * Close a dropdown
     *
     * @param recursively If true, close the parent dropdown as well
     */
    public closeDropdown(recursively = false): void {
        this.isOpened.set(false);
        this.expand.emit(false);
        this.euiDropdownItemsEventSubscriptions.forEach((euiDropdownItemsEventSubscription) => {
            euiDropdownItemsEventSubscription.unsubscribe();
        });
        this.keydownListenerSubscription.unsubscribe();
        if (this.hasDropdownItems) {
            this.activeDescendantKeyManager?.setFirstItemActive();
        }
        this.scrollDispatcherSubscription.unsubscribe();
        this.activeDescendantKeyManagerChangeSubscription.unsubscribe();
        this.scrollSubscription.unsubscribe();
        this.overlayRef?.dispose();
        this.overlayRef = null;
        this.activeDescendantKeyManager = null;
        if (this.trapFocusAutoCapture) {
            this.origin.focus();
        }
        if (recursively && this.parentDropdown) {
            this.parentDropdown.closeDropdown(true);
        }

        this.isDropdownOpen.emit(false);
    }
    /**
     * Method fired when the dropdown content is changed.
     *
     */
    public projectContentChanged(): void {
        if (!this.isRightClickEnabled) {
            this.positionStrategy = this.getPositionStrategy();
            this.overlayRef.updatePositionStrategy(this.positionStrategy);
        }
    }
    /**
     * Handles the keyboard navigation on the menu items upon opening the dropdown.
     *
     */
    public createKeyboardHandlerSubscription(): void {
        this.keydownListenerSubscription = fromEvent(document, 'keydown').subscribe((event: KeyboardEvent) => {
            if (this.isOpened()) {
                if (
                    event.code === 'Enter' &&
                    !this.hasTabNavigation &&
                    !this.activeDescendantKeyManager?.activeItem.elementRef?.nativeElement?.disabled
                ) {
                    this.activeDescendantKeyManager?.activeItem.focus();
                    // eslint-disable-next-line
                    this.isExpandOnHover
                        ? this.activeDescendantKeyManager?.activeItem.mouseenter()
                        : this.activeDescendantKeyManager?.activeItem.click();

                    if (this.activeDescendantKeyManager?.activeItem.subDropdown) {
                        this.activeDescendantKeyManager.activeItem.subDropdown.setParentDropdown(this);
                        this.keydownListenerSubscription.unsubscribe();
                    } else {
                        this.closeDropdown();
                    }
                    event.preventDefault();
                } else if ((this.subDropdownPosition === 'right' && event.code === 'ArrowLeft') || this.subDropdownPosition === 'left' && event.code === 'ArrowRight') {
                    if (this.parentDropdown) {
                        this.parentDropdown.createKeyboardHandlerSubscription();
                        this.closeDropdown();
                    }
                    event.preventDefault();
                } else if ((this.subDropdownPosition === 'right' && event.code === 'ArrowRight') || (this.subDropdownPosition === 'left' && event.code === 'ArrowLeft')) {
                    if (this.activeDescendantKeyManager?.activeItem.subDropdown) {
                        this.activeDescendantKeyManager.activeItem.focus();
                        // eslint-disable-next-line
                        this.isExpandOnHover
                            ? this.activeDescendantKeyManager.activeItem.mouseenter()
                            : this.activeDescendantKeyManager.activeItem.click();
                        this.activeDescendantKeyManager.activeItem.subDropdown.setParentDropdown(this);
                        this.keydownListenerSubscription.unsubscribe();
                    }
                    event.preventDefault();
                } else if (event.code === 'Tab' && !this.hasTabNavigation) {
                    this.closeDropdown(true);
                } else {
                    this.activeDescendantKeyManager?.onKeydown(event);
                }

                this.cd.markForCheck();
            }
        });
    }
    /**
     * Sets the parent dropdown for a sub-dropdown.
     *
     * @param parentDropdown Parent dropdown component
     */
    public setParentDropdown(parentDropdown: EuiDropdownComponent): void {
        this.parentDropdown = parentDropdown;
        this.position = this.subDropdownPosition;

        this.setPosition();

        const positionStrategy = this.getPositionStrategy();
        this.overlayRef.updatePositionStrategy(positionStrategy);
    }
    /**
     * Method that returns the dropdown items.
     *
     * @type {boolean}
     */
    private get hasDropdownItems(): boolean {
        return this.euiDropdownItems?.length > 0;
    }
    /**
     * Method that returns the strategy for the overlay position.
     *
     * @type {FlexibleConnectedPositionStrategy}
     */
    private getPositionStrategy(): FlexibleConnectedPositionStrategy {
        return this.overlay
            .position()
            .flexibleConnectedTo(this.origin as FlexibleConnectedPositionStrategyOrigin)
            .withPositions([
                new ConnectionPositionPair(
                    { originX: this.originX, originY: this.originY },
                    { overlayX: this.overlayX, overlayY: this.overlayY },
                ),
            ])
            .withFlexibleDimensions(false)
            .withLockedPosition(true);
    }
    /**
     * Method that returns the strategy for the contextual menu position.
     *
     * @type {GlobalPositionStrategy}
     */
    private getContextualMenuPositionStrategy(): GlobalPositionStrategy {
        if(isPlatformServer(this.platformId)) {
            throw new Error('getContextualMenuPositionStrategy is not supported on the server');
        }
        const panelHeight = this.overlayRef?.overlayElement.clientHeight || 0;
        const scrollX = window.scrollX || window.pageXOffset;
        const scrollY = window.scrollY || window.pageYOffset;
        const newX = this.mousePositionX + (this.initialScrollX - scrollX);
        const newY = this.mousePositionY + (this.initialScrollY - scrollY);
        const menuBottomPosition = newY + panelHeight;
        const isMenuBelowWindowBottom = menuBottomPosition > window.innerHeight;

        const positionStrategy = this.overlay
            .position()
            .global()
            .left(newX + 'px');

        if (isMenuBelowWindowBottom) {
            positionStrategy.bottom(window.innerHeight - newY + 'px');
        } else {
            positionStrategy.top(newY + 'px');
        }

        return positionStrategy;
    }
    /**
     * Method that checks if the dropdown is visible.
     *
     * @param origin Origin of the dropdown position
     * @param scrollableParent Scrollable parent element
     * @type {boolean}
     */
    private isVisible(origin: HTMLElement, scrollableParent: HTMLElement): boolean {
        const originY = origin.getBoundingClientRect().y;
        const scrollableParentY = Math.abs(scrollableParent.getBoundingClientRect().y);
        const scrollableParentHeight = scrollableParent.getBoundingClientRect().height - 50;

        return (
            (originY > 0 && originY < scrollableParentHeight) ||
            (originY - scrollableParentY > 0 && originY < scrollableParentY + scrollableParentHeight)
        );
    }
    /**
     * Method that checks if the trigger is focusable upon closing the dropdown panel.
     *
     * @param origin Origin html element
     * @type {boolean}
     */
    private isTriggerFocusableOnClose(origin: HTMLElement): boolean {
        return origin.matches('button:not([disabled])') || origin.matches('a');
    }
    /**
     * Method that sets the position of the dropdown panel.
     *
     */
    private setPosition(): void {
        if (this.position === 'top') {
            this.originY = 'top';
            this.overlayY = 'bottom';

            if (this.isDropDownRightAligned) {
                this.originX = 'end';
                this.overlayX = 'end';
            }
        }
        if (this.position === 'right') {
            this.originX = 'end';
            this.overlayX = 'start';
            this.overlayY = 'center';
        }
        if (this.position === 'bottom') {
            this.originY = 'bottom';
            this.overlayY = 'top';

            if (this.isDropDownRightAligned) {
                this.originX = 'end';
                this.overlayX = 'end';
            }
        }
        if (this.position === 'left') {
            this.originX = 'start';
            this.overlayX = 'end';
            this.overlayY = 'center';
        }
    }
}
