export interface UserDetails {
    userId: string;
    firstName?: string;
    lastName?: string;
    fullName?: string;
}

// TODO: on v18 replace any with no object as a type and declare it as breaking change
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export interface UserPreferences<DASHBOARD = any, T = any> {
    dashboard?: DASHBOARD;
    lang?: string;

    [key: string]: string | DASHBOARD | T;
}

export const initialUserPreferences: UserPreferences = Object.assign(
    {},
    {
        lang: null,
        dashboard: null,
    },
);
