import { Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, Input } from '@angular/core';

/**
 * @description
 * Component used internally by `eui-autocomplete` with the option `groupBy`. It allows to display the options in groups.
 */
@Component({
    selector: 'eui-autocomplete-option-group',
    template: '<ng-content/>',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
})
export class EuiAutocompleteOptionGroupComponent {
    /**
     * ARIA role for the host element to ensure proper accessibility.
     * @default 'optgroup'
     */
    @HostBinding('attr.role') role = 'optgroup';

    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return ['eui-autocomplete-option-group'].join(' ').trim();
    }

    /**
     * Sets the label of the group.
     */
    @Input() label: string;

}
