import { Component, HostBinding, input, ViewEncapsulation } from '@angular/core';

export type EuiResizablePosition = 'left' | 'right';

@Component({
    selector: 'eui-resizable',
    templateUrl: './eui-resizable.component.html',
    styleUrls: ['./styles/index.scss'],
    encapsulation: ViewEncapsulation.None,
})
export class EuiResizableComponent {
    /**
     * This is used to determine the placement of the resizable handle and the resizing behavior.
     * Possible values are 'left' or 'right'. Default is 'right'.
     */
    position = input<EuiResizablePosition>('right');
    @HostBinding('class') get cssClasses(): string {
        return [
            'eui-resizable',
            this.position() === 'left' ? 'eui-resizable--left' : 'eui-resizable--right',
        ].join(' ').trim();
    }
    @HostBinding('attr.data-e2e') e2e = 'eui-resizable';
}
