import { AsyncPipe } from '@angular/common';
import { Component, HostBinding, Input, ViewEncapsulation, inject } from '@angular/core';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EuiAppShellService, consumeEvent } from '@eui/core';

@Component({
    selector: 'eui-sidebar-toggle',
    templateUrl: './sidebar-toggle.component.html',
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        ...EUI_ICON_BUTTON,
    ],
})
export class EuiSidebarToggleComponent {
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-sidebar-toggle';
    @HostBinding('class') name = 'eui-sidebar-toggle';

    @Input() iconSvgFillColor;
    asService = inject(EuiAppShellService);

    onToggleSidebar(event: Event): void {
        this.asService.sidebarToggle();
        consumeEvent(event);
    }
}
