import { Component, HostBinding, ViewEncapsulation, OnInit, OnDestroy, inject } from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { DOCUMENT } from '@angular/common';

@Component({
    selector: 'eui-app-sidebar-footer',
    template: '<ng-content/>',
    encapsulation: ViewEncapsulation.None,
})
export class EuiAppSidebarFooterComponent implements OnInit, OnDestroy {
    @HostBinding() class = 'eui-app-sidebar-footer';
    private asService = inject(EuiAppShellService);
    private document = inject<Document>(DOCUMENT);

    ngOnInit(): void {
        this.asService.activateSidebarFooter();
    }

    ngOnDestroy(): void {
        this.document.documentElement.style.removeProperty('--eui-app-sidebar-footer-height');
    }
}
