import {
    AUTO_STYLE,
    animate,
    state,
    style,
    transition,
    trigger,
  } from '@angular/animations';

export const euiAnimationCollapse = trigger('euiAnimationCollapse', [
    state('false', style({ height: AUTO_STYLE, visibility: AUTO_STYLE })),
    state('true', style({ height: '0', visibility: 'hidden', paddingTop: '0', paddingBottom: '0' })),
    transition('false => true', animate(100 + 'ms ease-in')),
    transition('true => false', animate(200 + 'ms ease-out')),
]);
