import { Inject, Injectable, Optional, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { StorageService } from './storage.service';
import { LogService } from '../log/log.service';

/**
 * localStorage service
 */
@Injectable()
export class LocalStorageService extends StorageService {
    static NAME = 'LocalStorageService';

    constructor(@Optional() protected log: LogService, @Inject(PLATFORM_ID) private platformId: unknown) {
        super();
    }

    /**
     * the name of the storage service
     */
    name(): string {
        return LocalStorageService.NAME;
    }

    /**
     * retrieve an object from local storage
     * @param key the associated key
     * @returns the value or undefined, if case of error
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    get(key: string): any {
        if(isPlatformBrowser(this.platformId)) {
            try {
                const serialized = localStorage.getItem(key);
                return serialized && JSON.parse(serialized);
            } catch (err) {
                if (this.log) {
                    this.log.error(this.name(), 'get', err);
                }
                return undefined;
            }
        }
    }

    /**
     * sets an object in local storage
     * @param key the associated key
     * @param value the value to set
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    set(key: string, value: any): void {
        if(isPlatformBrowser(this.platformId)) {
            try {
                const serialized = JSON.stringify(value);
                localStorage.setItem(key, serialized);
            } catch (err) {
                if (this.log) {
                    this.log.error(this.name(), 'set', err);
                }
            }
        }
    }

    /**
     * removes an object from local storage
     * @param key the associated key
     */
    remove(key: string): void {
        if(isPlatformBrowser(this.platformId)) {
            try {
                localStorage.removeItem(key);
            } catch (err) {
                if (this.log) {
                    this.log.error(this.name(), 'remove', err);
                }
            }
        }
    }
}
