import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    OnInit,
    OnDestroy,
    Input,
    booleanAttribute,
    inject,
} from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { AsyncPipe, DOCUMENT } from '@angular/common';
import { EuiSidebarToggleComponent } from '../../eui-sidebar-toggle';
import { EUI_LANGUAGE_SELECTOR } from '@eui/components/eui-language-selector';

@Component({
    selector: 'eui-app-toolbar',
    templateUrl: './toolbar.component.html',
    styleUrl: './toolbar.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        EuiSidebarToggleComponent,
        ...EUI_LANGUAGE_SELECTOR,
    ],
})
export class EuiAppToolbarComponent implements OnInit, OnDestroy {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-app-toolbar',
            this.euiSecondary ? 'eui-app-toolbar--secondary eui--secondary' : 'eui-app-toolbar--primary eui--primary',
        ].join(' ').trim();
    }

    @HostBinding('attr.role') role = 'banner';

    @Input({ transform: booleanAttribute }) euiSecondary = false;
    asService = inject(EuiAppShellService);
    private document = inject<Document>(DOCUMENT);

    ngOnInit(): void {
        this.asService.activateToolbar();
    }

    ngOnDestroy(): void {
        this.asService.setState({
            ...this.asService.state,
            hasToolbar: false,
        });
        this.document.documentElement.style.removeProperty('--eui-app-toolbar-height');
    }
}
