import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    HostListener,
    Output,
    EventEmitter,
    booleanAttribute,
    inject,
    ElementRef,
    Renderer2,
} from '@angular/core';
import { CdkTrapFocus } from '@angular/cdk/a11y';

@Component({
    selector: 'eui-overlay',
    templateUrl: './eui-overlay.component.html',
    styleUrls: ['./styles/_index.scss'],
    encapsulation: ViewEncapsulation.None,
    imports: [CdkTrapFocus],
})
export class EuiOverlayComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-overlay',
            this.isActive ? 'eui-overlay--is-active' : '',
            this.euiHighlighted ? 'eui-overlay--highlighted' : '',
            this.position ? 'eui-overlay-offset eui-overlay-offset--position-' + this.position : '',
            this.width ? 'eui-overlay-offset eui-overlay-offset--width-' + this.width : '',
            this.fixedWidth ? 'eui-overlay-offset eui-overlay-offset--fixed-width-' + this.fixedWidth : '',
            this.hasClosedOnClickOutside ? 'eui-overlay--slideInRight' : '',
        ]
            .join(' ')
            .trim();
    }

    @HostBinding('attr.role') role = 'dialog';
    @HostBinding('attr.aria-label') 'aria-label' = 'dialogOverlay';
    @HostBinding('attr.inert')
    get inert(): string {
        return this.isActive ? null : '';
    }

    @Input({ transform: booleanAttribute }) isActive = false;
    @Input({ transform: booleanAttribute }) euiHighlighted = false;
    @Input({ transform: booleanAttribute }) hasClosedOnClickOutside = false;
    @Input() position = 'right';
    @Input() width: string;
    @Input() fixedWidth: string;

    @Output() activeState = new EventEmitter<boolean>();
    private readonly elementRef: ElementRef = inject(ElementRef);
    private readonly renderer: Renderer2 = inject(Renderer2);

    // ngOnChanges(changes: SimpleChanges): void {
    //     if (changes.isActive) {
    //         if(!this.isActive) {
    //             // Reset the width when the overlay is deactivated
    //             this.renderer.removeStyle(this.elementRef.nativeElement, 'width');
    //             this.renderer.removeStyle(this.elementRef.nativeElement, 'min-width');
    //             this.renderer.removeStyle(this.elementRef.nativeElement, 'max-width');
    //         }
    //     }
    // }

    @HostListener('keydown', ['$event'])
    onKeydown(event: KeyboardEvent): void {
        if (event.key === 'Escape') {
            this.activeState.emit(false);
        }
    }

    @HostListener('document:click', ['$event'])
    onClick(event: MouseEvent): void {
        if (this.hasClosedOnClickOutside) {
            let targetElement = event.target as HTMLElement;
            let isInsideOverlay = false;

            while (targetElement) {
                if (targetElement.classList.contains('eui-overlay')) {
                    isInsideOverlay = true;
                    break;
                }
                targetElement = targetElement.parentElement;
            }

            if (!isInsideOverlay && this.isActive) {
                this.activeState.emit(false);
            }
        }
    }
}
