import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    ElementRef,
    AfterViewInit,
    Input,
    OnInit,
    Output,
    EventEmitter,
    OnDestroy,
    ChangeDetectorRef,
    ViewChild,
    booleanAttribute,
    inject,
} from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { BaseStatesDirective } from '@eui/components/shared';
import { Subject, startWith, Subscription, takeUntil, distinctUntilChanged } from 'rxjs';
import { ContentObserver } from '@angular/cdk/observers';
import { CssUtils } from '@eui/core';
import { DOCUMENT } from '@angular/common';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';

@Component({
    selector: 'eui-app-top-message',
    templateUrl: './top-message.component.html',
    changeDetection: ChangeDetectionStrategy.Default,
    styleUrl: './top-message.scss',
    encapsulation: ViewEncapsulation.None,
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiInfo',
                'euiWarning',
                'euiSuccess',
                'euiDanger',
                'euiAccent',
                'euiVariant',
            ],
        },
    ],
    imports: [
        ...EUI_ICON_BUTTON,
    ],
})
export class EuiAppTopMessageComponent implements AfterViewInit, OnInit, OnDestroy {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-app-top-message'),
            !this.isVisible ? 'eui-app-top-message--hidden' : '',
            this.hasCustomContent ? 'eui-app-top-message--custom' : '',
    ].join(' ').trim();
    }
    @HostBinding('attr.role') role = 'banner';

    @ViewChild('appTopMessage') appTopMessage: ElementRef;
    appTopMessageChanges: Subscription;

    @Input({ transform: booleanAttribute }) isCloseable = false;
    @Input({ transform: booleanAttribute }) hasCustomContent = false;

    @Input()
    set isVisible(value: boolean) {
        this._isVisible = value;
        this._calculateHeight();
    }

    get isVisible(): boolean {
        return this._isVisible;
    }
    @Output() topMessageClose = new EventEmitter<null>();

    asService = inject(EuiAppShellService);
    private _isVisible = true;
    private destroy$: Subject<boolean> = new Subject<boolean>();
    private elRef = inject(ElementRef);
    private cd = inject(ChangeDetectorRef);
    private obs = inject(ContentObserver);
    protected baseStatesDirective = inject(BaseStatesDirective);
    private document = inject<Document>(DOCUMENT);

    ngOnInit(): void {
        // Trigger for recalculate when resizing viewport (works perfect)
        this.asService.breakpoint$.pipe(takeUntil(this.destroy$)).subscribe(() => {
            this._calculateHeight();
        });
    }

    ngAfterViewInit(): void {
        // TODO: This will not work when there are more than one top-message
        this.appTopMessageChanges = this.obs
            .observe(this.appTopMessage.nativeElement)
            .pipe(startWith(0))
            .subscribe(() => this._calculateHeight());
    }

    ngOnDestroy(): void {
        this.asService.setState({
            ...this.asService.state,
            hasTopMessage: false,
        });
        CssUtils.activateTopMessageCssVars(0, this.document);
        this.appTopMessageChanges.unsubscribe();

        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    onCloseClick(): void {
        this.isVisible = false;
        CssUtils.activateTopMessageCssVars(0, this.document);
        this.topMessageClose.emit();
    }

    private _calculateHeight(): void {
        // Differ DC from AfterViewInit due to the styles the are not yet applied when retrieving the CSS var value
        setTimeout( () => {
            this.cd.detach();
            const height = this.elRef.nativeElement.offsetHeight;
            this.asService.activateTopMessage(height);
            this.cd.reattach();
            this.cd.detectChanges();
        }, 0);
    }
}
