import {
    Component,
    HostBinding,
    Input,
    ChangeDetectionStrategy,
    ViewChild,
    QueryList,
    forwardRef,
    ContentChildren,
    OnInit,
    ChangeDetectorRef,
    AfterContentInit,
    AfterViewInit,
    EventEmitter,
    Output,
    OnDestroy,
    Directive,
    OnChanges,
    SimpleChanges,
    ElementRef,
    ViewChildren,
    booleanAttribute,
    numberAttribute,
    inject,
} from '@angular/core';

import { EUI_CHIP } from '@eui/components/eui-chip';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EuiTruncatePipe } from '@eui/components/pipes';
import { EuiTooltipDirective } from '@eui/components/directives';
import { BaseStatesDirective } from '@eui/components/shared';
import { NgTemplateOutlet } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { DomSanitizer } from '@angular/platform-browser';
import { Subject, startWith, takeUntil } from 'rxjs';
import {
    CdkDragDrop,
    moveItemInArray,
    CdkDropList,
    transferArrayItem,
    CdkDragStart,
    CdkDragEnter,
    CdkDragRelease,
    DragDropModule,
} from '@angular/cdk/drag-drop';

import { EuiChipComponent, EuiChip, EuiChipTooltip } from '@eui/components/eui-chip';

import { EuiChipDragDrop } from './models/eui-chip-drag-drop.model';
import { EuiChipListDragService } from './services/eui-chip-list-drag.service';

/**
 * @description
 * Multiple eui-chips displayed dynamically as a group of multiple interactive elements.
 */
@Component({
    templateUrl: './eui-chip-list.component.html',
    selector: 'eui-chip-list, div[euiChipList], ul[euiChipList]',
    styleUrl: './eui-chip-list.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        NgTemplateOutlet,
        DragDropModule,
        TranslateModule,
        EuiTruncatePipe,
        EuiTooltipDirective,
        ...EUI_CHIP,
        ...EUI_BUTTON,
        ...EUI_ICON,
    ],
    providers: [EuiChipListDragService],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiVariant',
                'euiSizeS',
                'euiSizeVariant',
                'euiOutline',
                'euiDisabled',
            ],
        },
    ],
})
export class EuiChipListComponent implements AfterViewInit, AfterContentInit, OnDestroy, OnChanges, OnInit {
    /**
     * Array of chips to display in the list when used with the data approach.
     */
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    @Input() chips: any[];
    /**
     * In combination with `maxVisibleChipsCount`, sets the label of the 'more chips' button, if not provided an arrow right icon will be displayed only.
     *
     * @type {string}
     */
    @Input() toggleLinkMoreLabel: string = null;
    /**
     * In combination with `maxVisibleChipsCount`, sets the label of the 'less chips' button, if not provided an arrow left icon will be displayed only.
     *
     * @type {string}
     */
    @Input() toggleLinkLessLabel: string = null;
    /**
     * In combination with `isChipsSorted`. Sets the sort criteria of the chips.
     *
     * @type {('ASC' | 'DESC')}
     * @default 'ASC'
     */
    @Input() chipsSortOrder: 'ASC' | 'DESC' = 'ASC';
    /**
     * In combination with `isChipsDragAndDrop`, sets the name to the chips source.
     *
     * @type {string}
     */
    @Input() dragAndDropSourceName: string;
    /**
     * In combination with `isChipsDragAndDrop`, sets the name to the chips source with which a drag and drop will be done.
     *
     * @type {string}
     */
    @Input() dragAndDropConnectedTo: string[] = [];
    /**
     * Sets the `aria-label` attribute for the host element.
     *
     * @default 'eUI Chip List'
     */
    @Input() ariaLabel = 'eUI Chip List';
    /**
     * In combination with `isChipsDragAndDrop`, sets the orientation of the list.
     *
     * @type {string} 'horizontal' | 'vertical'
     * @default 'horizontal'
     */
    @Input() dropListOrientation: 'horizontal' | 'vertical' = 'horizontal';

    /**
     * @deprecated This option is not applicable anymore to comply Design System.
     */
    @Input({ transform: booleanAttribute }) isSquared = false;
    /**
     * Whether the chip can be removed from the list.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipsRemovable = false;
    /**
     * In combination with `maxVisibleChipsCount`. Whether all chips are shown by default.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isMaxVisibleChipsOpened = false;
    /**
     * Whether this chips are sorted on their label.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipsSorted = false;
    /**
     * Whether the chips can be drag and dropped.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isChipsDragAndDrop = false;
    /**
     * In combination with `isChipsDragAndDrop`. Whether the chips are drag and droppable in a flex container.
     *
     * @default false
     */
    @Input({ transform: booleanAttribute }) isGrid = false;
    /**
     * Whether a limited amount, defined by this option, is used to display the chips.
     */
    @Input({ transform: numberAttribute }) maxVisibleChipsCount = null;
    /**
     * Whether the chips label length are limited by the value of this option.
     */
    @Input({ transform: numberAttribute }) chipsLabelTruncateCount = null;

    /**
     * Event emitted with `CdkDropList` object when the chiplist is initiated.
     */
    @Output() chipsInit = new EventEmitter<CdkDropList>();
    /**
     * Event emitted when a chip is removed from the list.
     */
    @Output() chipRemove = new EventEmitter<{ chips: EuiChip[]; removed: EuiChip | { chip: EuiChip; event: Event } }>();
    /**
     * Event emitted when a chip drag starts.
     */
    @Output() chipDragStart = new EventEmitter<EuiChipDragDrop>();
    /**
     * Event emitted when a chip drag is released.
     */
    @Output() chipDragRelease = new EventEmitter<EuiChipDragDrop>();
    /**
     * Event emitted when a chip drag is released.
     */
    @Output() chipDrop = new EventEmitter<EuiChipDragDrop>();
    /**
     * Event emitted when the list gets the focus.
     */
    @Output() chiplistFocus = new EventEmitter<boolean>();

    /**
     * @description
     * Computes and returns the CSS classes for the label title component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return this.baseStatesDirective.getCssClasses('eui-chip-list');
    }

    public droppableArea: (CdkDropList | string)[];
    public connectComponent: CdkDropList[] = [];
    public e2eAttr = 'eui-chip-list';

    @ContentChildren(forwardRef(() => EuiChipComponent)) euiChipsContent: QueryList<EuiChipComponent>;
    @ViewChild('chipListDropList', { read: CdkDropList }) chipListDropList: CdkDropList;
    @ViewChild('chipListDragAndDropItems', { read: CdkDropList }) chipListDragAndDropItems: CdkDropList;
    @ViewChildren('euiChipItem', { read: ElementRef }) euiChipItems: QueryList<ElementRef>;

    private destroy$: Subject<boolean> = new Subject<boolean>();
    private cd = inject(ChangeDetectorRef);
    private euiChipListDragService = inject(EuiChipListDragService);
    private domSanitizer = inject(DomSanitizer);
    protected baseStatesDirective = inject(BaseStatesDirective);

    ngOnChanges(c: SimpleChanges): void {
        if (c.chips && this.isChipsSorted) {
            this.chips = this.orderItems(this.chips, this.chipsSortOrder);
        }
    }

    ngOnInit(): void {
        this.chips = this.chips?.map((chip) => ({
            ...chip,
            tooltip: new EuiChipTooltip(chip.tooltip),
        }));
    }

    ngAfterContentInit(): void {
        this.chips = this.chips?.map((chip) => ({
            ...chip,
            tooltip: new EuiChipTooltip(chip.tooltip),
        }));
    }

    ngAfterViewInit(): void {
        this.chipsInit.emit(this.chipListDragAndDropItems);
        if (this.isChipsSorted && this.chips) {
            this.chips = this.orderItems(this.chips, this.chipsSortOrder);
        }

        if (this.dragAndDropSourceName) {
            this.euiChipListDragService.setComponentConnector(this.dragAndDropSourceName);
        }

        if (this.dragAndDropConnectedTo) {
            this.euiChipListDragService.setDroppableArea(this.chipListDropList, this.dragAndDropConnectedTo);
            this.dragAndDropConnectedTo.forEach((connectTo) => {
                this.connectComponent = this.euiChipListDragService.componentConnector[connectTo];
            });
        }

        setTimeout(() => {
            this.droppableArea = this.euiChipListDragService.droppableArea[this.dragAndDropSourceName];
            this.cd.detectChanges();
        });

        Object.keys(this.euiChipListDragService.componentConnector).map((connectTo) => {
            this.euiChipListDragService.componentConnector[connectTo].push(this.chipListDragAndDropItems);
        });

        this.euiChipsContent.changes.pipe(startWith(true), takeUntil(this.destroy$)).subscribe(() => {
            if (this.euiChipsContent.toArray().length > 0) {
                this.chips = this.euiChipsContent.toArray().map((chip) => Object.assign(chip, { euiInternalId: this.generateId() }));

                if (this.isChipsSorted) {
                    this.chips = this.orderItems(this.chips, this.chipsSortOrder);
                }
                this.cd.detectChanges();
            }
        });
    }

    ngOnDestroy(): void {
        this.euiChipListDragService.resetConnector();
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    /**
     * Method toggling the display of the chips in combination with `maxVisibleChipsCount`.
     */
    public toggleTags(): void {
        this.isMaxVisibleChipsOpened = !this.isMaxVisibleChipsOpened;
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public getChipContent(euiChip: any): string {
        return euiChip.chipLabel ? (this.domSanitizer.bypassSecurityTrustHtml(euiChip.chipLabel.nativeElement.innerHTML) as string) : euiChip.label;
    }

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public getChipLabel(euiChip: any): string {
        return euiChip.chipLabel ? euiChip.chipLabel.nativeElement.textContent : euiChip.label;
    }

    /**
     * Method that returns a boolean indicating if an icon has been declared before the label.
     *
     * @param euiChip Chip to check.
     * @returns `true` if an icon has been declared otherwise `false`.
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public getChipIconBefore(euiChip: any): boolean {
        return euiChip.iconBefore;
    }

    /**
     * Method that returns a boolean indicating of an icon has been declared after the label.
     *
     * @param euiChip Chip to check.
     * @returns `true` if an icon has been declared otherwise `false`.
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public getChipIconAfter(euiChip: any): boolean {
        return euiChip.iconAfter;
    }

    /**
     * Remove chip from the list handler
     *
     * @param removed Chip that is removed
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public onRemove(removed: EuiChipComponent | EuiChip | { chip: EuiChipComponent | EuiChip; event?: Event } | any): void {
        const chips = this.euiChipsContent.toArray().length > 0 ? this.chips.map((c) => c.data) : this.chips;
        const removedChip = removed as { chip: EuiChip; event: Event };
        let index = removedChip instanceof EuiChip ? chips.indexOf(removedChip) : chips.indexOf(removedChip.chip);

        if (index === -1 && removed.id) {
            index = chips.map((chip) => chip.id).indexOf(removed.id);
        }

        this.chips.splice(index, 1);

        this.chipRemove.emit({
            chips: this.euiChipsContent.toArray().length > 0 ? this.chips.map((c) => c.data) : this.chips,
            removed: removedChip,
        });
    }

    /**
     * Drag and Drop chip handler used when a chip is moved to another container.
     *
     * @param event `CdkDragEnter` object used to move the chip in a list.
     */
    public onDragEnter(event: CdkDragEnter): void {
        const dropList = event.container;
        const phContainer = dropList.element.nativeElement;
        const phElement = phContainer.querySelector('.cdk-drag-placeholder');
        phContainer.parentElement.insertBefore(phElement, phContainer);
        moveItemInArray(this.chips, event.item.data.index, event.container.data.index);
    }

    /**
     * Method called when a chip is dropped.
     *
     * @param event `CdkDragDrop` object used to move the chip in a list.
     */
    public onDropGrid(e: CdkDragDrop<{ chip: EuiChip; index: number }>): void {
        this.chipDrop.emit(
            {
                type: 'dropped',
                sourceName: this.dragAndDropSourceName,
                chip: e.item.data.chip,
                chips: this.chips,
            },
        );
    }

    /**
     * Drag and Drop chip handler used when a chip is moved inside a container.
     *
     * @param e `CdkDragDrop` object used to move the chip in a list.
     */
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public drop(e: CdkDragDrop<{ chips: any[] }>): void {
        if (e.previousContainer === e.container) {
            moveItemInArray(e.container.data['chips'], e.previousIndex, e.currentIndex);
        } else {
            transferArrayItem(
                e.previousContainer.data['chips'],
                e.container.data['chips'],
                e.previousContainer.data['chips'].indexOf(e.item.data),
                e.currentIndex,
            );
            // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            this.chips = e.container.data['chips'].map((item: any) => item);
        }

        this.chipDrop.emit(
            {
                type: 'dropped',
                sourceName: this.dragAndDropSourceName,
                chip: e.item.data,
                chips: e.container.data['chips'],
            },
        );
    }

    /**
     * Method called when a chip starts to be dragged.
     *
     * @param event `CdkDragStart` object used to move the chip in a list.
     */
    public onDragStarted(event: CdkDragStart): void {
        this.chipDragStart.emit(
            {
                type: 'started',
                sourceName: this.dragAndDropSourceName,
                chip: event['source'].data instanceof EuiChipComponent ? event['source'].data : event['source'].data.chip,
                chips: this.chips,
            },
        );
    }

    /**
     * Method called when a chip is released after dragging.
     *
     * @param event `CdkDragRelease` object used to move the chip in a list.
     */
    public onDragReleased(event: CdkDragRelease): void {
        this.chipDragRelease.emit(
            {
                type: 'released',
                sourceName: this.dragAndDropSourceName,
                chip: event['source'].data instanceof EuiChipComponent ? event['source'].data : event['source'].data.chip,
                chips: this.chips,
            },
        );
    }

    /**
     * Method called when the list gets the focus.
     */
    onFocus(): void {
        this.chiplistFocus.emit(true);
    }

    /**
     * Generates a random id to be used in the chips.
     *
     * @returns an id as a string
     */
    private generateId(): string {
        return '_' + Math.random().toString(36).substr(2, 9);
    }

    /**
     * Method that orders the chips in the list.
     *
     * @param tab Array of chips to order.
     * @param sortOrder Sorting to apply `ASC` or `DESC`.
     * @returns The array ordered.
     */
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private orderItems(tab: any, sortOrder: string): any[] {
        // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        tab.sort((a: any, b: any) => {
            const aObj = a.chipLabel ? a.chipLabel.nativeElement.textContent.toLowerCase() : a.label.toLowerCase();
            const bObj = b.chipLabel ? b.chipLabel.nativeElement.textContent.toLowerCase() : b.label.toLowerCase();

            if (sortOrder === 'ASC') {
                if (aObj < bObj) {
                    return -1;
                }
                if (aObj > bObj) {
                    return 1;
                }
                return 0;
            } else {
                if (aObj > bObj) {
                    return -1;
                }
                if (aObj < bObj) {
                    return 1;
                }
                return 0;
            }
        });

        return tab;
    }
}

/**
 * @description
 * This directive is only used internally by eui-autocomplete component to be able to display the chips above, below and inside the text input with an option.
 */
/* eslint-disable */
@Directive({ selector: 'euiChipListAppendContent' })
export class EuiChipListAppendContentDirective {}
/* eslint-enable */
