import {
    ChangeDetectionStrategy,
    Component,
    HostBinding,
    HostListener,
    Input,
    booleanAttribute,
    inject,
} from '@angular/core';
import { EuiToolbarNavbarComponent } from '../toolbar-navbar/toolbar-navbar.component';

@Component({
    selector: 'eui-toolbar-navbar-item',
    template: '{{ label }}',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EuiToolbarNavbarItemComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-toolbar-navbar-item',
            this.isActive ? 'eui-toolbar-navbar-item--active' : '',
        ].join(' ').trim();
    }

    @HostBinding('attr.tabindex') tabindex = 0;

    @Input() id: string;
    @Input() label: string;
    @Input({ transform: booleanAttribute }) isActive = false;

    navBarComponentParent: EuiToolbarNavbarComponent;

    constructor() {
        const navBarComponent = inject(EuiToolbarNavbarComponent, { host: true, optional: true })!;

        this.navBarComponentParent = navBarComponent;
    }

    @HostListener('click')
    protected onClick(): void {
        this._click();
    }

    @HostListener('keydown', ['$event'])
    protected onKeydown(event: KeyboardEvent): void {
        switch (event.code) {
            case 'Enter':
            case 'Space':
                event.preventDefault();
                event.stopPropagation();
                this._click();
                break;
        }
    }

    private _click(): void {
        this.navBarComponentParent.itemSelected(this.id);
    }
}
