import { Inject, Injectable, InjectionToken } from '@angular/core';
import {
    HttpErrorResponse,
    HttpEvent,
    HttpHandler,
    HttpInterceptor,
    HttpRequest,
} from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { ErrorMappingHandler, transformToUxHttpResponse, UxHttpErrorResponse } from '@eui/base';

export const UX_ERROR_MAPPING_HANDLER_TOKEN = new InjectionToken<ErrorMappingHandler>('UX_ERROR_MAPPING_HANDLER');

@Injectable()
export class UxRequestErrorModelInterceptor implements HttpInterceptor {
    constructor(@Inject(UX_ERROR_MAPPING_HANDLER_TOKEN) private errorMappingHandler: ErrorMappingHandler) {}

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
        return next.handle(req).pipe(
            // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            catchError((err: any) => {
                if (this.errorMappingHandler) {
                    if (err instanceof HttpErrorResponse) {
                        err = transformToUxHttpResponse(err, this.errorMappingHandler) as UxHttpErrorResponse;
                    }
                }
                return of(err);
            }),
        );
    }
}
