import {
    ChangeDetectionStrategy,
    Component,
    Input,
    HostBinding,
    OnInit,
    ViewEncapsulation,
    OnChanges,
    SimpleChanges,
    AfterContentInit,
    inject,
    booleanAttribute,
    NgModule,
} from '@angular/core';
import { EUI_CONFIG_TOKEN } from '@eui/core';
import { EuiConfig } from '@eui/core';

/**
 * @description
 * The EuiIconSvgComponent is used to display SVG icons in the application.
 * It allows for customization of the icon's size, color, and other properties.
 *
 */
@Component({
    selector: 'eui-icon-svg, span[euiIconSvg], i[euiIconSvg]',
    templateUrl: './eui-icon-svg.component.html',
    styleUrls: ['./styles/_index.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
})
export class EuiIconSvgComponent implements AfterContentInit, OnChanges, OnInit {
    @HostBinding('attr.role') ariaRole = 'img';

    @Input() icon: string; // could be the form of "icon:set" to pass them both in a single input
    @Input() fillColor: string;
    @Input() set = 'eui';
    @Input() size: '2xs' | 'xs' | 's' | 'm' | 'l' | 'xl' | '2xl' | '3xl' | '4xl' | string = 'm';
    @Input() style = '';
    @Input() iconUrl: string;
    @Input() transform = '';
    /**
     * @deprecated euiVariant is not used and will be removed in v20.
     */
    @Input() euiVariant: string; // fake it as used in showcase on samples loops (eui-tabs f.e.) shouldn't be

    @HostBinding('class')
    public get cssClasses(): string {
        return [
            // Always refer to the baseStatesDirective
            'eui-icon-svg',
            `eui-icon-svg--size-${this.size}`,
            this.transform ? `eui-icon-svg--${this.transform}` : '',

            // own cmp state => reflected with the scss states
            this.euiStart ? 'eui-icon-svg--start' : '',
            this.euiEnd ? 'eui-icon-svg--end' : '',
            this.isInputIcon ? 'eui-icon-svg--input-icon': '',
            this.isLoading ? 'eui-icon-svg--loading': '',
        ]
            .join(' ')
            .trim();
    }

    @HostBinding('attr.aria-label')
    // TODOv21: remove the aria-label alias causing aria-prohibited attribute errors
    @Input('aria-label') ariaLabel = 'Icon';

    public iconName: string;
    public assetsBaseUrl = 'assets';
    public iconStyle: string;

    @Input({ transform: booleanAttribute }) ariaHidden = true;
    @Input({ transform: booleanAttribute }) focusable = false;
    @Input({ transform: booleanAttribute }) isLoading = false;
    @Input({ transform: booleanAttribute }) isInputIcon = false;
    @Input({ transform: booleanAttribute }) euiStart = false;
    @Input({ transform: booleanAttribute }) euiEnd = false;
    private config = inject<EuiConfig>(EUI_CONFIG_TOKEN, { optional: true })!;

    ngOnInit(): void {
        const assetsBaseUrl = this.config?.appConfig?.global?.eui?.assetsBaseUrl;
        if (assetsBaseUrl) {
            this.assetsBaseUrl = this.config.appConfig.global.eui.assetsBaseUrl;
        }
        if (!this.size || this.size === '') {
            this.size = 'm';
        }
    }

    ngOnChanges(c: SimpleChanges): void {
        if (c && c.set) {
            if (c.set.currentValue !== c.set.previousValue) {
                this._setIconAndSet();
            }
        }

        if (c && c.icon) {
            if (c.icon.currentValue !== c.icon.previousValue) {
                this._setIconAndSet();
            }
        }

        if (c && c.size) {
            if (c.size.currentValue !== c.size.previousValue) {
                this._setStyle();
            }
        }
        if (c && c.fillColor) {
            if (c.fillColor.currentValue !== c.fillColor.previousValue) {
                this._setStyle();
            }
        }
    }

    ngAfterContentInit(): void {
        this._setIconAndSet();
        this._setStyle();
    }

    private _setIconAndSet(): void {
        if (this.icon && this.icon.indexOf(':') > -1) {
            const iconSet = this.icon.split(':');
            this.icon = iconSet[0];
            this.set = iconSet[1];
        }

        if (!this.set || this.set === '') {
            this.set = 'eui';
        } else {
            if (this.set === 'sharp' || this.set === 'outline' || this.set === 'filled') {
                this.iconName = `${this.icon}-${this.set}`;
            } else {
                this.iconName = this.icon;
            }
        }
    }

    private _setStyle(): void {
        let fill = '';
        if (this.fillColor) {
            fill = `fill: var(--eui-c-${this.fillColor}); color: var(--eui-c-${this.fillColor});`;
        }
        // const height = `height: var(--eui-is-${this.size});`;
        // const width = `width: var(--eui-is-${this.size});`;
        // this.iconStyle = `${fill} ${height} ${width}`;
        this.iconStyle = `${fill}`;
    }
}

/**
 * @description
 * A module for the icon component. This module imports the
 *
 * @deprecated Use the {@link EUI_ICON} instead
 */
@NgModule({
    imports: [EuiIconSvgComponent],
    exports: [EuiIconSvgComponent],
})
export class EuiIconModule {}
