import { Directive, ElementRef, HostBinding, HostListener, inject } from '@angular/core';

@Directive({
    selector: '[euiArrowKeyNavigable]',
})

/**
 * @description
 * A directive that can be used when there is rich content on an item to make this content focusable with arrow keys.
 *
 */
export class EuiArrowKeyNavigableDirective {
    elementRef = inject(ElementRef);

    @HostBinding('attr.tabindex') tabindex = '-1';
    isFocused = false;

    @HostListener('focus')
    onFocus(): void {
        this.isFocused = true;
    }

    @HostListener('blur')
    onBlur(): void {
        this.isFocused = false;
    }
}
