import { createSelector, Selector } from 'reselect';
import { AppState, LoadedConfigModules } from '../state';
import { getAppState } from './core.selectors';
import { ApiQueue, ApiQueueItem } from '../models';

export const getAppVersion: Selector<AppState, string> = createSelector(getAppState, (state: AppState) => state.version);
export const getAppConnection: Selector<AppState, boolean> = createSelector(getAppState, (state: AppState) => state.connected);
/**
 * Returns the loaded config modules from the app state
 * @deprecated It will be removed in the future.
 */
export const getAppLoadedConfigModules: Selector<AppState, LoadedConfigModules> = createSelector(
    getAppState,
    (state: AppState) => state.loadedConfigModules,
);
/**
 * Returns the last added module from the app state
 * @deprecated It will be removed in the future.
 */
export const getLastAddedModule: Selector<AppState, string> = createSelector(
    getAppState,
    (state: AppState) => state.loadedConfigModules.lastAddedModule,
);

export const getAppStatus: Selector<AppState, string> = createSelector(getAppState, (state: AppState) => state.status);
export const getCurrentModule: Selector<AppState, string> = createSelector(getAppState, (state: AppState) => state.currentModule);
export const getApiQueue: Selector<AppState, ApiQueue> = createSelector(getAppState, (state: AppState) => state.apiQueue);
export const getApiQueueItem = (itemId: string): Selector<AppState, ApiQueueItem> =>
    createSelector(getAppState, (state: AppState) => state.apiQueue[itemId]);
