import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    OnChanges,
    OnInit,
    SimpleChanges,
    Output,
    EventEmitter,
    OnDestroy,
    booleanAttribute,
    inject,
} from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { EUI_MENU, EuiMenuItem } from '@eui/components/eui-menu';
import { Subscription } from 'rxjs';
import { AsyncPipe } from '@angular/common';

@Component({
    selector: 'eui-app-sidebar-menu',
    templateUrl: './sidebar-menu.component.html',
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        ...EUI_MENU,
    ],
})
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export class EuiAppSidebarMenuComponent<Items = any> implements OnInit, OnChanges, OnDestroy {
    asService = inject(EuiAppShellService);

    @HostBinding() class = 'eui-app-sidebar-menu';

    @Input({ transform: booleanAttribute }) hasFilter = false;
    @Input({ transform: booleanAttribute }) hasIcons = false;
    @Input({ transform: booleanAttribute }) hasIconsLabels = false;
    @Input({ transform: booleanAttribute }) hasTooltip = true;
    @Input({ transform: booleanAttribute }) hasTooltipOnExpanded = false;
    @Input({ transform: booleanAttribute }) expandAllItems = false;
    @Input({ transform: booleanAttribute }) isCollapsed = false;
    @Input({ transform: booleanAttribute }) hasCollapsedInitials = false;
    @Input({ transform: booleanAttribute }) isFlat = false;
    @Input({ transform: booleanAttribute }) hasScrollToItem = false;
    @Input({ transform: booleanAttribute }) hasBoldRootLevel = false;

    @Input() items: Items[];

    @Output() sidebarItemClick = new EventEmitter<EuiMenuItem>();
    @Output() sidebarItemToggle = new EventEmitter<EuiMenuItem>();

    private subs: Subscription;

    constructor() {
        this.subs = new Subscription();
    }

    ngOnInit(): void {
        if (this.items) {
            this.asService.setState({
                ...this.asService.state,
                sidebarLinks: this.items,
            });
        }
        
        if (this.hasIconsLabels) {
            this.asService.hasSidebarCollapsedVariant = this.hasIconsLabels;
        }

        this.subs.add(this.asService.state$.subscribe((state) => {
            if (state?.breakpoints?.isMobile) {
                this.items = <Items[]>state.combinedLinks;
            } else {
                this.items = <Items[]>state.sidebarLinks;
            }
        }));

        // subscribe to state changes
        // this.subs.add(this.asService.getState<Items[]>('combinedLinks').subscribe((links) => (this.items = links)));
    }

    ngOnDestroy(): void {
        this.subs.unsubscribe();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.items) {
            this.asService.setState({
                ...this.asService.state,
                sidebarLinks: this.items,
            });
        }
    }

    public onMenuItemClicked(event: EuiMenuItem): void {
        // Auto-close sidebar menu after click when in mobile / tablet modes
        if (
            event.url &&
            (this.asService.state.breakpoints.isMobile || this.asService.state.breakpoints.isTablet || this.asService.state.isSidebarHidden)
        ) {
            this.asService.isSidebarOpen = false;
        }

        this.sidebarItemClick.emit(event);
    }

    public onSidebarItemToggled(event: EuiMenuItem): void {
        this.sidebarItemToggle.emit(event);
    }
}
