import { Injector } from '@angular/core';
import { LogAppenderConfig } from '../eui-config';
import { LogEvent } from './log.model';

/**
 * Abstract Log Appender
 */
export abstract class LogAppender<CFG extends LogAppenderConfig = LogAppenderConfig> {
    constructor(protected config: CFG, protected injector: Injector = null) {}

    /**
     * Gets the config
     *
     * @returns the config
     */
    getConfig(): CFG {
        return this.config;
    }

    /**
     * Logs a Log Event
     *
     * @param event log event
     */
    abstract append(event: LogEvent): void;
}
