import { Component, ChangeDetectionStrategy, HostBinding, ViewEncapsulation, Input, OnInit, inject } from '@angular/core';
import { EuiConfig } from '@eui/core';
import { EUI_CONFIG_TOKEN } from '@eui/core';

@Component({
    selector: 'eui-header-app-name-logo',
    template: '<img class="title-logo-svg" [src]="svgUrl" alt="Application title logo" />',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiHeaderAppNameLogoComponent implements OnInit {
    @HostBinding('class') cssClass = 'eui-header-app-name-logo';

    @Input() homeUrl = '..';
    @Input() logoFilename: string;

    private assetsBaseUrl: string;
    private config = inject<EuiConfig>(EUI_CONFIG_TOKEN, { optional: true })!;

    ngOnInit(): void {
        this.assetsBaseUrl = this.config?.appConfig?.global?.eui?.assetsBaseUrl || 'assets';
    }

    get svgUrl(): string {
        return `${this.assetsBaseUrl}/${this.logoFilename}`;
    }
}
