export const isObject = <T>(item: T): boolean => item && typeof item === 'object' && !Array.isArray(item);

/* eslint-disable */
export function merge<T>(target: T): T;
export function merge<T, A>(target: T, a: A): T & A;
export function merge<T, A, B>(target: T, a: A, b: B): T & A & B;
export function merge<T, A, B, C>(target: T, a: A, b: B, c: C): T & A & B & C;
export function merge<T, A, B, C, D>(target: T, a: A, b: B, c: C, d: D): T & A & B & C & D;
export function merge<T, A, B, C, D, E>(target: T, a: A, b: B, c: C, d: D, e: E): T & A & B & C & D & E;
export function merge<T, A, B, C, D, E, F>(target: T, a: A, b: B, c: C, d: D, e: E, f: F): T & A & B & C & D & E & F;
export function merge(target: any, ...sources: any[]): any {
    return mergeDeep(target, ...sources);
}
/* eslint-enable */

/**
 * deep merge of two or more objects
 *
 * @param target immutable target
 * @param sources immutable sources to apply to target
 * @returns a new merged object
 */
// TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const mergeDeep = <T extends object, S>(target: T, ...sources: S[]): any => {
    const output: object & T = Object.assign({}, target);
    if (!sources.length) {
        return output as T | T & S;
    }
    const source = sources.shift();

    if (isObject(target) && isObject(source)) {
        Object.keys(source).forEach((key: string) => {
            if (isObject(source[key])) {
                if (!(key in target)) {
                    /* istanbul ignore next */
                    Object.assign(output, { [key]: source[key] });
                } else {
                    output[key] = mergeDeep(target[key], source[key]);
                }
            } else {
                Object.assign(output, { [key]: source[key] });
            }
        });
    }
    return mergeDeep(output, ...sources);
};
/* istanbul ignore next */
export const mergeAll = <T>(array: Array<T>): T => array.reduce((prev, next) => mergeDeep(prev, next), {});
