import {
    Component,
    HostBinding,
    ViewEncapsulation,
    AfterViewInit,
    QueryList,
    ContentChildren,
    OnDestroy,
    HostListener,
    forwardRef,
    inject,
} from '@angular/core';
import { FocusKeyManager } from '@angular/cdk/a11y';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

import { EuiUserProfileMenuItemComponent } from '../user-profile-menu-item/user-profile-menu-item.component';
import { EuiUserProfileComponent } from '../user-profile.component';

@Component({
    selector: 'eui-user-profile-menu',
    template: '<ng-content/>',
    encapsulation: ViewEncapsulation.None,
})
export class EuiUserProfileMenuComponent implements OnDestroy, AfterViewInit {
    @HostBinding() class = 'eui-user-profile-menu';
    @HostBinding('attr.role') role = 'menu';

    @ContentChildren(forwardRef(() => EuiUserProfileMenuItemComponent)) items: QueryList<EuiUserProfileMenuItemComponent>;

    public parent: EuiUserProfileComponent = inject(forwardRef(() => EuiUserProfileComponent), { optional: true });
    private focusKeyManager: FocusKeyManager<EuiUserProfileMenuItemComponent>;
    private destroy$: Subject<boolean> = new Subject<boolean>();

    @HostListener('keydown', ['$event'])
    onKeydown(event): void {
        if (this.focusKeyManager) {
            this.focusKeyManager.onKeydown(event);
        }
    }

    ngAfterViewInit(): void {
        this.subscribeToParent();
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    subscribeToParent(): void {
        this.parent?.$isDropdownOpen.pipe(takeUntil(this.destroy$)).subscribe((isOpen: boolean) => {
            if (isOpen) {
                this.focusKeyManager = new FocusKeyManager(this.items).withWrap();
                this.focusKeyManager.setFirstItemActive();
            }
        });
    }
}
