import { Directive, Input, TemplateRef, NgModule, inject } from '@angular/core';

@Directive({
    selector: '[euiTemplate]',
})
export class EuiTemplateDirective<T = never> {
    template = inject<TemplateRef<T>>(TemplateRef);

    @Input() type: string;
    @Input('euiTemplate') name: string;

    getType(): string {
        return this.name;
    }
}

/**
 * @deprecated Use {@link EuiTemplateDirective} instead.
 */
@NgModule({
    imports: [EuiTemplateDirective],
    exports: [EuiTemplateDirective],
})
export class EuiTemplateDirectiveModule {}
