import { Component, ContentChild, HostBinding, QueryList, ViewEncapsulation, forwardRef } from '@angular/core';

import { EuiOverlayHeaderTitleComponent } from '../eui-overlay-header/eui-overlay-header-title/eui-overlay-header-title.component';

@Component({
    selector: 'eui-overlay-header',
    templateUrl: './eui-overlay-header.component.html',
    encapsulation: ViewEncapsulation.None,
})
export class EuiOverlayHeaderComponent {

    @ContentChild(forwardRef(() => EuiOverlayHeaderTitleComponent), { static: false }) hasHeaderTitle: QueryList<EuiOverlayHeaderTitleComponent>;

    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-overlay-header',
            this.hasHeaderTitle ? 'eui-overlay-header--with-title' : '',
        ].join(' ').trim();
    }
}
