import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    Output,
    EventEmitter,
    HostListener,
    OnInit,
    OnChanges,
    SimpleChanges,
    booleanAttribute,
    ElementRef,
    inject,
} from '@angular/core';
import { FocusableOption } from '@angular/cdk/a11y';

import { consumeEvent } from '@eui/core';
import { EuiMenuItem } from './models/eui-menu-item.model';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { NgTemplateOutlet } from '@angular/common';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_BADGE } from '@eui/components/eui-badge';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EuiTooltipDirective } from '@eui/components/directives';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
    selector: 'eui-menu-item',
    templateUrl: './eui-menu-item.component.html',
    styleUrls: ['./styles/_index.scss'],
    encapsulation: ViewEncapsulation.None,
    imports: [
        RouterLink,
        RouterLinkActive,
        NgTemplateOutlet,
        TranslateModule,
        ...EUI_ICON,
        ...EUI_BADGE,
        ...EUI_ICON_BUTTON,
        ...EUI_BUTTON,
        EuiTooltipDirective,
    ],
})
export class EuiMenuItemComponent implements OnInit, OnChanges, FocusableOption {
    @HostBinding('attr.role') role = 'menuitem';
    @HostBinding('attr.aria-label') ariaLabel = '';

    @HostBinding('class')
    public get cssClasses(): string {
        return this.getCssClasses();
    }
    @HostBinding('attr.tabindex') tabindex = '-1';
    @HostBinding('attr.aria-haspopup')
    get ariaHasPopup(): boolean {
        return this.item?.children?.length > 0 ? true : undefined;
    }
    @HostBinding('attr.aria-expanded')
    get ariaExpanded(): boolean {
        return this.item.children ? coerceBooleanProperty(this.item.expanded) : undefined;
    }
    @HostBinding('attr.aria-disabled')
    get ariaDisabled(): boolean {
        return this.item.disabled
    }

    @Input() item: EuiMenuItem;
    @Input() parent: EuiMenuItem;
    @Input() hasExpandIcon = true;
    @Output() expandToggle = new EventEmitter<EuiMenuItem>();
    @Output() itemClick = new EventEmitter<EuiMenuItem>();

    expandMenuLabel = 'Expand';
    collapseMenuLabel = 'Collapse';

    isUrlItem = false;
    isLinkItem = false;
    isLabelItem = false;
    isActionIconFocused = false;

    @Input({ transform: booleanAttribute }) hasIcon: boolean;
    @Input({ transform: booleanAttribute }) hasIconLabel: boolean;
    @Input({ transform: booleanAttribute }) hasTooltip: boolean;
    @Input({ transform: booleanAttribute }) hasTooltipOnExpanded: boolean;
    @Input({ transform: booleanAttribute }) isCollapsed: boolean;
    @Input({ transform: booleanAttribute }) hasCollapsedInitials: boolean;
    @Input({ transform: booleanAttribute }) hasBoldRootLevel: boolean;
    private elementRef = inject(ElementRef);

    ngOnInit(): void {
        this.isUrlItem = (this.item.url || this.item.urlExternal || this.item.children || this.item.command) && !this.item.link;
        this.isLabelItem = !this.item.url && !this.item.urlExternal && !this.item.command && !this.item.children && !this.item.link;

        this.isLinkItem = !this.isUrlItem && !this.isLabelItem;
        this.ariaLabel = this.getAriaLabel();
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.item && changes.item.isFirstChange()) {
            this.item = changes.item.currentValue;
            if(!this.item.urlExternalTarget) {
                this.item.urlExternalTarget = '_blank';
            }

            this.item.filtered = typeof this.item.filtered == 'boolean' ? this.item.filtered : true;
            this.item.visible = typeof this.item.visible == 'boolean' ? this.item.visible : true;
        }
    }

    @HostListener('click', ['$event'])
    public stopPropagation(event: MouseEvent): void {
        this.itemClick.emit(this.item);
        consumeEvent(event);
    }

    get menuItemTooltip(): string {
        if ((this.hasTooltip && this.isCollapsed) || (this.hasTooltipOnExpanded && !this.isCollapsed)) {
            return this.item.tooltip || this.getTooltipFromItem(this.item);
        }
        return null;
    }

    public onClick(event: MouseEvent | KeyboardEvent): void {
        this.itemClick.emit(this.item);
        this.focus();
        consumeEvent(event);
    }

    public onExpandToggle(event: Event): void {
        this.expandToggle.emit(this.item);
        consumeEvent(event);
    }

    public onActionIconClick(event: MouseEvent): void {
        this.item.actionIcon?.action(event);
        consumeEvent(event);
    }

    public onActionIconKeyDown(event: KeyboardEvent): void {
        if (event.key === 'Enter') {
            this.item.actionIcon?.action(event);
            consumeEvent(event);
        }
    }

    public focusActionIcon(): void {
        this.elementRef.nativeElement.querySelector('.eui-menu-item__link-action-icon').focus();
        this.isActionIconFocused = true;
    }

    onActionIconFocusOut(): void {
        this.isActionIconFocused = false;
    }

    public focus(): void {
        this.elementRef.nativeElement.focus();
    }

    /**
     * Check if an element is visible in the viewport
     * @param partiallyVisible
     */
    elementIsVisibleInViewport(partiallyVisible = false): boolean {
        const { top, left, bottom, right } = this.elementRef.nativeElement.getBoundingClientRect();
        const { innerHeight, innerWidth } = window as Window;
        return partiallyVisible
            ? ((top > 0 && top < innerHeight) ||
                (bottom > 0 && bottom < innerHeight)) &&
            ((left > 0 && left < innerWidth) || (right > 0 && right < innerWidth))
            : top >= 0 && left >= 0 && bottom <= innerHeight && right <= innerWidth;
    }

    /**
     * Scroll the element into view
     * @param properties
     */
    scrollIntoView(properties: unknown): void {
        this.elementRef.nativeElement.scrollIntoView(properties);
    }

    private getTooltipFromItem(item: EuiMenuItem): string {
        return item.label && item.tagLabel ? `${item.label} (${item.tagLabel})` : item.label ||
            item.tagLabel ||
            null;
    }

    private getAriaLabel(): string {
        return this.item.label ||
            this.item.tagLabel ||
            (this.item.actionIcon && this.item.actionIcon.label) ||
            this.item.iconLabel ||
            'Eui menu item';
    }

    /**
     * Returns the default eui-menu-item class on the HostBinding function
     * @private
     */
    private getCssClasses(): string {
        return [
            'eui-menu-item',
            this.isCollapsed && this.hasIconLabel ? 'eui-menu-item--icon-label': '',
            !this.parent && this.hasBoldRootLevel ? 'eui-menu-item--bold' : '',
        ].join(' ').trim();
    }
}
