import { animate, state, style, transition, trigger } from '@angular/animations';

export const openClose = trigger('openClose', [
    state(
        'open',
        style({
            opacity: 1,
            transform: 'scale(1)',
        }),
    ),
    state(
        'closed',
        style({
            opacity: 0,
            transform: 'scale(0.9)',
        }),
    ),
    transition('closed => open', [animate('50ms 25ms linear')]),
]);
