import { inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { ActionReducer, Action } from '../ngrx_kit';
import { CoreAppActionTypes, InitStoreAction } from '../actions/app.actions';
import { AppState, CoreState } from '@eui/base';
import * as extendProxy from 'extend';

const extend = (<{ default: unknown }>extendProxy).default || extendProxy;

/**
 * Utility meta-reducer to load the state from the local storage
 * @param platformId the platformId based on PLATFORM_ID token of Angular
 * @deprecated it will be removed in the next major version
 */
export function localStorageSync<S extends CoreState>(platformId: unknown): ((reducer: ActionReducer<S>) => (state: S, action: Action) => S);
/**
 * Utility meta-reducer to load the state from the local storage
 * @param reducer the action reducer
 */
export function localStorageSync<S extends CoreState>(reducer: ActionReducer<S>): (state: S, action: Action) => S;
// eslint-disable-next-line
export function localStorageSync<S extends CoreState>(reducer: ActionReducer<S>, platformId?: unknown): Function {
    if(platformId) {
        return <T extends CoreState>(reducer: ActionReducer<T>): (state: T, action: Action) => T => {
            return cb<T>(reducer, isPlatformBrowser(platformId) ? localStorage : null);
        }
    } else {
        const platformId = inject(PLATFORM_ID, { optional: true });
        return cb<S>(reducer, isPlatformBrowser(platformId) ? localStorage : null);
    }
}

/**
 * Utility meta-reducer to load the state from the session storage
 * @param platformId the platformId based on PLATFORM_ID token of Angular
 * @deprecated it will be removed in the next major version
 */
export function sessionStorageSync<S extends CoreState>(platformId: unknown): ((reducer: ActionReducer<S>) => (state: S, action: Action) => S);
/**
 * Utility meta-reducer to load the state from the session storage
 * @param reducer the action reducer
 * @deprecated it will be removed in the next major version
 */
export function sessionStorageSync<S extends CoreState>(reducer: ActionReducer<S>): (state: S, action: Action) => S;
// eslint-disable-next-line
export function sessionStorageSync<S extends CoreState>(reducer: ActionReducer<S>, platformId?: unknown): Function {
    if(platformId) {
        return <T extends CoreState>(reducer: ActionReducer<T>): (state: T, action: Action) => T => {
            return cb<T>(reducer, isPlatformBrowser(platformId) ? sessionStorage : null);
        }
    } else {
        const platformId = inject(PLATFORM_ID, { optional: true });
        return cb<S>(reducer, isPlatformBrowser(platformId) ? sessionStorage : null);
    }
}

// Keys that are allowed to be synced with NgRx state from BrowserStorage
const disallowedKeys = ['loadedConfigModules', 'connect', 'currentModule', 'status', 'apiQueue'];

/**
 * filters the AppState by removing those keys from the state and return a new state Object
 * @param app the AppState
 * @deprecated it will be removed in the next major version
 */
const filterAppState = (app: AppState): AppState => {
    // in case app is undefined or null it should return empty object
    if (!app) {
        return {};
    }

    return (
        Object.keys(app)
            // select keys that are present in the allowed list
            .filter((key) => !disallowedKeys.includes(key))
            // build a new object with only the allowed properties
            .reduce((obj, key) => {
                obj[key] = app[key];
                return obj;
            }, {})
    );
};

/**
 *
 * @param storage Type of storage to load the state from
 * @deprecated it will be removed in the next major version
 */
export const loadState = <S extends CoreState>(storage: Storage | null = localStorage): S => {
    if (!storage) {
        return undefined;
    }

    try {
        // by default falls back to localStorage
        const serializedState = storage.getItem('state');

        if (serializedState === null) {
            return undefined;
        }

        // deserialize state
        let state: S = JSON.parse(serializedState);

        // filter AppState and replace
        state = { ...state, app: filterAppState(state?.app) };

        return state;
    } catch (err) {
        return undefined;
    }
};

const cb =
    <S extends CoreState>(reducer: ActionReducer<S>, storage: Storage | null) =>
    (state: S, action: Action): S => {
        if (action.type === CoreAppActionTypes.INIT_STORE) {
            // This action must be dispatched from an app initializer
            // We load the state from a storage and compare the version and userId with the provided ones.
            // If they are the same, we merge the local state into the initial state.
            // If there is a mismatch, we don't merge the local state, but update only the initial state.

            if (storage) {
                // load the state from the localStorage
                const localState: S = loadState<S>(storage);

                // extract the details about user and app version from the action payload
                const payloadVersion = (action as InitStoreAction).payload?.version;

                if (localState) {
                    // TODO: Why all these checks here? What is the purpose of this code?
                    // extract the details about user and app version from the storage state
                    const localVersion = localState?.app?.version;
                    // const localUserId = localState.user && localState.user.userId;

                    const isVersionOK = !localVersion || !payloadVersion || localVersion === payloadVersion;
                    // const isUserIdOK = (localUserId === payloadUserId);

                    // update the entire state with deep merge of states, if the version and user are the same
                    if (isVersionOK) {
                        state = extend(true, {}, state, localState);
                    }
                }

                // update the app version, if defined
                if (payloadVersion) {
                    state = { ...state, app: { ...state?.app, version: payloadVersion } };
                }
            }
        }

        return reducer(state, action);
    };
