import { Component, HostBinding, Input, booleanAttribute } from '@angular/core';

@Component({
    selector: 'eui-icon-input',
    templateUrl: './eui-icon-input.component.html',
    styleUrls: [ './eui-icon-input.component.scss' ],
})
export class EuiIconInputComponent {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-icon-input',
            this.euiIconPositionStart && !this.euiIconPositionEnd ? 'eui-icon-input--start' : '',
            this.euiIconPositionEnd ? 'eui-icon-input--end' : '',
        ]
            .join(' ')
            .trim();
    }

    @Input({ transform: booleanAttribute }) euiIconPositionStart = true;
    @Input({ transform: booleanAttribute }) euiIconPositionEnd = false;
}
