import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    Output,
    OnInit,
    Directive,
    ContentChild,
    forwardRef,
    QueryList,
    EventEmitter,
    inject,
    booleanAttribute,
    OnDestroy,
    ChangeDetectionStrategy,
} from '@angular/core';
import { Subject, debounceTime, takeUntil } from 'rxjs';
import { EuiAppShellService } from '@eui/core';
import { EuiPageColumnsComponent } from '../eui-page-columns/eui-page-columns.component';
import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { AsyncPipe, NgTemplateOutlet } from '@angular/common';
import { CdkScrollable } from '@angular/cdk/scrolling';

@Component({
    selector: 'eui-page-column',
    templateUrl: './eui-page-column.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgTemplateOutlet,
        CdkScrollable,
        AsyncPipe,
        ...EUI_ICON,
        ...EUI_BUTTON,
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiSizeS',
                'euiSizeM',
                'euiSizeL',
                'euiSizeXL',
                'euiSize2XL',
                'euiSize3XL',
                'euiSize4XL',
                'euiSizeVariant',
                'euiHighlighted',
            ],
        },
    ],
})
export class EuiPageColumnComponent implements OnInit, OnDestroy {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            this.isCollapsed ? 'eui-page-column eui-page-column--collapsed' : this.baseStatesDirective.getCssClasses('eui-page-column'),
            this.isCollapsedWithIcons ? 'eui-page-column__header--with-icons' : '',
            this.isHighlighted ? 'eui-page-column--highlighted' : '',
            this.isActive ? 'eui-page-column--active' : '',
            this.hasSidebarMenu ? 'eui-page-column--has-sidebar-menu' : '',
            this.isHeaderBodyShrinked ? 'eui-page-column__header--shrinked' : '',
            this.hasPreventMobileRendering ? 'eui-page-column--prevent-mobile-rendering' : '',
        ]
            .join(' ')
            .trim();
    }

    @Input() label;
    @Input() subLabel;
    @Input() autocloseContainerWidth: number = null;
    @Input() expandAriaLabel: string;
    @Input() collapseAriaLabel: string;

    @Input({ transform: booleanAttribute }) isCollapsible = false;
    @Input({ transform: booleanAttribute }) isCollapsed = false;
    @Input({ transform: booleanAttribute }) isRightCollapsible = false;
    @Input({ transform: booleanAttribute }) isHighlighted = false;
    @Input({ transform: booleanAttribute }) isCollapsedWithIcons = false;
    @Input({ transform: booleanAttribute }) hasSidebarMenu = false;
    @Input({ transform: booleanAttribute }) hasHeaderBodyShrinkable = false;
    @Input({ transform: booleanAttribute }) isAutocloseOnContainerResize = false;
    @Input({ transform: booleanAttribute }) isAutocloseOnMobile = false;

    @Output() collapse = new EventEmitter();
    @Output() headerCollapse = new EventEmitter();
    isActive = false;

    isHeaderBodyShrinked = false;

    hasPreventMobileRendering = false;

    @ContentChild(forwardRef(() => EuiPageColumnHeaderBodyContentDirective))
    customHeaderBodyContent: QueryList<EuiPageColumnHeaderBodyContentDirective>;

    @ContentChild(forwardRef(() => EuiPageColumnHeaderLeftContentDirective))
    customHeaderLeftContent: QueryList<EuiPageColumnHeaderLeftContentDirective>;

    @ContentChild(forwardRef(() => EuiPageColumnHeaderRightContentDirective))
    customHeaderRightContent: QueryList<EuiPageColumnHeaderRightContentDirective>;

    @ContentChild(forwardRef(() => EuiPageColumnHeaderCollapsedContentDirective))
    customHeaderCollapsedContent: QueryList<EuiPageColumnHeaderCollapsedContentDirective>;

    @ContentChild(forwardRef(() => EuiPageColumnFooterContentDirective))
    customFooterContent: QueryList<EuiPageColumnFooterContentDirective>;

    currentOffset = 0;

    previousOffset = 0;
    treshHold = 50;
    asService = inject(EuiAppShellService);
    protected baseStatesDirective = inject(BaseStatesDirective);
    private pageColumnsParent: EuiPageColumnsComponent = inject(EuiPageColumnsComponent, { host: true, optional: true })!;
    private destroy$ = new Subject<boolean>();

    ngOnInit(): void {
        // this.baseStatesDirective.euiSizeS = false; // Bypass size default
        if (this.pageColumnsParent && this.isAutocloseOnContainerResize && this.autocloseContainerWidth) {
            this.pageColumnsParent.width.pipe(debounceTime(100), takeUntil(this.destroy$)).subscribe((parentWidth: number) => {
                if (parentWidth <= this.autocloseContainerWidth) {
                    this.isCollapsed = true;
                    this.collapse.emit(this.isCollapsed);
                }
            });
        }

        if (this.pageColumnsParent && this.pageColumnsParent.hasPreventMobileRendering) {
            this.hasPreventMobileRendering = this.pageColumnsParent.hasPreventMobileRendering;
        }

        if (this.isAutocloseOnMobile) {
            this.asService.breakpoints$.pipe(takeUntil(this.destroy$)).subscribe((bkps) => {
                if (bkps.isMobile) {
                    this.isCollapsed = true;
                }
            });
        }

        this.expandAriaLabel = `Expand ${this.label}`;
        this.collapseAriaLabel = `Collapse ${this.label}`;
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    public onToggle(): void {
        this.isCollapsed = !this.isCollapsed;
        this.collapse.emit(this.isCollapsed);
    }
}

/* eslint-disable */
@Directive({ selector: 'eui-page-column-header-body' })
export class EuiPageColumnHeaderBodyContentDirective {}
@Directive({ selector: 'eui-page-column-header-left-content' })
export class EuiPageColumnHeaderLeftContentDirective {}
@Directive({ selector: 'eui-page-column-header-right-content' })
export class EuiPageColumnHeaderRightContentDirective {}
@Directive({ selector: 'eui-page-column-header-collapsed-content' })
export class EuiPageColumnHeaderCollapsedContentDirective {}
@Directive({ selector: 'eui-page-column-body' })
export class EuiPageColumnBodyContentDirective {}
@Directive({ selector: 'eui-page-column-footer' })
export class EuiPageColumnFooterContentDirective {}
/* eslint-enable */
