import { NgModule, Pipe, PipeTransform } from '@angular/core';
import { BooleanInput, coerceBooleanProperty } from '@angular/cdk/coercion';

@Pipe({
    name: 'coerceBool',
    pure: true,
})
export class EuiCoerceBooleanPipe implements PipeTransform {
    transform(value: BooleanInput): boolean {
        return coerceBooleanProperty(value);
    }
}

/**
 * @description
 * Module that provides the EuiCoerceBooleanPipe pipe.
 *
 * @deprecated Use {@link EuiCoerceBooleanPipe} instead.
 */
@NgModule({
    imports: [EuiCoerceBooleanPipe],
    exports: [EuiCoerceBooleanPipe],
})
export class EuiCoerceBooleanPipeModule {}
