import {
    Injector,
    ModuleWithProviders,
    NgModule,
    Optional,
    SkipSelf,
    InjectionToken,
    Inject,
} from '@angular/core';

import { MODULE_CONFIG_TOKEN, MODULE_NAME_TOKEN } from './services/config/tokens';
import { StoreService } from './services/store/index';
import { getCoreChildProviders, getCoreProviders } from './services/app/eui-startup';
import { CoreState } from '@eui/base';

const AddAppLoadedConfigModules = (state: CoreState, action: { moduleName, moduleConfig }): CoreState => ({
    ...state,
    app: {
        ...state.app,
        loadedConfigModules: {
            lastAddedModule: action.moduleName,
            modulesConfig: {
                ...state.app.loadedConfigModules.modulesConfig,
                [action.moduleName]: {
                    ...action.moduleConfig,
                },
            },
        },
    },
});

export const CORE_ROOT_GUARD = new InjectionToken<void>('Internal Theme ForRoot Guard');

@NgModule()
export class CoreModule {
    /**
     * No more providing config from forRoot, you have to use EUI_CONFIG_TOKEN to pass config via providers.
     */
    static forRoot(): ModuleWithProviders<CoreModule> {
        return {
            ngModule: CoreModule,
            providers: [
                {
                    provide: EuiCoreRootGuardClass,
                    useFactory: euiCoreRootGuardClass,
                    deps: [],
                },
                {
                    provide: CORE_ROOT_GUARD,
                    useFactory: createEuiCoreRootGuard,
                    deps: [[EuiCoreRootGuardClass, new Optional(), new SkipSelf()]],
                },
                ...getCoreProviders(),
            ],
        };
    }

    static forChild(moduleName: string): ModuleWithProviders<CoreModule> {
        return {
            ngModule: CoreModule,
            providers: getCoreChildProviders(moduleName),
        };
    }

    constructor(@Optional() @Inject(CORE_ROOT_GUARD) guard: null, @Optional() @SkipSelf() parentModule: CoreModule, injector: Injector) {
        // if there is a parentModule, a new instance is created in a lazy loaded module
        if (parentModule) {
            // extract the i18n service and the i18n loader config
            // todo, this thing should be achieved by store, and localization service dependency should be removed
            const storeService = injector.get(StoreService);
            const moduleName = injector.get(MODULE_NAME_TOKEN);
            const moduleConfig = injector.get(MODULE_CONFIG_TOKEN);
            storeService.updateState({ moduleName, moduleConfig }, AddAppLoadedConfigModules);
        }
    }
}

const createEuiCoreRootGuard = (core): string => {
    if (core) {
        throw new TypeError('CoreModule.forRoot() called twice. Feature modules should use ThemeModule.forChild() instead.');
    }
    return 'guarded';
};

export class EuiCoreRootGuardClass {
    constructor() { /* empty */ }
}

const euiCoreRootGuardClass = (): EuiCoreRootGuardClass => new EuiCoreRootGuardClass();

export { createEuiCoreRootGuard, euiCoreRootGuardClass };
