import { InjectionToken, Injector, ModuleWithProviders, NgModule } from '@angular/core';
import { LogConfig } from '@eui/base';

import { LogService } from './log.service';
import { DEFAULT_LOG_CONFIG } from '../config/defaults';
import { logServiceFactory } from '../app/factories/log';

const LOG_MODULE_CONFIG_TOKEN = new InjectionToken<LogConfig>('LOG_CONFIG');

/**
 * Log Module
 */
@NgModule()
export class LogModule {
    /** method called in your root module to provide the LogService */
    static forRoot(config: LogConfig = DEFAULT_LOG_CONFIG): ModuleWithProviders<LogModule> {
        return {
            ngModule: LogModule,
            providers: [
                { provide: LOG_MODULE_CONFIG_TOKEN, useValue: config },
                { provide: LogService, useFactory: logServiceFactory, deps: [LOG_MODULE_CONFIG_TOKEN, Injector] },
            ],
        };
    }

    /** method called in your other (non root, lazy loaded) modules to import a different instance of LogService */
    static forChild(config: LogConfig = DEFAULT_LOG_CONFIG): ModuleWithProviders<LogModule> {
        return {
            ngModule: LogModule,
            providers: [
                { provide: LOG_MODULE_CONFIG_TOKEN, useValue: config },
                { provide: LogService, useFactory: logServiceFactory, deps: [LOG_MODULE_CONFIG_TOKEN, Injector] },
            ],
        };
    }
}
