import { ChangeDetectionStrategy, Component, HostBinding, Input, ViewEncapsulation, inject } from '@angular/core';
import { coerceBooleanProperty, BooleanInput } from '@angular/cdk/coercion';
import { Event as NavigationEvent, NavigationStart, Router } from '@angular/router';
import { filter } from 'rxjs/operators';

import { EuiAppShellService } from '@eui/core';

/**
 * EuiDimmerComponent provides a dimming overlay on the page.
 *
 * The dimmer can be manually activated by setting `isDimmerActive` to true,
 * or automatically controlled via browser navigation events.
 *
 */
@Component({
    selector: 'eui-dimmer',
    template: '',
    changeDetection: ChangeDetectionStrategy.Default,
    styleUrls: ['./dimmer.scss'],
    encapsulation: ViewEncapsulation.None,
})
export class EuiDimmerComponent {
    asService = inject(EuiAppShellService);

    /**
     * Gets the active state of the dimmer.
     *
     * @returns {boolean} True if dimmer is active, false otherwise.
     */
    @Input()
    get isDimmerActive(): boolean {
        return this._isDimmerActive;
    }
    /**
     * Sets the active state of the dimmer.
     *
     * @param {BooleanInput} value - The value to set for the dimmer active state.
     */
    set isDimmerActive(value: BooleanInput) {
        this._isDimmerActive = coerceBooleanProperty(value);
    }

    /**
     * Gets the CSS classes to apply to the host element.
     * Adds the 'eui-dimmer--active' class when the dimmer is active.
     *
     * @returns {string} The CSS classes as a space-separated string.
     */
    @HostBinding('class')
    get cssClasses(): string {
        return ['eui-dimmer', this._isDimmerActive ? 'eui-dimmer--active' : ''].join(' ').trim();
    }

    /**
     * E2E testing attribute for the component.
     */
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-dimmer';

    /** The active state of the dimmer. */
    private _isDimmerActive: true | false = false;

    /** Debug flag to control logging. */
    private _DEBUG: true | false = false;

    /**
     * Creates an instance of EuiDimmerComponent.
     *
     * Listens to router navigation events to handle dimmer state during navigation,
     * particularly when the user navigates back in browser history.
     *
     * @param {EuiAppShellService} asService - The app shell service for dimmer state management.
     * @param {Router} router - The Angular router service for navigation event monitoring.
     */
    constructor() {
        const router = inject(Router);

        // The events stream contains all the navigation events including the NavigationStart event
        // which gives information about what initiated the navigation sequence
        router.events.pipe(filter((event: NavigationEvent) => event instanceof NavigationStart)).subscribe((event: NavigationStart) => {
            if (this._DEBUG) {
                console.group('NavigationStart Event');
                // Every navigation sequence is given a unique ID.
                console.log('navigation id:', event.id);
                console.log('route:', event.url);
                // The 'navigationTrigger' will be one of:
                // - imperative : ie. user clicked on a link
                // - popstate : browser controlled change such as Back button which gets a new, unique ID
                // - hashchange
                // @See: https://angular.io/api/router/NavigationStart
                console.log('trigger:', event.navigationTrigger);
                // The 'restoredState' property is defined when the navigation event is triggered by a 'popstate' event
                // It will contain the ID of the previous navigation event from which the browser is returning
            }
            if (event.restoredState) {
                this.asService.setDimmerActiveState(false);
                this._isDimmerActive = false;
                if (this._DEBUG) {
                    console.warn('restoring navigation id:', event.restoredState.navigationId);
                }
            }
            if (this._DEBUG) {
                console.groupEnd();
            }
        });
    }
}
