import { ChangeDetectionStrategy, Component, HostBinding, Input } from '@angular/core';

import { showHide } from '../animations/show-hide';
import { EuiTooltipInterface } from '../models/eui-tooltip.config';

@Component({
    selector: 'eui-tooltip-container.component',
    templateUrl: 'eui-tooltip-container.component.html',
    // Styles are in globals: \packages\styles\src\styles\07-elements\directives\_eui-tooltip.scss
    animations: [showHide],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EuiTooltipContainerComponent {
    /**
     * Configuration provided by euiTooltip directive at instantiation.
     *
     * @type {EuiTooltipInterface} A config object containing e2eAttr, tooltipContent, position, contentAlign, colorClass.
     */
    @Input() config: EuiTooltipInterface;
    /**
     * Sets the `data-e2e` attribute for the host element.
     *
     * @default 'eui-tooltip'
     */
    @HostBinding('attr.data-e2e') e2e = 'eui-tooltip';
    /**
     * @description
     * Computes and returns the CSS classes for the component based on its current state.
     *
     * @returns {string} Space-separated string of CSS class names
     */
    @HostBinding('class')
    get cssClasses(): string {
        return ['eui-tooltip', 'eui-tooltip--content-' + this.config.contentAlign, 'eui-tooltip--' + this.config.colorClass]
            .join(' ')
            .trim();
    }
    @HostBinding('@showHide') get showHide(): string {
        return 'visible';
    }
}
