import { Component, HostBinding, ChangeDetectionStrategy, Input, booleanAttribute, inject, ContentChild, forwardRef, QueryList } from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EuiAvatarImageComponent } from './avatar-image/avatar-image.component';

/**
 * @description
 * Component for displaying avatars in the EUI design system.
 *
 * An avatar is a visual representation of a user or entity and can contain
 * an image, text, or an icon. This component serves as the container for
 * various avatar subcomponents, such as EuiAvatarImage, EuiAvatarText,
 * EuiAvatarIcon, and EuiAvatarBadge.
 *
 * The component supports various customizations, including colors (via state directives),
 * sizes, shapes, and appearance modifiers.
 *
 */
@Component({
    selector: 'div[euiAvatar], span[euiAvatar], eui-avatar',
    templateUrl: './eui-avatar.component.html',
    styleUrl: './eui-avatar.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        ...EUI_ICON,
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiSuccess',
                'euiInfo',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiVariant',

                'euiSizeXS',
                'euiSizeS',
                'euiSizeL',
                'euiSizeXL',
                'euiSize2XL',
                'euiSizeVariant',
            ],
        },
    ],
})
export class EuiAvatarComponent {
    /**
     * Gets the CSS classes to be applied to the host element.
     * Combines base classes with modifier classes.
     * @returns {string} The combined CSS classes
     */
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-avatar'),
            this.isShapeSquare ? 'eui-avatar--shape-square' : '',
            this.isFlat ? 'eui-avatar--flat eui--basic' : '',
            this.hasNoBackground ? 'eui-avatar--no-background' : '',
            this.isReverse ? 'eui-avatar--reverse' : '',
            this.avatarImage ? 'eui-avatar--image' : '',
        ].join(' ').trim();
    }

    /**
     * Data attribute for E2E testing
     * @default 'eui-avatar'
     */
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-avatar';

    /**
     * ARIA role for accessibility
     * @default 'status'
     */
    @HostBinding('attr.role') role = 'status';

    /**
     * ARIA label for accessibility
     * @default 'avatar'
     */
    @HostBinding('attr.aria-label') @Input('aria-label') ariaLabel: string | null = 'avatar';

    /**
     * Whether the avatar should have a shadow effect
     * @default false
     */
    @Input({ transform: booleanAttribute }) hasShadow = false;

    /**
     * Whether the avatar shape should be square instead of circular
     * @default false
     */
    @Input({ transform: booleanAttribute }) isShapeSquare = false;

    /**
     * Whether the avatar should have a flat appearance
     * @default false
     */
    @Input({ transform: booleanAttribute }) isFlat = false;

    /**
     * Whether the avatar should have no background color
     * @default false
     */
    @Input({ transform: booleanAttribute }) hasNoBackground = false;

    /**
     * Whether the avatar reverse layout with content
     * @default false
     */
    @Input({ transform: booleanAttribute }) isReverse = false;    

    @ContentChild(forwardRef(() => EuiAvatarImageComponent)) avatarImage: QueryList<EuiAvatarImageComponent>;

    /**
     * Reference to the BaseStatesDirective providing state-based styling
     * @internal
     */
    protected baseStatesDirective = inject(BaseStatesDirective);
}
