import { ChangeDetectionStrategy, Component, ElementRef, HostBinding, Input, NgZone, OnDestroy, OnInit, ViewEncapsulation, booleanAttribute, inject } from '@angular/core';
import { Subject } from 'rxjs';

// eslint-disable-next-line
declare var ResizeObserver;

@Component({
    selector: 'eui-page-columns',
    template: '<ng-content/>',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiPageColumnsComponent implements OnInit, OnDestroy {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-page-columns',
            this.hasPreventMobileRendering ? 'eui-page-columns--prevent-mobile-rendering': '',
        ].join(' ').trim();
    }

    @Input({ transform: booleanAttribute }) hasPreventMobileRendering = false;

    public width = new Subject;

    private observer;
    private host = inject(ElementRef);
    private zone = inject(NgZone);

    ngOnInit():void {
      this.observer = new ResizeObserver(entries => {
        this.zone.run(() => {
          this.width.next(entries[0].contentRect.width);
        });
      });
      this.observer.observe(this.host.nativeElement);
    }

    ngOnDestroy():void {
      this.observer.unobserve(this.host.nativeElement);
    }
}
