import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    OnInit,
    ViewChild,
    OnDestroy,
    forwardRef,
    QueryList,
    AfterViewInit,
    ContentChildren,
    ElementRef,
    booleanAttribute,
    Signal,
    computed,
    ChangeDetectorRef,
    inject,
} from '@angular/core';
import { UserState } from '@eui/core';
import { UserService } from '@eui/core';
import { EUI_DROPDOWN, EuiDropdownComponent, EuiDropdownService } from '@eui/components/eui-dropdown';
import { BehaviorSubject, Subject } from 'rxjs';
import { BaseStatesDirective } from '@eui/components/shared';
import { EuiUserProfileMenuComponent } from './user-profile-menu/user-profile-menu.component';
import { NgTemplateOutlet } from '@angular/common';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_AVATAR } from '@eui/components/eui-avatar';
import { EUI_BADGE } from '@eui/components/eui-badge';

/**
 * Represents an extended user profile that includes impersonation capabilities
 * and organizational information.
 * @extends {UserState}
 *
 * When using this interface with UserService, specify it as the generic type parameter:
 * Example: private userService: UserService<UserProfile>
 */
export interface UserProfile extends UserState {
    /** The profile of another user being impersonated, if applicable */
    impersonatingUser?: UserProfile;
    /** The user's function or role within the system */
    function?: string;
    /** The organization details associated with the user */
    organisation?: {
        /** The unique code identifying the organization */
        code: string
    }
}

@Component({
    selector: 'eui-user-profile',
    templateUrl: './user-profile.component.html',
    styleUrls: ['./_styles/_index.scss'],
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgTemplateOutlet,
        ...EUI_DROPDOWN,
        ...EUI_ICON,
        ...EUI_AVATAR,
        ...EUI_BADGE,
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiSizeS',
                'euiSecondary',
                'euiPrimary',
            ],
        },
    ],
    providers: [EuiDropdownService],
})
export class EuiUserProfileComponent implements OnInit, OnDestroy, AfterViewInit {
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-user-profile'),
            this.isReverse ? 'eui-user-profile--reverse': '',
            this.isShowAvatarInitials ? 'eui-user-profile--initials': '',
        ].join(' ').trim();
    }

    userState: Signal<UserProfile>;
    avatarInitials: Signal<string>;

    @Input() welcomeLabel = 'Welcome';
    @Input() impersonateLabel = 'acting as';
    @Input() avatarUrl: string;
    @Input() subInfos: string;
    @Input() statusVariant = 'success';

    @Input({ transform: booleanAttribute }) hasMenu = false;
    @Input({ transform: booleanAttribute }) hasWelcomeLabel = true;
    @Input({ transform: booleanAttribute }) isShowAvatarInitials = false;
    @Input({ transform: booleanAttribute }) hasTabNavigation = false;
    @Input({ transform: booleanAttribute }) isReverse = false;
    @Input({ transform: booleanAttribute }) hasToggle = false;
    @Input({ transform: booleanAttribute }) isHeaderUserProfile = false;
    @Input({ transform: booleanAttribute }) isToolbarUserProfile = false;
    @Input({ transform: booleanAttribute }) isShowUserInfos = true;
    @Input({ transform: booleanAttribute }) isMobileOnly = true;

    @Input({ transform: booleanAttribute }) euiStatusSecondary = false;
    @Input({ transform: booleanAttribute }) euiStatusSuccess = false;
    @Input({ transform: booleanAttribute }) euiStatusDanger = false;
    /**
     * If true, the name will be displayed in reverse order (first name, first)
     */
    @Input() reverseNameOrder = false;

    @ViewChild('dropdown') dropdown: EuiDropdownComponent;
    @ContentChildren(forwardRef(() => EuiUserProfileMenuComponent), { descendants: true })
    hasMenuContent: QueryList<EuiUserProfileMenuComponent>;

    isDropdownOpen = false;
    baseStatesDirective = inject(BaseStatesDirective);
    $isDropdownOpen = new BehaviorSubject<boolean>(false);
    private unsubscribeSubject$: Subject<void> = new Subject();
    private elRef = inject(ElementRef);
    private cd = inject(ChangeDetectorRef);
    private userService = inject<UserService<UserProfile>>(UserService);

    ngOnInit(): void {
        this.userState = this.userService.getSignal();
        this.avatarInitials = computed(() => {
            const firstNameInitial = this.userState().firstName?.substring(0, 1).toUpperCase();
            const lastNameInitial = this.userState().lastName?.substring(0, 1).toUpperCase();
            return this.reverseNameOrder ?
                `${firstNameInitial}${lastNameInitial}`
                : `${lastNameInitial}${firstNameInitial}`;
        });
    }

    ngAfterViewInit(): void {
        this.cd.markForCheck();

        let hasToolbarItemParent = false, toolbar;

        if (this.isToolbarUserProfile) {
            this.baseStatesDirective.euiSizeS = true;
            this.hasMenu = this.hasMenuContent.length !== 0;

        } else {
            try {
                hasToolbarItemParent = this.elRef.nativeElement.closest('eui-toolbar-item');
                toolbar = this.elRef.nativeElement.closest('eui-toolbar');
            } catch(e) {
               // do nothing
            }

            setTimeout(() => {
                if (hasToolbarItemParent) {
                    this.baseStatesDirective.euiSizeS = true;
                    if (toolbar && toolbar.classList.contains('eui--secondary') || this.baseStatesDirective.euiSecondary) {
                        this.baseStatesDirective.euiSecondary = true;
                    } else {
                        this.baseStatesDirective.euiPrimary = true;
                    }
                }
                if (hasToolbarItemParent || !this.isHeaderUserProfile) {
                    this.hasMenu = this.hasMenuContent.length !== 0;
                }
                if (this.isMobileOnly) {
                    this.baseStatesDirective.euiSizeS = true;
                }
                this.cd.markForCheck();
            });
        }
    }

    ngOnDestroy(): void {
        this.unsubscribeSubject$.next();
        this.unsubscribeSubject$.complete();
    }

    closeDropdown(): void {
        this.dropdown.closeDropdown();
        this.isDropdownOpen = false;
    }

    onDropdownExpand(isOpen: boolean): void {
        this.isDropdownOpen = isOpen;
    }

    onOpenChange(open: boolean): void {
        this.isDropdownOpen = open;
        this.$isDropdownOpen.next(open);
    }
}
