import { Inject, Injectable, Optional } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { TranslateLoader } from '@ngx-translate/core';
import { forkJoin, Observable, of } from 'rxjs';
import { catchError, map } from 'rxjs/operators';

import {
    getI18nLoaderConfig,
    I18nResource,
    type EuiAppConfig,
    mergeAll,
    Logger,
    I18nLoaderConfig,
    I18nConfig,
    TranslationsCompiler,
} from '@eui/base';
import { I18nResourceImpl } from './i18n.resource';
import { CONFIG_TOKEN } from '../config/tokens';
import { LogService } from '../log/log.service';

interface ResourceError {
    isError: boolean;
    error?: string;
    resource?: I18nResourceImpl;
}

export interface LoadedResources {
    translations: object;
    hasError: boolean;
    errors?: Array<LoadedResourcesError>;
}

export interface LoadedResourcesError {
    resource: I18nResourceImpl;
    error: string;
}

export interface TranslationKeys {
    [key: string]: string
}

@Injectable()
export class I18nLoader implements TranslateLoader {
    protected resources: I18nResourceImpl[] = [];
    protected failedResources: Array<LoadedResourcesError> = [];
    private logger: Logger;

    constructor(
        protected http: HttpClient,
        @Optional() protected logService: LogService,
        @Inject(CONFIG_TOKEN) protected euiAppConfig: EuiAppConfig,
    ) {
        if (logService) {
            this.logger = this.logService.getLogger('core.I18nLoader')
        }

        // create the resources from the config object
        const i18nConfig: I18nConfig = this.euiAppConfig.global && this.euiAppConfig.global.i18n;
        const i18nLoaderConfig: I18nLoaderConfig = i18nConfig && i18nConfig.i18nLoader;
        this.resources.push(...this.createResources(i18nLoaderConfig));
    }

    /**
     * Gets the translations from the server
     *
     * @param lang
     * @returns Observable<object>
     */
    public getTranslation(lang: string): Observable<object> {
        return this.loadResources(this.resources, lang).pipe(
            map((loadedResources: LoadedResources) => {
                this.failedResources = loadedResources.hasError ? loadedResources.errors : [];
                return loadedResources.translations;
            }),
        );
    }

    /**
     * Adds resources
     *
     * @param config loader configuration
     * @returns Observable<any> | false
     */
    public addResources(config: I18nLoaderConfig): I18nResourceImpl[] {
        // create the resources
        let resources = this.createResources(config);

        // filter the resources first, to avoid duplicates
        resources = resources.filter((resource) => !this.resources.some((res) => res.equals(resource)));

        // add the new resources to the list of existing resources
        this.resources.push(...resources);

        // return the filtered resources
        return resources;
    }

    /**
     * Removes resources from the loader instance
     */
    public removeResources(removedResources: I18nResourceImpl[]): void {
        this.resources = this.resources.filter((res) => !removedResources.some((removedResource) => removedResource.equals(res)));
    }

    /**
     * Loads an array of resources, by language
     *
     * @param resources the definition of the resources
     * @param lang the resource language to load
     * @returns Observable<any>
     */
    public loadResources(resources: I18nResourceImpl[], lang: string): Observable<{ hasError: boolean; translations: object; errors?: LoadedResourcesError[] }> {
        // if there are resources to load
        if (Array.isArray(resources) && resources.length > 0) {
            // load all the resources in an array of Observable
            const requests = resources.map((resource) => this.loadResource(resource, lang));
            // group all the observables with forkJoin and deep merge them
            return forkJoin(requests).pipe(
                map((response) => {
                    const successResp = [];
                    const errResp: Array<LoadedResourcesError> = [];
                    response.forEach((item) => {
                        if ((<ResourceError>item).isError) {
                            errResp.push({ resource: (<ResourceError>item).resource, error: (<ResourceError>item).error });
                        } else {
                            successResp.push(item);
                        }
                    });
                    if (successResp.length === response.length) {
                        return { hasError: false, translations: mergeAll(successResp) };
                    } else {
                        return { hasError: true, translations: mergeAll(successResp), errors: errResp };
                    }
                }),
            );
        } else {
            // no resources to load
            return of({ hasError: false, translations: {} });
        }
    }

    /**
     * Returns resources that failed
     */
    public getFailedResources(): Array<LoadedResourcesError> {
        return this.failedResources;
    }

    /**
     * Create resources from a config file
     *
     * @param config loader configuration
     * @returns I18nResourceImpl[] resources
     */
    protected createResources(config: I18nLoaderConfig): I18nResourceImpl[] {
        // use the default config as a reference base
        config = getI18nLoaderConfig(config);

        const resources = [];

        // extract the i18n folders from config
        const i18nFolders: string[] = Array.isArray(config.i18nFolders)
            ? config.i18nFolders
            : config.i18nFolders
            ? [config.i18nFolders]
            : [];
        if (i18nFolders) {
            // add the i18n folders to resources
            resources.push(...i18nFolders.map((folder) => new I18nResourceImpl(`assets/${folder}/`, '.json')));
        }

        // extract the i18n services from config
        const i18nServices: string[] = Array.isArray(config.i18nServices)
            ? config.i18nServices
            : config.i18nServices
            ? [config.i18nServices]
            : [];
        if (i18nServices) {
            // add the i18n services to resources
            resources.push(...i18nServices.map((service) => new I18nResourceImpl(service)));
        }

        // extract the i18n resources from config
        const i18nResources: I18nResource[] = Array.isArray(config.i18nResources)
            ? config.i18nResources
            : config.i18nResources
            ? [config.i18nResources]
            : [];
        if (i18nResources) {
            // add the i18n resources to resources
            resources.push(
                ...i18nResources.map(
                    (resource) =>
                        new I18nResourceImpl(
                            resource.prefix,
                            resource.suffix,
                            this.getResourceCompileFunction(resource.compileTranslations),
                        ),
                ),
            );
        }

        return resources;
    }

    /**
     * Loads a resource, by language
     *
     * @param resource the definition of the resource
     * @param lang the resource language to load
     * @returns Observable<any>
     */
    protected loadResource(resource: I18nResourceImpl, lang: string): Observable<TranslationKeys | ResourceError> {
        // the path to the resource
        const path = resource.getPath(lang);

        // load the translations from the path
        return this.http.get(path).pipe(
            // preprocess the translations using the resource compiler
            map((translations: unknown) => resource.compileTranslations(translations, lang)),
            map((translations: TranslationKeys) => {
                // resource loaded properly, send a info message
                this.logger?.info(`I18n resource loaded from path ${path}`);
                // return the translations
                return translations;
            }),
            catchError((err) => {
                // remove failed resource from loaded resource array
                // this.removeResources([resource]);
                // resource not loaded properly, send a warning message
                this.logger?.warn(`I18n resource NOT loaded from path ${path}`, err);
                const resourceError: ResourceError = { error: `I18n resource NOT loaded from path ${path}`, resource, isError: true };
                return of(resourceError);
            }),
        );
    }

    private getResourceCompileFunction(id: string): TranslationsCompiler {
        const customHandlers = this.euiAppConfig.customHandler;
        if (customHandlers && typeof customHandlers[id] === 'function') {
            return customHandlers[id];
        }
        return undefined;
    }
}

export const translateConfig = {
    loader: {
        provide: TranslateLoader,
        useClass: I18nLoader,
    },
};
