import {
    booleanAttribute,
    Directive,
    ElementRef,
    HostBinding,
    Injector,
    Input,
    OnChanges,
    OnDestroy,
    OnInit,
    Renderer2,
    SimpleChange,
    SimpleChanges,
    ViewContainerRef,
    inject,
} from '@angular/core';
import { FormControl, FormControlDirective, FormControlName, FormGroupDirective, NgControl } from '@angular/forms';
import { coerceBooleanProperty, BooleanInput } from '@angular/cdk/coercion';
import { Subscription } from 'rxjs';

@Directive({
    // eslint-disable-next-line @angular-eslint/directive-selector
    selector: 'input[euiInput]',
    standalone: false,
})
export class InputDirective implements OnInit, OnDestroy, OnChanges {
    @Input({ transform: booleanAttribute }) euiDisabled = false;
    @Input({ transform: booleanAttribute }) euiDanger = false;

    @HostBinding('attr.disabled')
    @Input()
    public get disabled(): boolean {
        return this._disabled ? true : null;
    }
    public set disabled(state: BooleanInput) {
        // in case it's controlled by NgControl override
        this._disabled = coerceBooleanProperty(state);
        // set BaseDirective Attribute
        this.euiDisabled = this._disabled;
    }

    @HostBinding('attr.readonly')
    @Input()
    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    public get readonly(): any {
        return this._readonly ? '' : null;
    }
    public set readonly(state: BooleanInput) {
        this._readonly = coerceBooleanProperty(state);
    }

    @HostBinding('attr.placeholder')
    @Input()
    public get placeholder(): string | null {
        return this.getPlaceholderAttribute();
    }
    public set placeholder(value: string | number | null) {
        this.setPlaceholderAttribute(value?.toString());
    }

    protected _disabled: boolean;
    protected _readonly: boolean;
    protected _placeholder: string;
    protected _statusListener: Subscription;
    protected _id: string;
    protected _viewContainerRef: ViewContainerRef;
    protected control: NgControl;
    protected _elementRef = inject(ElementRef);
    protected _renderer = inject(Renderer2);
    protected injector = inject(Injector);

    constructor() {
        this._viewContainerRef = this.injector.get(ViewContainerRef);
    }

    ngOnInit(): void {
        // extract the FormControl or NgControl
        this.control = this.injector.get(NgControl, undefined, { optional: true, self: true });

        let c: NgControl | FormControl = this.control;
        if (this.control instanceof FormControlName) {
            c = (this.injector as Injector).get(FormGroupDirective).getControl(this.control);
        } else if (this.control instanceof FormControlDirective) {
            c = this.control.form as FormControl;
        }
        if (c) {
            this.disabled = c.disabled;
            this.euiDisabled = this.disabled;
            // subscribe to NG control status changes to adjust inputs
            this._statusListener = c.statusChanges.subscribe((status) => {
                this.euiDanger = status === 'INVALID' && c.touched;
                this.disabled = status === 'DISABLED' && c.disabled;
            });
        }
    }

    ngOnDestroy(): void {
        if (this._statusListener) {
            this._statusListener.unsubscribe();
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        const readOnlyChange: SimpleChange = changes.readonly;

        if (readOnlyChange?.currentValue === true) {
            this._renderer.removeAttribute(this._elementRef.nativeElement, 'placeholder');
        }
    }

    getCssClasses(rootClass: string): string {
        return [
            rootClass,
            this.euiDanger ? `${rootClass}--danger eui--danger` : '',
            this.euiDisabled ? `${rootClass}--disabled eui--disabled disabled` : '',
        ].join(' ').trim();
    }

    protected getPlaceholderAttribute(): string | undefined {
        // in readonly memorize placeholder value and remove placeholder. The reason is that CSS style for readonly
        // cannot hide the placeholder text
        if (this._elementRef.nativeElement.attributes['readonly']) {
            if (!this._placeholder) {
                this.setPlaceholderAttribute(this._elementRef.nativeElement.placeholder);
            }
            return undefined;
        }

        // keep placeholder's value
        this._placeholder = this._elementRef.nativeElement.placeholder || this._placeholder;
        return this._placeholder;
    }

    protected setPlaceholderAttribute(value: string | null): void {
        if (!value) {
            this._renderer.removeAttribute(this._elementRef.nativeElement, 'placeholder');
        } else {
            this._renderer.setAttribute(this._elementRef.nativeElement, 'placeholder', value);
        }
        this._placeholder = value;
    }

    protected setIdAttribute(value: string | null = null): void {
        this._renderer.setAttribute(this._elementRef.nativeElement, 'id', value ? value : `${this._elementRef.nativeElement.type}_${Math.floor(Math.random() * 1000000)}`);
    }
}
