import {
    Component,
    ViewEncapsulation,
    HostBinding,
    OnDestroy,
    OnInit,
    ChangeDetectorRef,
    Input,
    Output,
    EventEmitter,
    booleanAttribute,
    ElementRef,
    AfterViewInit,
    SimpleChanges,
    OnChanges,
    inject,
} from '@angular/core';
import { distinctUntilKeyChanged, map, takeUntil } from 'rxjs/operators';
import { Subject } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';

import { EuiEuLanguages, EuiLanguage } from '@eui/core';
import { EuiAppShellService } from '@eui/core';
import { EuiDialogConfig, EuiDialogService } from '@eui/components/eui-dialog';

import { EuiModalSelectorComponent } from './modal-selector/modal-selector.component';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_DROPDOWN } from '@eui/components/eui-dropdown';
import { AsyncPipe, NgTemplateOutlet } from '@angular/common';

/**
 * @description A component that provides language selection functionality for applications.
 *
 * This component displays available languages and allows users to select their preferred language.
 * It adapts its display based on the number of available languages:
 * - For 1 language: No selector is shown
 * - For 2-3 languages: Displays a dropdown menu
 * - For 4+ languages: Opens a modal dialog with the full list
 *
 * The component integrates with EuiAppShellService to manage language state
 * and uses TranslateService for localization.
 */
@Component({
    selector: 'eui-language-selector',
    templateUrl: './language-selector.component.html',
    styleUrl: './language-selector.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        AsyncPipe,
        NgTemplateOutlet,
        ...EUI_DROPDOWN,
        ...EUI_ICON,
        ...EUI_BUTTON,
    ],
    providers: [
        EuiDialogService,
    ],
})
export class EuiLanguageSelectorComponent implements OnInit, AfterViewInit, OnDestroy, OnChanges {
    @HostBinding('class')
    get cssClasses(): string {
        return [
            'eui-language-selector',
            this.languages?.length <= 1 ? 'eui-language-selector--empty' : '',
            this.isToolbarSelector ? 'eui-language-selector--toolbar-selector' : '',
        ]
            .join(' ')
            .trim();
    }

    languages: EuiLanguage[];
    selectedLanguage: EuiLanguage;
    /**
     * @property hasLanguageSelection - Enables/disables language selection functionality.
     * @default true
     */
    @Input({ transform: booleanAttribute }) hasLanguageSelection = true;
    /**
     * @property isToolbarSelector - When true, applies styling for toolbar integration.
     * @default false
     */
    @Input({ transform: booleanAttribute }) isToolbarSelector = false;
    /**
     * @property euiPrimary - When true, applies primary styling.
     * @default false
     */
    @Input({ transform: booleanAttribute }) euiPrimary = false;
    /**
     * @property ariaLabel - Accessibility label for the language selector.
     * If not provided, defaults to "Change Language - Current Language: [selected language]"
     */
    @Input('aria-label') ariaLabel: string;
    /**
     * @event languageSelectorClick - Emitted when the language selector is clicked.
     */
    @Output() languageSelectorClick = new EventEmitter<null>();

    appShellService = inject(EuiAppShellService);
    private destroy$: Subject<boolean> = new Subject<boolean>();
    private isAriaLabelChanged = false;
    private cd = inject(ChangeDetectorRef);
    private euiDialogService = inject(EuiDialogService);
    private translateService = inject(TranslateService);
    private elRef = inject(ElementRef);

    /**
     * returns true if there are at least one and max four languages.
     */
    get isShowDropDown(): boolean {
        return this.languages?.length > 1 && this.languages?.length < 4;
    }

    /**
     * returns true if there are at least five languages.
     */
    get isShowModal(): boolean {
        return this.languages?.length >= 4;
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes && changes['ariaLabel']) {
            this.isAriaLabelChanged = true;
            this.ariaLabel = changes['ariaLabel'].currentValue;
        }
    }

    ngOnInit(): void {
        // update languages array based on AppShell State 'language' changes
        this.appShellService.state$
            .pipe(
                takeUntil(this.destroy$),
                distinctUntilKeyChanged('languages'),
                map((state) => state.languages),
            )
            .subscribe((languages) => {
                this.languages = languages ? EuiEuLanguages.getOrderedLanguages(languages) : EuiEuLanguages.getLanguages();
                this.cd.detectChanges();
            });

        // update activeLanguage array based on AppShell State 'language' changes
        this.appShellService.state$
            .pipe(
                takeUntil(this.destroy$),
                distinctUntilKeyChanged('activeLanguage'),
                map((state) => state?.activeLanguage),
            )
            .subscribe((activeLanguage) => {
                this.selectedLanguage = this.getLanguage(activeLanguage);
                if (!this.isAriaLabelChanged) {
                    this.ariaLabel = `Change Language - Current Language: ${this.selectedLanguage.label}`;
                }
                this.cd.detectChanges();
            });
    }

    ngAfterViewInit(): void {
        // TODO: Using DI like "inject(EuiToolbarComponent, {optional: true, skipSelf: true})" would create
        //  circular dependencies. Better approaches would be:
        //  1. Parent component provides the isToolbarSelector input
        //  2. Apply the eui-language-selector--toolbar-selector class directly
        let hasToolbarParent = false;
        try {
            hasToolbarParent = this.elRef.nativeElement.closest('eui-toolbar');
        } catch (e) {
            // do nothing
        }

        if (hasToolbarParent) {
            setTimeout(() => {
                this.isToolbarSelector = true;
            }, 1);
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    /**
     * Updates the active language in the application.
     * @param language - The language object to set as active.
     */
    onLanguageChanged(language: EuiLanguage): void {
        // Update the AppShellService state
        this.appShellService.setState({
            ...this.appShellService.state,
            activeLanguage: language.code,
        });
    }

    /**
     * Opens a modal dialog with the full list of available languages.
     * @param [titleLabel] - Optional custom title for the modal.
     */
    onOpen(titleLabel: string = this.translateService.instant('eui.languageSelector.modalTitle')): void {
        this.euiDialogService.openDialog(
            new EuiDialogConfig({
                title: titleLabel,
                hasFooter: false,
                hasClosedOnClickOutside: true,
                bodyComponent: {
                    component: EuiModalSelectorComponent,
                    config: {
                        languages: this.languages,
                        selectedLanguage: this.selectedLanguage,
                        languageChanged: (language: EuiLanguage): void => this.onLanguageChanged(language),
                    },
                },
            }),
        );
    }

    onClick(): void {
        this.languageSelectorClick.emit();
    }

    /**
     * Retrieves a language object by its code.
     *
     * @param languageCode - Two-character language code.
     */
    protected getLanguage(languageCode: string): EuiLanguage {
        return this.languages.find((lang) => lang.code === languageCode);
    }
}
