import { Action } from '../ngrx_kit';
import { LocaleState, initialLocaleState } from '@eui/base';
import { CoreLocaleActionTypes, CoreLocaleActions, UpdateLocaleStateAction } from '../actions/locale.actions';

/**
 * @deprecated it will be removed in the next major version
 */
const updateLocaleState = (state: LocaleState, action: UpdateLocaleStateAction): LocaleState => ({
    ...state,
    ...action.payload,
});

/**
 * @deprecated it will be removed in the next major version
 */
const actionToReducerMap: { [key: string]: (state: LocaleState, action: CoreLocaleActions) => LocaleState } = {
    [CoreLocaleActionTypes.UPDATE_LOCALE_STATE]: updateLocaleState,
};

/**
 * @deprecated it will be removed in the next major version
 */
export const coreLocaleReducers: (state: LocaleState, action: Action) => LocaleState = (
    state = initialLocaleState,
    action: CoreLocaleActions,
) => {
    if (actionToReducerMap[action.type]) {
        return actionToReducerMap[action.type](state, action);
    }
    return state;
};
