import {
    Component,
    HostBinding,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    Input,
    OnInit,
    EventEmitter,
    Output,
    booleanAttribute,
    computed,
    Signal,
    inject,
} from '@angular/core';
import { UserProfile } from '../user-profile.component';
import { UserService, UserDetails } from '@eui/core';
import { EUI_ICON_BUTTON } from '@eui/components/eui-icon-button';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_AVATAR } from '@eui/components/eui-avatar';

@Component({
    selector: 'eui-user-profile-card',
    templateUrl: './user-profile-card.component.html',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_BUTTON,
        ...EUI_ICON_BUTTON,
        ...EUI_ICON,
        ...EUI_AVATAR,
    ],
})
export class EuiUserProfileCardComponent implements OnInit {
    @HostBinding('class')
    public get cssClasses(): string {
        return 'eui-user-profile-card';
    }

    avatarInitials: Signal<string>;
    /**
     * Holds the full name of the user and the impersonated user
     */
    fullName: Signal<{ user: string, impersonated: string }>;
    userState: Signal<UserProfile> = inject(UserService).getSignal();
    /**
     * If true, the user is online
     * @deprecated This property is not used anymore
     */
    isOnline = true;

    @Input() impersonateLabel = 'acting as';
    @Input() showDetailsLabel = 'Show profile details';
    @Input() avatarUrl: string;
    @Input({ transform: booleanAttribute }) isShowAvatarInitials = true;
    /**
     * If true, the name will be displayed in reverse order (first name, first)
     */
    @Input() reverseNameOrder = false;

    @Output() showProfileInfo: EventEmitter<void> = new EventEmitter();
    @Output() closeProfileMenu: EventEmitter<void> = new EventEmitter();

    ngOnInit(): void {
        this.avatarInitials = computed(() => {
            const firstNameInitial = this.userState().firstName?.substring(0, 1).toUpperCase();
            const lastNameInitial = this.userState().lastName?.substring(0, 1).toUpperCase();
            return this.reverseNameOrder ?
                `${firstNameInitial}${lastNameInitial}`
                : `${lastNameInitial}${firstNameInitial}`;
        });
        this.fullName = computed(() => {
            const user = this.userState();
            const impersonated = this.userState().impersonatingUser;

            const fullName = (user: UserDetails): string=> {
                return this.reverseNameOrder
                    ? `${user.firstName} ${user.lastName}`
                    : `${user.lastName} ${user.firstName}`;
            };
            return {
                user: fullName(user),
                impersonated: impersonated ? fullName(impersonated) : undefined,
            };
        });
    }

    onShowInfoClick(): void {
        this.showProfileInfo.emit();
    }

    onClose(): void {
        this.closeProfileMenu.emit();
    }
}
