import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    SimpleChanges,
    OnInit,
    OnDestroy,
    Output,
    EventEmitter,
    ChangeDetectorRef,
    OnChanges,
    inject,
} from '@angular/core';
import { EuiAppShellService } from '@eui/core';
import { EuiMenuItem } from '@eui/components/eui-menu';
import { Subscription } from 'rxjs';
import { EUI_ICON } from '@eui/components/eui-icon';
import { DOCUMENT } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { RouterLink, RouterLinkActive } from '@angular/router';

export interface ToolbarItem<M = unknown> extends EuiMenuItem<M> {
    isHome?: boolean;
    isSeparator?: boolean;
    children?: ToolbarItem<M>[];
}

@Component({
    selector: 'eui-toolbar-menu',
    templateUrl: './toolbar-menu.component.html',
    styleUrl: './toolbar-menu.component.scss',
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_ICON,
        RouterLink,
        RouterLinkActive,
        TranslateModule,
    ],
})
export class EuiToolbarMenuComponent<Item extends ToolbarItem = ToolbarItem> implements OnInit, OnDestroy, OnChanges {
    @HostBinding('class')
    public get cssClasses(): string {
        return 'eui-toolbar-menu';
    }

    @Input() items: Item[];

    @Output() menuItemClick = new EventEmitter<ToolbarItem>();

    isdropdownOpen = false;
    asService = inject(EuiAppShellService);
    private subs: Subscription;
    private cd = inject(ChangeDetectorRef);
    private document = inject<Document>(DOCUMENT);

    constructor() {
        this.subs = new Subscription();
    }

    ngOnInit(): void {
        this.asService.setState({
            ...this.asService.state,
            hasToolbarMenu: true,
        });

        // subscribe to state changes
        this.subs.add(this.asService.getState<Item[]>('menuLinks').subscribe((links: Item[]) => (this.items = links)));
    }

    ngOnDestroy(): void {
        this.subs.unsubscribe();
        this.asService.setState({
            ...this.asService.state,
            hasToolbarMenu: false,
        });
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.items) {
            this.asService.setState({
                ...this.asService.state,
                menuLinks: changes.items.currentValue,
            });
        }
    }

    onLinkClick(link: ToolbarItem): void {
        if (link.url) {
            window.scrollTo(0, 0);
        }
        if (!link.disabled && link.children) {
            this.menuItemClick.emit(link);
        }
        if (!link.disabled && !link.children) {
            this.menuItemClick.emit(link);

            // click on dropitems to close dropdown
            const dropdown = this.document.querySelectorAll('#top-menu li:hover > ul');
            dropdown.forEach((menus) => {
                menus.classList.remove('show');
                menus.classList.remove('showOnEnter');
            });

            // open again on mouseover
            const dropBtns = this.document.querySelectorAll('#top-menu li:hover');
            dropBtns.forEach((btn) => {
                btn.addEventListener('mouseover', (e) => {
                    const dropContent = btn.querySelector('#top-menu li:hover > ul');
                    const shouldOpen = dropContent ? !dropContent.classList.contains('show') : null;
                    e.preventDefault();

                    if (shouldOpen) {
                        dropContent.classList.add('show');
                    }
                    e.stopPropagation();
                });
            });
        }
        if (link.urlExternal) {
            window.open(link.urlExternal, link?.urlExternalTarget || '_blank');
        }
        if (link.command) {
            link.command();
        }
    }

    onKeyDown(event: KeyboardEvent, link: ToolbarItem): void {
        switch (event.key) {
            case 'Enter': {
                if (link.url) {
                    window.scrollTo(0, 0);
                }
                if (link.children) {
                    this.menuItemClick.emit(link);
                    this.isdropdownOpen = true;
                }
                if (!link.children) {
                    this.menuItemClick.emit(link);
                    this.isdropdownOpen = false;
                }
                if (link.urlExternal) {
                    window.open(link.urlExternal, link.urlExternal);
                }
                if (link.command) {
                    link.command();
                }
                break;
            }
            case 'Tab': {
                if (this.isdropdownOpen) {
                    const lastchild = Array.from(this.document.querySelectorAll('.child > a')).reverse()[0] as HTMLElement;
                    lastchild.onblur = (): void => {
                        // last child onblur
                        if (!event.shiftKey) {
                            this.isdropdownOpen = false;
                            this.cd.detectChanges();
                            // eslint-disable-next-line @typescript-eslint/no-empty-function
                            lastchild.onblur = (): void => {};
                        }
                    };
                }
                break;
            }
            case 'Escape': {
                this.isdropdownOpen = false;
                break;
            }
            default:
                break;
        }

        if (event.shiftKey && event.key === 'Tab') {
            if (this.isdropdownOpen) {
                const firstchild = Array.from(this.document.querySelectorAll('.child > a'))[0] as HTMLElement;
                firstchild.onblur = (): void => {
                    // first child onblur
                    this.isdropdownOpen = false;
                    this.cd.detectChanges();
                    // eslint-disable-next-line @typescript-eslint/no-empty-function
                    firstchild.onblur = (): void => {};
                };
                if (link.children) {
                    this.isdropdownOpen = false;
                }
            }
        }
    }
}
