import {
    Component,
    HostBinding,
    ViewEncapsulation,
    Input,
    OnInit,
    Output,
    EventEmitter,
    OnChanges,
    SimpleChanges,
    HostListener,
    booleanAttribute,
    OnDestroy,
    AfterViewInit,
    ViewChildren,
    QueryList,
    ChangeDetectorRef,
    ViewChild,
    ElementRef,
    inject,
} from '@angular/core';
import { Router, ActivatedRoute, NavigationEnd } from '@angular/router';
import { coerceBooleanProperty } from '@angular/cdk/coercion';
import { FocusKeyManager } from '@angular/cdk/a11y';
import { Subscription } from 'rxjs';

import { consumeEvent } from '@eui/core';
import { EuiMenuItemComponent } from './eui-menu-item.component';
import { EuiMenuItem } from './models/eui-menu-item.model';
import { NgTemplateOutlet } from '@angular/common';
import { EUI_ICON } from '@eui/components/eui-icon';
import { EUI_ICON_INPUT } from '@eui/components/eui-icon-input';
import { EUI_INPUT_TEXT } from '@eui/components/eui-input-text';

@Component({
    selector: 'eui-menu',
    templateUrl: './eui-menu.component.html',
    styleUrls: ['./styles/_index.scss'],
    encapsulation: ViewEncapsulation.None,
    imports: [
        NgTemplateOutlet,
        EuiMenuItemComponent,
        ...EUI_ICON,
        ...EUI_ICON_INPUT,
        ...EUI_INPUT_TEXT,
    ],
})
export class EuiMenuComponent implements OnInit, OnChanges, OnDestroy, AfterViewInit {
    @ViewChildren(EuiMenuItemComponent) protected menuItemsComponents: QueryList<EuiMenuItemComponent>;
    @ViewChild('filterInput', { read: ElementRef }) protected filterInput: ElementRef<HTMLInputElement>;

    @HostBinding('class')
    public get cssClasses(): string {
        return [
            'eui-menu',
            this.isCollapsed ? 'eui-menu--collapsed' : '',
            !this.hasIcons ? 'eui-menu--no-icons' : '',
            this.isFlat ? 'eui-menu--flat': '',
        ].join(' ').trim();
    }

    @Input() items: EuiMenuItem[];
    @Input() searchFilterLabel: string;
    @Input() externalLinkLabel: string;
    @Input() fragmentId: string;
    @Input() filterValue = '';

    @Input({ transform: booleanAttribute }) isCollapsed = false;
    @Input({ transform: booleanAttribute }) hasCollapsedInitials = false;
    @Input({ transform: booleanAttribute }) hasFilter = false;
    @Input({ transform: booleanAttribute }) hasIcons = false;
    @Input({ transform: booleanAttribute }) hasIconsLabels = false;
    @Input({ transform: booleanAttribute }) hasTooltip = true;
    @Input({ transform: booleanAttribute }) hasTooltipOnExpanded = false;
    /**
     * Expand all items in the menu. Affects only items that have no expanded property set.
     * e.g. items = [{label: test, expanded: true}, {label: test2, expanded: false}, {label: test3}] will expand only test3.
     */
    @Input({ transform: booleanAttribute }) expandAllItems = false;
    @Input({ transform: booleanAttribute }) isFlat = false;
    @Input({ transform: booleanAttribute }) hasScrollToItem = false;
    @Input({ transform: booleanAttribute }) hasBoldRootLevel = false;

    @Output() isClick: EventEmitter<boolean> = new EventEmitter();
    @Output() itemClick: EventEmitter<EuiMenuItem> = new EventEmitter<EuiMenuItem>();
    @Output() expandToggle = new EventEmitter<EuiMenuItem>();

    protected hasExpandIcon = true;
    private subscription: Subscription;
    private focusKeyManager: FocusKeyManager<EuiMenuItemComponent>;
    private router = inject(Router);
    private route = inject(ActivatedRoute);
    private cd = inject(ChangeDetectorRef);

    @HostListener('click', ['$event'])
    stopPropagation(event: MouseEvent): void {
        event.stopPropagation();
    }

    onKeydown(event: KeyboardEvent): void {
        // finds first child when ArrowDown
        const firstChild = this.focusKeyManager.activeItem?.item.children? this.findFirstFilteredItem(this.focusKeyManager.activeItem?.item.children) : undefined;
        const firstFocusableItem = this.findFocusableItem(firstChild);
        // finds the parent element
        const parent = this.focusKeyManager.activeItem?.item.parent;
        const parentFocusableItem = this.findFocusableItem(parent);
        switch (event.key) {
            case 'Enter': {
                if (
                    (this.focusKeyManager.activeItem.isLinkItem || this.focusKeyManager.activeItem.isUrlItem) &&
                    !this.focusKeyManager.activeItem.disabled
                ) {
                    this.focusKeyManager.activeItem.onClick(event);
                    event.preventDefault();
                }
                break;
            }
            case 'ArrowRight': {
                if(this.isFilterEnabled()) {
                    break;
                }
                if(this.focusKeyManager.activeItem?.item.actionIcon){
                    this.checkActionIconFocusState();
                    break;
                } else {
                    if (!this.focusKeyManager.activeItem?.item.expanded) {
                        this.focusKeyManager.activeItem?.onExpandToggle(event);
                        this.cd.detectChanges();
                    }
                    break;
                }
            }
            case 'ArrowLeft': {
                if(this.isFilterEnabled()) {
                    break;
                }
                if(this.focusKeyManager.activeItem?.item.actionIcon){
                    this.checkActionIconFocusState();
                    break;
                } else {
                    if (this.focusKeyManager.activeItem?.item.expanded) {
                        this.focusKeyManager.activeItem.onExpandToggle(event);
                        this.cd.detectChanges();
                        event.preventDefault();
                    }
                    break;
                }
            }
            case 'ArrowDown': {
                event.preventDefault();
                if (this.shouldRenderChild(this.focusKeyManager.activeItem?.item)) {
                    //focuses first child
                    firstFocusableItem?.focus();
                    this.focusKeyManager.updateActiveItem(firstFocusableItem);
                } else if (parent) {
                    // finds last filtered child when ArrowDown and navigating within submenu
                    const filteredChildren = this.findFilteredItems(parent.children);
                    const lastChildIndex = (filteredChildren?.length) - 1;
                    const lastChild = filteredChildren[lastChildIndex];
                    const lastFocusableItem = this.findFocusableItem(lastChild);
                    // if the active item is the last child, puts the focus on the next parent
                    if(this.focusKeyManager.activeItem === lastFocusableItem){
                       this.focusKeyManager.updateActiveItem(parentFocusableItem);
                       this.focusKeyManager.setNextItemActive();
                    } else {
                        this.focusKeyManager.setActiveItem(this.focusKeyManager.activeItemIndex +1);
                    }
                } else {
                    // skips remaining children in the query list when there is expanded node
                    this.focusKeyManager.skipPredicate(menuItem => menuItem.parent != undefined || menuItem.item.visible === false);
                    this.focusKeyManager.onKeydown(event);
                }
                break;
            }
            case 'ArrowUp': {
                event.preventDefault();
                if (parent) {
                    // finds first filtered child when ArrowUp
                    const filteredChildren = this.findFilteredItems(parent.children);
                    const firstChildUp = filteredChildren['0']
                    const firstFocusableItemUp = this.findFocusableItem(firstChildUp);
                    // when navigating up on a submenu focuses the parent if the active item is the first child
                    if(this.focusKeyManager.activeItem === firstFocusableItemUp){
                        this.focusKeyManager.setActiveItem(parentFocusableItem);
                     } else {
                        this.focusKeyManager.setActiveItem(this.focusKeyManager.activeItemIndex -1);
                     }
                } else {
                    this.focusKeyManager.onKeydown(event);
                    // when navigating up from a parent element to an expanded submenu, finds the last child and focuses it
                    if(this.shouldRenderChild(this.focusKeyManager.activeItem?.item)){
                        const filteredChildren = this.findFilteredItems(this.focusKeyManager.activeItem?.item.children);
                        const lastChildIndexUp = (filteredChildren.length) - 1;
                        const lastFocusableItemUp =this.findFocusableItem(filteredChildren[lastChildIndexUp]);
                        this.focusKeyManager.setActiveItem(lastFocusableItemUp);
                    }
                }
                break;
            }
            default: {
                this.focusKeyManager.onKeydown(event);
                break;
            }
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.items) {
            this.items = this.configureItems(this.items);
            // get current url
            const currentUrl = this.router.url;
            // find an item that matches the current url or the most relevant one
            const item = this.findMostRelevantItem(currentUrl, this.items);
            // expand to that item
            if (item) {
                this.expandToGivenItem(item);
            }
        }

        // Expand / Collapse All items
        if (changes.expandAllItems) {
            this.items = this.setExpandedToAllItems(coerceBooleanProperty(changes.expandAllItems.currentValue), this.items);
        }

        if (changes.filterValue && this.hasFilter) {
            this.onFilter(changes.filterValue.currentValue ?? '');
        }

        // Refresh when interactive collapsed to initials
        if (changes.hasCollapsedInitials) {
            this.hasCollapsedInitials = changes.hasCollapsedInitials.currentValue;
            this.items = this.configureItems(this.items);
        }

        if(changes.hasScrollToItem){
            this.hasScrollToItem = changes.hasScrollToItem.currentValue;
            if(this.hasScrollToItem){
                this.scrollToItem(this.router.url);
            }
        }

        if(changes.hasFilter){
            this.hasFilter = changes.hasFilter.currentValue;
            if(!this.hasFilter) {
                // iterate through all items and reset the filtered property
                this.items = this.filterMenuItems(this.items, '')
            }
        }
    }

    ngOnInit(): void {
        // Labels default values - TODO : translations
        if (!this.searchFilterLabel) {
            this.searchFilterLabel = 'Search filter';
        }

        // subscription to routes url changes for activating the scrollIntoView
        this.router.events.subscribe((event) => {
            // Handle route change event
            if (event instanceof NavigationEnd) {
                if (this.hasScrollToItem) {
                    this.scrollToItem(event.url);
                }
            }
        });
    }

    ngAfterViewInit(): void {
        // instantiates FocusKeyManager with the query list of items enabling wrapping
        this.focusKeyManager = new FocusKeyManager(this.menuItemsComponents).withWrap();

        // scrolls to the item that matches the current url
        if(this.hasScrollToItem){
            this.scrollToItem(this.router.url);
        }
    }

    ngOnDestroy():void {
        if (this.subscription) {
            this.subscription.unsubscribe();
        }
    }

    protected onClick(item: EuiMenuItem): void {
        if (!item.disabled) {
            if (item.urlExternal) {
                window.open(item.urlExternal, item.urlExternalTarget || '_blank');
            } else if (item.url) {
                this.router.navigate([item.url], { relativeTo: this.route, fragment: this.fragmentId });
            } else {
                if (typeof item.command === 'function') {
                    item.command();
                } else {
                    this.onExpandToggle(item);
                }
            }

            if (item.link) {
                this.items = this.items?.map((it) => {
                    it.active = false;
                    if (it.id === item.id) {
                        it.active = true;
                    }
                    return it;
                });
            }
        }

        this.isClick.emit(true);
        this.itemClick.emit(item);

        const focusedItem = this.findFocusableItem(item);
        this.focusKeyManager.updateActiveItem(focusedItem);
    }

    protected onExpandToggle(item: EuiMenuItem): void {
        if (item.children) {
            this.expandToggle.emit(item);
            this.onExpandToggled(item, this.items);
            // TODO: investigate why the above is needed. Can it be simply "item.expanded = !item.expanded;" ?
        }
    }

    protected onMenuFilterClick(event: MouseEvent): void {
        consumeEvent(event);
    }

    /**
     * Filter the menu items based on the input value
     * @param event
     * @protected
     */
    protected onFilter(event: Event): void;
    protected onFilter(value: string): void;
    protected onFilter(eventOrValue: Event | string): void {
        const value = eventOrValue instanceof Event
            ? (eventOrValue.target as HTMLInputElement).value
            : eventOrValue;
        this.items = this.filterMenuItems(this.items, value);
        this.hasExpandIcon = !(this.isFilterEnabled());
    }

    /**
     * Check if the children of an item should be rendered. The children should be rendered if the item is expanded
     * or if the item is filtered and the filter input has a value. There are two cases when the filter input has a value:
     * 1. The user has typed something in the filter input
     * 2. The user has typed something in the filter input and the item is filtered
     * In general there are two states to be taken into account, the expanded state and the filtered state.
     *
     * @param item
     * @protected
     */
    protected shouldRenderChild(item: EuiMenuItem): boolean {
        return item?.children &&
            (
                item?.expanded || (
                    this.hasFilter &&
                    item?.filtered &&
                    this.isFilterEnabled()
                )
            )
    }

    /**
     * finds the EuiMenuItemComponent in the queried focusableItems[] that  matches the passed EuiMenuItem object
     *
     * @param menuItem an EuiMenuItem
     * @private
     */
    private findFocusableItem(menuItem: EuiMenuItem ): EuiMenuItemComponent {
        return this.menuItemsComponents.find(
            (focusableItem) => focusableItem.item.label === menuItem?.label && focusableItem.item.id === menuItem.id,
        );
    }

    /**
     * finds the first item that is filtered
     *
     * @param menuItems an array of EuiMenuItem
     * @private
     */
    private findFirstFilteredItem(menuItems: EuiMenuItem []): EuiMenuItem {
        return menuItems.find((item) => item.filtered);
    }

    /**
     * finds all filtered menu items
     *
     * @param menuItems an array of EuiMenuItem
     * @private
     */
    private findFilteredItems(menuItems: EuiMenuItem []): EuiMenuItem [] {
        return menuItems.filter((items) => items.filtered);
    }

    /**
     * checks the focus state of the action icon
     *
     * @private
     */
    private checkActionIconFocusState(): void {
        // check if the action icon is focused and if not focus it, otherwise focus the active item
        // eslint-disable-next-line
        !this.focusKeyManager.activeItem.isActionIconFocused ? this.focusKeyManager.activeItem.focusActionIcon() : this.focusKeyManager.activeItem.focus();
    }

    /**
     * filter all menu items given a value
     *
     * @param menuItems an array of menu items
     * @param filterValue the value to filter menu items
     * @private
     */
    private filterMenuItems(menuItems: EuiMenuItem[], filterValue: string): EuiMenuItem[] {
        return menuItems?.map((item: EuiMenuItem) => {
            const found = item.label?.toLowerCase().indexOf(filterValue.toLowerCase()) !== -1;
            if (item.children) {
                item.children = this.filterMenuItems(item.children, filterValue);
                item.filtered = item.children.filter((l) => l['filtered'] === true).length > 0;
            } else if (found) {
                item.filtered = found;
            } else {
                item.filtered = false;
            }
            return item;
        }) || [];
    }

    /**
     * expand / collapse all items
     *
     * @param isExpanded
     * @param items
     * @private
     */
    private setExpandedToAllItems(isExpanded: boolean, items: EuiMenuItem[]): EuiMenuItem[] {
        return items?.map((item) => {
            if (item.children) {
                item.expanded = item.expanded ?? isExpanded;
                item.children = this.setExpandedToAllItems(isExpanded, item.children);
            }
            return Object.assign(item, { visible: item.visible === undefined ? true : item.visible });
        });
    }

    /**
     * expand / collapse a menu item
     *
     * @param item The item where the "expand" had been toggled
     * @param items The items list (used for recursion)
     * @private
     */
    private onExpandToggled(item: EuiMenuItem, items: EuiMenuItem[]): void {
        const itemIdx = items?.indexOf(item);
        if (itemIdx > -1) {
            items[itemIdx].expanded = !items[itemIdx].expanded;
        } else {
            items.forEach((i) => {
                if (i.children) {
                    this.onExpandToggled(item, i.children);
                }
            });
        }
    }

    /**
     * configure an array of items with visible, filtered and expand (in case of expandAllItems flag enabled) properties
     *
     * @param items An array of EuiMenuItem
     * @param parent the parent item of items if exists
     * @private
     */
    private configureItems(items: EuiMenuItem[], parent?: EuiMenuItem): EuiMenuItem[] {
        return items?.map((item) => {
            // recursion in case there are children
            if (item.children) {
                item.children = this.configureItems(item.children, item);
                // expand all parents with children
                if (this.expandAllItems) {
                    item.expanded = true;
                }
            }
            // point to the parent
            if (parent) {
                item.parent = parent;
            }

            // make sure the items are configured with a unique id
            this.items = this.items?.map((item) => this.setRandomId(item));

            if (item.label && this.hasCollapsedInitials) {
                const words = item.label.split(' ');
                if (words.length === 1) {
                    item.initials = `${item.label.substring(0, 1)}${item.label.substring(1, 1)}`;

                } else {
                    item.initials = `${words[0].substring(0, 1)}${words[1].substring(0, 1)}`;
                }
            }

            return Object.assign(item, { visible: item.visible === undefined ? true : item.visible, filtered: true });
        });
    }

    /**
     * Given a URL and a list of items, it will expand the item that matches the URL. If not item matches exactly the url, then it will
     * match the item that is most relevant to that url.
     *
     * @param url
     * @param items
     * @param relevantItem
     * @private
     */
    private findMostRelevantItem(url: string, items: EuiMenuItem[], relevantItem?: EuiMenuItem): EuiMenuItem {
        if (!items) {
            return null;
        }

        items.forEach((item) => {
            if (item.url && url.indexOf(item.url.substring(1)) > -1) {
                relevantItem = this.getMostRelevantItem(url, relevantItem, item);
            }

            if (item.children) {
                relevantItem = this.findMostRelevantItem(url, item.children, relevantItem);
            }
        });

        return relevantItem;
    }

    /**
     * Given two items with url return the one with the most relevant url that matches given url
     *
     * @param url A URL to be matched with the one of given items
     * @param item1
     * @param item2
     * @private
     */
    private getMostRelevantItem(url: string, item1: EuiMenuItem, item2: EuiMenuItem): EuiMenuItem {
        const remainder1 = url.replace(item1?.url || '', '');
        const remainder2 = url.replace(item2?.url || '', '');

        return remainder1.length < remainder2.length ? item1 : item2;
    }

    /**
     * Given an item, if there's a parent expand it until you reach the root item
     *
     * @param item Given menu item
     * @private
     */
    private expandToGivenItem(item: EuiMenuItem): void {
        if (item.parent) {
            setTimeout(() => (item.parent.expanded = true));
            this.expandToGivenItem(item.parent);
        }
    }

    /**
     * Set a random id to an item and its child if they don't have one
     * @param item
     * @private
     */
    private setRandomId(item: EuiMenuItem): EuiMenuItem {
        item.id = item.id || crypto.randomUUID();
        if(item.children){
            item.children = item.children.map((child) => {
                return this.setRandomId(child);
            });
        }
        return item;
    }

    /**
     * Scroll to an item if it's not visible in the viewport
     * @param url
     * @private
     */
    private scrollToItem(url: string): void {
        const item = this.findMostRelevantItem(url, this.items);
        if (item) {
            // change the state of that item to expanded if it's not
            this.expandToGivenItem(item);
            setTimeout(_ => {
                const menuItem = this.menuItemsComponents?.find((menuItem) => menuItem.item.id === item.id);
                if(menuItem && !menuItem.elementIsVisibleInViewport()){
                    menuItem.scrollIntoView({ behavior: 'smooth' });
                }
            }, 300);
        }
    }

    /**
     * Check if the filter input has a value
     * @private
     */
    private isFilterEnabled(): boolean {
        return this.filterInput?.nativeElement?.value.length > 0
    }
}
