import { Action } from '../ngrx_kit';
import {
    CoreAppActionTypes,
    CoreAppActions,
    UpdateAppVersionAction,
    UpdateAppConnectionAction,
    AddAppLoadedConfigModulesAction,
    UpdateAppStatusAction,
    UpdateCurrentModuleAction,
    AddApiQueueItemAction,
    RemoveApiQueueItemAction,
    EmptyApiQueueAction,
} from '../actions';
import { AppState, initialAppState } from '@eui/base';

const updateAppVersion = (state: AppState, action: UpdateAppVersionAction): AppState => ({ ...state, version: action.payload });

const updateAppConnection = (state: AppState, action: UpdateAppConnectionAction): AppState => ({ ...state, connected: action.payload });

const updateAppStatus = (state: AppState, action: UpdateAppStatusAction): AppState => ({ ...state, status: action.payload });

const updateCurrentModule = (state: AppState, action: UpdateCurrentModuleAction): AppState =>
    Object.assign({}, state, { currentModule: action.payload });

const addApiQueueItem = (state: AppState, action: AddApiQueueItemAction): AppState => {
    // apply the timestamp to the queue item
    const apiQueueItem = Object.assign({}, action.payload.item, { timestamp: new Date().getTime() });
    // update the queue
    const apiQueue = Object.assign({}, state.apiQueue, { [action.payload.id]: apiQueueItem });
    return Object.assign({}, state, { apiQueue });
};

const removeApiQueueItem = (state: AppState, action: RemoveApiQueueItemAction): AppState => {
    // remove the specified id from the list of item ids and recreate the apiQueue from the remaining ids
    const apiQueue = Object.keys(state.apiQueue)
        .filter((id) => id !== action.payload)
        .reduce((queue, key) => {
            queue[key] = state.apiQueue[key];
            return queue;
        }, {});
    return Object.assign({}, state, { apiQueue });
};

const emptyApiQueue = (state: AppState, action: EmptyApiQueueAction): AppState =>
    // remove all items in the Api Queue
    Object.assign({}, state, { apiQueue: {} });
const actionToReducerMap: { [key: string]: (state: AppState, action: CoreAppActions) => AppState } = {
    [CoreAppActionTypes.UPDATE_APP_VERSION]: updateAppVersion,
    [CoreAppActionTypes.UPDATE_APP_CONNECTION]: updateAppConnection,
    [CoreAppActionTypes.UPDATE_APP_STATUS]: updateAppStatus,
    [CoreAppActionTypes.UPDATE_CURRENT_MODULE]: updateCurrentModule,
    [CoreAppActionTypes.ADD_API_QUEUE_ITEM]: addApiQueueItem,
    [CoreAppActionTypes.REMOVE_API_QUEUE_ITEM]: removeApiQueueItem,
    [CoreAppActionTypes.EMPTY_API_QUEUE]: emptyApiQueue,
};

/**
 * @deprecated it will be removed in the next major version
 */
export const coreAppReducers: (state: AppState, action: Action) => AppState = (state = initialAppState, action: CoreAppActions) => {
    if (actionToReducerMap[action.type]) {
        return actionToReducerMap[action.type](state, action);
    }
    // if the action type is not in the map, call the base reducers method
    return state;
};
