import { booleanAttribute, Component, HostBinding, ChangeDetectionStrategy, ViewEncapsulation, Input, EventEmitter, Output, ContentChildren, forwardRef, QueryList, HostListener } from '@angular/core';
import { consumeEvent } from '@eui/core';
import { EUI_USER_PROFILE, EuiUserProfileMenuComponent } from '@eui/components/eui-user-profile';
import { EUI_BUTTON } from '@eui/components/eui-button';
import { EUI_ICON } from '@eui/components/eui-icon';

@Component({
    selector: 'eui-app-sidebar-header-user-profile',
    templateUrl: './sidebar-header-user-profile.component.html',
    styleUrls: ['./_styles/_index.scss'],
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
    imports: [
        ...EUI_USER_PROFILE,
        ...EUI_BUTTON,
        ...EUI_ICON,
    ],
})
export class EuiAppSidebarHeaderUserProfileComponent {
    @HostBinding('class')
    public get cssClasses(): string {
        return this._getCssClasses();
    }

    @Input() welcomeLabel = 'Welcome';
    @Input() impersonateLabel = 'acting as';
    @Input() avatarUrl: string;

    @Input({ transform: booleanAttribute }) isShowUserInfos = true;
    @Input({ transform: booleanAttribute }) isShowAvatarInitials = false;
    @Input({ transform: booleanAttribute }) isOnline = true;
    @Input({ transform: booleanAttribute }) hasWelcomeLabel = true;
    @Input({ transform: booleanAttribute }) hasTabNavigation = false;
    @Input({ transform: booleanAttribute }) hasToggle = false;
    @Input({ transform: booleanAttribute }) hasProfileDrawer = false;

    // eslint-disable-next-line
    @Output() toggle: EventEmitter<any> = new EventEmitter();
    public toggleProfile = false;

    @ContentChildren(forwardRef(() => EuiUserProfileMenuComponent)) userProfileMenu: QueryList<EuiUserProfileMenuComponent>;

    // TODO: find the correct type or turn into a generic, https://www.typescriptlang.org/docs/handbook/2/generics.html
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    onProfileClick(event: any): void {
        this.toggleProfile = !this.toggleProfile;
        consumeEvent(event);
        this.toggle.emit();
    }

    @HostListener('click', ['$event'])
    onClick(event: MouseEvent): void {
        if (this.hasProfileDrawer) {
            this.onProfileClick(event);
        }
        consumeEvent(event);
    }

    private _getCssClasses(): string {
        return [
            'eui-app-sidebar-header-user-profile',
            this.hasProfileDrawer ? 'eui-app-sidebar-header-user-profile--has-drawer' : '',
        ].join(' ').trim();
    }
}
