import { Component, ChangeDetectionStrategy, HostBinding, ViewEncapsulation, OnInit, ElementRef, OnDestroy, inject } from '@angular/core';
import { EuiAppShellService } from '@eui/core';

@Component({
    selector: 'eui-header-environment',
    template: '<ng-content />',
    styleUrl: './header-environment.component.scss',
    changeDetection: ChangeDetectionStrategy.Default,
    encapsulation: ViewEncapsulation.None,
})
export class EuiHeaderEnvironmentComponent implements OnInit, OnDestroy {
    @HostBinding('class') cssClass = 'eui-header-environment';
    protected asService = inject(EuiAppShellService);
    private elRef = inject(ElementRef);

    ngOnInit(): void {
        this.asService?.setState({
            ...this.asService.state,
            hasHeaderEnvironment: true,
            environmentValue: this.elRef.nativeElement.innerHTML,
        });
    }

    ngOnDestroy(): void {
        this.asService?.setState({
            ...this.asService.state,
            hasHeaderEnvironment: false,
        });
    }
}
