import {
    Directive,
    ElementRef,
    Input,
    Output,
    AfterContentInit,
    NgModule,
    EventEmitter,
    OnDestroy,
    HostListener,
    OnChanges,
    SimpleChanges,
    Renderer2,
    numberAttribute,
    booleanAttribute,
    inject,
} from '@angular/core';
import { NgControl } from '@angular/forms';
import { Subscription } from 'rxjs';

/**
 * @description
 * A directive that adds maxLength functionality to input and textarea elements with visual feedback.
 * It shows the remaining characters count and provides visual indication when the limit is reached.
 *
 * @selector input[euiMaxlength], textarea[euiMaxlength], [ngModel][euiMaxlength], [formControlName][euiMaxlength]
 *
 * @example
 * ```HTML
 * <!-- Basic usage -->
 * <input [euiMaxlength]="50">
 *
 * <!-- With form control -->
 * <input [formControlName]="'name'" [euiMaxlength]="100">
 *
 * <!-- Hide maxlength indicator -->
 * <textarea [euiMaxlength]="200" [isShowMaxlength]="false"></textarea>
 * ```
 *
 * @publicApi
 */
@Directive({
    selector: `
    input[euiMaxlength],
    textarea[euiMaxlength],
    [ngModel][euiMaxlength],
    [formControlName][euiMaxlength]`,
})
export class EuiMaxLengthDirective implements AfterContentInit, OnDestroy, OnChanges {
    /**
     * @description
     * It accepts number values to indicate the maxLength of an input. To reset or disable it set the value to null.
     * NULL value will remove any MaxLength indicator even if another input like isShowMaxlength equals true.
     */
    @Input({ alias:'euiMaxlength', transform: numberAttribute }) maxLength: number;
    /**
     * @description
     * Controls the visibility of the maxLength indicator.
     * When true, shows a counter with remaining characters.
     * When false, hides the counter but maintains the maxLength restriction.
     *
     * @default true
     */
    @Input({ transform: booleanAttribute }) isShowMaxlength = true;
    /**
     * @description
     * Emits when the input value length reaches or exceeds the maxLength limit.
     * Emits true when a limit is reached, false when below limit.
     *
     * @emits {boolean} True when max length is reached, false otherwise
     */
    @Output() maxLengthReached: EventEmitter<boolean> = new EventEmitter<boolean>();

    valueChangesSubscription: Subscription;

    private maxLengthSpan: HTMLSpanElement;
    private wrapper: HTMLDivElement;
    private lengthCalcFn: () => number;
    private el = inject(ElementRef);
    private renderer = inject(Renderer2);
    private control = inject(NgControl, { self: true, optional: true })!;

    constructor() {
        // set the default length calculation behavior
        this.setLengthCalcFactory((value) => value?.length || 0);
    }

    ngOnDestroy(): void {
        // remove all DOM added elements
        this.destroyMaxLengthBox();

        // unsubscribe from valueChanges
        if(this.valueChangesSubscription) {
            this.valueChangesSubscription.unsubscribe();
        }
    }

    ngOnChanges(changes: SimpleChanges): void {
        if(changes['isShowMaxlength']) {
            if(this.isShowMaxlength) {
                this.createMaxLengthBox();
                this._refreshValue();
            } else {
                this.destroyMaxLengthBox();
            }
        }
        if(changes['maxLength']) {
            if(this.maxLength < 0) {
                throw new Error('euiMaxlength of an input or a textarea cannot be negative.')
            }
            if(this.maxLength) {
                this._refreshValue();
            } else {
                this.renderer.removeAttribute(this.el.nativeElement, 'maxLength');
                this.destroyMaxLengthBox();
            }
        }
    }

    ngAfterContentInit(): void {
        if (this.maxLength) {
            this.createMaxLengthBox();
            this._refreshValue();
        }

        // this subscription is needed apart from HostListener to Changes in case usage of this directive
        // in custom component that implements ngDefaultControl
        if (this.control?.valueChanges) {
            this.valueChangesSubscription = this.control.valueChanges.subscribe(() => {
                this._refreshValue();
            });
        }
    }

    @HostListener('change', ['$event'])
    onChange(event: Event): void {
        if(!this.control || this.control?.control.updateOn !== 'change') {
            this._refreshValue();
        }
    }

    @HostListener('input', ['$event'])
    onInput(event: KeyboardEvent): void {
        if(!this.control || this.control?.control.updateOn !== 'change') {
            this._refreshValue();
        }
    }

    @HostListener('paste', ['$event'])
    onPaste(event: ClipboardEvent): void {
        // get the value from clipboard
        const value = (event.clipboardData || window['clipboardData']).getData('text');
        // calculate and set the maxLength based on the clipboard value
        const input = <HTMLInputElement>this.el.nativeElement;
        if(this.maxLength) {
            this.renderer.setProperty(input, 'maxLength', this.calculateMaxLength(value));
        }
    }

    /**
     * Sets a custom function to calculate the length of the input value.
     * Useful for implementing custom length calculation logic (e.g., counting characters differently).
     *
     * @param fn Function that takes a string input and returns its calculated length
     *
     * @example
     * ```typescript
     * // Custom length calculation excluding spaces
     * directive.setLengthCalcFactory((value: string) => value.replace(/\s/g, '').length);
     * ```
     */
    public setLengthCalcFactory(fn: (input: string) => number): void {
        this.lengthCalcFn = (): number => {
            const value = this.getValue();
            return fn(value);
        }
    }

    /**
     * Calculates the maximum length for the input element based on current value or provided value.
     *
     * @param value Optional value to calculate max length against (overrides the current input value)
     * @returns {number} Calculated maximum length
     * @private
     */
    private calculateMaxLength(value?: string): number {
        const inputValue = this.getValue();
        return (value?.length || (inputValue?.length || 0) - this.lengthCalcFn()) + this.maxLength;
    }

    /**
     * @description
     * Refreshes the visual state of the maxLength indicator and updates input restrictions.
     * - Updates the remaining characters count
     * - Applies/removes error styling
     * - Emits maxLengthReached event
     * - Truncates value if it exceeds maxLength
     *
     * @private
     */
    private _refreshValue(): void {
        if(isNaN(this.maxLength)) {
            return;
        }
        const input = <HTMLInputElement>this.el.nativeElement;
        const valueLength = this.lengthCalcFn();
        const remainingLength = this.maxLength - valueLength;

        this.renderer.setProperty(input, 'maxLength', this.calculateMaxLength());
        if(this.maxLengthSpan) {
            // based on the remaining length add/remove the error class
            if (remainingLength <= 0) {
                this.renderer.addClass(this.maxLengthSpan, 'eui-input-maxlength--invalid')
                this.maxLengthReached.emit(true);
            } else {
                this.renderer.removeClass(this.maxLengthSpan, 'eui-input-maxlength--invalid')
                this.maxLengthReached.emit(false);
            }
            // set the value of remaining characters
            if (remainingLength < 0) {
                // this feature is only available when the calculation of length is not custom
                // to support this feature you need to calculate this.maxLength also
                if (this.control) {
                    this.control.control.setValue(input.value.substring(0, this.calculateMaxLength()))
                } else {
                    input.value = input.value.substring(0, this.calculateMaxLength());
                }
                this.renderer.setProperty(this.maxLengthSpan, 'innerHTML', '0')
            } else if (remainingLength >= 0) {
                this.renderer.setProperty(this.maxLengthSpan, 'innerHTML', (this.maxLength - valueLength).toString())
            }
        }
    }

    /**
     * @description
     * Creates the maxLength indicator box in the DOM.
     * Wraps the input element and adds the counter span with appropriate styling.
     *
     * @private
     */
    private createMaxLengthBox(): void {
        if(this.maxLengthSpan) {
            this.destroyMaxLengthBox();
        }
        // creates the span that holds the max length value which changes according to input
        this.maxLengthSpan = this.renderer.createElement('span');
        this.renderer.addClass(this.maxLengthSpan, 'eui-input-maxlength')
        this.renderer.setAttribute(this.maxLengthSpan, 'innerHTML', this.maxLength.toString());

        // create wrapper element
        const nativeElement: HTMLElement = this.el.nativeElement;
        if (nativeElement != null) {
            // set width to 100%
            this.renderer.setStyle(nativeElement, 'width', '100%');
            const parent: Node = nativeElement.parentNode;
            if (parent != null && this.isShowMaxlength) {
                // creates wrapper div of input and maxLength span
                this.wrapper = this.renderer.createElement('div');
                this.renderer.addClass(this.wrapper, 'eui-input-maxlength-wrapper');
                // swap, wrapper should wrap the nativeElement and maxLength span
                parent.replaceChild(this.wrapper, nativeElement);
                this.renderer.appendChild(this.wrapper, nativeElement);
                this.renderer.appendChild(this.wrapper, this.maxLengthSpan);
            }
        }
    }

    /**
     * @description
     * Removes the maxLength indicator box from the DOM.
     * Restores the original DOM structure by unwrapping the input element.
     *
     * @private
     */
    private destroyMaxLengthBox(): void {
        // removes maxlength element from DOM
        if(this.maxLengthSpan) {
            this.renderer.removeChild(this.maxLengthSpan.parentElement, this.maxLengthSpan);
            this.maxLengthSpan = undefined;
        }

        // remove wrapper from DOM
        if(this.wrapper) {
            // get parent node of wrapper
            const parent: Node = this.wrapper.parentNode;
            const nativeElement: HTMLElement = this.el.nativeElement;
            // swap wrapper and nativeElement
            parent?.replaceChild(nativeElement, this.wrapper);
            // removes wrapper element from DOM
            this.renderer.removeChild(this.wrapper.parentElement, this.wrapper);
            this.wrapper = undefined;
        }
    }

    /**
     * @description
     * Returns the current value of the input element.
     * Handles different update strategies when used with forms.
     *
     * @returns {string} Current input value
     * @private
     */
    private getValue(): string {
        const input = <HTMLInputElement>this.el.nativeElement;
        return this.control && this.control.control.updateOn === 'change' ? this.control.value : input.value;
    }
}

/**
 * @description
 * Module that provides the EuiMaxLengthDirective.
 * Import this module to use the directive in your application.
 *
 * @deprecated Use {@link `EuiMaxLengthDirective`} instead.
 *
 * @example
 * ```typescript
 * @NgModule({
 *   imports: [EuiMaxLengthDirectiveModule]
 * })
 * export class MyModule { }
 * ```
 *
 * @deprecated Use {@link `EuiMaxLengthDirective`} instead.
 * @publicApi
 */
@NgModule({
    imports: [EuiMaxLengthDirective],
    exports: [EuiMaxLengthDirective],
})
export class EuiMaxLengthDirectiveModule {
}
