import { Component, HostBinding, inject, Input } from '@angular/core';
import { BaseStatesDirective } from '@eui/components/shared';

/**
 * @description
 * A component that serves as the main container for input group elements.
 * Can only be used as an attribute selector on a div element.
 */
@Component({
    // eslint-disable-next-line @angular-eslint/component-selector
    selector: 'div[euiInputGroup]',
    styleUrl: './eui-input-group.scss',
    template: '<ng-content/>',
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiSizeS',
                'euiSizeVariant',
            ],
        },
    ],    
})
export class EuiInputGroupComponent {
    /**
     * @description
     * Input property for setting the data-e2e attribute value.
     * Used for end-to-end testing purposes.
     *
     * @default 'eui-input-group'
     */
    @HostBinding('attr.data-e2e') @Input() e2eAttr = 'eui-input-group';
    /**
     * @description
     * Getter that returns the CSS class for the component.
     * Bound to the host element's class attribute.
     *
     * @returns {string} The CSS class name
     */
    @HostBinding('class')
    public get cssClasses(): string {
        return [
            this.baseStatesDirective.getCssClasses('eui-input-group'),
        ].join(' ').trim();
    }

    /**
     * @description
     * Protected property that defines the type of the input group.
     * Bound to the host element's type attribute.
     *
     * @protected
     * @default 'inputGroup'
     */
    @HostBinding('attr.type') protected type = 'inputGroup';

    public baseStatesDirective: BaseStatesDirective = inject(BaseStatesDirective);
}
