import {
    Component,
    ChangeDetectionStrategy,
    ViewEncapsulation,
    Input,
    ViewChild,
    TemplateRef,
    ViewContainerRef,
    AfterViewInit,
    OnDestroy,
    Output,
    EventEmitter,
    Directive,
    ContentChild,
    forwardRef,
    QueryList,
    ElementRef,
    OnInit,
    booleanAttribute,
    SimpleChanges,
    OnChanges,
    inject,
} from '@angular/core';
import { TemplatePortal } from '@angular/cdk/portal';
import { BehaviorSubject, Subject } from 'rxjs';

import { BaseStatesDirective } from '@eui/components/shared';

import { EuiDialogService } from './services/eui-dialog.service';
import { EuiDialogInterface } from './models/eui-dialog.config';
import { DIALOG_COMPONENT_CONFIG } from './services/eui-dialog.token';
import { OpenedDialog } from './models/opened-dialog.model';
import { EuiDialogVerticalPosition } from './models/eui-dialog-alignment';

@Component({
    selector: 'eui-dialog',
    templateUrl: './eui-dialog.component.html',
    styleUrl: './eui-dialog.scss',
    providers: [{ provide: DIALOG_COMPONENT_CONFIG, useValue: null }],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    imports: [
    ],
    hostDirectives: [
        {
            directive: BaseStatesDirective,
            inputs: [
                'euiPrimary',
                'euiSecondary',
                'euiInfo',
                'euiSuccess',
                'euiWarning',
                'euiDanger',
                'euiAccent',
                'euiVariant',
            ],
        },
    ],
})
export class EuiDialogComponent implements AfterViewInit, OnDestroy, OnInit, OnChanges {
    @Input() e2eAttr = 'eui-dialog';
    @Input() title: string;
    @Input() acceptLabel = 'eui.OK';
    @Input() dismissLabel = 'eui.CANCEL';
    @Input() verticalPosition: EuiDialogVerticalPosition;
    @Input() width = '50%';
    @Input() height = 'auto';
    @Input({ transform: booleanAttribute }) isFullScreen = false;
    @Input({ transform: booleanAttribute }) hasCloseButton = true;
    @Input({ transform: booleanAttribute }) hasAcceptButton = true;
    @Input({ transform: booleanAttribute }) hasDismissButton = true;
    @Input({ transform: booleanAttribute }) hasMobileCustomSize = false;
    @Input({ transform: booleanAttribute }) hasClosedOnClickOutside = false;
    @Input({ transform: booleanAttribute }) hasClosedOnEscape = true;
    @Input({ transform: booleanAttribute }) isHandleCloseOnDismiss = false;
    @Input({ transform: booleanAttribute }) isHandleCloseOnClose = false;
    @Input({ transform: booleanAttribute }) isHandleCloseOnAccept = false;
    @Input({ transform: booleanAttribute }) isHandleCloseOnClickOutside = false;
    @Input({ transform: booleanAttribute }) isHandleCloseOnEscape = false;
    @Input({ transform: booleanAttribute }) isMessageBox = false;
    @Input({ transform: booleanAttribute }) isDraggable = false;
    @Input({ transform: booleanAttribute }) hasNoBodyPadding = false;
    @Input({ transform: booleanAttribute }) hasFooter = true;
    @Input() classList: string = null;

    @Output() clickOutside = new EventEmitter();
    @Output() escape = new EventEmitter();
    @Output() dialogOpen = new EventEmitter();
    @Output() dialogClose = new EventEmitter();
    @Output() dismiss = new EventEmitter();
    @Output() accept = new EventEmitter();

    public content: string | TemplatePortal;
    public isOpen$: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);

    @ViewChild('templateRefHeader') templateRefHeader: TemplateRef<EuiDialogHeaderDirective>;
    @ViewChild('templateRefContent') templateRefContent: TemplateRef<ElementRef>;
    @ViewChild('templateRefFooter') templateRefFooter: TemplateRef<EuiDialogFooterDirective>;

    @ContentChild(forwardRef(() => EuiDialogHeaderDirective)) euiDialogHeaderDirective: QueryList<EuiDialogHeaderDirective>;
    @ContentChild(forwardRef(() => EuiDialogFooterDirective)) euiDialogFooterDirective: QueryList<EuiDialogFooterDirective>;

    baseStatesDirective = inject(BaseStatesDirective);
    private dialog: OpenedDialog;
    private templatePortalHeader: TemplatePortal<EuiDialogHeaderDirective>;
    private templatePortalContent: TemplatePortal<ElementRef>;
    private templatePortalFooter: TemplatePortal<EuiDialogFooterDirective>;
    private destroy$: Subject<boolean> = new Subject<boolean>();
    private viewContainerRef = inject(ViewContainerRef);
    private euiDialogService = inject(EuiDialogService);

    ngOnChanges(changes: SimpleChanges): void {
        if (changes.title && this.dialog) {
            const newTitle = changes.title.currentValue;

            // Update the dialog service with the new title
            this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.dialogContainerConfig.title = newTitle;

            // Trigger change detection to reflect the updated title
            this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.cd.markForCheck();
        }
    }

    ngOnInit(): void {
        if (this.isFullScreen) {
            this.width = '98vw';
            this.height = '97vh';
        }

        if (this.isMessageBox) {
            this.hasClosedOnEscape = false;
            this.hasCloseButton = false;
        }
    }

    ngAfterViewInit(): void {
        if (this.euiDialogHeaderDirective) {
            this.templatePortalHeader = new TemplatePortal(this.templateRefHeader, this.viewContainerRef);
        }

        this.templatePortalContent = new TemplatePortal(this.templateRefContent, this.viewContainerRef);

        if (this.euiDialogFooterDirective) {
            this.templatePortalFooter = new TemplatePortal(this.templateRefFooter, this.viewContainerRef);
        }
    }

    ngOnDestroy(): void {
        this.destroy$.next(true);
        this.destroy$.unsubscribe();
    }

    /**
     * Whether the eui-dialog is open.
     *
     * @usageNotes
     * ```html
     * <eui-dialog #dialog>
     *      \@if (dialog.isOpen) {
     *          <my-component></my-component>
     *      }
     * </eui-dialog>
     * ```
     * @returns A boolean with value `true` when open, otherwise `false`.
     */
    get isOpen(): boolean {
        return this.isOpen$.value;
    }

    /**
     * Open a dialog.
     *
     * @returns A dialog object of type `OpenedDialog`
     */
    public openDialog<HC, HCC, BC, BCC, FC, FCC>(): OpenedDialog {
        const config: EuiDialogInterface<HC, HCC, BC, BCC, FC, FCC> = {
            e2eAttr: this.e2eAttr,
            title: this.title,
            width: this.width,
            height: this.height,
            isFullScreen: this.isFullScreen,
            variant: this.baseStatesDirective.euiVariant,
            acceptLabel: this.acceptLabel,
            dismissLabel: this.dismissLabel,
            hasCloseButton: this.hasCloseButton,
            hasAcceptButton: this.hasAcceptButton,
            hasDismissButton: this.hasDismissButton,
            hasMobileCustomSize: this.hasMobileCustomSize,
            hasClosedOnClickOutside: this.hasClosedOnClickOutside,
            hasClosedOnEscape: this.hasClosedOnEscape,
            isHandleCloseOnDismiss: this.isHandleCloseOnDismiss,
            isHandleCloseOnClose: this.isHandleCloseOnClose,
            isHandleCloseOnAccept: this.isHandleCloseOnAccept,
            isHandleCloseOnClickOutside: this.isHandleCloseOnClickOutside,
            isHandleCloseOnEscape: this.isHandleCloseOnEscape,
            isDraggable: this.isDraggable,
            hasNoBodyPadding: this.hasNoBodyPadding,
            hasFooter: this.hasFooter,
            verticalPosition: this.verticalPosition,
            header: this.templatePortalHeader,
            content: this.templatePortalContent,
            footer: this.templatePortalFooter,
            classList: this.classList,
            clickOutside: () => {
                if (this.hasClosedOnClickOutside) {
                    this.isOpen$.next(false);
                }
                this.clickOutside.emit();
            },
            escape: () => {
                if (this.hasClosedOnEscape) {
                    this.isOpen$.next(false);
                }
                this.escape.emit();
            },
            open: () => {
                this.dialogOpen.emit();
            },
            close: () => {
                if (!this.isHandleCloseOnClose) {
                    this.isOpen$.next(false);
                }
                this.dialogClose.emit();
            },
            dismiss: () => {
                if (!this.isHandleCloseOnDismiss) {
                    this.isOpen$.next(false);
                }
                this.dismiss.emit();
            },
            accept: () => {
                if (!this.isHandleCloseOnAccept) {
                    this.isOpen$.next(false);
                }
                this.accept.emit();
            },
        };

        this.isOpen$.next(true);
        this.dialog = this.euiDialogService.openDialog(config);

        return this.dialog;
    }

    /**
     * Close a Dialog
     */
    public closeDialog(): void {
        this.isOpen$.next(false);
        this.euiDialogService.closeDialog();
    }

    /**
     * Disable Accept button of default eui-dialog footer.
     */
    public disableAcceptButton(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.disableAcceptButton();
    }

    /**
     * Enable Accept button of default eui-dialog footer.
     */
    public enableAcceptButton(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.enableAcceptButton();
    }

    /**
     * Disable Dismiss button of default eui-dialog footer.
     */
    public disableDismissButton(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.disableDismissButton();
    }

    /**
     * Enable Dismiss button of default eui-dialog footer.
     */
    public enableDismissButton(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.enableDismissButton();
    }

    /**
     * Scroll to the bottom of the content
     */
    public scrollToBottom(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.scrollToBottom();
    }

    /**
     * Scroll to the top of the content
     */
    public scrollToTop(): void {
        this.euiDialogService.getDialog(this.dialog.id).containerRef.instance.scrollToTop();
    }
}

/* eslint-disable */
@Directive({ selector: 'eui-dialog-header', })
export class EuiDialogHeaderDirective {}

@Directive({ selector: 'eui-dialog-footer', })
export class EuiDialogFooterDirective {}
/* eslint-enable */
