import { CoreState, AppState, I18nState, LocaleState, NotificationsState, UserState } from '../state';

export const getAppState = (state: CoreState): AppState => state.app;
export const getUserState = (state: CoreState): UserState => state.user;
export const getNotificationsState = (state: CoreState): NotificationsState => state.notifications;
export const getI18nState = (state: CoreState): I18nState => state.i18n;
export const getLocaleState = (state: CoreState): LocaleState => state.locale;
