import { Inject, Injectable, Optional } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { GLOBAL_CONFIG_TOKEN } from './config/tokens';
import { GlobalConfig } from '@eui/base';
import { EuiAppShellService } from './eui-app-shell.service';
import { DOCUMENT } from '@angular/common';

export enum EuiTheme {
    DEFAULT = 'default',
    ECL_EC = 'ecl-ec',
    ECL_EC_RTL = 'ecl-ec-rtl',
    ECL_EU = 'ecl-eu',
    ECL_EU_RTL = 'ecl-eu-rtl',
    EUI_LEGACY = 'eui-legacy',
    EUI_LEGACY_HC = 'eui-legacy-high-contrast',
    DARK = 'dark',
    COMPACT = 'compact',
    DS2025 = 'ds2025',
};

interface IEuiTheme {
    name: EuiTheme,
    isActive: boolean,
    styleSheet: string,
    cssClass: string,
};

export interface ThemeState {
    themes: IEuiTheme[];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    theme: any;
}

const initialState: ThemeState = {
    themes: [
        { name: EuiTheme.DEFAULT, isActive: false, styleSheet: null, cssClass: null },
        { name: EuiTheme.ECL_EC, isActive: false, styleSheet: 'eui-ecl-ec.css', cssClass: null },
        { name: EuiTheme.ECL_EC_RTL, isActive: false, styleSheet: 'eui-ecl-ec-rtl.css', cssClass: null },
        { name: EuiTheme.ECL_EU, isActive: false, styleSheet: 'eui-ecl-eu.css', cssClass: null },
        { name: EuiTheme.ECL_EU_RTL, isActive: false, styleSheet: 'eui-ecl-eu-rtl.css', cssClass: null },
        { name: EuiTheme.EUI_LEGACY, isActive: false, styleSheet: null, cssClass: 'eui-t-eui-legacy' },
        { name: EuiTheme.EUI_LEGACY_HC, isActive: false, styleSheet: null, cssClass: 'eui-t-high-contrast' },
        { name: EuiTheme.DARK, isActive: false, styleSheet: null, cssClass: 'eui-t-dark' },
        { name: EuiTheme.COMPACT, isActive: false, styleSheet: null, cssClass: 'eui-t-compact' },
        { name: EuiTheme.DS2025, isActive: false, styleSheet: null, cssClass: 'eui-t-ds2025' },
    ],
    theme: {
        isDefault: false,
        isEclEc: false,
        isEclEcRtl: false,
        isEclEu: false,
        isEclEuRtl: false,
        isEuiLegacy: false,
        isEuiLegacyHc: false,
        isDark: false,
        isCompact: false,
        isDs2025: false,
    },
};

@Injectable({
    providedIn: 'root',
})
export class EuiThemeService {
    private _state$: BehaviorSubject<ThemeState>;

    constructor(
        @Inject(DOCUMENT) private document: Document,
        @Optional() @Inject(GLOBAL_CONFIG_TOKEN) protected config: GlobalConfig,
        private asService: EuiAppShellService,
    ) {
        this._state$ = new BehaviorSubject(initialState);
        const themeName = (this.config?.eui?.theme as EuiTheme) || EuiTheme.DEFAULT;
        this.setActiveTheme(themeName, true);
    }

    get state$(): Observable<ThemeState> {
        return this._state$.asObservable();
    }

    get state(): ThemeState {
        return this._state$.getValue();
    }

    isDefault(): boolean {
        return this.state.theme.isDefault;
    }
    isEclEc(): boolean {
        return this.state.theme.isEclEc;
    }
    isEclEcRtl(): boolean {
        return this.state.theme.isEclEcRtl;
    }
    isEclEu(): boolean {
        return this.state.theme.isEclEu;
    }
    isEclEuRtl(): boolean {
        return this.state.theme.isEclEuRtl;
    }
    isEuiLegacy(): boolean {
        return this.state.theme.isEuiLegacy;
    }
    isEuiLegacyHc(): boolean {
        return this.state.theme.isEuiLegacyHc;
    }
    isDark(): boolean {
        return this.state.theme.isDark;
    }
    isCompact(): boolean {
        return this.state.theme.isCompact;
    }
    isDs2025(): boolean {
        return this.state.theme.isDs2025;
    }

    setActiveTheme(theme: EuiTheme, isActive: boolean): void {
        const themes = this.state.themes;
        const themeIdx = themes.findIndex(t => t.name === theme);

        if (themeIdx < 0) {
            throw new Error('NO_THEME_FOUND');

        } else {
            themes[themeIdx].isActive = isActive;

            const themeFound: IEuiTheme = themes[themeIdx];

            const status = initialState.theme;

            switch(theme) {
                case EuiTheme.DEFAULT: { status.isDefault = isActive; break; }
                case EuiTheme.ECL_EC: { status.isEclEc = isActive; break; }
                case EuiTheme.ECL_EC_RTL: { status.isEclEcRtl = isActive; break; }
                case EuiTheme.ECL_EU: { status.isEclEu = isActive; break; }
                case EuiTheme.ECL_EU_RTL: { status.isEclEuRtl = isActive; break; }
                case EuiTheme.DARK: { status.isDark = isActive; break; }
                case EuiTheme.COMPACT: { status.isCompact = isActive; break; }
                case EuiTheme.EUI_LEGACY: { status.isEuiLegacy = isActive; break; }
                case EuiTheme.EUI_LEGACY_HC: { status.isEuiLegacyHc = isActive; break; }
                case EuiTheme.DS2025: { status.isDs2025 = isActive; break; }
            }

            this._state$.next({
                themes,
                theme: status,
            });

            this._renderTheme(themeFound, isActive);
        }
    }

    private _renderTheme(themeFound: IEuiTheme, isActive: boolean): void {
        if (themeFound.name === EuiTheme.COMPACT) {
            if (isActive) {
                this.asService.setBaseFontSize('14px');
            } else {
                this.asService.setBaseFontSize('16px');
            }
            const compactLink = this.document.getElementById('eui-theme') as HTMLLinkElement;
            this._renderThemeCss(themeFound, isActive, compactLink);

        } else if (themeFound.name === EuiTheme.ECL_EC_RTL || themeFound.name === EuiTheme.ECL_EU_RTL) {
            const rtlLink = this.document.getElementById('rtl-theme') as HTMLLinkElement;
            this._renderThemeCss(themeFound, isActive, rtlLink);

        } else {
            const themeLink = this.document.getElementById('eui-theme') as HTMLLinkElement;
            this._renderThemeCss(themeFound, isActive, themeLink);
        }
    }

    private _renderThemeCss(themeFound: IEuiTheme, isActive: boolean, link: HTMLLinkElement): void {
        const head = this.document.getElementsByTagName('head')[0];

        if (isActive) {
            if (themeFound.cssClass) {
                document.querySelector('html').classList.add(themeFound.cssClass);
            }
            if (themeFound.styleSheet) {
                if (link) {
                    link.href = themeFound.styleSheet;
                } else {
                    const style = this.document.createElement('link');
                    style.id = 'eui-theme';
                    style.rel = 'stylesheet';
                    style.href = `assets/${themeFound.styleSheet}`;

                    head.appendChild(style);
                }
            }
        } else {
            if (themeFound.cssClass) {
                document.querySelector('html').classList.remove(themeFound.cssClass);
            }

            if (themeFound.styleSheet) {
                if (link) {
                    link.media = '';
                }
            }
        }
    }
}
